import{ARABIAN_HORSE_SHOW_ARTICLE as re}from"./arabianHorseShow-B7XpyR6b.js";import{bd as ae,a4 as n,ar as i,aq as r,b9 as Rs,K as h,n as u,C as p,cK as Wd,d2 as rd,d1 as Ld,bh as vo,dv as od,ay as Od,b5 as nd,av as xs,a as _d,b as Gd,au as Ds}from"./index-CFjdMUdS.js";import{g as l,s as Is,C as Ud,p as ie,b as Bd,f as fa,S as sd,c as Hd,d as zd,e as qd,w as Ns,h as Vd,A as Yd,M as Ft,i as id,j as Jd,D as xa,k as Ea,l as hd,n as Zd,o as Kd,q as Ks,r as jd,T as Qd,I as Xd,t as el,u as Ws}from"./eventFunnelM3f-ClrkuOIi.js";import{S as dd}from"./companyFacts-BN9bpiSI.js";const js="2026-09-04",tl=["premium-suv-scottsdale","maybach-shuttle-sprinter-8","maybach-jet-sprinter-scottsdale","executive-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","limo-sprinter-16-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"].filter(ae),nt=tl.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours}));function ld(e){return h(r[e].hourlyRateCents)}function cd(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}const al=[{href:"/services/wedding-transportation-scottsdale",label:"Scottsdale wedding transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport group transportation"},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published hourly pricing"}];function rl(e){return/^The\s/.test(e)?e:/^[AEIOU]/i.test(e)?`An ${e}`:`A ${e}`}function Wa(e){const t=nt.find(o=>o.slug==="executive-sprinter-scottsdale"),a=nt.find(o=>o.slug==="motorcoach-56");return{path:e.path,title:`${e.name} Wedding Shuttle Guide | Scottsdale Sprinters`,description:`Plan ${e.name} wedding shuttles with published vehicle capacities, hotel pickup waves, venue arrival coordination, and an end-of-night return plan.`,metaDescription:"Hotel pickup waves, vehicle sizing and the end-of-night return",updatedAt:"2026-09-18",h1:`${e.name} wedding shuttle and guest transportation`,eyebrow:"Wedding venue transportation guide",intro:`${rl(e.name)} shuttle from Scottsdale Sprinters works best when one transportation lead owns the guest list, every pickup has a written address, and the venue confirms the final arrival point. This guide turns that into vehicle counts, pickup waves, driver notes, and a return schedule, without inventing a gate or loading zone.`,fleetTable:!0,sections:[{heading:`What should couples know about ${e.name} before planning transportation?`,answer:`${e.name} planning starts with 3 verified details: the venue address, the contracted event space, and the arrival instructions supplied by the venue team, because a property name alone is not enough for a driver brief and public websites do not always publish a wedding-specific loading point.`,paragraphs:[`${e.name} is at ${e.address}. ${e.venueFacts} That tells a transportation planner where the property is and what kind of celebration the venue supports, but it does not replace the instructions in the couple's venue contract. The final driver sheet should use the venue's current written directions and the event-space name exactly as the coordinator provides them.`,`${e.arrivalNote} We do not label an unverified driveway, gate, porte cochere, or service entrance as the wedding drop-off. The couple or planner should ask the venue which approach is approved for the booked space, whether a vehicle may wait, and where guests with mobility needs should be delivered. Those answers belong in the dispatch note before the wedding day.`,e.venueSpecific[0],"Treat the venue source linked below as a planning reference, then reconcile it with the banquet event order. Websites can change, private-event operations can differ from hotel arrivals, and another event may affect traffic flow. One confirmed instruction shared with the reservations team, planner, and venue contact is safer than several guests forwarding different map pins."]},{heading:`Which vehicle size fits the ${e.name} wedding guest count?`,answer:`For ${e.name}, use 10 published capacity bands from a 6-passenger luxury SUV through a 56-passenger motorcoach, then reserve seats for the people actually riding rather than the total attendance; a 120-guest reception may need transportation for only 42 hotel guests while the wedding party follows a separate schedule.`,paragraphs:[`The table on this page uses the same current capacities and hourly rates shown with each vehicle. The ${t.name} seats ${t.capacity} and starts at ${h(t.hourlyRateCents)} per hour, while the ${a.name} seats ${a.capacity} and starts at ${h(a.hourlyRateCents)} per hour. Those figures update with the published fleet information rather than relying on estimates copied into the article.`,"Build the rider count from RSVPs, hotel blocks, family assignments, and accessibility needs. Do not divide the full invitation list by the largest vehicle. Some guests will drive, some will stay on property, and some may need an earlier departure. A clean manifest groups people by pickup and return wave, which can reduce empty seats without putting the ceremony at risk.",e.venueSpecific[1],"Leave operational margin. A vehicle advertised for a maximum seated capacity is not a promise that every combination of passengers, dresses, mobility devices, gifts, and personal items will fit comfortably. Tell the reservations team what the group is carrying. Luggage and gear fit should be confirmed separately whenever airport arrivals, welcome bags, decor, or vendor materials are part of the ride."]},{heading:`How should hotel pickup waves for ${e.name} be organized?`,answer:`Plan at least 2 pickup waves for ${e.name} when guests are split across hotels or readiness times: an early family and wedding-party movement with schedule padding, followed by the main guest shuttle, while one named transportation lead confirms each vehicle's manifest instead of asking chauffeurs to reconcile a changing group chat.`,paragraphs:[`${e.hotelPlan} Start with exact hotel names and street addresses, because similarly named Scottsdale resorts can appear in search results. List a lobby contact for each property and tell guests whether they should wait inside or at a venue-approved pickup point. A chauffeur should never have to circle a resort while a guest finishes packing upstairs.`,"For each wave, publish one ready time and one departure time. The ready time is when guests are fully dressed, carrying everything they need, and physically present at the pickup point. The departure time is when the vehicle rolls. Put buffer between that departure and the ceremony's guest-seating deadline, not merely the invitation time, so normal loading and traffic variation do not consume the entire margin.",e.venueSpecific[2],"A transportation lead should check names against the manifest, call the designated guest contact when someone is missing, and make the go-or-hold decision. That role should not sit with the couple. Share the lead's number with the reservations team before service and choose a backup who can answer while the primary person is in the ceremony."]},{heading:`Where should a shuttle drop guests at ${e.name}?`,answer:`Use 1 venue-confirmed arrival point for each scheduled wave, written exactly as the ${e.name} event team provides it; where the venue publishes no wedding shuttle lane we confirm the live one with them instead of naming a gate, because a guessed entrance sends a full vehicle into the wrong traffic pattern.`,paragraphs:["Send the venue the vehicle type, approximate length, arrival window, and number of passengers. Ask whether the vehicle may dwell while guests unload, whether a coordinator will meet it, and whether the same point is used after the reception. If the answer changes by event space or time of day, place both instructions in the schedule with a clear effective time.","The chauffeur follows current property signage, traffic staff, and venue instructions on arrival. A static web guide cannot see a temporary barricade, private event, construction change, or emergency route. Guests should remain seated until the vehicle is in the approved unloading position, then move together toward the venue contact instead of scattering across a drive.",e.venueSpecific[3],"For older guests or anyone using a mobility device, ask the venue about its accessible route before assigning the vehicle. Vehicle capacity and property accessibility are different questions. Tell the reservations team about boarding needs early so the proposed fleet can be checked; never assume that a capacity number by itself confirms an accessible boarding setup."]},{heading:`How should ${e.name} wedding groups use separate movements?`,answer:`Separate a ${e.name} wedding day into 3 manifests when schedules differ: wedding party, immediate family, and general guests, because one all-purpose shuttle can be delayed by portraits or pre-ceremony duties while another group still needs to reach its seating time, hotel, rehearsal meal, or reception entrance.`,paragraphs:["The wedding party often carries garments, flowers, personal items, and timing responsibilities that the general guest group does not. Give that vehicle a direct contact who understands photography and ceremony cues. If partners are getting ready at different locations, write each movement as its own trip rather than describing the day as a round trip with several implied stops.","Immediate family may need a later pre-ceremony pickup and an earlier return after formal photographs. General guests benefit from the simplest possible instruction: one pickup place, one ready time, and one venue arrival. Keeping those flows separate makes the service easier to understand and gives the planner a clean way to adjust one group without rewriting every rider's plan.",e.venueSpecific[4],"If the ceremony and reception are in different spaces on the same property, confirm whether guests walk or require a vehicle transfer. Do not assume the distance or route from a property map. If off-property movement is required, schedule it explicitly and verify that every guest who arrived by shuttle also has a seat for the next leg."]},{heading:`What is the best end-of-night return plan from ${e.name}?`,answer:`Schedule 2 or 3 return windows from ${e.name} instead of one final departure: an early option for families, a primary option after major reception moments, and a last sweep after the contracted end, with every rider told which hotels are served and who authorizes an unscheduled stop.`,paragraphs:["Return demand is rarely even. Some guests want to leave after dinner, while others stay through the final song. A single departure can either strand early riders or leave a vehicle idle for hours. Staggered waves give guests a clear choice and let the planner protect the final pickup without turning the chauffeur into an on-demand dispatcher.","Write a destination list for every return wave. If multiple hotels are served, order them before the day and tell guests that the shuttle is not a private car making individual address changes. The transportation lead should record anyone who switches waves so the final sweep does not wait for a guest who already left.",e.venueSpecific[5],"Confirm where the vehicle may wait and when it should approach the pickup point. At properties with active resort traffic, arriving too early can be as disruptive as arriving late. The driver and venue contact should have each other's current instructions through the transportation lead, while guests receive a simple meeting-place description approved by the venue."]},{heading:`When should ${e.name} wedding transportation be reserved?`,answer:`Availability varies by date and by vehicle, so no fixed lead time applies: build the ${e.name} plan in 3 passes — settle the service window and pickup addresses, freeze the first manifest once RSVPs are in, then send a final update after the venue confirms access — and we confirm in writing what is open.`,paragraphs:["The first conversation should cover date, service window, pickup addresses, approximate riders, venue, and the kind of experience the couple wants. The reservations team can then identify a sensible capacity mix. A quote is more useful when it describes actual movements than when it contains only a guest total and a broad request for a shuttle.","At the RSVP checkpoint, reconcile replies with hotel lists and identify children, mobility needs, bulky items, and guests who require the early return. Confirm the venue contact and event-space name. This is also the moment to test every phone number, eliminate duplicate guest names, and make sure the planner's schedule matches the transportation schedule.",e.venueSpecific[6],`The final update should be short: approved addresses, ready and departure times, rider counts, contact hierarchy, and venue instructions. Avoid sending a fresh narrative to the driver on the wedding morning. If a true change occurs, route it through the transportation lead and reservations team so there is one acknowledged version. ${Rs}`]},{heading:`How do couples request a precise ${e.name} shuttle quote?`,answer:`A useful ${e.name} quote request includes 7 items: event date, contracted space, every pickup address, first pickup time, final return time, rider count by wave, and a transportation contact; send those details plus special boarding considerations to the reservations team at ${u} or ${p}.`,paragraphs:["Published rates provide the starting point, but the right schedule still depends on time and routing. Tell the reservations team whether the vehicle remains with the group, returns for later waves, or performs only defined transfers. Mention any airport luggage, coolers, decor, mobility devices, or oversized personal items so fit can be confirmed before a vehicle is selected.",`Ask the venue for written transportation instructions and attach them to the request. For ${e.name}, include the contracted event space and the venue coordinator's name. If the venue has not yet finalized access, say that clearly; the quote can use a planning assumption while the final dispatch sheet waits for verified directions.`,e.venueSpecific[7],"Compare the proposed seat count with the manifest, not with a rounded attendance number. A slightly larger vehicle can simplify a wave, while two smaller vehicles can protect groups with different timelines. The best answer is the one that makes the schedule resilient and understandable, not automatically the vehicle with the lowest hourly rate."]},{heading:`What are the most common ${e.name} shuttle questions?`,answer:`Most ${e.name} plans come down to 4 questions: how many people are actually riding, which hotel or home each wave leaves from, what arrival point the venue approves, and how many return times guests need; the answers below give a practical starting point for the planner.`,paragraphs:[]}],faqs:[{question:`Can a shuttle wait at ${e.name} during the wedding?`,answer:`Waiting depends on the venue's current instructions, the contracted service plan, and available staging. Ask the ${e.name} event team where a vehicle may stand, then give that direction to the reservations team before dispatch.`},{question:"Should every invited guest receive a shuttle seat?",answer:"No. Count guests who commit to each pickup and return wave, then add operational margin. Guests staying on property or driving themselves should not inflate the vehicle count."},{question:"Can airport arrivals and the wedding shuttle use the same vehicle?",answer:"Sometimes, but only when flight timing, luggage fit, and the wedding schedule align. Keep airport movements separate on the itinerary so a delayed flight cannot quietly endanger a ceremony departure."},{question:"Who should communicate with the chauffeur?",answer:"Choose one transportation lead and one backup. The couple should not manage guest calls or access changes during portraits, the ceremony, or the reception."}],links:al,sources:[{label:e.sourceLabel,href:e.sourceUrl},...e.secondarySource?[e.secondarySource]:[]]}}const ol=[Wa({path:"/guides/venues/el-chorro",name:"El Chorro",address:"5550 East Lincoln Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official weddings page presents multiple indoor and outdoor event spaces between Camelback and Mummy mountains.",arrivalNote:"The official site publishes the Lincoln Drive address but does not publish a named wedding-shuttle gate, so the exact unload point must come from the venue team.",hotelPlan:"Guests may be staying across Paradise Valley and Scottsdale rather than at the venue itself, so hotel consolidation matters.",sourceLabel:"El Chorro weddings and events",sourceUrl:"https://elchorro.com/weddings-and-events/",venueSpecific:["El Chorro identifies eight event spaces on its wedding materials, with indoor and outdoor choices between Camelback and Mummy mountains. Put the contracted space on every chauffeur note; the Lincoln Drive street address gets the vehicle to the property, but the space name gives the venue team the context needed to confirm the final approach.","Eight named spaces can support very different guest plans, so count riders for the actual ceremony and reception layout instead of treating El Chorro as one generic room. Ask whether the contracted spaces share an arrival area and whether guests move on foot between them before deciding that one capacity plan covers the entire celebration.","El Chorro is not a lodging property, so every guest who uses the shuttle begins somewhere else. Consolidate Paradise Valley and Scottsdale hotel riders into a small number of documented pickups, then keep private-home pickups separate when their timing or access instructions differ. This avoids turning the Lincoln Drive arrival into the first moment the manifest is reconciled.","For the Lincoln Drive approach, the useful venue answer is the approved wedding unload point for the contracted space, not a guessed entrance based on a public map. Give El Chorro the vehicle type and arrival window, record the response verbatim, and ask whether the same point remains available when the reception ends.","A wedding party assigned to one of El Chorro’s outdoor settings may have a different readiness cue from guests entering an indoor event space. Tie each manifest to a named coordinator cue and space, then state whether portraits occur before or after that movement. The chauffeur needs a departure instruction, not the entire photography schedule.","Return waves should name the destination hotels before the first vehicle approaches El Chorro. If guests are split between Paradise Valley and Scottsdale, group compatible stops and publish which wave serves each one. The last sweep should be tied to the contracted event end and the pickup instruction the venue confirms for that evening.","At the 14-day review, repeat the full El Chorro address and every contracted space name with the venue contact. Ask whether another event affects the approach, where the transportation lead should assemble riders, and when a vehicle may be called forward. Record changes in the final schedule rather than relying on an earlier email thread.","An El Chorro quote request is strongest when it names the eight-space choice actually booked, the hotel clusters, and the guest count for each direction. Include whether the ceremony and reception use different spaces and whether any passenger needs extra boarding time. Those details matter more than sending the reservations team the invitation total alone."]}),Wa({path:"/guides/venues/clayton-house",name:"The Clayton House",address:"3719 North 75th Street, Scottsdale, Arizona 85251",venueFacts:"The official tourism listing describes separate event rooms, covered patios, and in-house catering and bar service.",arrivalNote:"The official tourism listing publishes the 75th Street address but does not name a wedding-shuttle curb or gate; confirm the approved unloading position with the venue.",hotelPlan:"Downtown hotels may look close on a map, yet formalwear, weather, and traffic make a scheduled pickup more dependable than asking guests to improvise.",sourceLabel:"Clayton House official venue page",sourceUrl:"https://www.wedgewoodweddings.com/venues/clayton-house",venueSpecific:["The Clayton House describes two indoor-outdoor event spaces plus in-house catering and bar service at its 75th Street property. Name the booked space in the transportation schedule so the venue can distinguish the wedding movement from a general arrival, especially when both parts of the property may be active.","A public address does not establish a shuttle loading position. Treat directions and commercial passenger unloading as separate questions: send the proposed vehicle type to The Clayton House, ask where it should approach, and keep unused seats available when formalwear, gifts, or mobility equipment affect the practical load.","Downtown Scottsdale lodging can produce several small guest clusters. Combine riders by exact hotel and ready time instead of scheduling an individual stop for every room block. A concise route into 3719 North 75th Street gives the transportation lead a realistic headcount at each pickup and leaves the chauffeur with a clear final destination.","Use the published 75th Street address as the routing anchor, then obtain the event team’s exact unloading instruction. Do not infer that the parking entrance, a nearby curb, or the closest door is approved for a larger vehicle. The venue contact should also state whether guests can remain under cover while waiting for a return wave.","Because The Clayton House offers two indoor-outdoor spaces, confirm whether wedding-party portraits, family arrival, and general guest seating all begin from the same side of the property. If they do not, write separate movements and contacts. A single vehicle can still serve multiple groups, but only when each handoff is explicit.","Do not treat nearby public parking as permission for a chauffeured vehicle to stage through the reception. Ask where an empty vehicle may wait, if waiting is allowed, and how the transportation lead should call it forward. That answer determines whether early and final return waves use one continuous booking or separate movements.","During the final review, confirm the event-space name, 75th Street address, authorized approach, and end-of-night assembly point with The Clayton House. Downtown activity can change the practical route even when the street address stays the same, so the current venue instruction and live traffic direction belong on the final chauffeur sheet.","For a Clayton House quote, list each event room only if the wedding actually uses it. Include downtown hotel names, private-home stops, and return-wave destinations, then attach the venue’s loading response. This gives the reservations team enough detail to compare one larger vehicle with coordinated smaller vehicles without assuming that a public address solves shuttle access."]}),Wa({path:"/guides/venues/fairmont-scottsdale-princess",name:"Fairmont Scottsdale Princess",address:"7575 East Princess Drive, Scottsdale, Arizona 85255",venueFacts:"The official weddings page describes indoor and outdoor wedding settings and an on-property wedding planner.",arrivalNote:"Fairmont publishes driving directions that end at the lobby entrance; because a private event space may use different instructions, confirm whether the wedding shuttle should follow that public arrival route.",hotelPlan:"On-property guests and off-property guests need separate counts, and large resort grounds make the named event space especially important on the driver sheet.",sourceLabel:"Fairmont Scottsdale Princess weddings",sourceUrl:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/weddings.html",secondarySource:{label:"Fairmont location and public arrival directions",href:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/location-contact.html"},venueSpecific:["Fairmont’s public driving directions end with the lobby entrance on the right, while its wedding page describes multiple indoor and outdoor settings. Put both the contracted event space and the venue’s private-event arrival instruction on the schedule; a lobby route is useful context, but it is not automatically the wedding shuttle route.","Separate Fairmont guests staying at the resort from riders coming from other hotels or homes before choosing capacity. On-property guests may not need a seat for every movement, while an off-property party may need a fully assigned wave. The manifest should reflect committed riders rather than the total number of rooms or reception guests.","For an on-property resort wedding, the most important hotel-wave question is which guests are truly boarding off property. Give each outside hotel an exact lobby or approved pickup instruction, then create a separate note for any Fairmont guest who needs transportation within the wedding plan. Do not mix walkers into the shuttle count simply for symmetry.","Ask the Fairmont wedding planner whether the vehicle follows the published lobby approach or a different route for the contracted setting. Record the answer with the event-space name and arrival window. If staff direct the chauffeur elsewhere on the day, that current instruction controls and the transportation lead should update waiting guests before they move.","A wedding party using a Fairmont lawn or outdoor setting may have a different cue from guests entering a ballroom or other indoor space. Keep the getting-ready location and event-space name beside each movement. That prevents the driver sheet from reducing a large resort plan to the property address and one ambiguous arrival time.","For Fairmont return waves, identify which riders remain at the resort and which leave for off-property lodging. Publish only the destinations served by each departure. The transportation lead should assemble outbound guests at the venue-approved point and call the vehicle forward when the group is complete, rather than using the public lobby as an assumed waiting area.","Use the on-property wedding planner named in Fairmont’s materials as the source for the final private-event approach. Recheck the public directions and the booked-space instruction 14 days out, then confirm them again in the final update. A resort map can orient the group, but a named current instruction is what belongs in dispatch.","A Fairmont quote request should distinguish resort guests, off-property hotel riders, wedding-party movements, and end-of-night destinations. Add the contracted indoor or outdoor setting and state whether the public lobby route has been approved for the shuttle. That detail lets the reservations team price real movements instead of assuming every guest starts outside the resort."]}),Wa({path:"/guides/venues/sanctuary-camelback-mountain",name:"Sanctuary Camelback Mountain",address:"5700 East McDonald Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official wedding site describes mountainside indoor and outdoor settings, including lawns, terraces, a ballroom, and intimate villa options.",arrivalNote:"Sanctuary publishes its McDonald Drive address but does not name a public wedding-shuttle gate; use the event team's instructions for the booked space and arrival window.",hotelPlan:"Some guests may be staying in resort casitas or villas while others arrive from Scottsdale hotels, so identify who truly needs an off-property shuttle.",sourceLabel:"Sanctuary Camelback Mountain weddings",sourceUrl:"https://www.sanctuaryaz.com/weddings",secondarySource:{label:"Sanctuary contact and address",href:"https://www.sanctuaryaz.com/contact"},venueSpecific:["Sanctuary’s wedding materials describe lawns, terraces, a ballroom, and intimate villa options at the McDonald Drive property. Use the exact contracted setting in the vehicle notes because “Sanctuary” alone does not tell the venue team which guest path or arrival instruction applies to this wedding.","Count resort guests and off-property riders separately before selecting a vehicle for Sanctuary. A couple using a villa setting may have a smaller movement than a ballroom celebration, and some guests may already be on site. Capacity planning should follow the manifest for each wave, not a broad estimate based on the venue’s range of settings.","Paradise Valley and Scottsdale hotel pickups should be grouped by readiness and destination, while anyone already at Sanctuary remains off the inbound shuttle manifest unless a movement is specifically planned. Give each hotel one approved waiting point and keep the McDonald Drive venue arrival as the final instruction, not another place for guests to negotiate where to meet.","Sanctuary publishes 5700 East McDonald Drive but no permanent public wedding-shuttle gate. Ask the event team where the assigned vehicle should unload for the booked lawn, terrace, ballroom, or villa setting. Also ask whether the return pickup uses that same point, because arrival and late-evening traffic patterns may be handled differently.","When the wedding uses more than one Sanctuary setting, write whether guests walk between them or board for another movement. Do not infer the route or distance from a resort illustration. The wedding party may need a separate cue for portraits or preparation, while general guests should receive one simple ready time and venue-approved arrival instruction.","A Sanctuary return plan should separate guests staying on property from those returning to Paradise Valley or Scottsdale lodging. The early wave can serve family or guests leaving after dinner, while the final sweep follows the contracted event end. Each wave needs its own destination list and a venue-confirmed assembly point.","At the final planning review, repeat the booked Sanctuary setting, McDonald Drive address, arrival point, return point, and resort contact. If the ceremony moves between an outdoor and indoor option, ask whether the transportation instruction changes. Record only the answer that affects vehicle movement; do not burden the chauffeur with unrelated event details.","For a Sanctuary quote, include the contracted lawn, terrace, ballroom, or villa only as the venue identifies it, plus rider counts from each hotel and the number staying on property. Note any guest who needs extra boarding time. This creates a route-based request rather than a generic resort wedding inquiry."]}),Wa({path:"/guides/venues/grand-hyatt-scottsdale-resort",name:"Grand Hyatt Scottsdale Resort",address:"7500 East Doubletree Ranch Road, Scottsdale, Arizona 85258",venueFacts:"Hyatt identifies the property as Grand Hyatt Scottsdale Resort and describes renovated ballrooms plus indoor and outdoor function space.",arrivalNote:"Hyatt publishes the Doubletree Ranch Road address but not a public wedding-shuttle gate on its event page; the booked space and arrival point should be confirmed with the resort team.",hotelPlan:"The property itself may house many guests, so separate in-resort walkers from riders coming from other hotels, homes, or the airport.",sourceLabel:"Hyatt announcement of the Grand Hyatt Scottsdale Resort name and event spaces",sourceUrl:"https://newsroom.hyatt.com/2024november11GrandHyattScottsdale",venueSpecific:["Hyatt now identifies the property as Grand Hyatt Scottsdale Resort and publishes 7500 East Doubletree Ranch Road. Use that current name on every manifest, map pin, and chauffeur note; older planning documents may still contain the former resort name, so the transportation lead should replace it before details are distributed.","Grand Hyatt lists ballrooms, lawns, gardens, and other event settings, making the contracted space essential to capacity and timing discussions. Separate guests staying at the resort from those riding in from other locations, then choose vehicles for the actual waves. The full reception attendance is not a substitute for that movement-by-movement count.","Begin hotel-wave planning by removing Grand Hyatt guests who will not ride inbound, then group off-property Scottsdale or Paradise Valley lodging by exact address and ready time. If airport luggage remains with any arriving guest, identify that movement separately. A wedding shuttle should not discover at the first pickup that a local guest wave also carries travel bags.","The Doubletree Ranch Road address routes the vehicle to Grand Hyatt, but Hyatt’s event page does not publish a wedding-shuttle gate. Ask the resort team for the approved arrival tied to the booked ballroom, lawn, or garden. Record whether the same location is used after the reception and whether a vehicle may wait nearby.","If the Grand Hyatt ceremony and reception use different settings, ask whether guests walk between them and whether the wedding party moves on a separate schedule. Keep any vehicle transfer as an explicit itinerary line with a rider count. Do not assume that every change of event space creates a transportation need or that every guest follows the wedding party.","For the return, divide guests who stay at Grand Hyatt from riders returning to other hotels, homes, or an airport-area property. A resort guest should not occupy a seat simply because their name appears on the reception list. Label each outbound wave by destination and have the transportation lead confirm who has already returned to a room.","At 14 days, verify the current Grand Hyatt name, Doubletree Ranch Road address, contracted setting, and vehicle instructions with the resort contact. Remove the former property name from guest messages unless it is needed to clarify an old document. The final update should use one naming convention so guests and chauffeurs search for the same destination.","A Grand Hyatt quote request should state how many guests stay at the resort, which off-property hotels need service, whether the ceremony and reception use separate settings, and the final return destinations. Attach the resort’s approved vehicle approach. These specifics let the reservations team evaluate the schedule without relying on the former name or a generic resort entrance."]})],nl={updatedAt:"2026-09-24",path:"/guides/scottsdale-bachelorette-weekend",title:"Scottsdale Bachelorette Party Weekend",description:"Plan a three-day Scottsdale bachelorette weekend with an Old Town crawl, published Sprinter pricing, airport transfers, and one mobile headquarters.",metaDescription:"A three-day plan: the Old Town crawl, group sizing and the nightly return",h1:"Scottsdale bachelorette party weekend: a practical 3-day itinerary",eyebrow:"Three-day Scottsdale itinerary",intro:"Scottsdale Sprinters plans a strong Scottsdale bachelorette weekend with one main plan per day, one transportation lead, and enough open time for the group to reset. This itinerary keeps Old Town stops walkable, uses a Sprinter as the mobile headquarters for longer moves, and prices the shared ride from published rates.",fleetTable:!0,itinerary:[{day:"Day 1",title:"Arrive, settle in, and start with dinner",plan:"Consolidate airport arrivals, stock the house or hotel, leave recovery time, and use one dinner reservation as the first fixed point."},{day:"Day 2",title:"Pool time, reset, and Old Town crawl",plan:"Keep the morning flexible, set one group-ready deadline, and stage the Sprinter before the first Old Town stop."},{day:"Day 3",title:"Brunch, a lighter activity, and departures",plan:"Choose one low-friction group activity, confirm luggage before pickup, and split airport waves by flight time."}],crawlStops:[{number:1,name:"A booked dinner anchor in Old Town",note:"One confirmed meal reservation before the entertainment-district portion of the night; confirm the address, time and reservation name directly with the restaurant."},{number:2,name:"The Entertainment District blocks",note:"The late venues cluster within a few blocks of Scottsdale Road and Stetson Drive; confirm current entry, cover and reservation details with each one directly."},{number:3,name:"One main celebration stop",note:"Choose a single venue for the centre of the night rather than a list, and check its current event calendar and dress guidance directly."},{number:4,name:"A quieter regrouping block",note:"The Fifth Avenue and Marshall Way shopping streets sit a short walk from the district and work as a meeting point when a line is long."},{number:5,name:"The late pickup point",note:"A lawful meeting place the chauffeur can reach, agreed before anyone leaves the last venue and sent to the whole group in writing."}],sections:[{heading:"What is the best shape for a 3-day Scottsdale bachelorette weekend?",answer:"Build the weekend around 3 anchors—arrival dinner, one main Old Town celebration, and a relaxed farewell—then protect at least 2 open blocks for pool time, getting ready, meals, and recovery, because a minute-by-minute schedule usually breaks as soon as one flight or reservation shifts.",paragraphs:["Day 1 should feel easy. Group arriving flights into a small number of airport pickup windows, give everyone time to check in, and make dinner the only hard deadline. Put the address, reservation name, ready time, and clothing plan in one shared note. Guests who land late should have a clear way to join without holding the entire group at the airport.","Day 2 carries the biggest celebration. Keep the morning optional, choose one pool or daytime reservation if the group wants it, then create a real reset window before Old Town. The transportation plan begins at the house or hotel, not at the first bar. Everyone boards together with charged phones, identification, and the items they need for the full evening.","Day 3 works best at a slower tempo. Brunch and one flexible activity give the group a final shared memory without creating another complex transfer. Organize luggage before the vehicle arrives and split airport departures by terminal timing rather than friendship groups. The person with the earliest flight should not wait through a late group brunch."]},{heading:"How does a Sprinter work as the weekend’s mobile headquarters?",answer:"A single Sprinter can serve as mobile headquarters for 8 to 16 guests by keeping the group on one departure clock, giving everyone the same pickup message, and creating a consistent regrouping point between the house, dinner, Old Town, and the final return without relying on several separate cars.",paragraphs:["“Mobile headquarters” means the transportation plan has one accountable schedule and one known vehicle; it does not mean the vehicle can wait anywhere or store unlimited belongings. The transportation lead keeps the manifest, confirms when everyone is aboard, and communicates changes to the reservations team. Guests receive the simple version: where to stand, when to be ready, and what return wave they chose.","Choose capacity from the fleet table, then discuss the real load. A nominal seat count does not describe dresses, coolers, welcome bags, airport luggage, or mobility devices. The reservations team can help check the proposed vehicle against those details. For a nightlife-only movement, a party-oriented Sprinter may fit the mood; for airport transfers, luggage can change the practical answer.","The vehicle is most valuable on the longer or less walkable legs: airport to lodging, lodging to Old Town, a planned daytime destination, and the final ride home. Inside a compact Old Town crawl, walking between confirmed nearby stops can be simpler than repeatedly loading the group. The chauffeur should use only legal, currently available loading places."]},{heading:"What does a Scottsdale Sprinter cost per person?",answer:`For 13 guests sharing the ${n["ultra-luxury-party-sprinter-scottsdale"]} for 5 billed hours, the published ${ld("ultra-luxury-party-sprinter-scottsdale")}-per-hour rate works out to about ${cd("ultra-luxury-party-sprinter-scottsdale",5,13)} per person before tax for the shared ride; the live total depends on the selected vehicle, service duration, and confirmed itinerary.`,paragraphs:["The calculation is deliberately transparent: the published hourly rate is multiplied by 5 billed hours and divided by 13 riders. If fewer people split the same vehicle, the per-person amount rises; if the group chooses a different vehicle or service window, it changes. Use the fleet table as a planning comparison, then request a quote for the actual route.","Do not compare a group vehicle with a single app estimate shown before a surge, a stop, or a post-event pickup. The useful comparison includes how many separate cars the group would need, whether everyone departs together, and who is responsible for finding missing riders. A shared hourly plan buys coordination as well as seats.","The itinerary should separate airport service from the nightlife service when the timing or luggage profile differs. A vehicle that fits the celebration may not be the best airport loadout. Send flight waves and luggage notes to the reservations team so each portion can be priced against the right vehicle rather than forcing one assumption across the entire weekend."]},{heading:"How should a practical Old Town crawl be sequenced?",answer:"Sequence the night in 3 moves—a booked dinner anchor, one main stop inside the Entertainment District, and a late pickup point the chauffeur can legally reach—then confirm reservations, dress rules, event programming, and entry conditions directly with each venue, because those conditions change without notice.",paragraphs:["The numbered route below is a planning sequence, not a promise of admission or a claim that every stop belongs in one night. A dinner reservation works as the meal anchor when booked directly. The late venues sit in the Entertainment District and are listed in Old Town Scottsdale’s official nightlife directory. No district claim or operating hours are assigned to any stop here.","Book the most important reservation first, then build around it. If the group cares about dinner or a particular evening’s programming, confirm that directly with the venue. Keep confirmation emails and the reservation name in the shared plan. A transportation booking does not create venue admission, skip a line, or override dress and identification requirements.","Designate a regrouping point before entering a loud venue. The group should know what happens if someone leaves early or cannot be reached. Do not ask a chauffeur to stop in an unapproved travel lane while the group decides. The transportation lead should call the movement only after guests are together and the driver confirms the legal pickup position."]},{heading:"How should the Old Town pickup and return be planned?",answer:"Use 2 written meeting points: a venue-confirmed arrival location and a separate late-night pickup location that the chauffeur can legally reach, then set one primary departure time plus a backup contact, because crowded streets and changing traffic controls make an improvised curbside search unreliable.",paragraphs:["Old Town is compact, but the entertainment district can be busy. The exact pickup point should be confirmed on the service day based on current traffic and venue instructions. This guide does not invent a club gate or claim a permanent shuttle lane. Guests should expect a short walk to a lawful meeting point if streets are restricted or congested.","Share a map pin only after the chauffeur or dispatch contact has confirmed it. A pin dropped by a guest from inside a building can land on an alley, patio, or wrong side of the block. The transportation lead should send the final location to the group and collect everyone there before calling the driver forward.","Choose the return rule before the night begins. If the group books one final departure, say clearly that leaving earlier requires a separate plan. If two waves are scheduled, assign riders in advance and record switches. The bride should never be the person counting heads on a crowded sidewalk while also trying to enjoy the celebration."]},{heading:"What should the group pack, assign, and confirm?",answer:"Give 1 person the master itinerary and assign 3 backups—lodging contact, reservation contact, and transportation contact—while every guest carries identification, a charged phone, the lodging address, and weather-appropriate basics, so one lost device or delayed guest does not stop the entire weekend plan.",paragraphs:["Keep the master itinerary short enough to use. It should show addresses, reservation names, ready times, departure times, and the transportation lead. Put optional activities in a separate section so guests can distinguish the fixed plan from suggestions. Avoid a long group-chat thread as the only source of truth; important information disappears quickly once travel begins.","For airport day, label bags and tell the reservations team the real luggage count. For nightlife, reduce what guests carry and confirm each venue’s current bag rules directly. Do not leave valuables or essential medication in a vehicle on the assumption that the same vehicle will remain in the same place all night.","Scottsdale conditions vary by season and time of day. Check an official forecast close to the weekend and plan water, sun protection, or a layer as appropriate. The group should also agree on a buddy system and a simple decision rule: no one changes venue alone without telling the transportation lead or their assigned buddy."]},{heading:"When should the weekend transportation be booked?",answer:"Availability varies by date and by vehicle, so no fixed lead time applies: work the manifest in 3 passes — confirm the flight waves once the group has booked flights, recheck lodging and venue details as they are fixed, then send the final passenger list 48 hours before service.",paragraphs:["Start with the pieces that are unlikely to change: travel dates, lodging, the main celebration night, estimated group size, and desired service window. The reservations team can recommend a fleet option from those facts. You do not need every brunch selected before asking, but you do need honest timing and a realistic pickup area.","Once flights are booked, collect them in a spreadsheet and group arrivals by a useful window. Confirm the exact lodging address, including unit or building instructions that the property permits you to share. Recheck every major venue reservation and current entry guidance. This is the point to decide whether one airport vehicle can serve everyone or separate waves are necessary.",`Forty-eight hours out, send a clean operational summary rather than forwarding the whole planning chat. Include named contacts, rider count, luggage note, ready times, addresses, and the confirmed Old Town meeting plan. If something changes afterward, have one person notify the reservations team and wait for acknowledgement before telling the group the plan is final. ${Rs}`]},{heading:"What are the most common bachelorette transportation questions?",answer:"Most groups ask 4 things: whether one Sprinter can cover airport and nightlife service, how per-person pricing is calculated, where an Old Town pickup can happen, and how late changes are handled; the answers below keep those decisions tied to the real manifest and confirmed itinerary.",paragraphs:[]}],faqs:[{question:"Can one vehicle handle the whole weekend?",answer:"It can cover several scheduled movements, but airport luggage, service gaps, and different group sizes may make separate bookings more practical. Share the complete itinerary with the reservations team."},{question:"Does the transportation reservation include club admission?",answer:"No. Venue reservations, admission, identification, dress rules, and event passes are separate. Confirm them directly with each official venue."},{question:"Can the group add stops during the night?",answer:"Ask the reservations team before service and route day-of requests through the transportation lead. A new stop must fit the booked time, legal access, and driver instructions."},{question:"Where does the Sprinter pick up in Old Town?",answer:"The exact lawful meeting point is confirmed for the service plan and current conditions. This guide intentionally does not promise a permanent curb or invented venue gate."}],links:[{href:"/experiences/bachelorette-party",label:"Bachelorette party transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter service"},{href:"/pricing",label:"Hourly and per-person pricing"}],sources:[{label:"Old Town Scottsdale nightlife directory",href:"https://oldtownscottsdaleaz.com/eat-drink/nightlife/"}]};function Qs(e){const t=e.article?`${e.article} ${e.name}`:e.name;return{path:e.path,updatedAt:e.updatedAt,title:e.metaTitle??`${e.name} Transportation Guide | Scottsdale Sprinters`,description:`Plan ${e.name} group transportation with the official date status, published fleet capacities, hotel pickup, arrival, and post-event pickup guidance.`,metaDescription:"Official date status, hotel pickup, venue arrival and the post-event pickup plan",h1:e.h1??`${e.name} group transportation`,eyebrow:e.dateLine,intro:`A dependable ${e.name} ride from Scottsdale Sprinters begins with the official event information, a realistic rider count, and one transportation lead. This guide uses published organizer or venue facts, leaves unannounced details unguessed, and turns the day into a written pickup, arrival, communication and return plan.`,fleetTable:!0,sections:[{heading:`When is ${t}?`,answer:e.dateAnswer,paragraphs:["Use the official source linked below as the date authority. Artist schedules, participating teams, kickoff times, venue hours, and traffic instructions may arrive later than the date itself. Do not build a pickup plan around an unofficial calendar listing. The transportation lead should recheck the organizer page at booking, again as the date approaches, and on the service day.",e.eventSpecific[0],"Publishing early matters because a large-event route needs more than a car reservation. The group may still need admission passes, lodging, a meeting point, and agreement about who rides home. An article published ahead of the event gives planners time to compare vehicle sizes, collect guest commitments, and confirm current access rules without inventing details.","When a date or time remains unannounced, the quote request can still describe the expected city, group size, hotel area, and service pattern. Mark uncertain times as planning placeholders, not confirmed instructions. The reservations team can update the service window once the official organizer publishes the missing information."]},...e.gettingThere?[e.gettingThere]:[],{heading:`Which vehicle size fits a ${e.name} group?`,answer:`For ${t}, compare the published capacity bands from ${nt[0].capacity} through ${nt[nt.length-1].capacity} passengers, then choose from the committed rider count and what the group will carry; the largest seat number is not automatically the best choice when people have permitted gear, accessibility needs, or hotel luggage.`,paragraphs:[`The fleet table uses current published information for each displayed name, maximum seated capacity, hourly rate, and minimum. A ${n["executive-sprinter-scottsdale"]} seats ${i["executive-sprinter-scottsdale"]}; a ${n["motorcoach-56"]} seats ${i["motorcoach-56"]}. Larger groups can use multiple coordinated vehicles when one vehicle does not fit the rider count or what guests will carry.`,"Count the riders for each direction. The outbound group may be larger than the return group, especially when some guests camp, stay near the venue, or leave with family. Give every return rider a specific vehicle or wave. “We will decide later” is not a useful manifest when a large event crowd is leaving at once.",e.eventSpecific[1],"Tell the reservations team about permitted personal items before choosing the vehicle. Event bag and chair rules belong to the organizer, and vehicle fit belongs to the operator. Something allowed into the venue may still consume meaningful cabin space. Keep aisles and exits clear, and never use an advertised seat count as a substitute for a real load review."]},{heading:`How should a group arrive at ${e.venue}?`,answer:`Plan 1 documented arrival route to ${e.venue}, with the chauffeur following current event staff, traffic control, and the organizer's published instructions; a saved gate name from an earlier event is not reliable enough for dispatch, so this guide uses only access details supported by an official source.`,paragraphs:[`${e.verifiedAccess} The operational plan should record the venue as ${e.venueAddress}, plus any event-specific permit, lot, or loading instruction supplied for the booked vehicle. If an organizer later publishes a different route, that current instruction replaces the general address.`,e.eventSpecific[2],"Build arrival buffer before the first activity the group cares about, not merely before the headline start. Loading riders, traffic control, security screening, and the walk from the approved unload area all take time. The vehicle cannot bypass public safety instructions, and the group should not ask to unload in a travel lane because the schedule ran tight.","Keep admission passes, identification, and allowed personal items ready before the door opens. The transportation lead counts riders as they leave and identifies the return meeting plan once more. Nobody should assume that the arrival position will remain the pickup position after the event; traffic plans can reverse or move during egress."]},{heading:`What should the ${e.name} itinerary include?`,answer:`Write 7 lines into the ${e.name} itinerary: guest ready time, vehicle departure, venue arrival target, primary contact, official address, post-event meeting instructions, and final roll time, then keep optional meals or gatherings in a separate section so riders can immediately see the commitments that affect transportation.`,paragraphs:[`${e.dayPlan} Turn that outline into clock times only after official hours or kickoff information is available. A useful schedule works backward from the desired arrival, adding expected loading and a conservative traffic allowance. Avoid publishing a universal drive time because origin, closures, day of week, and event operations all change it.`,e.eventSpecific[3],"The ready time is when guests are physically at the pickup point with everything they will take. It is not the time they begin leaving hotel rooms. The transportation lead should arrive earlier, check the manifest, and contact missing riders. Decide in advance who has authority to hold the vehicle and how long the schedule can absorb that hold.","Include one contingency sentence: if the group becomes separated, each rider follows the written meeting instruction and contacts the transportation lead. Do not create multiple competing pins during the event. A simple, approved plan is easier to execute when cellular service is busy and the surrounding streets are controlled."]},{heading:`How should pickup after ${t} work?`,answer:`Use 2 checkpoints after ${t}: the group first gathers at a pedestrian meeting place permitted by venue instructions, then the transportation lead confirms the vehicle’s active pickup point before anyone walks toward it, preventing riders from chasing a moving vehicle through controlled traffic or crowd flow.`,paragraphs:["The chauffeur may be directed away from the arrival location or held until traffic staff release a lane. That is normal large-event operations, not a reason for guests to enter a roadway. The lead stays with the group, keeps a headcount, and waits for a confirmed message about where and when to move.","Set expectations before arrival: the vehicle cannot stop wherever a phone pin lands, and an event's official traffic team controls access. Guests should wear appropriate footwear for the walk they can reasonably expect around a large venue and keep enough phone charge for post-event messages. Anyone leaving separately tells the transportation lead.",e.eventSpecific[4],"For multiple return waves, label vehicles and destinations clearly. A hotel shuttle and a local-home shuttle should not rely on guests recognizing a driver in a crowd. Use the vehicle name, lead name, and destination list. The final sweep verifies the manifest before departure rather than waiting on people who changed plans without notice."]},{heading:`How far ahead should ${e.name} transportation be reserved?`,answer:`Availability for ${t} varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and service pattern, and the reservations team confirms in writing what is open across the published capacity bands from ${nt[0].capacity} to ${nt[nt.length-1].capacity} passengers, updating it as official information is announced.`,paragraphs:["The first request needs the event, lodging or pickup area, likely passenger count, desired arrival, and return concept. A group does not need every attendee name to begin, but it should distinguish committed riders from possible riders. The reservations team can compare a single larger vehicle with several coordinated smaller options using current published capacities.","Once the group is committed, close the manifest and collect mobility needs, allowed gear, and destination choices. Confirm the official event status and make sure every rider has an admission plan independent of transportation. If the organizer has not announced an important detail, mark it open and assign one person to monitor the official source.",e.eventSpecific[5],"During the final 48 hours, verify addresses, contact numbers, service times, and current venue directions. Send one final summary to riders. If official instructions change on the day, the chauffeur follows traffic personnel and the transportation lead relays the update; the group should not treat an older screenshot as authority over current controls."]},{heading:`How is ${e.name} transportation priced per person?`,answer:`For 12 ${e.name} riders sharing the ${n["executive-sprinter-scottsdale"]} across 5 billed hours, the published ${ld("executive-sprinter-scottsdale")}-per-hour rate is about ${cd("executive-sprinter-scottsdale",5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, duration, itinerary, and confirmed service plan.`,paragraphs:["That example is arithmetic, not a flat event fare: hourly rate multiplied by billed hours, divided by riders. It gives a group a common basis for comparison while staying aligned with the published rate. If only ten people ride, divide across ten. If the group needs a larger vehicle or a longer service window, request the matching calculation.","A complete plan may include a continuous vehicle, separated inbound and outbound transfers, or several hotel waves. Each structure uses time differently. Describe the actual service pattern when asking for a quote instead of requesting “round trip” and leaving a many-hour gap unexplained. The reservations team can then price the schedule that the group expects.",e.eventSpecific[6],"Per-person math is most useful after the rider list stabilizes. Name one person to collect shares and one person to manage the manifest; they can be the same person, but neither job should fall to the chauffeur. The transportation service moves the confirmed group while the lead owns internal guest decisions."]},{heading:`What are the most common ${e.name} transportation questions?`,answer:`Most ${e.name} groups need 4 answers before booking: the official date status, the number of committed riders, the venue's current vehicle instructions, and the return meeting process; the FAQ below addresses those points without promising an unpublished time, access route, parking privilege, or gate.`,paragraphs:[]}],faqs:[...e.faqs??[],{question:`Does a transportation booking include ${e.name} admission?`,answer:"No. Admission passes, wristbands, parking credentials, and venue entry are separate. Purchase and verify them only through the event’s official channels."},{question:"Can the vehicle wait next to the venue?",answer:"Only where current event operations permit it. Staging and pickup instructions can change, so the chauffeur follows venue staff and the transportation lead shares the confirmed meeting plan."},{question:"Can a group bring chairs, coolers, or bags?",answer:"Check the organizer’s current allowed-items policy first, then tell the reservations team exactly what the group will carry so vehicle fit can be reviewed."},{question:"What if the official event time changes?",answer:"Have the transportation lead contact the reservations team promptly. A revised service window is not assumed until the change is acknowledged and the updated plan is confirmed."}],links:[...e.links,{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:[e.source,e.accessSource,...e.additionalSources??[]]}}const sl=[Qs({updatedAt:"2026-09-26",path:"/guides/country-thunder-transportation",name:"Country Thunder Arizona",titleName:"Country Thunder Arizona 2027",dateLine:"Official dates: April 8–11, 2027",dateAnswer:"Country Thunder Arizona is officially scheduled for April 8–11, 2027—4 festival days at AZ Talio Ranch in Florence—and the organizer says 2027 hours will be announced closer to the festival, so build transportation around the published dates but wait for official daily times before locking departures.",venue:"AZ Talio Ranch",venueAddress:"20585 East Water Way, Florence, Arizona 85132",verifiedAccess:"Country Thunder’s official information page publishes the ranch address, tells fans to buy parking in advance because onsite parking is limited and not guaranteed on the day, names Stagecoach Express Shuttles as its partner shuttle from Mesa and Apache Junction, and says Uber and Lyft are available in Florence, with pre-booking recommended.",dayPlan:"For a festival day, the outline is hotel pickup, comfort stop if scheduled, venue arrival, a written post-show regrouping process, and the return to the named lodging stops.",gettingThere:{heading:"Where do you park at Country Thunder Arizona, and how do rideshares and shuttles work?",answer:"Country Thunder Arizona tells fans to buy parking in advance because onsite parking at AZ Talio Ranch, 20585 E Water Way in Florence, is limited and not guaranteed on the day; its partner shuttle runs from Mesa and Apache Junction, Uber and Lyft serve Florence with pre-booking advised, and no lot allows tailgating.",paragraphs:["The festival sells its parking online ahead of time. The passes it lists include weekend day parking, a weekend overnight lot, one extra-vehicle pass per campsite, and a camper drop-off pass for an RV delivered by someone without festival admission. Accessible spaces sit at the front of the reserved parking area, across from the reserved entrance; tell the front-gate staff on arrival.","Its parking-lot rules ban tailgating in every lot, reserved, day, ADA, glamping, staff and overnight alike, and ban cooking, grills, amplified sound and drinking games there too. Only vehicles accredited for a lot may enter it, and a vehicle without the right credential can be towed. A group that planned a lot party should plan it for the drive instead.","For rideshare, the festival says Uber and Lyft are available in Florence and recommends pre-booking a ride to guarantee a driver. As of September 24, 2026, its information page names no rideshare zone at the ranch and no drop-off lane for limousines, party buses or charters, so a chauffeur unloads where festival traffic staff direct and follows any instruction the festival publishes later.","The festival’s partner shuttle, Stagecoach Express Shuttles, picks up and drops off in Mesa at 240 West Baseline Road and in Apache Junction at 185 West Apache Trail, booked by phone. It does not start in Scottsdale. From a Scottsdale hotel or home, the ranch is about 63 miles and 66 minutes from Old Town by Google Directions, without festival traffic.","With a chauffeured ride, nobody in the group buys a parking pass or drives home after the headliner. The vehicle picks everyone up at the hotel or home and unloads where staff direct, and when it is booked by the hour the same vehicle brings the group back after the last set. Each festival day is its own booking."]},source:{label:"Country Thunder Arizona official 2027 event page",href:"https://www.countrythunder.com/az"},accessSource:{label:"Country Thunder Arizona official festival information",href:"https://www.countrythunder.com/az-info"},additionalSources:[{label:"Country Thunder festival policies: bags and parking lots",href:"https://www.countrythunder.com/policies"},{label:"Country Thunder Arizona 2027 lineup page",href:"https://www.countrythunder.com/az-lineup"}],links:[{href:"/experiences/country-thunder",label:"Country Thunder transportation experience"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/party-bus-28-scottsdale",label:"28-passenger party bus"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts and festivals, 2026–27"}],faqs:[{question:"Where is Country Thunder Arizona held?",answer:"At AZ Talio Ranch, 20585 E Water Way, Florence, Arizona 85132. By Google Directions it is about 63 miles and 66 minutes from Old Town Scottsdale, and about 73 miles and 75 minutes from the Fairmont Scottsdale Princess, without festival traffic."},{question:"What are the Country Thunder Arizona 2027 dates?",answer:"Four days: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. The festival says the 2027 hours are announced closer to the festival, and its full lineup is still to come."},{question:"Who is performing at Country Thunder Arizona 2027?",answer:"The 2027 lineup is not announced yet. As of September 26, 2026, the festival’s lineup page says the full lineup is coming soon and teases a Sunday, April 11 headliner without naming the artist, and it notes that artists and schedule can change without notice."},{question:"What is Country Thunder Arizona?",answer:"A four-day country music festival with camping at AZ Talio Ranch in Florence, run by Country Thunder, which also holds festivals in Wisconsin and Saskatchewan. It runs rain or shine, and the festival guarantees admission bought only from Country Thunder or its official partner."},{question:"What time do the gates open at Country Thunder Arizona?",answer:"The 2027 hours are announced closer to the festival. Last year the concert bowl opened at 3 p.m. on Thursday, 1 p.m. on Friday and Saturday, and 1:30 p.m. on Sunday, and the front gate was open from 9 a.m. to 10 p.m.; anyone arriving after it closed could not drive onto the grounds."},{question:"Can Uber or Lyft drop off at Country Thunder Arizona?",answer:"Uber and Lyft are available in Florence, and the festival recommends pre-booking a ride to guarantee a driver. It names no rideshare zone at the ranch, so drivers follow festival traffic staff. A chauffeured ride booked by the hour covers both ways: the same vehicle takes the group there and brings it home."},{question:"Is there a shuttle to Country Thunder Arizona from Scottsdale?",answer:"The festival’s partner shuttle, Stagecoach Express Shuttles, runs from Mesa and Apache Junction, not Scottsdale. From Scottsdale, a private ride starts at your hotel or home and unloads where festival traffic staff direct; booked by the hour, it brings the group back after the last set."},{question:"Can single-day guests use the campgrounds?",answer:"No. The festival says the campgrounds need full-event admission and that single-day holders do not have access. A campsite is sold for the whole festival, never by the night, and comes with two weekend general admission passes and parking for one vehicle."},{question:"Can we book a ride for all four days?",answer:"Yes, one booking per day. Each festival day is its own ride, with its own pickup time, riders and return, so a group can book Thursday and Saturday only, or all four. The price of each day is shown before you pay."},{question:"Is tailgating allowed at Country Thunder Arizona?",answer:"No. The festival’s parking-lot rules ban tailgating in every lot, along with cooking, grills, amplified sound and drinking games. The pre-party can ride with you instead: our party vehicles carry wet bars, lounge lighting and big sound for the hour-long drive to Florence."},{question:"What can we bring into the concert bowl?",answer:"Clear bags up to 14 by 14 inches, a one-gallon freezer bag or a small clutch; soft lawn chairs without canopies; and one unopened bottle of water per person. Outside food and drinks, coolers, backpacks, glass and umbrellas stay out, and the festival is cashless."}],eventSpecific:["Country Thunder publishes four festival dates but says the 2027 hours will be announced closer to the event. Keep each daily departure in draft until those hours appear, and do not assume that one day’s timing applies to the next. The transportation lead should recheck the Arizona event page for every day the group plans to attend.","A Country Thunder group may carry only items allowed by the festival: into the concert bowl, clear bags up to 14 by 14 inches, soft lawn chairs without canopies and one sealed bottle of water per person, with coolers, backpacks and outside food left behind. Anything the group brings still consumes vehicle space, so count it before selecting from the published capacities. A vehicle that fits riders for a Scottsdale night out may need a different load review for a camping weekend in Florence.","The official destination is AZ Talio Ranch at 20585 East Water Way in Florence, and the festival warns that onsite parking is limited. That statement does not create a commercial drop-off privilege, and the festival’s lot rules admit only vehicles accredited for each lot. Send the current event instructions to the reservations team, document the assigned arrival process, and follow staff direction when the vehicle reaches the ranch.","A four-day Country Thunder plan should be written as four separate service days even if the same group attends each one: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. Rider counts, readiness, permitted items, and return choices can change by day. Label every schedule with the correct date so an unannounced daily hour can be inserted later without silently changing another day’s plan.","After each Country Thunder day, the group gathers at one agreed meeting point before anyone walks toward the vehicle, and the lead sends one confirmed message about where the chauffeur is waiting. Last year the front gate was open from 9 a.m. to 10 p.m., and the festival said anyone arriving after it closed could not drive onto the grounds, so plan the late pickup before the headliner starts, not after it ends.","At the 14-day review, check whether Country Thunder has published the 2027 daily hours, the lineup, and any updated transportation or allowed-items information. If a detail remains unannounced, leave it clearly open and tell riders when it will be checked again. The official Arizona page, not a recycled itinerary from an earlier festival, controls the planning facts.","Price each Country Thunder service window from the lodging pickup through the confirmed return plan. Florence is about 66 minutes from Old Town each way by Google Directions, so a festival day booked by the hour runs well past a short example: our ready-made festival days run 10 to 12 hours door to door. A group attending more than one day books each day on its own."]}),Qs({updatedAt:"2026-09-24",path:"/guides/fiesta-bowl-transportation",name:"Fiesta Bowl",article:"the",titleName:"Fiesta Bowl 2026-27",metaTitle:"Fiesta Bowl 2026: Parking & Parade",h1:"Fiesta Bowl 2026: parking, the parade and getting there",dateLine:"Official date: December 30, 2026",dateAnswer:"The 2026-27 Vrbo Fiesta Bowl is the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium in Glendale, so planners can anchor the service date now and should recheck the official page before confirming pickup times.",venue:"State Farm Stadium",venueAddress:"1 Cardinals Drive, Glendale, Arizona 85305",verifiedAccess:"The official 2026-27 Fiesta Bowl parking map and State Farm Stadium’s directions page both identify the Black Lot for rideshare. That published rideshare point is a planning reference, not a commercial-vehicle assignment; a charter drop-off for this game is announced closer to the date, and traffic staff remain controlling.",dayPlan:"For game day, the outline is hotel pickup, an optional pregame stop only if scheduled, arrival ahead of the 5:30 p.m. Arizona kickoff, a security and admission buffer, a postgame pedestrian regrouping point, and the confirmed vehicle pickup.",source:{label:"College Football Playoff Fiesta Bowl schedule",href:"https://collegefootballplayoff.com/sports/2021/9/7/fiesta-bowl"},accessSource:{label:"State Farm Stadium directions and parking",href:"https://www.statefarmstadium.com/plan-your-visit/directions-parking"},additionalSources:[{label:"Fiesta Sports Foundation 2026-27 CFP dates",href:"https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx"},{label:"Fiesta Sports Foundation 2026-27 parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation Fiesta Bowl Parade",href:"https://www.fiestasportsfoundation.org/sports/2019/10/22/fiesta-bowl-parade.aspx"}],links:[{href:"/services/scottsdale-executive-minibus-group-shuttle",label:"Scottsdale group shuttle service"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter rental"},{href:"/fleet/executive-mini-bus-26-scottsdale",label:"24-passenger mini bus"},{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking guide"}],faqs:[{question:"Where is the Fiesta Bowl played?",answer:"At State Farm Stadium, 1 Cardinals Drive, Glendale, Arizona 85305. The 2026-27 game is the College Football Playoff quarterfinal."},{question:"What time does the Fiesta Bowl start?",answer:"5:30 p.m. Arizona time on Wednesday, December 30, 2026, the only College Football Playoff game that day. The College Football Playoff lists the same kickoff as 7:30 p.m. Eastern, because Arizona does not observe daylight saving time."},{question:"Where is the best place to park for the Fiesta Bowl?",answer:"The official 2026-27 parking map lists the West, North and East Preferred lots; the East Lot, Lot F and oversized parking; the West Lot, W2, the Great Lawn and the Yellow Lot; and the Black and Blue Lots, on game day only. Last season the lots opened at 11:30 a.m. and closed one hour after the game; this season’s times are announced closer to the date. With a chauffeured ride, nobody in the group parks."},{question:"Where do I buy Fiesta Bowl parking?",answer:"Parking passes are sold through the Fiesta Sports Foundation’s official parking link (SeatGeek), and State Farm Stadium’s lots take cards only."},{question:"How do I buy seats for the Fiesta Bowl?",answer:"From the Fiesta Sports Foundation, which runs the bowl: call 480.350.0911 or use its official website. A ride booking does not include game admission or a parking pass."},{question:"When is the Fiesta Bowl Parade?",answer:"Saturday, January 2, 2027, starting at 10 a.m. It is the 54th annual parade, admission is free, and it comes after the bowl games, not before."},{question:"Where does the Fiesta Bowl Parade go?",answer:"It is a 1.5-mile march through Central Phoenix, starting at North Central Avenue and Montebello Avenue, Phoenix 85012. The full 2027 route, grandstands and street closures are announced closer to the date."},{question:"Can we book a ride to the Fiesta Bowl Parade?",answer:"Yes, as its own ride on Saturday morning. Your chauffeur picks the group up at the hotel or home, drops everyone near the start at North Central Avenue and Montebello Avenue where police and event staff direct, and brings the group back when you are done."}],eventSpecific:["Fiesta Sports Foundation schedules this game as the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium. The College Football Playoff lists that same kickoff as 7:30 p.m. ET, because Arizona does not observe daylight saving time. Recheck both official pages if the organizer updates event information.","A Fiesta Bowl group usually needs one count for the stadium arrival and another for the return. Remove anyone using a separate postgame plan before assigning seats, and ask about mobility devices or personal items that affect fit. The vehicle choice should follow those confirmed movements, not the number of people included in a broader game-day gathering.","The official 2026-27 parking map places rideshare on the Black Lot, and the stadium directions page also names the Black Lot south of the stadium for rideshare and family-or-friend pickup. A limo or charter drop-off for this game is announced closer to the date. Use the Black Lot as rideshare orientation until the reservations team confirms the instruction for the booked vehicle.","Build the December 30 itinerary backward from the 5:30 p.m. Arizona kickoff at 1 Cardinals Drive in Glendale. If the group also wants the parade, schedule it as its own service: Saturday, January 2, 2027, at 10 a.m., starting at Central and Montebello in Phoenix, after the game. The 2027 parade route, grandstands, and street closures are announced closer to the date.","Postgame traffic at State Farm Stadium can be directed differently from arrival, so the lead should not send the group toward the Black Lot until the active pickup instruction is confirmed. Assemble first in a safe pedestrian place permitted by venue guidance, complete the headcount, and move only after the vehicle location and route are understood.","Before the Fiesta Bowl, confirm the December 30 date, the 5:30 p.m. Arizona kickoff, hotel addresses, the rider list, and the 2026-27 parking map. During the final 48 hours, recheck the Fiesta Sports Foundation and stadium pages. Live direction from stadium staff takes precedence over a saved map. January 2 parade closures are announced closer to the date.","A Fiesta Bowl quote should state whether the vehicle remains with the group, performs separate inbound and outbound transfers, or serves more than one hotel wave. Price examples based on five hours are comparisons only; the written quote must reflect the December 30 schedule, confirmed stadium access, rider count, and actual time requested."]})],il=[nl,...ol,...sl];function hl(e){return{path:e.path,title:e.h1,metaTitle:e.title,description:e.description,intro:e.intro,metaDescription:e.metaDescription,lastUpdated:e.updatedAt??js,lastUpdatedLabel:l(e.updatedAt??js),sections:e.sections.map(t=>({question:t.heading,answer:t.answer,paragraphs:[...t.paragraphs,...t.bullets??[]]})),faqs:e.faqs,links:e.links,sources:e.sources,eyebrow:e.eyebrow,fleetRows:e.fleetTable?nt:void 0,itinerary:e.itinerary,crawlStops:e.crawlStops}}const dl=il.map(hl);function ud(e){const t=dl.find(a=>a.path===e);if(!t)throw new Error(`[guides] Missing P3 guide: ${e}`);return t}const ll=ud("/guides/fiesta-bowl-transportation"),cl=ud("/guides/country-thunder-transportation"),Xs="2026-09-24",ul="https://www.barrett-jackson.com/2027-scottsdale",pl="https://calendar.westworldaz.com/scottsdaleaz_westworld/260203141",Fo={collectors:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-sprinter-scottsdale","executive-luxury-bus-29-scottsdale","executive-mini-bus-26-scottsdale","party-bus-28-scottsdale"]},fl=[...Fo.collectors,...Fo.crews,...Fo.corporate].filter(ae),pd=fl.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),Bt="executive-sprinter-scottsdale",Ae="maybach-jet-sprinter-scottsdale",Qr="motorcoach-56",ei="ultra-luxury-party-sprinter-scottsdale",gr="maybach-shuttle-sprinter-8",yr="premium-suv-scottsdale",ml="limo-sprinter-13-scottsdale",gl="limo-sprinter-16-scottsdale",yl="executive-luxury-bus-29-scottsdale",bl="executive-mini-bus-26-scottsdale",wl="party-bus-28-scottsdale",vl=Math.max(...pd.map(e=>e.capacity)),fd="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.";function Mo(e){return h(r[e].hourlyRateCents)}function kl(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function it(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Sl=[{label:"Barrett-Jackson 2027 Scottsdale official event page",href:ul},{label:"City of Scottsdale WestWorld calendar, Barrett-Jackson 2027",href:pl}],Al=[it("When is Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale runs Saturday, January 23 through Sunday, January 31, 2027, which is 9 public days at WestWorld of Scottsdale, with gates, food courts and sponsor displays open from 8:00 a.m. until auction close, plus an invitation-only Opening Night Gala on Friday, January 22, 2027, from 7:00 to 10:00 p.m.","Use the Barrett-Jackson 2027 Scottsdale page as the date authority. The City of Scottsdale WestWorld calendar lists the same Saturday, January 23 through Sunday, January 31 window. The city calendar shows a 10:00 a.m. start; the organizer’s own schedule says gates, food courts and sponsor displays open at 8:00 a.m. until auction close every day of those 9 days. Plan departures from the organizer’s 8:00 a.m. gate time, and recheck that page before the service day.","The Opening Night Gala is Friday, January 22, 2027, from 7:00 to 10:00 p.m., by invitation only in the Auction Arena. It is not a public gate day. A group attending the gala needs its own invitation and a separate service window from the public days that start the next morning. Do not treat January 22 as a day the general-admission crowd can enter.","The organizer says 2027 is 9 days of live auction action, with over 2,000 collector vehicles on display, an exhibitor marketplace, thrill rides and more. Daily auction close times, and which days the docket runs, are announced closer to the date. The venue map, travel notes, featured list and sponsors tab are also announced closer to the date. Mark those as open items rather than copying a prior year’s schedule.","A quote can still name the city, the hotel area, the rider count and whether the group is attending one day or several of the 9. Unannounced close times stay placeholders until Barrett-Jackson publishes them. The reservations team updates the service window from that page, not from a recycled itinerary."),it("Which vehicle fits a Barrett-Jackson collector or hospitality group?",`Collectors and VIP groups lead with the ${n[Ae]}, which seats ${i[Ae]}, then the ${n[ei]}, the ${n[gr]} and the ${n[yr]}; friends and bidder crews ride a Limo Party Sprinter; corporate hosts and big groups take the ${n[Bt]}, the mini coach, the mini bus or the party bus.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Collectors and VIP: the ${n[Ae]}, our pick for Barrett-Jackson, seats ${i[Ae]} at ${Mo(Ae)}/hr, then the ${n[ei]}, the ${n[gr]} and the ${n[yr]}. Friends and bidder crews: the ${n[ml]} and the ${n[gl]}. Corporate hosts and big groups: the ${n[Bt]}, the ${n[yl]}, the ${n[bl]} and the ${n[wl]}.`,`A VIP party larger than the ${n[Ae]} rides in two vehicles, one booking each for the same day and times: the ${n[Ae]} with the ${n[gr]} seats ${i[Ae]+i[gr]}, and with the ${n[yr]} it seats ${i[Ae]+i[yr]}. The largest vehicle in the table seats ${vl}; for a bigger party the reservations team quotes two or more vehicles together.`,"Count riders for each direction. A morning arrival at the 8:00 a.m. gate and an evening return after auction close are often different lists. Someone who leaves with another host, or who stays for a later lot, should come off the return manifest before seats are assigned. “We will decide at the arena” is not a useful count when the grounds are releasing traffic.","Tell the reservations team which group is riding, collectors and VIP, a bidder crew or a corporate host party, so the written quote starts from that group’s vehicles.","Tell the reservations team what the group will carry before the vehicle is chosen. The organizer checks every bag and screens guests. A clear bag that the gate allows can still take a seat or an aisle. Seat counts are seated capacities, not a promise that coolers, display materials or extra coats will fit. Coolers are prohibited on the grounds."),it("How does parking work at Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale 2027 has plenty of complimentary public parking at WestWorld of Scottsdale, 16601 North Pima Road, with shuttles to and from the main gate and valet for a fee; rideshares use the McDowell Mountain Ranch Road lot, and with a chauffeured ride nobody in the group drives or parks: the chauffeur unloads where event staff direct.","Barrett-Jackson publishes plenty of complimentary public parking. Follow the road signs to parking. Shuttles run to and from the Scottsdale auction’s main gate. Valet parking is available for a fee. That is the official parking plan: complimentary public parking with shuttles, plus paid valet. It is not a statement that a booked commercial vehicle may unload at the arena door.","Rideshare drop-off and pick-up use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road. Follow the signs to the rideshare area. That lot is the published rideshare point. It is not, by itself, a commercial-vehicle privilege. A chauffeured coach or Sprinter still needs the current event instruction, which for a limo, charter or commercial drop-off is announced closer to the date.","No city traffic plan or Pima Road closure list for 2027 is published yet. Those controls are announced closer to the date. Until then the address is the routing anchor: 16601 North Pima Road, Scottsdale, AZ 85260. If Barrett-Jackson or the city later publishes a credential, a lot or a loading lane, that current instruction replaces this general address for the booked vehicle.","Build the buffer before the group wants to be inside, not merely before the property line. Gates open at 8:00 a.m. Loading, the approach, security screening and the walk from the authorized unload point all take time. The vehicle cannot bypass traffic staff, and the group should not ask to unload in a travel lane because the schedule ran tight."),it("What should the Barrett-Jackson day plan include?","Write 7 lines into the Barrett-Jackson day plan: guest ready time, vehicle departure, the 8:00 a.m. gate target, a primary contact, the WestWorld address, the return meeting rule, and a final roll time, and keep meals or client entertainment on separate lines so riders can see what actually moves the vehicle.","A public day runs from the 8:00 a.m. gate until auction close. Auction close itself is announced closer to the date, so the return clock stays a placeholder until the organizer publishes that day’s end. Work backward from the arrival the group wants, add loading time, and do not print one drive time for every Scottsdale hotel. Origin, day of week and event operations all change it.","The ready time is when guests are at the pickup point with tickets, identification and the bag they will carry through screening. It is not the moment they start getting dressed. The transportation lead arrives earlier, checks the manifest and calls anyone missing. Decide in advance who may hold the vehicle and for how long.","Most of the site is climate-controlled. The Performance Track thrill rides and hot laps are outdoors, for ages 8 and up or guests at least 48 inches tall. If the group includes children who will ride, say so on the itinerary so the return is not planned around an activity they cannot enter. General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating.","One contingency line belongs on the sheet: if the group splits, each rider follows the written meeting instruction and contacts the transportation lead. Do not create several competing pins during the auction. A single approved plan is easier to run when the grounds are busy and cellular service is uneven."),it("How should pickup after Barrett-Jackson work?","Use 2 checkpoints after Barrett-Jackson: the group gathers first at a pedestrian point the current instructions allow, then the transportation lead confirms the vehicle’s active pickup before anyone walks toward traffic, because a commercial loading lane is announced closer to the date and the arrival curb may not be the departure curb.",`What if the auction runs late? ${fd}`,"The published rideshare lot, west of Thompson Peak Parkway on McDowell Mountain Ranch Road, is the official place rideshare guests request a car. A booked Sprinter, Maybach or motorcoach follows venue staff and the instruction confirmed for that vehicle. Guests should not walk into a roadway to chase a phone pin. The lead keeps the headcount and waits for a confirmed place to move.","Set the expectation before arrival. The vehicle cannot stop wherever a pin lands, and event traffic staff control access. Comfortable shoes matter for the walk from the shuttle or the authorized curb. Anyone leaving separately tells the transportation lead so the return manifest stays accurate.","For more than one return wave, label the vehicle, the lead and the hotel. A collector group heading to one resort and a hospitality group heading to another should not rely on recognizing a driver in a crowd. The final sweep checks the manifest before the vehicle rolls, rather than waiting on people who changed plans without notice."),it("What can guests bring, and what is the gate like?","The 2027 gate allows 3 bag shapes: a clutch up to 6.5 by 4.5 inches, a clear bag up to 12 by 6 by 12 inches, or a 1-gallon clear bag, and every bag is checked while guests are screened; weapons, video cameras, skateboards, drones, coolers and animals are prohibited, with licensed service animals allowed.","One sealed water bottle under 17 ounces per person is the published drink allowance. The event is cashless except for certain food concessions and valet parking. Bring the payment method those concessions and the valet booth will take, and do not plan to pay the gate or a food stand with cash unless that stand is one of the exceptions the organizer names.","Admission is separate from transportation. General-admission tickets are sold online and at the on-site AXS box office. General admission does not guarantee a seat in the arena. Buy and verify tickets only through Barrett-Jackson’s official channels. A vehicle booking does not include a credential, a parking pass or an invitation to the January 22 gala.","If an allowed-items rule changes, the organizer’s current page replaces this summary. Send the reservations team the exact list the group will carry so vehicle fit can be reviewed against that list. Something the gate permits can still be a poor fit in the cabin."),it("How far ahead should Barrett-Jackson transportation be requested?","Availability for Barrett-Jackson varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and which of the 9 days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as Barrett-Jackson announces the remaining details closer to the date.","The first request needs the days, the lodging or pickup area, the likely passenger count, the desired arrival against the 8:00 a.m. gate, and the return concept. A group does not need every name to begin. It does need to separate committed riders from possible ones, and to say which group is riding: collectors and VIP, a bidder crew, or a corporate host party.","Once the group is committed, close the manifest and collect mobility needs and the bags that will go through screening. Confirm that every rider has an admission plan of their own. If the docket, the auction close or the commercial loading lane is still announced closer to the date, leave that line open and name one person to recheck the official page.",`During the final 48 hours, verify addresses, contact numbers and the newest Barrett-Jackson directions. Send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${u} or ${p}. An older screenshot does not outrank the current control.`),it("How is Barrett-Jackson transportation priced per person?",`For 12 Barrett-Jackson riders sharing the ${n[Bt]} across 5 billed hours, the published ${Mo(Bt)}-per-hour rate is about ${kl(Bt,5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, the duration, the itinerary and the confirmed service plan.`,"That example is arithmetic, not a flat auction fare: hourly rate multiplied by billed hours, divided by riders. If only ten people ride, divide across ten. If the group needs the motorcoach or a longer window that waits through auction close, request that calculation instead of stretching the 5-hour illustration.","A complete plan may be a continuous vehicle, separate inbound and outbound transfers, or several hotel waves across the 9 days. Each shape uses time differently. Describe the actual pattern. A many-hour gap between drop-off and pickup is not a round trip until the quote says how those hours are billed.",`The same arithmetic on the ${n[Qr]} uses its own published rate of ${Mo(Qr)}/hr and its own seated capacity of ${i[Qr]}. Per-person math is useful after the rider list settles. One person collects shares and one person owns the manifest. Neither job belongs to the chauffeur.`)],Tl=[{question:"What are the dates for Barrett-Jackson Scottsdale 2027?",answer:"Saturday, January 23 through Sunday, January 31, 2027, at WestWorld of Scottsdale: nine days of live auction action with over 2,000 collector vehicles on display. The invitation-only Opening Night Gala is the evening before, Friday, January 22."},{question:"Where is Barrett-Jackson Scottsdale held?",answer:"At WestWorld of Scottsdale, 16601 North Pima Road, Scottsdale, AZ 85260. Barrett-Jackson’s 2027 venue map is announced closer to the date."},{question:"What time does Barrett-Jackson open?",answer:"Gates, food courts and sponsor displays open at 8:00 a.m. every day from January 23 to 31 and stay open until auction close. Daily auction close times are announced closer to the date, so plan the ride home as a window rather than a fixed time."},{question:"Is parking free at Barrett-Jackson?",answer:"Yes. Barrett-Jackson publishes plenty of complimentary public parking for Scottsdale 2027: follow the road signs to parking. Shuttles run to and from the main gate, and valet parking is available for a fee."},{question:"Is there a shuttle at Barrett-Jackson?",answer:"Yes. Barrett-Jackson says shuttles run to and from the Scottsdale auction’s main gate. With a chauffeured ride nobody in the group drives or parks; the vehicle unloads where event staff direct, and a limo, charter or commercial drop-off zone is announced closer to the date."},{question:"Where do rideshares drop off at Barrett-Jackson?",answer:"Use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road and follow the signs to the rideshare area. A chauffeured commercial drop-off zone is announced closer to the date."},{question:"How do I buy Barrett-Jackson tickets?",answer:"General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating. Buy only through Barrett-Jackson’s official channels. A ride booking does not include admission, valet or an invitation to the Opening Night Gala."},{question:"What if the auction runs late?",answer:fd},{question:"What is the Barrett-Jackson Opening Night Gala?",answer:"An invitation-only evening in the Auction Arena on Friday, January 22, 2027, from 7:00 to 10:00 p.m., the night before the public auction days begin. Invited guests who want a chauffeured ride book it as its own evening service."}],md={path:"/guides/barrett-jackson-transportation",title:"Barrett-Jackson Scottsdale 2027: parking and getting there",metaTitle:"Barrett-Jackson 2027: Parking & Rides",description:"Barrett-Jackson Scottsdale 2027 runs January 23–31 at WestWorld of Scottsdale. The official dates, complimentary public parking and main-gate shuttles, valet, the rideshare lot, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official Jan 23–31 dates, free parking and shuttles, valet, or a chauffeured ride",lastUpdated:Xs,lastUpdatedLabel:l(Xs),eyebrow:"Official dates: January 23–31, 2027",intro:`A Barrett-Jackson ride from Scottsdale Sprinters starts with the official 2027 page, a realistic rider count and one transportation lead. Collectors and VIP groups lead with the ${n[Ae]}; friends and bidder crews ride a Limo Party Sprinter; corporate hosts and big groups take the ${n[Bt]}, the mini coach, the mini bus or the party bus. This guide uses only published organizer facts, leaves unannounced details for closer to the date, and turns each day into a written pickup, arrival and return plan.`,sections:Al,faqs:Tl,links:[{href:"/fleet/executive-sprinter-scottsdale",label:n[Bt]},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:n[Ae]},{href:"/fleet/motorcoach-56",label:n[Qr]},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:Sl,fleetRows:pd},Sv=[md],io="2026-09-24";function _(e,t,...a){return{question:e,answer:t,paragraphs:a}}const $l=Wd.filter(e=>ae(e)).map(e=>({slug:e}));function Ls(e,t){const a=Ld($l,{occasionClass:e,headcount:t});if(a.mismatch)throw new Error(`Venue parking guide: no ${e} unit fits ${t??"any"} riders`);const o=[a.featured,a.companion,...a.rest].flatMap(d=>d?[d.slug]:[]);if(o.length<2)throw new Error(`Venue parking guide: fewer than 2 ${e} units are listed`);return o}const pa=Ls(rd({occasion:"game day party"})),Fa=Ls(rd({occasion:"corporate outing"})),ko=Math.max(...pa.map(e=>i[e])),Ma=Ls("large_group",ko+1),te=e=>n[e],ks=e=>i[e];function Cl(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}const Pl=4;function Ro(e){return Cl(e.slice(0,Pl).map(t=>`${te(t)} up to ${ks(t)}`))}function El(e){const t=r[e],a=od({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:ks(e)},vo);return`The ${te(e)} is ${h(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${ks(e)} seats are filled.`}const gd=[pa[0],Fa[0],Ma[0]];function yd(){return gd.map(e=>({href:`/fleet/${e}`,label:te(e)}))}function bd(){const e=gd;return[`Seats come from the published fleet. For game-day groups: ${Ro(pa)}. For client outings: ${Ro(Fa)}. For more than ${ko} riders: ${Ro(Ma)}.`,`Every rate prices the whole vehicle by the hour, and here is a ${vo}-hour booking in each lead vehicle. ${e.map(El).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole outing, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead of by the hour; the written quote shows how the drive is priced."]}const Ce="https://www.mlb.com/dbacks/ballpark",Fl=[{label:"Arizona Diamondbacks — Where to Park at Chase Field",href:`${Ce}/transportation/parking`},{label:"Arizona Diamondbacks — Chase Field A-to-Z Guide",href:`${Ce}/information/guide`},{label:"Arizona Diamondbacks — Chase Field Disability Access Guide",href:`${Ce}/disability-access-guide`},{label:"Arizona Diamondbacks — Know Before You Go",href:`${Ce}/information/know-before-you-go`},{label:"Arizona Diamondbacks — Driving Directions",href:`${Ce}/transportation/driving-directions`},{label:"Arizona Diamondbacks — Additional Traffic Information",href:`${Ce}/transportation/additional-information`},{label:"Arizona Diamondbacks — Valley Metro Rail",href:`${Ce}/transportation/valley-metro-rail`},{label:"Arizona Diamondbacks — Clear Bag Policy",href:`${Ce}/information/bag-policy`},{label:"Valley Metro — Destinations",href:"https://www.valleymetro.org/how-to-ride/destinations"},{label:"City of Phoenix — ParkPHX downtown parking tool",href:"https://www.phoenix.gov/newsroom/convention-center-news/3371.html"},{label:"Arizona Diamondbacks — 2027 Regular Season Schedule",href:"https://www.mlb.com/dbacks/schedule/2027-03"},{label:"MLB.com — MLB releases 2027 regular-season schedule",href:"https://www.mlb.com/dbacks/news/mlb-2027-schedule-released"},{label:"Arizona Diamondbacks — Chase Field Events",href:`${Ce}/events`},{label:"Arizona Diamondbacks — The Hondo Rodeo Fest at Chase Field",href:`${Ce}/events/upcoming/hondo-rodeo-fest`},{label:"MLB.com — Commissioner Rob Manfred on initial CBA proposals",href:"https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals"}],Va=["January","February","March","April","May","June","July","August","September","October","November","December"],Ml={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function xo(e){const t=ie(e);return`${Ml[Ns(e)]}, ${Va[t.month]} ${t.day}, ${t.year}`}function Rl(e,t){const a=ie(e),o=ie(t);return e===t?`${Va[a.month]} ${a.day}`:a.month===o.month?`${Va[a.month]} ${a.day}–${o.day}`:`${Va[a.month]} ${a.day} – ${Va[o.month]} ${o.day}`}function ar(e){return e.label.replace(/^.*\bvs\. /,"")}function xl(e){const t=[],a=o=>{const d=ie(o);return Date.UTC(d.year,d.month,d.day)/864e5};for(const o of e){const d=t[t.length-1];d&&a(o.date)-a(d.last)<=2?(d.last=o.date,d.visitors.includes(ar(o))||d.visitors.push(ar(o))):t.push({first:o.date,last:o.date,visitors:[ar(o)]})}return t}function Dl(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}function Il(){const e=Is({items:Ud}),t=e[0],a=e[e.length-1],o=e.filter(D=>D.startsAt),d=o.length===e.length?"each with its first-pitch time below":o.length>0?"with first-pitch times announced for some of them so far":"and the team has not announced first-pitch times yet",z=xl(e).map(D=>`${Rl(D.first,D.last)} (${Dl(D.visitors)})`),he=ie(t.date).year;return _("When are the D-backs home games and concerts at Chase Field?",`The Arizona Diamondbacks play ${e.length} home games at Chase Field in ${he}, from the home opener against the ${ar(t)} on ${xo(t.date)} to the last home game against the ${ar(a)} on ${xo(a.date)}, ${d}.`,`The home stands, in order: ${z.join("; ")}. Opening Day, Thursday, March 25, ${he}, is on the road in San Diego, so the first game at Chase Field is the home opener.`,o.length>0?`Announced first pitches, in Arizona time: ${o.map(D=>`${xo(D.date)}, ${D.label}, ${fa(D.startsAt)}`).join("; ")}. The rest are added here as the Diamondbacks announce them. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.`:"The Diamondbacks announce first-pitch times closer to the season, and they are added here as they are. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.",`The one concert the Diamondbacks list for Chase Field as of ${l(Bd)} is the Hondo Rodeo Fest, November 13–15, 2026: each night a full rodeo, then a full-length concert, with Tim McGraw and Miranda Lambert on Friday, Blake Shelton and Turnpike Troubadours on Saturday, and Parker McCollum and Lynyrd Skynyrd on Sunday. Shows for ${he} are announced by the ballpark closer to the date.`,"One caveat for the season: Major League Baseball’s labor agreement expires on December 1, 2026. If a new agreement is not in place in time, games can move, and this list follows the official schedule as MLB and the Diamondbacks publish it.")}const Nl=[_("Where do you park for Chase Field?","Chase Field has an attached 1,500-car garage just south of the ballpark on 4th Street that works first come, first served, and the Diamondbacks also offer pre-booked spaces through ParkWhiz, their preferred parking partner, so you can hold a spot before driving to the game.","The ballpark is at 401 East Jefferson Street in downtown Phoenix, bounded by 7th Street on the east, 4th Street on the west, Jefferson Street on the north and the Southern Pacific Railroad tracks on the south. The Diamondbacks’ traffic advice is to park in the same quadrant you drive in from. Arriving from the south, for example, means parking between 3rd Avenue and 9th Street, from Lincoln Street to Jefferson Street.","Payment is not the same everywhere. The Diamondbacks warn that some garages and lots around Chase Field take only credit cards while others take only cash, so carry both unless the space is prepaid. The City of Phoenix’s ParkPHX tool lists every public downtown parking facility in one place, with height limits, accessible spaces and reservations at participating facilities.","Downtown parking is not one system. The City of Phoenix runs its own garages through the Phoenix Convention Center, and the Diamondbacks’ pre-booking runs through ParkWhiz, so rates and payment rules differ by facility. Book or choose the space before you leave, not at the last light before the ballpark."),_("What should you know about the Chase Field Garage?","The Chase Field Garage is attached to the ballpark just south of it on 4th Street, holds 1,500 cars, takes high-profile vehicles at every entrance, sets aside 31 accessible spaces, and has its own entrance on Level 3 for Suite and 200-level seats, with accessible turnstiles.","All of its parking, the accessible spaces included, is first come, first served. When demand is high, the Diamondbacks say some garages accept only special parking passes, so a driver without one may need another garage. A sign at the booth shows when accessible parking in the Chase Field or Jefferson Street garage is full, before you pull in.","The Jefferson Street Garage is the second garage the team names. Both garages have bicycle racks at street level, which the Diamondbacks list among the places to lock a bike, because bicycles are not allowed inside the ballpark.","If the plan depends on the attached garage, pre-book or arrive early. The City of Phoenix, which runs the city-owned downtown garages, says spaces are in high demand during peak events."),_("Where is the Chase Field rideshare drop-off and pickup?","The Diamondbacks publish 2 rideshare points for pickup and drop-off, 5th Street north of Washington Street and Jackson Street east of 9th Street, plus a staffed drop-off on the south side of Jefferson Street just west of 7th Street, near Gate K, listed in the ballpark’s accessibility guide.","One rideshare point is north of the ballpark, past Washington Street; the other is east of it, beyond 9th Street on Jackson Street. Pick the one on the side you are heading home from and agree on it before the game. A group that splits between the two points is waiting in two places.","The Jefferson Street drop-off is staffed and has shaded benches for guests waiting on a ride. The driver who drops a guest there should ask for a Pick-Up Pass, which carries a map and directions back to the same spot after the game. Hold it up when traffic control detours you, so staff can direct you back to that lot.","None of these points is reserved for chauffeured vehicles: the Diamondbacks publish no separate limo or charter zone. A booked vehicle works from the published points and the instruction confirmed for the booking. The team also warns that traffic around the ballpark can be rerouted as conditions dictate, as it does for southbound 3rd Street at Washington Street."),_("Can you take light rail to Chase Field?","Yes, Valley Metro’s A line stops at 2 stations near the ballpark, 3rd Street and Washington and 3rd Street and Jefferson, with trains every 15 to 20 minutes, and the Diamondbacks list 13 light rail Park-and-Ride locations for fans who drive part of the way.","Buy the fare at any station with cash, credit or debit, or load the Valley Metro app or a Copper card before the game. The Diamondbacks suggest paying in advance to skip the lines after the game, and a daily fare cap means you stop paying once you reach it.","Valley Metro also lists 2 bus connections for Chase Field: Route 1 on Washington Street and Route 7 on 7th Street. The Diamondbacks’ Park-and-Ride list runs from 19th Avenue and Dunlap to Gilbert Road and Main Street, and the Valley Metro app plans the trip from any of them.","Rail suits a couple or a small party staying near a station. A larger group coming from Scottsdale resorts has more steps: getting everyone to a Park-and-Ride, onto one train and back again after the final out."),_("How much time and hassle does parking at Chase Field add?","Driving yourself adds 3 jobs to the game: getting a space before the garage or lot fills, paying the way that facility accepts, and leaving by the Diamondbacks’ quadrant exit routes after the final out, alongside everyone else leaving the ballpark at the same time.","Arrival comes first. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, and the city says downtown garages are in high demand during peak events. Pre-booking through ParkWhiz or ParkPHX removes the search, not the drive.","Then comes the exit. The Diamondbacks route traffic by quadrant after the game. From the southeast quadrant, south of Jefferson and east of 4th Street, drivers go south to Lincoln Street and then east to 7th Street. From the southwest quadrant they go south to Lincoln, which becomes Grant, and west to 7th Avenue. North of Washington, 3rd and 7th Avenues lead to the freeways.","The drive in has its own warnings. From north central Phoenix the team calls 7th Street the least preferred route because of heavy use, and it calls the 3rd Street HOV exit the least preferred during arrival. None of it is hard, but all of it falls on whoever drives, who also has to stay fit to drive home."),_("Why does a chauffeured drop-off beat parking at Chase Field?","A chauffeured drop-off removes 3 costs of driving: the group steps out at the drop-off point confirmed for the booking instead of walking in from wherever a space was found, nobody sits in a garage exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It is not a way around traffic control. After the game every vehicle, ours included, moves with the downtown traffic plan, and the chauffeur meets the group at the agreed point once it is reachable. What changes is who does the work: the chauffeur handles the route in, the drop-off, the timing of the pickup and the route out.","One vehicle also keeps a group together. Separate cars mean separate garages, separate exits and separate arrival times. A Sprinter or bus arrives with everyone at once, which matters when the plan includes dinner or a hotel pickup before first pitch.","The trade-off is timing. A pickup runs on the traffic plan and the chauffeur’s approach, not on the minute you walk out, so agree on the pickup point in advance and message the chauffeur once the whole group is together."),_("Which vehicle fits a Chase Field group, and what does it cost?",`Match the vehicle to the group: game-day friends start with the ${te(pa[0])} or the ${te(pa[1])}, a client outing starts with the ${te(Fa[0])} or the ${te(Fa[1])}, and a group larger than ${ko} moves up to the ${te(Ma[0])} or the ${te(Ma[1])}.`,...bd()),_("How should a group plan the Chase Field arrival and pickup?","Plan 4 things before leaving the hotel: an arrival inside the gate window, which opens 90 minutes before first pitch Sunday through Friday and 2 hours before on Saturday, one agreed pickup point, one person who messages the chauffeur, and bags that pass the clear bag policy.","The clear bag policy decides what leaves the vehicle. It allows one clear bag up to 12 by 6 by 12 inches or a one-gallon clear bag, plus a small clutch up to 4.5 by 6.5 inches, and no backpacks. A group that is dropped off has no car in the garage to leave a bag in, so settle bags at the hotel. The Diamondbacks’ locker partner, Mobile Locker Company, stores non-approved bags for a fee.","For the return, choose the rideshare point on the side you will leave from, or the Jefferson Street drop-off when a guest needs the accessible entrance, and share it with the whole group before first pitch. When the game ends, gather first, then message the chauffeur once with the group count, rather than having several people send pins.",`Guests who have difficulty walking to their seats can ask any Chase Field staff member for a complimentary wheelchair escort from the gates or drop-off areas to their seats; the Diamondbacks say no advance request is needed. For a change of plan on the day, call the reservations team at ${u} or email ${p}.`),_("What is the Chase Field bag policy?","Chase Field allows one clear bag up to 12 by 6 by 12 inches or a one-gallon clear bag, plus a small clutch up to 4.5 by 6.5 inches, and no backpacks, so a purse that is not clear gets in only at clutch size and most groups carry one clear bag each.","The rule is the Diamondbacks’ clear bag policy. Bags that do not pass can be stored for a fee with the team’s locker partner, Mobile Locker Company, but a group that is dropped off has no car in a garage to leave anything in, so settle bags at the hotel before pickup.","Concerts and other events at the ballpark can set their own entry rules; check the event’s page before the day."),Il()],Wl=[{question:"How much is parking at Chase Field?",answer:"The Diamondbacks do not publish one parking price. Garages and lots around the ballpark set their own rates, and some take only cards while others take only cash. To see a price before you go, pre-book through ParkWhiz, the team’s preferred parking partner, or compare downtown garages on the City of Phoenix’s ParkPHX."},{question:"Where is the best place to park for Chase Field?",answer:"The Chase Field Garage is attached to the ballpark, just south of it on 4th Street, with 1,500 spaces on a first come, first served basis. Otherwise the Diamondbacks advise parking in the same quadrant you drive in from, and pre-booking through ParkWhiz holds a space before you leave."},{question:"Is there free parking near Chase Field?",answer:"The Diamondbacks publish no free parking. Their alternative to a garage is light rail: they list 13 Park-and-Ride locations, and trains stop at 3rd Street and Washington or 3rd Street and Jefferson, within walking distance of the ballpark."},{question:"Where is the rideshare pickup at Chase Field?",answer:"At 5th Street north of Washington Street, or Jackson Street east of 9th Street. Agree on one with your group before the game."},{question:"Where is accessible parking and drop-off at Chase Field?",answer:"The attached garage has 31 spaces for a valid disabled plate or placard, first come, first served. The staffed drop-off is on the south side of Jefferson Street, just west of 7th Street, near Gate K. Ask for a Pick-Up Pass to get back to it after the game."},{question:"What time do Chase Field gates open?",answer:"90 minutes before first pitch Sunday through Friday, and 2 hours before first pitch on Saturday. The Diamondbacks post special gate times for some dates in their A-to-Z guide."},{question:"What bags are allowed at Chase Field?",answer:"One clear bag up to 12 by 6 by 12 inches or a one-gallon clear bag, plus a small clutch up to 4.5 by 6.5 inches. Backpacks are not allowed."},{question:"Can a chauffeured Sprinter drop our group at Chase Field?",answer:"Yes, at a point the live traffic plan allows. The Diamondbacks publish two rideshare points and a staffed drop-off on Jefferson Street but no separate limo or charter zone, so the chauffeur confirms the drop-off for your booking and vehicle."}],Ll={path:"/guides/venues/chase-field",title:"Chase Field Parking Guide: Garages, Rideshare & Drop-Off",metaTitle:"Chase Field Parking & Drop-Off Guide",description:"Where to park for Chase Field: the attached 1,500-car garage, ParkWhiz pre-booking, the two rideshare points, light rail stations and gate times, and how a chauffeured group drop-off compares.",metaDescription:"The 1,500-car garage, ParkWhiz pre-booking, light rail stops and gate times",lastUpdated:io,lastUpdatedLabel:l(io),intro:"Scottsdale Sprinters’ short answer on Chase Field parking: use the attached 1,500-car Chase Field Garage on 4th Street, which is first come, first served, or pre-book a nearby space through ParkWhiz, the Diamondbacks’ preferred parking partner, and carry a card and cash because some lots take only one. Rideshare pickups use 5th Street north of Washington Street or Jackson Street east of 9th Street, and light rail stops at 3rd Street and Washington or 3rd Street and Jefferson. For a group, one chauffeured vehicle replaces the garage, the payment and the drive out after the final out.",sections:Nl,faqs:Wl,links:[...yd(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:Fl},ht="https://www.statefarmstadium.com",Ol=[{label:"State Farm Stadium — Directions and Parking",href:`${ht}/plan-your-visit/directions-parking`},{label:"State Farm Stadium — 2025 Cardinals parking map",href:`${ht}/assets/img/2025-Cardinals-Parking-Map-db3cd0d2f1.png`},{label:"State Farm Stadium — 2025 event parking map (concerts, soccer, dirt shows)",href:`${ht}/assets/img/2025-Stadium-Event-Parking-Map-fb2439fd59.png`},{label:"State Farm Stadium — A-Z Guide",href:`${ht}/a-z-guide`},{label:"State Farm Stadium — ADA and Accessibility",href:`${ht}/ada-accessibility`},{label:"State Farm Stadium — Safety and Clear Bag Policy",href:`${ht}/clear-bag-policy`},{label:"Fiesta Sports Foundation — 2026-27 Vrbo Fiesta Bowl parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation — Vrbo Fiesta Bowl A-Z Guide",href:"https://www.fiestasportsfoundation.org/sports/2019/12/6/vrbo-fiesta-bowl-a-z-guide.aspx"},{label:"Valley Metro — West Valley destinations",href:"https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley"},{label:"State Farm Stadium — Upcoming events",href:`${ht}/events`},{label:"State Farm Stadium — Harry Styles: Together, Together Tour 2027",href:`${ht}/events/detail/tgtgtour`}],wd=["January","February","March","April","May","June","July","August","September","October","November","December"],_l={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function Pa(e){const t=ie(e);return`${wd[t.month]} ${t.day}, ${t.year}`}function Ss(e){if(!e.orDate)return`${_l[Ns(e.date)]}, ${Pa(e.date)}`;const t=ie(e.date),a=ie(e.orDate);return t.month===a.month&&t.year===a.year?`${wd[t.month]} ${t.day} or ${a.day}, ${a.year}`:`${Pa(e.date)} or ${Pa(e.orDate)}`}function ti(e,t){if(t.length===1)return`${e} on ${Ss(t[0]).replace(/^\w+, /,"")}`;if(t.length===2&&ie(t[0].date).year===ie(t[1].date).year){const[d,z]=t.map(he=>Pa(he.date));return`${e} on ${d.replace(/, \d{4}$/,"")} and ${z}`}const a=t[t.length-1],o=a.orDate?Ss(a):Pa(a.date);return`${t.length} ${e} from ${Pa(t[0].date)} to ${o}`}function ai(e){return`${Ss(e)}, ${e.label}, ${Vd(e).replace(/^Day and /,"day and ")}`}function Gl(){const e=Is({items:sd}),t=Hd.map(D=>({series:D,items:e.filter(Eo=>Eo.series===D.id)})).filter(D=>D.items.length>0),[a,...o]=t,d=zd({items:e}),z=o.map(({series:D,items:Eo})=>ti(D.article?`${D.article} ${D.label}`:D.label,Eo)),he=z.length>1?`${z.slice(0,-1).join(", ")} and ${z[z.length-1]}`:z.join("");return _("When are the Cardinals home games and concerts at State Farm Stadium?",`Our ${ie(d.start).year}-${String(ie(d.end??d.start).year).slice(2)} date list for State Farm Stadium has ${ti(a.series.label,a.items)}${he?`, plus ${he}`:""}, each with its kickoff or show time below.`,`${a.series.label}, in Arizona time: ${a.items.map(ai).join("; ")}.`,...o.length?[`Also at the stadium: ${o.flatMap(({items:D})=>D.map(ai)).join("; ")}.`]:[],`These dates and times are as State Farm Stadium and the Arizona Cardinals listed them on ${l(qd)}. Start times can change, so check the event’s own page before the day. Give the reservations team your date when you book, and the chauffeur plans the pickup around that start: on Cardinals game days the lots open 4 hours before kickoff, and the gates open 2 hours before kickoff for NFL games.`)}const Ul=[_("Where do you park at State Farm Stadium?","State Farm Stadium recommends buying parking in advance through SeatGeek and describes event-day parking in 2 colors, red Preferred Parking entered only at Maryland Avenue and 95th Avenue and blue General Parking, where staff fill lots by capacity and traffic flow, and every parking area takes credit cards only.","On the stadium’s 2025 Cardinals parking map, the red Preferred lots, West Preferred and North Preferred, sit beside the stadium, and East Preferred is marked as its own lot on the east side. For the red lots, leave Loop 101 at Cardinals Way when coming from the south. From the north, leave at Glendale Avenue, head west to 99th Avenue and then east on Maryland Avenue. The stadium suggests searching Red Lot - State Farm Stadium on Waze.","General Parking is reached from Glendale Avenue or Cardinals Way off Loop 101, or from 91st and 99th Avenues. You do not pick the lot: parking staff and Glendale police direct each car to the closest lot with room, so follow the message boards and their instructions.","On Cardinals game days the lots open 4 hours before kickoff. Parking in Sportsman’s Park, the lots around the stadium, serves pre-sold permit holders and single-game visitors, and the Black Lot is set aside for same-day parking without a pre-sold permit. Other events set their own hours, so check that event’s page."),_("Which lots are on the State Farm Stadium parking map?","The stadium’s 2025 Cardinals parking map names its lots by area and color, among them West Preferred, North Preferred, East Preferred, West, Great Lawn, East, Lot F, Oversized, Yellow, Blue, Pink and the Black lot, and it prints exit routes to Northern Avenue and Indian School Road.","Exits depend on where you came from. Guests in the Pink, Blue, Yellow, Grey and Green lots who arrived from the north leave by Northern Avenue, and guests in the Green and Grey lots who arrived from the south leave by Indian School Road. Southbound Loop 101 drivers heading for the Black lot follow its own route, entering from Camelback Road onto Montebello Avenue.","RVs and other oversized vehicles park only in the designated oversized lot, on event days only, and never overnight. On Cardinals game days that is Lot F. It opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass, takes one vehicle per space and fits vehicles up to 45 feet.","Some events publish a map of their own. The 2026-27 Vrbo Fiesta Bowl map labels the Black and Blue lots gameday only and shows a West Bus area; our Fiesta Bowl guide covers that game’s parking and transportation."),_("Where is the State Farm Stadium rideshare drop-off and pickup?","Rideshare drop-off and pickup, and drop-offs by family or friends, all use the Black Lot south of the stadium across Cardinals Way, and on Cardinals game days the stadium’s 2025 map marks that rideshare lane westbound only, with the eastbound lane of Cardinals Way closed.","The stadium asks guests to check the event’s own page for updates. The Fiesta Bowl’s guide for last season’s game told guests to walk back to the Black Lot after the game, request the ride there and meet the car in the lot. Build that walk into the plan, and remember that every rideshare guest is using the same point.","No limo or charter lane is published. The Black Lot is the stadium’s named point for drop-off and pickup, so it is the planning anchor for a chauffeured group. The exact spot for your vehicle, and especially for a bus, comes from the event’s traffic plan and the instruction confirmed for the booking.","Guests with mobility needs have another option. Every Sportsman’s Park lot has ADA spaces, and a courtesy cart runs from designated ADA parking to the plaza security checkpoints. It runs from 3 hours before kickoff to 1 hour after on Cardinals days, and from 2 hours before major events to 1 hour after."),_("Can you get to State Farm Stadium without driving?","Valley Metro lists 1 connection for the Westgate Entertainment District beside the stadium, bus Route 70 on Glendale Avenue, and no light rail, so without your own car the practical options are rideshare to the Black Lot, a taxi or a booked vehicle.","The Fiesta Bowl’s guide also points to a bus stop at Glendale Avenue and 95th Avenue and to Valley Metro’s schedules. Check the current Route 70 timetable for your date before relying on it for the ride home.","Parking in the neighborhoods is not an option either. The same guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets, and that police do not let event traffic reach the stadium through local neighborhoods, so use the arterial streets.","The stadium’s own A-Z guide is direct about the ride home: never drink and drive, and use a designated driver, a rideshare service or a taxi. A booked vehicle follows that advice for a whole group at once."),_("What are the State Farm Stadium tailgating rules?","Tailgating is allowed in the carparks once they open, 4 hours before kickoff on Cardinals game days, with these rules: stay in 1 stall, keep the tailgate behind your vehicle, weight tents above ground, do not save spaces, arrive together, and pack up before carparks close 1 hour after the event.","Keep equipment out of neighboring stalls, walkways and aisles, and use above-ground weights rather than stakes for tents. Saving a space for friends who come later is not allowed: a group that wants to tailgate together has to arrive together.","On Cardinals game days the team adds its own guidelines, and post-game tailgating is prohibited. Events such as the Fiesta Bowl publish their own rules for game day, so read the current version for the date you are going.","Tailgating is built around a parked vehicle, one stall and the space behind it. A group arriving by drop-off has no stall. If the plan includes a tailgate, tell the reservations team, because the vehicle then has to stay parked, which needs its own parking arrangement and, for a bus, the oversized-lot rule above."),_("How much time and hassle does parking at State Farm Stadium add?","On a Cardinals game day, the stadium’s map encourages fans to arrive within the first 2 hours after the lots open, which is 4 to 2 hours before kickoff, then staff direct each car to a lot with room, parking is card-only, and the map sets exit routes by lot after the game.","Arriving early is the stadium’s advice, not a rule, but the gates open 2 hours before kickoff for NFL games. A car that arrives when the lots open therefore waits about 2 hours before anyone can go in.","After the game, carparks close 1 hour after the event, and the 2025 Cardinals map sends drivers out by Northern Avenue or Indian School Road depending on the lot and the direction they came from. On game day, dial 511 and press star 7 for Cardinals traffic information from the Arizona Department of Transportation.","All of that falls on whoever drives, who also has to stay fit to drive home after the game."),_("Why does a chauffeured drop-off beat parking at State Farm Stadium?","A chauffeured drop-off removes 3 parts of the day: the group steps out at the Black Lot or the point confirmed for the booking instead of walking from an assigned lot, nobody waits in a lot exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It does not skip traffic. Every vehicle leaving the stadium, ours included, moves with the event traffic plan, and the chauffeur meets the group at the agreed point when the plan allows. The difference is that the group walks to one meeting point and rides home, instead of walking to a lot, finding the car and joining the exit.","It also changes the timing. A group that is dropped off does not have to be there when the lots open, so it can plan from the gate time, 2 hours before kickoff for NFL games, instead of the 4-hour lot window.","The trade-off is that no car in the lot means nowhere to leave a bag. The clear bag policy allows clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, including clear backpacks and fanny packs, and small non-clear bags up to 4.5 by 6.5 inches. Coolers are prohibited, and once you leave the stadium there is no re-entry."),_("Which vehicle fits a State Farm Stadium group, and what does it cost?",`Match the vehicle to the group: a game-day group of friends starts with the ${te(pa[0])} or the ${te(pa[1])}, client hospitality starts with the ${te(Fa[0])} or the ${te(Fa[1])}, and anything over ${ko} riders moves up to the ${te(Ma[0])} or the ${te(Ma[1])}.`,...bd(),"State Farm Stadium is in Glendale, on the far side of Phoenix from Scottsdale, so the drive each way is longer than a trip downtown. Tell the reservations team your pickup address and kickoff time, and the quote will show the hours that trip needs."),_("What bags are allowed at State Farm Stadium?","State Farm Stadium allows clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, including clear backpacks and fanny packs, and small non-clear bags up to 4.5 by 6.5 inches, but no coolers, and once you leave the stadium there is no re-entry.","Some events add their own rule. For Harry Styles on April 2 and 3, 2027, the stadium’s event page allows one clear bag up to 12 by 6 by 12 inches or a one-gallon freezer bag, and strongly recommends bringing no bag at all.","A group that is dropped off at the Black Lot has no car in a lot to go back to, so settle bags at the hotel before pickup."),Gl()],Bl=[{question:"How much is parking at State Farm Stadium?",answer:"It depends on the event and the lot. The stadium recommends buying parking in advance through SeatGeek, its official parking maps print the rates, and every parking area takes credit cards only."},{question:"Where is the best place to park at State Farm Stadium?",answer:"The red Preferred lots, West Preferred and North Preferred, sit beside the stadium and are entered only at Maryland Avenue and 95th Avenue. General Parking is assigned by staff to the closest lot with room, and on Cardinals days the Black Lot takes same-day parking without a pre-sold permit."},{question:"What time does parking open at State Farm Stadium?",answer:"On Cardinals game days, 4 hours before kickoff, with the oversized Lot F at 4 hours and 30 minutes. Other events list their own times on the event page, and stadium gates open 2 hours before kickoff for NFL games."},{question:"Where is rideshare pickup at State Farm Stadium?",answer:"In the Black Lot, south of the stadium across Cardinals Way. It is also the drop-off and pickup point for family and friends."},{question:"Can you tailgate at State Farm Stadium?",answer:"Yes, in the carparks once they open: one stall per vehicle, tailgate behind your vehicle, weight tents above ground, no saved spaces, and arrive together. Carparks close 1 hour after the event, and post-game tailgating is prohibited at Cardinals games."},{question:"Is there free parking near State Farm Stadium?",answer:"The stadium publishes no free parking, and the Fiesta Bowl’s official guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets. A drop-off at the Black Lot is the way to arrive without a parking space."},{question:"Where do RVs and oversized vehicles park at State Farm Stadium?",answer:"In the designated oversized lot, on event days only. On Cardinals game days that is Lot F, which opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass and fits vehicles up to 45 feet."},{question:"What is the State Farm Stadium bag policy?",answer:"Clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, including clear backpacks and fanny packs, and small non-clear bags up to 4.5 by 6.5 inches. No coolers."},{question:"Can a chauffeured Sprinter drop our group at State Farm Stadium?",answer:"Yes, at the point the event’s traffic plan allows. The Black Lot is the stadium’s published drop-off and pickup point, and no separate limo or charter zone is published, so the chauffeur confirms the drop-off for your booking and vehicle."}],Hl={path:"/guides/venues/state-farm-stadium",title:"State Farm Stadium Parking Guide: Lots, Rideshare & Drop-Off",metaTitle:"State Farm Stadium Parking & Drop-Off",description:"Where to park at State Farm Stadium: Preferred and General lots, the Black Lot rideshare drop-off, Cardinals lot hours, tailgating rules and oversized parking, and how a chauffeured group drop-off compares.",metaDescription:"Preferred and General lots, the Black Lot drop-off, hours and tailgating rules",lastUpdated:io,lastUpdatedLabel:l(io),intro:"Scottsdale Sprinters’ short answer on State Farm Stadium parking: buy a space in advance through SeatGeek, as the stadium recommends, pay by credit card because every parking area is cashless, and expect staff to direct you to a lot unless you hold Preferred Parking, which is entered only at Maryland Avenue and 95th Avenue. Rideshare and family drop-off and pickup use the Black Lot south of the stadium, and on Cardinals game days the lots open 4 hours before kickoff. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive out.",sections:Ul,faqs:Bl,links:[{href:"/guides/fiesta-bowl-transportation",label:"Fiesta Bowl parking and transportation guide"},{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking and concerts, across Maryland Avenue"},...yd(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:Ol},ri="2026-09-24",La="https://mortgagematchupcenter.com";function ze(e,t,...a){return{question:e,answer:t,paragraphs:a}}const ho="executive-sprinter-scottsdale",lo="limo-sprinter-16-scottsdale",co="ultra-luxury-party-sprinter-scottsdale",ca=e=>n[e],oi=e=>i[e];function zl(e){const t=r[e],a=od({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:oi(e)},vo);return`The ${ca(e)} is ${h(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${oi(e)} seats are filled.`}const ql=[{label:"Mortgage Matchup Center — Transportation & Parking",href:`${La}/plan-your-visit/transportation-parking/`},{label:"Mortgage Matchup Center — Accessibility and ADA Information",href:`${La}/venue/accessibility-ada-information/`},{label:"Mortgage Matchup Center — official venue site (bag policy, door times, parking)",href:`${La}/`},{label:"Mortgage Matchup Center — naming rights announcement (October 2, 2025)",href:`${La}/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/`},{label:"Mortgage Matchup Center — Private Events",href:`${La}/private-events/`},{label:"Phoenix Suns — 2026-27 schedule",href:"https://www.nba.com/suns/schedule"},{label:"NBA — Phoenix to host NBA All-Star 2027",href:"https://pr.nba.com/phoenix-to-host-nba-all-star-2027/"},{label:"Live Nation — Mortgage Matchup Center events",href:"https://www.livenation.com/venue/KovZpZAE617A/mortgage-matchup-center-events"}],Vl=[ze("Where do you park for Mortgage Matchup Center?","Mortgage Matchup Center points guests to the several garages and lots within walking distance and asks them to buy parking in advance through ParkWhiz; event parking generally opens about 30 minutes before doors, parking has no in-and-out privileges, and availability, pricing and access vary by event.","The arena is at 201 E. Jefferson Street, on the southeast corner of 1st Street and Jefferson in downtown Phoenix. Its site also lists more than 700 on-site parking spaces, including designated parking for guests with disabilities, with rates that vary by event, and it sends guests to the Mortgage Matchup Center Parking Office at 602-379-2003 for event pricing.","Public garages downtown are typically open all day, but for an event the arena says to plan on parking from about 30 minutes before doors open, unless that event says otherwise. Because parking has no in-and-out privileges, a group that parks early for dinner nearby cannot move the car and come back.","Valet is not open to the public. The arena reserves it for select guests and membership areas, from about 2 hours before the event, at the Ra Ra Room Valet on Jackson Street between 1st and 2nd Streets, the Annexus Valet on Jackson Street between 2nd and 3rd Streets, and inside the Jefferson Street Garage on the 2nd floor, reached from the garage’s 4th Street entrance. Everyone else is asked to buy parking in advance through ParkWhiz."),ze("Where is the drop-off and pickup at Mortgage Matchup Center?","The arena publishes one drop-off and pickup for a game or event: 3rd Street just south of Jefferson, at the green curb; the will-call drop-off is on 1st Street just north of Madison, and no vehicle may be parked or left unattended in a drop-off zone.","For rideshare, the arena lists four Lyft drop-off points: 1st Street and Jefferson at the arena plaza, S 2nd Street by The Ryan, S 3rd Street by the Phoenix Convention Center, and E Jefferson Street by Hotel Palomar and the Arrogant Butcher. After the event, Lyft pickups are at S 3rd Street and E Jefferson Street, by the Phoenix Convention Center.","No separate limo or charter zone is published. A chauffeured group uses the published drop-off on 3rd Street or the point event staff direct on the night. Because no vehicle may wait in a drop-off zone, the chauffeur clears the curb after unloading and comes back when the group is together.","Agree on the pickup before the game or show, and share it with everyone. After the final buzzer or the encore, gather first, then message the chauffeur once with the group count, rather than several people sending pins from inside the arena."),ze("Can you take light rail to Mortgage Matchup Center?","Yes: Valley Metro Rail stops at 3rd St/Jefferson, right by the arena, and the arena’s own directions also use the Downtown Phoenix Hub, about 0.3 mile’s walk away, and 3rd St/Washington for riders coming west from Gilbert Rd/Main St.","Southbound from Metro Parkway, the arena says to exit at the Downtown Phoenix Hub’s 1st Ave platform and walk about 0.3 mile, or transfer at the Hub’s Jefferson St platform and exit at 3rd St/Jefferson. Northbound from Baseline/Central Ave, exit at the Hub’s Central Ave platform and walk, or make the same transfer. Eastbound from the Hub, board at the Jefferson St platform and exit at 3rd St/Jefferson.","The arena adds that its bus stops and light rail stations are all on accessible routes to and from the building.","Rail suits a couple staying near a station. A group coming from a Scottsdale resort has more steps: getting everyone to a station, onto one train, and back again together after the game or the show."),ze("How do you drive to Mortgage Matchup Center from Scottsdale?","From North Phoenix and Scottsdale, the arena’s own route is State Route 51 south to the Interstate 10 East interchange, the Washington/Jefferson Street exit, right on Washington Street to 3rd Street, then left on 3rd Street to the arena and its drop-off.","From the East Valley and Tempe, take Interstate 10 west to Washington/Jefferson Street, turn left on Washington Street to 3rd Street, then left on 3rd Street. From the west, the arena routes drivers along Jefferson Street to 1st Street, where the arena stands on the corner.","The drive is the easy part. The parking, the no in-and-out rule and the walk back to the car after the game fall on whoever drives, who also has to stay fit to drive home."),ze("What is the bag policy at Mortgage Matchup Center?","The arena asks guests to arrive without bags when they can: small clutches and crossbody bags are permitted, purses, medical bags and diaper bags are allowed within 14 x 14 x 6 inches with extra screening, and standard backpacks are not permitted inside.","Guests without bags, or with a clutch smaller than 4 x 6 inches, can use the Evolv express entry lanes, which the arena recommends for the quickest way in. Some concerts and special events run modified item rules, so check your event, or ask the arena at feedback@phxses.com before you go.","A group that is dropped off has no car in a garage to leave a backpack in, so settle bags before pickup. Door times vary by event as well: the arena posts them on each event’s page."),ze("Is Footprint Center now Mortgage Matchup Center?","Yes: on October 2, 2025, the Suns and the Mercury announced that their downtown Phoenix arena, home to more than 100 sporting and entertainment events a year, is named Mortgage Matchup Center; before that it was Footprint Center, and it is the same building.","The address is unchanged: 201 E. Jefferson Street. The NBA’s 2024 release awarding Phoenix the 2027 All-Star Game still names it Footprint Center, home of the Phoenix Suns, and guests search for it under both names, so this guide uses both.","On its private-events page the arena calls itself the newly renovated, 18,000 capacity arena."),ze("What is on at Mortgage Matchup Center this season?","The Suns open their 2026-27 home schedule against the Golden State Warriors on Saturday, October 24, 2026, their last regular-season home game is Friday, April 9, 2027, and the NBA All-Star Game comes to the arena on Sunday, February 21, 2027, with concerts on the nights between.","The home opener tips off at 7 p.m. Most Suns home games do too, and a few start in the afternoon or at another evening time, so check the tip-off for your game. Concerts fill the nights between games. The arena’s calendar includes Kacey Musgraves on October 17, Gorillaz on October 23, Doja Cat on October 29, Don Omar on November 8, Banda MS on November 28 and Trans-Siberian Orchestra on December 6, then Hans Zimmer on March 30 and Niall Horan on May 20, 2027.","The Mercury’s 2027 home dates and the All-Star weekend schedule are announced closer to the date. Door times vary by event, so check the event’s own page before you set a pickup time."),ze("Which vehicle fits a Mortgage Matchup Center group, and what does it cost?",`Match the vehicle to the night: a game-night crew or a company outing starts with the ${ca(ho)}, a concert crew with the ${ca(lo)}, and a courtside or suite party with the ${ca(co)}.`,`Every rate prices the whole vehicle by the hour. Here is a ${vo}-hour booking in each lead vehicle. ${[ho,lo,co].map(zl).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole night, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead; the written quote shows how the drive is priced."),ze("How should a group plan the night at Mortgage Matchup Center?","Plan 4 things before pickup: a ready time worked back from the event’s door time, one agreed pickup point on 3rd Street after the game or show, one person who messages the chauffeur for the group, and bags that pass the arena’s bag policy.","Guests who need a wheelchair escort can ask any guest service representative at the entrances or the guest services office in the main north pavilion, or text 602-379-7668 from 30 minutes before doors until the end of the event. Mobility devices can be checked in the Guest Services Office.",`For a change of plan on the day, call the reservations team at ${u} or email ${p}.`)],Yl=[{question:"How much is parking at Mortgage Matchup Center?",answer:"The arena publishes no single price: parking rates vary by event. Buy in advance through ParkWhiz to see the price before you drive, or call the Mortgage Matchup Center Parking Office at 602-379-2003."},{question:"Where do you park for Mortgage Matchup Center?",answer:"In the garages and lots within walking distance, bought in advance through ParkWhiz, as the arena recommends. Event parking generally opens about 30 minutes before doors, with no in-and-out privileges."},{question:"Where is the drop-off at Mortgage Matchup Center?",answer:"On 3rd Street just south of Jefferson, at the green curb, for games and events. Vehicles cannot be parked or left unattended in the drop-off zone."},{question:"Where is the rideshare pickup at Mortgage Matchup Center?",answer:"At S 3rd Street and E Jefferson Street, by the Phoenix Convention Center."},{question:"Where is Mortgage Matchup Center?",answer:"At 201 E. Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson in downtown Phoenix."},{question:"What was Mortgage Matchup Center called before?",answer:"Footprint Center. The Suns and the Mercury announced the Mortgage Matchup Center name on October 2, 2025."},{question:"How many people does Mortgage Matchup Center hold?",answer:"The arena describes itself as an 18,000 capacity arena on its private-events page."},{question:"Can a chauffeured Sprinter drop our group at Mortgage Matchup Center?",answer:"Yes, at the published drop-off on 3rd Street or where event staff direct. No separate limo or charter zone is published, and no vehicle may wait at the curb, so the chauffeur returns when your group is ready."}],Jl={path:"/guides/venues/footprint-center",title:"Mortgage Matchup Center Parking Guide: Drop-Off & Rides at the Former Footprint Center",metaTitle:"Mortgage Matchup Center Parking Guide",description:"Where to park for Mortgage Matchup Center, formerly Footprint Center: garages and ParkWhiz, the 3rd Street drop-off, rideshare and light rail, the bag policy, the Suns schedule, and how a chauffeured group ride compares.",metaDescription:"Garages, the 3rd Street drop-off and rideshare",lastUpdated:ri,lastUpdatedLabel:l(ri),intro:"Scottsdale Sprinters’ short answer on Mortgage Matchup Center, formerly Footprint Center: buy parking ahead through ParkWhiz for the garages and lots within walking distance, plan on parking from about 30 minutes before doors, and remember there is no in-and-out. The arena’s drop-off and pickup for games and events is on 3rd Street just south of Jefferson, at the green curb, and light rail stops at 3rd St/Jefferson. For a group, one chauffeured vehicle replaces the garage, the walk back to the car and the drive home.",sections:Vl,faqs:Yl,links:[{href:`/fleet/${ho}`,label:ca(ho)},{href:`/fleet/${lo}`,label:ca(lo)},{href:`/fleet/${co}`,label:ca(co)},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:ql},Zl={path:re.path,title:re.h1,metaTitle:"Scottsdale Arabian Horse Show 2027",description:re.description,metaDescription:"WestWorld lots, drop-off, rideshare and hotel pickups for February 11–21",intro:re.intro,lastUpdated:re.lastUpdated,lastUpdatedLabel:re.lastUpdatedLabel,heroImage:re.image,heroAlt:re.imageAlt,sections:[...re.sections.map(e=>({question:e.heading,answer:e.lead,paragraphs:e.paragraphs})),{question:re.faqHeading,answer:re.faqLead,paragraphs:[]}],faqs:re.faqs,links:[...re.moneyLinks,{href:"/guides/venues/westworld-of-scottsdale",label:"WestWorld of Scottsdale venue guide"}],sources:re.sources},ni="2026-09-26",Kl="/guides/venues/arizona-financial-theatre",Ht="ultra-luxury-party-sprinter-scottsdale",Do="maybach-jet-sprinter-scottsdale",jl="maybach-shuttle-sprinter-8",Ql="premium-suv-scottsdale",zt="limo-sprinter-13-scottsdale",Io="limo-sprinter-16-scottsdale",No="party-bus-28-scottsdale",qt="executive-sprinter-scottsdale",Xl="executive-white-sprinter-scottsdale",Wo="executive-mini-bus-26-scottsdale",Lo="executive-luxury-bus-29-scottsdale",C=e=>n[e],dt=e=>i[e],Oo=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,pr="https://www.arizonafinancialtheatre.com",ec=`${pr}/visit`,tc=`${pr}/know-before-you-go`,ac=`${pr}/accessibility`,rc=`${pr}/private-events`,oc=`${pr}/shows`,nc="https://specialevents.livenation.com/venues/arizona-financial-theatre",sc="https://cdn.brandfolder.io/IW4GVCQ6/at/5zmhq9h6tznncwhz75bq2rt/Arizona_Financial_Theatre_One-Sheet.pdf",ic="https://cdn.brandfolder.io/IW4GVCQ6/at/7t8p46kw2kh8n3m6h9v3rswc/Arizona_Financial_Theatre_Floor_Plans.pdf",hc="https://www.livenation.com/venue/KovZpZAEk7lA/arizona-financial-theatre-events",dc=[{label:"Arizona Financial Theatre, plan your visit and FAQ",href:ec},{label:"Arizona Financial Theatre, know before you go",href:tc},{label:"Arizona Financial Theatre, accessibility, parking and drop-offs",href:ac},{label:"Arizona Financial Theatre, upcoming shows",href:oc},{label:"Arizona Financial Theatre, private events",href:rc},{label:"Live Nation Special Events, Arizona Financial Theatre spaces",href:nc},{label:"Arizona Financial Theatre, private events one-sheet (capacities)",href:sc},{label:"Arizona Financial Theatre, floor plans",href:ic},{label:"Live Nation, Arizona Financial Theatre events",href:hc}],vd=["January","February","March","April","May","June","July","August","September","October","November","December"],lc=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function cc(e){const[t,a,o]=e.split("-").map(Number);return`${lc[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${vd[a-1]} ${o}, ${t}`}function si(e){const[,t,a]=e.split("-").map(Number);return`${vd[t-1]} ${a}`}function uc(e){return`${cc(e.date)}: ${e.title} (show ${fa(`${e.date}T${e.starts}:00-07:00`)}).`}function Qe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const hr=Yd,ii=hr[0],hi=hr[hr.length-1],pc=[Qe("How does parking work at Arizona Financial Theatre?","Arizona Financial Theatre’s parking is the Adams Street Garage at 4th Avenue and Adams Street, next to the venue: it typically opens at 6 p.m. Monday to Friday and earlier on weekends, spaces are sold online, at the box office or at the garage entrance on show days, and the garage is cashless.","The venue says the 6 p.m. weekday opening does not apply to weekday shows that start before 6 p.m. There are accessible parking spaces on every level of the garage, with elevator access.","The venue’s pages publish no parking price: spaces are sold per show. Pay by card or phone, and buy the space ahead when the garage matters to your group.","Every point of sale inside the venue is cashless too, credit, debit or mobile pay, with cash-to-card conversion at the upgrade podium."),Qe("Where is the drop-off at Arizona Financial Theatre?","If you are being dropped off at Arizona Financial Theatre, tell staff as you arrive and they direct you to 4th Avenue and Adams Street, near the main entrance; that corner, beside the Adams Street Garage where most cars park, is the one drop-off point the venue publishes for guests arriving by car.","That is the point a chauffeured group uses too. We tell staff we are dropping off, unload the group where they direct at 4th Avenue and Adams Street, and agree one pickup point for the ride home before the show.","The venue publishes no separate area for rideshare, limousines or charters, so no curb is held for booked vehicles. If the venue posts a drop-off plan for a show, that plan comes first.","A group that splits across cars also splits across the garage, the card readers and the exit line. One vehicle arrives with everyone at once and leaves with everyone at once."),Qe("Where is Arizona Financial Theatre, and how do you get there?","Arizona Financial Theatre is at 400 West Washington Street, Phoenix, AZ 85003, in downtown Phoenix within 1 mile of the Phoenix Convention Center; the box office and will call sit in front of the building on the corner of 4th Avenue and Washington Street, and the venue’s garage is next to it at 4th Avenue and Adams Street.","Live Nation runs the venue. By car, set the navigation to the garage at 4th Avenue and Adams Street rather than the street address, so the last turn is the garage entrance, not the front of the building.","A chauffeured group needs neither: the driver takes the group to the drop-off at 4th Avenue and Adams Street and waits for the ride home."),Qe("What time do doors open at Arizona Financial Theatre?","Doors at Arizona Financial Theatre generally open 1 hour before the show’s scheduled start time unless the show says otherwise, and your ticket has the exact time; the venue recommends arriving early, and every show is mobile entry, with tickets on your phone rather than printed or emailed.","The box office opens on show days only, typically at 5 p.m., and 90 minutes before show time for a morning or afternoon show. It handles will call with a picture ID that matches the name on the order and the confirmation number, at (602) 379-2800.","VIP and Meet & Greet check-in can begin before the garage or the doors open, and its instructions come from the official VIP provider, typically 24 to 72 hours before the show. Camping out overnight is not permitted.","All events are all ages unless the show says otherwise, and every child over one year old needs a ticket."),Qe("What is the Arizona Financial Theatre bag policy?","Bags up to 12 by 6 by 12 inches are allowed inside Arizona Financial Theatre, every bag is searched before entry, bags that are not clear get an additional search, and no backpacks are allowed; each guest may bring up to 2 factory-sealed water bottles of up to 1 liter, but no Hydroflasks.","Not allowed: outside food or drinks, unsealed liquids or gels, personal video cameras and GoPros, selfie sticks, drones, masks, laser pointers, glowsticks and K-Pop light sticks, stuffed animals and toys, and weapons of any kind. The venue says the list can change by show.","Arizona Financial Theatre is a non-smoking building, with designated smoking areas outside depending on the event. Settle bags at the hotel: a group that is dropped off has no car in the garage to go back to during the show."),Qe("What is the seating like at Arizona Financial Theatre, and how many people does it hold?","Arizona Financial Theatre is a multi-level theatre that Live Nation’s special events team lists at up to 5,000 guests for a full-venue event, with a pit area on the floor, a club level, and VIP Suites above the club level, each with theatre-style seats and a small lounge, the suite level with its own private bar.","The layout changes with the show: the venue’s floor plans set the room for concert seating, concert seating with an orchestra, Broadway seating and boxing. Some shows are reserved seating, where you see your seat when you pick the ticket, and some are general admission.","Movable walls and padded chairs let the venue size the room to the show, and a 1,700 square foot VIP lounge sits beside the wrap-around lobby. For a group, the seating decides the arrival: a general admission night rewards getting in together at doors, and on a reserved night everyone already has a seat."),Qe("Which vehicle fits an Arizona Financial Theatre group?",`A VIP night takes the ${C(Do)}, the ${C(Ht)}, the ${C(jl)} or the ${C(Ql)}. Friends and birthday crews ride the ${C(zt)}, the ${C(Io)} or the ${C(No)}. Company nights and big groups take the ${C(qt)}, the ${C(Xl)}, the ${C(Wo)} or the ${C(Lo)}.`,`Seat counts are seated capacities from the fleet: the ${C(Ht)} seats ${dt(Ht)}, the ${C(zt)} ${dt(zt)}, the ${C(Io)} ${dt(Io)}, the ${C(No)} ${dt(No)} and the ${C(Do)} ${dt(Do)}. The ${C(qt)} seats ${dt(qt)}, the ${C(Wo)} ${dt(Wo)} and the ${C(Lo)} ${dt(Lo)}.`,`Our pick for a show night downtown is the ${C(Ht)}, ${Oo(Ht)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${C(zt)} is ${Oo(zt)}, and the ${C(qt)} is ${Oo(qt)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),Qe("How should a group plan the ride to an Arizona Financial Theatre show?","Plan backwards from the show time on the ticket: doors generally open 1 hour before it, so a pickup that lands the group at the 4th Avenue and Adams Street drop-off around doors leaves room for the bag search, the mobile tickets and, on a general admission night, getting in together.","The ride home is the part to plan hardest. Agree the pickup point before the show, and your chauffeur is there when the house lights come up, so the group walks out to its own vehicle instead of the garage line.","Events are all ages unless the show says otherwise. If even one passenger is under 21, the trip is alcohol-free for the whole group, adults included; we sell no alcohol on any trip.",`Book by the hour and the vehicle is yours for the whole night, dinner downtown before the show included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the date, the pickup area and the rider count.`)],fc=Qe("What’s coming up at Arizona Financial Theatre?",`Coming up at Arizona Financial Theatre this fall, among the shows the venue lists: ${hr.length} headliners from ${ii.label} on ${si(ii.date)} to ${hi.label} on ${si(hi.date)}, 2026, including Jack White, Rise Against, Modest Mouse, 311, Daniel Tosh and Sabaton. As the venue’s show list gave them on September 26, 2026:`,...hr.map(uc),"Doors generally open one hour before each show; the ticket has the exact time. New shows are added to the venue’s calendar through the year, and it is the place to check before you book."),mc=[{question:"Where do you park for Arizona Financial Theatre?",answer:"In the Adams Street Garage at 4th Avenue and Adams Street, next to the venue. It typically opens at 6 p.m. on weekdays and earlier on weekends, sells spaces online, at the box office or at the garage entrance on show days, and is cashless."},{question:"How much is parking at Arizona Financial Theatre?",answer:"The venue’s pages publish no price: spaces in the Adams Street Garage are sold per show, online, at the box office or at the garage entrance, and the garage takes no cash."},{question:"Where is the drop-off for Arizona Financial Theatre?",answer:"Tell staff you are being dropped off and they direct you to 4th Avenue and Adams Street, near the main entrance. A limo or party bus unloads there too, where staff direct."},{question:"What is the bag policy at Arizona Financial Theatre?",answer:"Bags up to 12 by 6 by 12 inches, searched at entry, with an additional search for bags that are not clear. No backpacks. Up to two factory-sealed water bottles of up to 1 liter per person; no Hydroflasks."},{question:"What time do doors open at Arizona Financial Theatre?",answer:"Generally one hour before the show’s scheduled start, unless the show says otherwise. The ticket has the exact time."},{question:"How many people does Arizona Financial Theatre hold?",answer:"Live Nation’s special events team lists the full venue at 5,000 guests. A show’s capacity depends on its layout: concert, orchestra, Broadway or boxing seating, reserved or general admission."},{question:"Is Arizona Financial Theatre seating reserved or general admission?",answer:"It depends on the show. On a reserved seated show you see your seat location when you pick the ticket; other shows are general admission. The venue has a pit area on the floor, a club level and VIP Suites above the club level."},{question:"Where is the box office at Arizona Financial Theatre?",answer:"On the corner of 4th Avenue and Washington Street, in front of the building. It opens on show days only, typically at 5 p.m., or 90 minutes before a morning or afternoon show."},{question:"Is Arizona Financial Theatre all ages?",answer:"Yes, unless the show says otherwise. Every child over one year old needs a ticket."},{question:"Is Arizona Financial Theatre cashless?",answer:"Yes. The garage and every point of sale take credit, debit or mobile pay; cash can be converted to a card at the upgrade podium."}],gc={path:Kl,title:"Arizona Financial Theatre Parking Guide: Seating, Drop-Off and Upcoming Shows",metaTitle:"Arizona Financial Theatre Parking",description:"Arizona Financial Theatre in downtown Phoenix: the Adams Street Garage, the 4th Avenue and Adams Street drop-off, doors, the bag policy, seating at a glance, the upcoming shows, and a chauffeured ride so nobody drives or parks.",metaDescription:"The garage, the drop-off, the bag policy and a chauffeured ride",lastUpdated:ni,lastUpdatedLabel:l(ni),eyebrow:"Phoenix · Downtown",intro:"Scottsdale Sprinters’ short answer on Arizona Financial Theatre parking: the venue’s garage is the Adams Street Garage at 4th Avenue and Adams Street, which typically opens at 6 p.m. on weekdays and earlier on weekends and takes no cash. The theatre is at 400 West Washington Street in downtown Phoenix, doors generally open an hour before the show, and a guest being dropped off is sent to 4th Avenue and Adams Street, near the main entrance. For a group, one chauffeured vehicle replaces the garage, the card reader and the drive home.",sections:[...pc,fc],faqs:mc,links:[{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts 2026–27, every show by venue"},{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center, formerly Footprint Center"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:`/fleet/${Ht}`,label:C(Ht)},{href:`/fleet/${zt}`,label:C(zt)},{href:`/fleet/${qt}`,label:C(qt)},{href:"/pricing",label:"Published hourly pricing"}],sources:dc},di="2026-09-27",yc="https://azstatefair.com/arizona-state-fair-hours/",bc="https://azstatefair.com/fair-directions-parking/",wc="https://azstatefair.com/know-before-you-go-faq/",vc="https://azstatefair.com/concerts/",kc="https://azstatefair.com/grandstandseries/",br={families:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale"],groups:["executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"]},Sc=[...br.families,...br.groups,...br.crews,...br.vip].filter(ae),Ac=Sc.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),ce="executive-sprinter-scottsdale",Tc="executive-white-sprinter-scottsdale",ke="executive-mini-bus-26-scottsdale",_o="executive-luxury-bus-29-scottsdale",Xr="limo-sprinter-13-scottsdale",$c="limo-sprinter-16-scottsdale",As="party-bus-28-scottsdale",li="maybach-jet-sprinter-scottsdale",ci="ultra-luxury-party-sprinter-scottsdale",ui="maybach-shuttle-sprinter-8",Cc="premium-suv-scottsdale",g=e=>n[e],Rt=e=>i[e];function Go(e){return h(r[e].hourlyRateCents)}function pi(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function qe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Pc=[{label:"Arizona State Fair: 2026 dates, admission and gate hours",href:yc},{label:"Arizona State Fair: directions, official lots, rideshare and the Phoenix College shuttle",href:bc},{label:"Arizona State Fair: know before you go (bags, food, rideshare, concerts)",href:wc},{label:"Arizona State Fair: 2026 Coliseum Concert Series",href:vc},{label:"Arizona State Fair: 2026 Grandstand series",href:kc}],Ec=[qe("When is the Arizona State Fair 2026, and what are the hours?","The Arizona State Fair 2026 runs October 1 to November 1, 2026, open Thursdays through Sundays only, at the State Fairgrounds, 1826 W McDowell Rd, Phoenix, AZ 85007; the gates open at noon, last entry is 9 p.m. on Thursdays and Sundays and 10 p.m. on Fridays and Saturdays.","The fair is closed Monday through Wednesday, so its five weekends carry the whole run: it opens on Thursday, October 1, and closes on Sunday, November 1. Halloween, October 31, is a Saturday fair day this year.","There is no fixed closing time. The fair says it stays open based on crowd size and activity, and the carnival ends for the night when the lights on the La Grande XL Wheel go dark. The livestock barns close at 9 p.m.; the Coliseum halls, the Shopping Pavilion and the Hangout at 10 p.m.","Admission, carnival rides and concert seats are the fair’s own, sold on its site, so this guide prints no ticket price: buy the tickets first, then book the ride for that day."),qe("Where do you park at the Arizona State Fair, and where is the drop-off?","The fair’s only official lots are the North Lot, entered from 19th Avenue at Monte Vista or Encanto, the West Lot, entered from Encanto between 19th and 20th Avenues, and a limited reserved VIP section of the North Lot; they open at 10 a.m., and rideshare drop-off is the southwest corner of the West Lot at 19th Avenue and Encanto.","The fair is clear that other lots around the fairgrounds are privately owned, not the fair’s. The official lots are paid; the fair’s parking page lists the current fee and sells the VIP spaces, which are limited.","Rideshare cars (Uber, Lyft and Waymo, in the fair’s words) enter on 19th Avenue at Encanto and are directed to the southwest corner of the West Lot to drop off and pick up. That is the corner a chauffeured group is sent to as well, unless the fair’s staff direct otherwise on the day.","With a chauffeur, the parking question goes away: the group steps out together, walks in together, and walks back out to a vehicle that has been waiting nearby, with the strollers, jackets and prizes aboard. Nobody circles for a space, and nobody drives home after a long day."),qe("How else can you get to the fair: the free shuttle and road closures?","The fair runs a free Park n’ Ride shuttle from Phoenix College, 1202 W Thomas Rd, with no shuttles on Thursdays: the first shuttle leaves at 5 p.m. on Fridays and at noon on Saturdays and Sundays, and the last one back leaves the fairgrounds at 11 p.m.; McDowell Road closes between 15th and 19th Avenues after 9 p.m. on Fridays and Saturdays.","The shuttle is the fair’s, free, and a good choice for a small group happy to park at the college and wait in line. A family with small children, grandparents or a stack of prizes usually wants a door-to-door ride instead, and a school or church group wants everyone in one vehicle with one headcount.","The McDowell Road closure matters for the ride home on a Friday or Saturday night: the fair’s own directions send drivers in from 19th Avenue, from I-10 at the 19th Avenue exit, and from I-17 at the 19th Avenue and State Capitol exit. Your chauffeur plans the pickup around the closure, so the group is not walking to a car on a closed street."),qe("What’s on at the 2026 Arizona State Fair: concerts and the Grandstand?","The 2026 Coliseum Concert Series at Veterans Memorial Coliseum is Gin Blossoms (October 2), Becky G (October 9), All Time Low (October 10), The Offspring (October 16), Russell Dickerson (October 17) and Public Enemy (October 24); every seat is reserved and includes fair admission, doors open at 6 p.m. and every show starts at 7 p.m., with no opening act.","The Grandstand Arena has its own series: a High School Rodeo on opening night, the Native American Rodeo on October 2 and 3, Xtreme Bull Riding on October 4, the All Star Monster Trucks on October 9 to 11 and again October 30 to November 1, and Figure 8 Races on October 16 to 18 and October 23 to 25.","A concert night is the busiest kind of fair night: the show fills the Coliseum on a Friday or Saturday, the midway is full, and McDowell Road closes late. A group that books the ride from the show’s start time, with an hour for the midway before it, walks out after the encore to a vehicle already waiting."),qe("What can you bring to the Arizona State Fair: bags, food and water?","Bags may not exceed 12 by 12 inches, and every bag, purse and backpack is screened at the gate; medical and diaper bags are exempt from the size limit but still inspected; no outside food, drinks, alcohol, glass or coolers, though each guest may bring one factory-sealed bottle of water and an empty refillable bottle.","Security may use walk-through metal detectors, pat-downs or wands. The fair’s list of things to leave at home includes drones, selfie sticks, bicycles, skateboards and balloons, and anything surrendered at the gate is not returned.","That is where a chauffeured day helps: the bigger bags, the cooler for the ride home and anything that would not pass the gate stay in the vehicle, which waits nearby with the chauffeur, instead of in a parked car in a lot.","Pets stay home: the fair welcomes service animals as defined by the ADA, but not pets or emotional support animals, and service animals are not allowed on carnival rides."),qe("Is the Arizona State Fair good for kids, school groups and teens?",`Yes: the fair calls itself family-friendly, children under 4 get in free, and its site has a field trips page for schools; for any group with riders under 21, our house rule applies: ${Ft}`,"Families and school groups are most of the fair’s crowd, and a ride keeps a group of kids together from the pickup to the gate and home again. Guest Services hands out free lost-child wristbands for a parent’s contact details, which is worth doing first thing.","Put a parent’s or a teacher’s cell number on the reservation, so the chauffeur has one point of contact for the day. We sell no alcohol, and no package on this page carries a drink service."),qe("What does a fair day cost with a chauffeur?",`A fair day is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${g(ce)} is ${Go(ce)}/hr and seats ${Rt(ce)}, the ${g(ke)} is ${Go(ke)}/hr and seats ${Rt(ke)}, a ${g(Xr)} is ${Go(Xr)}/hr; fair tickets are not included, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${Rt(ce)} riders in the ${g(ce)} for 6 hours is about ${pi(ce,6,Rt(ce))} each before tax. ${Rt(ke)} riders sharing the ${g(ke)} for 6 hours is about ${pi(ke,6,Rt(ke))} each. That is arithmetic on the published rates, not a flat fair fare.`,"The hours run from the pickup at your door to the drop-off at home, and the vehicle waits at the fairgrounds in between, so the day is one booking, not two rides, and no parking fee. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books.","Not in the fare: fair admission, carnival ride tickets, concert seats, food and anything bought inside."),qe("Which vehicle fits a State Fair group?",`Families and school groups lead with the ${g(ce)}, our pick for a fair day, then the white Executive Sprinter, the ${g(ke)} and the ${g(_o)}; concert and birthday crews ride a Limo Party Sprinter or the ${Rt(As)}-seat party bus; VIP groups take the ${g(li)}, the ${g(ci)}, the ${g(ui)} or the Suburban.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Families and school groups: the ${g(ce)}, the ${g(Tc)}, the ${g(ke)} and the ${g(_o)}. Concert and birthday crews: the ${g(Xr)}, the ${g($c)} and the ${g(As)}. VIP: the ${g(li)}, the ${g(ci)}, the ${g(ui)} and the ${g(Cc)}.`,`A family larger than the ${g(ce)} moves up to the ${g(ke)} or the ${g(_o)} rather than splitting into two vehicles, so everyone arrives and leaves together. Count heads from the ticket order, and leave room for strollers.`),qe("How far ahead should a State Fair ride be booked?","Buy the fair tickets first, then book the ride: availability varies by day and vehicle, so no fixed lead time applies, and the Friday and Saturday concert nights and the Halloween weekend go first; send the date, the rider count, the pickup address and any concert, and the reservations team confirms what is open.","The first request needs the day, the home, hotel, school or church pickup, a likely passenger count, and the concert or grandstand show if there is one. A group does not need every name to begin. It does need to say which group is riding: a family, a school or church group with a teacher’s number, a concert crew, or VIP guests.",`During the final 48 hours, confirm addresses, phone numbers and the show time. Reach the reservations team at ${u} or ${p}. A ride booking never includes a fair ticket.`)],Fc=[{question:"What are the Arizona State Fair 2026 dates?",answer:"October 1 to November 1, 2026, open Thursdays through Sundays only, at the Arizona State Fairgrounds, 1826 W McDowell Rd, Phoenix, AZ 85007."},{question:"What time does the Arizona State Fair open?",answer:"The gates open at noon. Last entry is 9 p.m. on Thursdays and Sundays and 10 p.m. on Fridays and Saturdays; the fair stays open based on crowd size, and the carnival ends when the La Grande XL Wheel goes dark."},{question:"Where do you park for the Arizona State Fair?",answer:"In the fair’s official North, West or VIP lots, which open at 10 a.m.; other nearby lots are privately owned. A chauffeured group skips parking and is dropped at the fair’s rideshare corner or where staff direct."},{question:"Where is the Uber and Lyft drop-off at the State Fair?",answer:"At the southwest corner of the West Lot, entered from 19th Avenue at Encanto. The fair names Uber, Lyft and Waymo for that corner."},{question:"Is there a shuttle to the Arizona State Fair?",answer:"Yes, the fair runs a free Park n’ Ride shuttle from Phoenix College, 1202 W Thomas Rd, on Fridays, Saturdays and Sundays; there are no shuttles on Thursdays."},{question:"What size bag can you bring to the Arizona State Fair?",answer:"Up to 12 by 12 inches, and every bag is screened. Medical and diaper bags are exempt from the size limit but still inspected."},{question:"Who is playing at the Arizona State Fair 2026?",answer:"The Coliseum Concert Series is Gin Blossoms, Becky G, All Time Low, The Offspring, Russell Dickerson and Public Enemy, October 2 to October 24; every show starts at 7 p.m., and a concert seat includes fair admission."},{question:"Can you rent a party bus or limo to the State Fair?",answer:`Yes. The ${g(As)}, the Limo Party Sprinters and the Executive Sprinters are booked by the hour, pickup to drop-off, and wait at the fairgrounds for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],Mc={path:"/guides/arizona-state-fair",title:"Arizona State Fair 2026: hours, parking, concerts and a chauffeured fair day",metaTitle:"Arizona State Fair: Hours & Parking",description:"The Arizona State Fair 2026 in Phoenix: October 1 to November 1, Thursdays to Sundays, gate hours, the official lots and the rideshare drop-off, the free Phoenix College shuttle, the Coliseum concerts, the bag rules, and a chauffeured fair day so the family stays together and nobody parks.",metaDescription:"Arizona State Fair 2026: dates, gate hours, official parking, drop-off, concerts and bag rules, or a chauffeured fair day",lastUpdated:di,lastUpdatedLabel:l(di),eyebrow:"Thursdays to Sundays · October 1 to November 1",intro:`A fair day with Scottsdale Sprinters starts with the fair’s own calendar, the day the group’s tickets are for and a rider count. Families and school groups lead with the ${g(ce)}; concert and birthday crews ride a Limo Party Sprinter or the party bus; VIP guests take the Maybach Jet. This guide uses only the fair’s published facts and turns the day into a written pickup, drop-off and ride home.`,sections:Ec,faqs:Fc,links:[{href:"/fleet/executive-sprinter-scottsdale",label:g(ce)},{href:"/fleet/executive-mini-bus-26-scottsdale",label:g(ke)},{href:"/fleet/limo-sprinter-13-scottsdale",label:g(Xr)},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:"/experiences/birthday-celebration",label:"Birthday party rides"},{href:"/pricing",label:"Published hourly pricing"}],sources:Pc,fleetRows:Ac},fi="2026-09-26",Rc="/guides/venues/asu-gammage",Vt="maybach-jet-sprinter-scottsdale",xc="ultra-luxury-party-sprinter-scottsdale",Dc="maybach-shuttle-sprinter-8",Oa="premium-suv-scottsdale",Yt="executive-sprinter-scottsdale",Ic="executive-white-sprinter-scottsdale",mi="limo-sprinter-13-scottsdale",uo="limo-sprinter-16-scottsdale",Uo="executive-mini-bus-26-scottsdale",Bo="executive-luxury-bus-29-scottsdale",N=e=>n[e],xt=e=>i[e],Ho=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,$e="https://www.asugammage.com",Nc=`${$e}/visitors/parking`,Wc=`${$e}/visitors/security-and-bag-policy`,Lc=`${$e}/visitors/faq`,Oc=`${$e}/shows-tickets/policies`,_c=`${$e}/visitors/accessibility`,Gc=`${$e}/contact`,Uc=`${$e}/about/rentals`,Bc=`${$e}/shows-tickets/groups`,Hc=`${$e}/visitors/dinner-and-show`,zc=`${$e}/seasontickets`,qc=`${$e}/shows-tickets/broadway-seating-chart`,Vc="https://www.valleymetro.org/how-to-ride/destinations/destinations-tempe",Os=e=>id.find(t=>t.fact===e),Yc=Os("GE1"),dr=Os("GE3"),So=Os("GE4"),Jc=[{label:"ASU Gammage, parking and directions",href:Nc},{label:"ASU Gammage, security and bag policy",href:Wc},{label:"ASU Gammage, visitor FAQ",href:Lc},{label:"ASU Gammage, ticketing terms and policies",href:Oc},{label:"ASU Gammage, accessibility",href:_c},{label:"ASU Gammage, box office and contact",href:Gc},{label:"ASU Gammage, 2026–27 season tickets",href:zc},{label:"ASU Gammage, Dr. Seuss’ How the Grinch Stole Christmas! The Musical",href:dr.url},{label:"ASU Gammage, Beetlejuice",href:So.url},{label:"ASU Gammage, Broadway seating chart",href:qc},{label:"ASU Gammage, Dinner and a Show",href:Hc},{label:"ASU Gammage, groups",href:Bc},{label:"ASU Gammage, private events and rentals",href:Uc},{label:"Valley Metro, Tempe destinations",href:Vc}],_a=["January","February","March","April","May","June","July","August","September","October","November","December"];function Pt(e){const[t,a,o]=e.dates.start.split("-").map(Number),[d,z,he]=e.dates.end.split("-").map(Number);return d!==t?`${_a[a-1]} ${o}, ${t} to ${_a[z-1]} ${he}, ${d}`:z===a?`${_a[a-1]} ${o} to ${he}, ${t}`:`${_a[a-1]} ${o} to ${_a[z-1]} ${he}, ${t}`}function Zc(e){return`${e.title}: ${Pt(e)}${e.inPackage?".":", a season option outside the eight-show package."}`}function Pe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Kc=[Pe("Where is ASU Gammage?","ASU Gammage is at 1200 S. Forest Avenue, Tempe, AZ 85281, on the Tempe campus of Arizona State University, where Broadway’s touring productions play the Valley. Frank Lloyd Wright designed the building, and the house has three seating levels: the orchestra, the grand tier and the balcony.","The casts are the professional touring Broadway companies, not student productions, the venue says. Its box office opens two hours before events on performance days, and tickets are sold only through ASU Gammage and Ticketmaster; third-party sellers are not authorized.","The theatre’s own lot, the Gold Lot, is Lot 3, entered from S. Forest Avenue at Lemon Street. The Maroon Garage, the Apache Boulevard structure, is entered from S. Normal Avenue north of Apache Boulevard."),Pe("How does parking work at ASU Gammage?","For Broadway, Beyond and School of Music performances, parking at ASU Gammage is included in the ticket price. On Broadway nights the Gold Lot is reserved for subscribers and guests who need accessible parking, and when it fills every guest is sent to the Maroon Garage, the Apache Boulevard structure.","For shows outside those series the Gold Lot is open to all ticket holders, and separate parking fees may apply; ASU Gammage publishes no figure for them. The Maroon Lot is open to all ticket holders for every event.","Accessible parking is available in every area, with dedicated spaces held in the Gold Lot. For the front Orchestra’s accessible seats, the venue says to use the North entrance for the elevator.","ASU Gammage asks everyone to arrive at least an hour before the performance, to park, clear security and be seated; latecomers wait for a break in the show."),Pe("Where do rideshare and chauffeured groups drop off at ASU Gammage?","ASU Gammage publishes no rideshare, limo or charter zone, so a chauffeured group unloads where ASU Gammage and ASU staff direct on the night. Its parking and accessibility pages do name designated drop-off areas at both theatre entrances, in their accessible-parking notes, where a driver can let members of a party out before parking.","Nothing here is a reserved lane for booked vehicles. The chauffeur drives the approach the night allows, lets the group out where staff direct, and agrees one pickup point for after the curtain call. If the venue publishes a drop-off plan for a show, that plan replaces this paragraph.","A guest who needs the elevator to the front Orchestra goes to the North entrance; tell us when you book and we plan the drop-off around it."),Pe("What is the ASU Gammage bag policy?","ASU Gammage screens every guest with metal detectors and allows one carry-in item per person: a clear bag up to 12 by 6 by 12 inches, or a small purse or bag, clear or not, up to 8.5 by 5.5 inches, about a folded sheet of letter paper. Every bag is subject to search, and the strap does not count.","Not allowed: weapons of any kind, pepper spray, any non-clear bag larger than the small-purse size, drinks and drink containers, full-size strollers, and wrapped presents or packages, which must be unwrapped to be inspected. A factory-sealed water, or an empty plastic or metal bottle of 32 ounces or less, is allowed.","Items that fail the check go back to the owner’s car or in the bin, the venue says. A group that is dropped off has no car in the garage to walk back to, so settle bags and holiday gifts at the hotel. The detectors use no magnetic waves and are safe with a pacemaker."),Pe("How do you get to ASU Gammage?","Drivers reach ASU Gammage from Apache Boulevard: the venue’s directions leave US 60 at Mill Avenue (exit 173) or Rural Road, Loop 101 at Broadway Road or University Drive by the Price Road frontage, and Loop 202 at Scottsdale Road, then turn north on S. Forest Avenue for the Gold Lot or S. Normal Avenue for the Maroon Garage.","Valley Metro lists four connections at ASU Gammage: bus Route 66 (Mill Avenue and Kyrene Road), FLASH, Orbit Jupiter and the Tempe Streetcar. It lists no light rail station as a connection there.","A chauffeured ride skips the choice of lot and exit. We drive from Scottsdale, Phoenix or your Tempe hotel, and nobody in the group walks a garage after the show."),Pe("What’s playing at ASU Gammage in the 2026–27 Broadway season?",`The 2026–27 Broadway season at ASU Gammage runs from ${Yc.title}, on now to October 4, 2026, through Death Becomes Her in August 2027, with Dr. Seuss’ How the Grinch Stole Christmas! The Musical on ${Pt(dr)} and Beetlejuice on ${Pt(So)}. The venue lists the season this way, as read on September 26, 2026:`,...id.map(Zc),"Most runs play evenings from Tuesday to Sunday with matinees on the weekend; the Grinch adds morning and afternoon family performances. Season tickets for 2026–27 are no longer available, and the venue keeps a waitlist for the next season. Other nights on its calendar sit outside the Broadway season; check each event’s parking on its own page."),Pe("Is the Grinch musical at ASU Gammage good for kids?",`Dr. Seuss’ How the Grinch Stole Christmas! The Musical plays ASU Gammage from ${Pt(dr)}, runs 85 minutes with no intermission, and the show’s content guide on the venue’s page calls it the perfect show for audiences of all ages. It allows no babes in arms, and recommend children who can sit and concentrate for 85 minutes.`,"ASU Gammage sets no age limit of its own and leaves the choice to parents, but everyone who attends needs a ticket, infants included. The Saturday and Sunday performances include morning and afternoon curtains, the easiest for young children.","Two rules matter in December: wrapped presents are not allowed through security, and full-size strollers are not either. A family that rides together leaves gifts and the big stroller at the hotel, and has one pickup point after the show instead of a garage line with tired children."),Pe("Where can you eat before a show at ASU Gammage?","ASU Gammage’s Dinner and a Show program lists restaurants that offer deals on the day of a performance when you show your ticket, among them rooftop dining at the Canopy Hotel and the Omni Tempe Hotel at ASU, a short walk from the theatre, and restaurants at Novus Place. Each restaurant sets its own offer.","The theatre’s own Portico Patio opens 90 minutes before Broadway shows with sandwiches, desserts, light refreshments, beer and wine. Only drinks bought at ASU Gammage concessions, in resealable bottles, go from the lobby into the theatre.","Book the vehicle by the hour and dinner is part of the night: we drop you at the restaurant, move the group to the theatre, and wait through the show."),Pe("Which vehicle fits an ASU Gammage night?",`A date night or a VIP evening takes the ${N(Vt)}, the ${N(xc)}, the ${N(Dc)} or the ${N(Oa)}. Families at the Grinch ride the ${N(Yt)} or the ${N(Ic)}; a girls’ night takes a Limo Sprinter; corporate and big groups take the ${N(Uo)} or the ${N(Bo)}.`,`Seat counts are seated capacities from the fleet: the ${N(Vt)} seats ${xt(Vt)}, the ${N(Oa)} ${xt(Oa)}, the ${N(Yt)} ${xt(Yt)}, the ${N(mi)} ${xt(mi)} and the ${N(uo)} ${xt(uo)}. The ${N(Uo)} seats ${xt(Uo)} and the ${N(Bo)} ${xt(Bo)}.`,`Our pick for a theatre night is the ${N(Vt)}, ${Ho(Vt)}: Maybach massage recliners, an executive table and a wet bar in a private-jet cabin. The ${N(Oa)} is ${Ho(Oa)}, and the ${N(Yt)} is ${Ho(Yt)}. Every rate prices the whole vehicle, before tax.`,"A family trip with anyone under 21 is alcohol-free for the whole group, and we sell no alcohol on any trip. For a group bigger than one coach, we plan two vehicles and quote them together."),Pe("How should a group plan an ASU Gammage night?","Plan backwards from the curtain. ASU Gammage asks guests to be there at least 60 minutes before the performance, its box office opens two hours before, and the Portico Patio 90 minutes before a Broadway show, so a pickup that lands the group an hour early leaves time for security and a drink.","Most shows have a 15-minute intermission; some have none, the Grinch among them. Dress is business casual for most patrons, the venue says, anything from jeans to gowns.","A group of 15 or more buying together through ASU Gammage Group Services gets one ticket free for a Broadway show (some exclusions apply), and pre-show reception space for 15 to 300 guests, from the Scoular Gallery to the open-air Promenade over the campus.",`Book by the hour and the vehicle is yours for dinner, the show and the ride home, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the performance, the pickup area and the rider count.`)],jc=[{question:"Is parking free at ASU Gammage?",answer:"For Broadway, Beyond and School of Music performances, parking is included in the ticket price. For other events separate parking fees may apply, and ASU Gammage publishes no figure for them."},{question:"Where do you park for ASU Gammage?",answer:"On Broadway nights the Gold Lot, Lot 3 off S. Forest Avenue at Lemon Street, holds subscribers and accessible parking, and everyone else is sent to the Maroon Garage, the Apache Boulevard structure off S. Normal Avenue."},{question:"What size bag can you bring to ASU Gammage?",answer:"One item per person: a clear bag up to 12 by 6 by 12 inches, or a small purse up to 8.5 by 5.5 inches. Everyone passes metal detectors, and wrapped presents are not allowed."},{question:"What is the address of ASU Gammage?",answer:"1200 S. Forest Avenue, Tempe, AZ 85281, on the Arizona State University campus."},{question:"When is the Grinch musical at ASU Gammage?",answer:`Dr. Seuss’ How the Grinch Stole Christmas! The Musical plays ${Pt(dr)}, with morning and afternoon performances on the weekend. It runs 85 minutes with no intermission.`},{question:"When is Beetlejuice at ASU Gammage?",answer:`Beetlejuice returns to ASU Gammage ${Pt(So)}, opening on New Year’s Day.`},{question:"How early should you arrive at ASU Gammage?",answer:"At least an hour before the performance, the venue says, to park, clear security and be seated. Latecomers wait for a break in the show."},{question:"Can a limo or Sprinter drop off at ASU Gammage?",answer:"Yes, where ASU Gammage and ASU staff direct on the night. The venue publishes no limo or rideshare zone, so the chauffeur confirms the drop-off for your show and agrees one pickup point for the ride home."},{question:"Is there light rail to ASU Gammage?",answer:"Valley Metro lists no light rail station as a connection at ASU Gammage. It lists bus Route 66, FLASH, Orbit Jupiter and the Tempe Streetcar."},{question:"What should you wear to ASU Gammage?",answer:"There is no formal dress code. Most patrons wear business casual, and the venue says anything from jeans to gowns is fine."}],Qc={path:Rc,title:"ASU Gammage Parking Guide: Drop-Off, Bag Policy and the 2026–27 Broadway Season",metaTitle:"ASU Gammage Parking & Broadway Season",description:"ASU Gammage in Tempe: how Broadway parking works in the Gold Lot and the Maroon Garage, the drop-off, the bag policy, getting there, the 2026–27 season with the Grinch and Beetlejuice, and a chauffeured theatre night so nobody parks.",metaDescription:"Gold Lot, Maroon Garage, bags, the season and a chauffeured ride",lastUpdated:fi,lastUpdatedLabel:l(fi),eyebrow:"Tempe · Arizona State University",intro:`Scottsdale Sprinters’ short answer on ASU Gammage parking: for Broadway shows it is included in the ticket, in the Gold Lot for subscribers and accessible parking and in the Maroon Garage on Apache Boulevard for everyone else. The theatre is at 1200 S. Forest Avenue on the ASU campus in Tempe, allows one carry-in item per person, and asks guests to arrive an hour early. Coming up: the Grinch musical on ${Pt(dr)} and Beetlejuice on ${Pt(So)}. For a date night, a family or a group, one chauffeured vehicle replaces the garage and the walk.`,sections:Kc,faqs:jc,links:[{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/guides/asu-gcu-graduation-transportation",label:"ASU graduation parking and rides"},{href:"/guides/christmas-lights-scottsdale-phoenix",label:"Holiday lights rides in Scottsdale and Phoenix"},{href:`/fleet/${Vt}`,label:N(Vt)},{href:`/fleet/${Yt}`,label:N(Yt)},{href:`/fleet/${uo}`,label:N(uo)},{href:"/pricing",label:"Published hourly pricing"}],sources:Jc},gi="2026-09-24",Xc="/guides/asu-gcu-graduation-transportation",Sa="executive-sprinter-scottsdale",po="executive-white-sprinter-scottsdale",wr="executive-luxury-bus-29-scottsdale",zo="executive-mini-bus-26-scottsdale",fo="limo-sprinter-13-scottsdale",yi="limo-sprinter-16-scottsdale",qo="party-bus-28-scottsdale",Vo="maybach-jet-sprinter-scottsdale",Yo="ultra-luxury-party-sprinter-scottsdale",Jo="maybach-shuttle-sprinter-8",Zo="premium-suv-scottsdale",P=e=>n[e],Ee=e=>i[e],eu="https://graduation.asu.edu/undergraduate-commencement",tu="https://graduation.asu.edu/graduate-commencement",au="https://graduation.asu.edu/ceremonies/schedule",ru="https://graduation.asu.edu/guests/parking",ou="https://graduation.asu.edu/know-before-you-go",nu="https://graduation.asu.edu/ceremonies/inclement-weather-plan-mountain-america-stadium",su="https://graduation.asu.edu/ceremonies/futuredates",iu="https://traditionalcommencement.gcu.edu/",hu="https://traditionalcommencement.gcu.edu/files/2026/09/WN26-Trad-Parking-Updated.pdf",du="https://traditionalcommencement.gcu.edu/files/2026/09/24EVT0093-WN26TradFAQ-FLY_FINAL_WORD.pdf",lu=[{label:"ASU Undergraduate Commencement, Fall 2026",href:eu},{label:"ASU Graduate Commencement, Fall 2026",href:tu},{label:"ASU Fall 2026 ceremony schedule",href:au},{label:"ASU graduation parking and transportation",href:ru},{label:"ASU graduation: know before you go",href:ou},{label:"ASU inclement weather plan, Mountain America Stadium",href:nu},{label:"ASU future commencement dates and live streams",href:su},{label:"GCU traditional commencement, Winter 2026",href:iu},{label:"GCU Winter 2026 commencement parking instructions (PDF)",href:hu},{label:"GCU Winter 2026 commencement FAQ (PDF)",href:du}];function lt(e,t,...a){return{question:e,answer:t,paragraphs:a}}const cu=[lt("When is ASU graduation in December 2026?","ASU’s fall 2026 University Commencement is Monday, December 14, 2026, on the Tempe campus: Graduate Commencement at 9:00 a.m. in Desert Financial Arena, and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, on Frank Kush Field. Neither ceremony needs tickets.","For the undergraduate ceremony, graduates should arrive no later than 1:30 p.m. to sit with their college, and seating is released to the general public at 1:45 p.m. ASU lists the ceremony as ending at 3:30 p.m., and the graduate ceremony at 11:00 a.m.","The same week holds the other ceremonies: celebrations on December 11 and 12, Barrett, The Honors College Convocation at 11:00 a.m. on December 14 at ASU Gammage, The College of Liberal Arts and Sciences Convocation at 7:30 p.m. on December 14 at the stadium, and college convocations on December 15, 16 and 17, most of them in Desert Financial Arena or ASU Gammage. The ASU Online Celebration is December 16 at 11:30 a.m. in the Student Pavilion.","ASU says times and locations are subject to change; the schedule was last updated on August 26, 2026. Recheck it the week before, and plan the ride around the ceremony your graduate is actually walking in.","Spring 2027 University Commencement is May 10, 2027, by ASU’s future-dates calendar, which also says dates can change. This page is updated for May when ASU posts that schedule."),lt("Where do you park for ASU graduation, and where can you be dropped off?","ASU’s commencement parking is complimentary and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The overflow for both is the Novus Parking Structure, which takes payment on the way out.","ASU warns that large attendance creates traffic around both venues and that exits from the lots and structures will be delayed, and it strongly encourages public transportation. ASU Gammage and the Student Pavilion use Lot 3.","Mountain America Stadium is at 500 E Veterans Way, Tempe, AZ 85287, and Desert Financial Arena at 600 E Veterans Way, Tempe, AZ 85281. Accessible parking is available at each venue with a placard or plate, and ASU publishes an ADA courtesy shuttle map for the arena and the stadium.","ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. So your chauffeur drives the approach and unloads where campus event staff and police direct, and you agree the pickup point before the ceremony, not after it. When ASU publishes more for December, that replaces this paragraph.","The parking maps on ASU’s page were last updated in December 2025 for the stadium and April 2026 for the arena. Recheck them the week of the ceremony."),lt("When is GCU graduation in December 2026?","GCU’s Winter 2026 traditional commencement is Thursday, December 17 and Friday, December 18, 2026, with ceremonies at 10 a.m. and 4 p.m. each day in Global Credit Union Arena, Phoenix. Each ceremony runs about an hour to an hour and a half.","December 17 at 10 a.m.: the College of Engineering and Technology and the College of Natural Sciences. December 17 at 4 p.m.: the College of Arts and Media, the College of Education, and the College of Humanities and Social Sciences.","December 18 at 10 a.m.: the Colangelo College of Business and the College of Theology. December 18 at 4 p.m.: the College of Engineering and Technology, the College of Natural Sciences, and the College of Nursing and Healthcare Professions.","Doors open two hours before each ceremony, and GCU asks ticketed guests to be seated at least 30 minutes before the start. Guests need general admission tickets: each registered graduate can reserve up to six, children three and under sit on a lap, and an overflow area shows the live stream.","GCU says its spring 2027 traditional commencement will be announced shortly after the winter ceremonies."),lt("Where do you park or get dropped off for GCU graduation?","GCU parks commencement guests in the 33rd Avenue garage beside Global Credit Union Arena, 3300 W. Camelback Road, with more parking in the 31st Avenue garage at 3050 W. Camelback Road. Its rideshare drop-off and pickup address is 3300 W. Camelback Road.","Phoenix police officers direct traffic during the ceremonies and may send drivers to another lot. Classes are in session that week, so GCU expects traffic to and on campus to be exceptionally busy, and asks guests to allow 30 to 45 minutes more for parking and the walk into the arena.","From the north on I-17, exit at Camelback Road and head to 33rd Avenue. From the south, exit at Bethany Home Road, take 35th Avenue south, then Camelback Road east to the garage. GCU estimates 30 to 45 minutes from Scottsdale and 45 minutes to an hour from Mesa, Gilbert and Chandler, before parking.","GCU names no separate lane for limousines or charters, so your chauffeur follows the officers on the day and meets the family at the pickup point you agreed."),lt("What can you bring into the ceremony?","Both universities enforce a clear bag policy. At GCU the limit is 12 by 12 by 6 inches, with metal detectors and bag checks, and there is no storage. At ASU the policy covers Mountain America Stadium and every ASU venue, and umbrellas are not allowed in the stadium.","GCU does not allow balloons, flags or banners, wrapped packages or gifts, noisemakers, alcohol, glass, strollers, wagons or car seats. Flowers are sold at a booth near the arena. ASU does not allow banners, flags or signs inside any venue, and allows clear, factory-sealed water bottles up to 1.5 liters at the stadium.","Book the vehicle by the hour and the flowers, balloons and gifts can stay on board during the ceremony, ready for the photos after."),lt("What happens if it rains on ASU commencement day?","ASU’s undergraduate commencement is outdoors and takes place rain or shine. If weather forces a delay, ASU may hold the start for up to an hour; if the ceremony cannot be held in the stadium, it is canceled, because no indoor space on campus holds the graduates and 30,000 or more guests.","ASU advises guests to bring ponchos or rain gear, since umbrellas are not allowed, and to prearrange a meeting place outside the stadium in case the ceremony is canceled.","Make that meeting place your pickup point. The chauffeur knows where it is before the ceremony starts, and nobody has to find the family in a crowd leaving at once."),lt("How long is graduation day, and how many hours should you book?","Plan the ceremony, the photos and a meal. ASU lists its undergraduate ceremony as starting at 2:00 p.m. and ending at 3:30 p.m., and GCU’s ceremonies last about an hour to an hour and a half, with doors open two hours before. A ceremony and a family dinner fit a four-hour block; an airport pickup or a party after needs more.","Book by the hour and the vehicle and chauffeur stay with you for the whole block: the pickup, the wait during the ceremony, the photos, dinner and the ride home. Or book a ride there and a ride back.","Every vehicle has a minimum number of hours, shown with its price on this page. Longer bookings earn free hours on the same published ladder as every other ride.",`Reach the reservations team at ${u} or ${p} with the ceremony, the pickup area, the number of riders and the plan after.`),lt("Which vehicle fits which graduation group?",`Graduates and their families ride the ${P(Sa)} or the ${P(po)}, or the ${P(wr)} or the ${P(zo)} for a big family. The grad party crew takes a Limo Party Sprinter or the ${P(qo)}. A VIP family celebration takes the ${P(Vo)}, the ${P(Yo)}, the ${P(Jo)} or the ${P(Zo)}.`,`Our pick for graduation day is the ${P(Sa)}: black-on-black leather shuttle seats that each recline, room for the whole family, and space for forty bags, so the flowers, gifts and gowns ride along. It delivers on every metric without the limo styling, which is what a day in caps and gowns calls for.`,`Seat counts are seated capacities from the fleet: the ${P(Sa)} and the ${P(po)} seat ${Ee(Sa)} each, the ${P(wr)} ${Ee(wr)}, the ${P(zo)} ${Ee(zo)}, the ${P(fo)} ${Ee(fo)}, the ${P(yi)} ${Ee(yi)}, the ${P(qo)} ${Ee(qo)}, the ${P(Vo)} ${Ee(Vo)}, the ${P(Yo)} ${Ee(Yo)}, the ${P(Jo)} ${Ee(Jo)} and the ${P(Zo)} ${Ee(Zo)}.`,`When a family outgrows its row, the page never offers it a party vehicle; for a group bigger than the ${P(wr)}, we plan two vehicles and quote them together. If anyone riding is under 21, no alcohol comes on board for the whole trip.`)],uu=[{question:"Where do you park for ASU graduation?",answer:"ASU’s commencement parking is free and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The Novus Parking Structure is the paid overflow. ASU warns that exits will be delayed and encourages public transportation."},{question:"Is there a drop-off area for ASU commencement?",answer:"ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. A chauffeur unloads where campus event staff and police direct."},{question:"Where is the GCU graduation rideshare drop-off?",answer:"GCU’s rideshare drop-off and pickup address is 3300 W. Camelback Road, Phoenix, beside Global Credit Union Arena. Guest parking is the 33rd Avenue garage there, with more in the 31st Avenue garage. Phoenix police direct traffic during the ceremonies."},{question:"When is ASU graduation 2026?",answer:"Monday, December 14, 2026: Graduate Commencement at 9:00 a.m. in Desert Financial Arena and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, both in Tempe. College convocations run December 14 to 17."},{question:"When is GCU graduation 2026?",answer:"Thursday, December 17 and Friday, December 18, 2026, at 10 a.m. and 4 p.m. each day, in Global Credit Union Arena, Phoenix. Doors open two hours before each ceremony."},{question:"Do you need tickets for ASU graduation?",answer:"Not for University Commencement: neither the graduate nor the undergraduate ceremony requires tickets, and stadium guest seating is first come, first served. Some convocations and celebrations do require tickets; ASU’s schedule marks which."},{question:"How many guest tickets do you get for GCU graduation?",answer:"Each registered graduate can reserve up to six general admission guest tickets. Children three and under do not need one but sit on a ticketed guest’s lap, and an overflow area shows the live stream."},{question:"How long is the ASU graduation ceremony?",answer:"ASU lists Undergraduate Commencement as starting at 2:00 p.m. and ending at 3:30 p.m., and Graduate Commencement as starting at 9:00 a.m. and ending at 11:00 a.m. Allow time before for the crowd and after for photos."},{question:"What is the ASU graduation bag policy?",answer:"Mountain America Stadium and every ASU venue have a clear bag policy, and umbrellas are not allowed in the stadium. Guests with a bag that does not comply are asked to return it to their car."},{question:"Can you watch ASU graduation online?",answer:"Yes. ASU streams its ceremonies live; each one’s link is on the ceremony schedule and in the ASU Mobile app. GCU streams every ceremony too, and posts the videos on its YouTube channel afterward."},{question:"When is ASU graduation in spring 2027?",answer:"ASU’s future-dates calendar lists Spring 2027 University Commencement on May 10, 2027, subject to change. GCU will announce its spring 2027 ceremonies after the winter ones."}],pu={path:Xc,title:"ASU & GCU graduation 2026: dates, parking and rides",metaTitle:"ASU & GCU Graduation 2026 Parking",description:"ASU commencement is Monday, December 14, 2026, at Desert Financial Arena and Mountain America Stadium; GCU’s ceremonies are December 17 and 18 at Global Credit Union Arena. Official times, parking, drop-off and bag rules, and a chauffeured ride for the family.",metaDescription:"ASU on December 14, GCU on December 17 and 18: times, parking, drop-off and a ride",lastUpdated:gi,lastUpdatedLabel:l(gi),eyebrow:"Graduation: ASU December 14 · GCU December 17 and 18, 2026",intro:"A graduation ride from Scottsdale Sprinters starts with the ceremony your graduate is walking in: ASU’s commencement in Tempe or GCU’s in Phoenix. This guide uses only what the two universities have published, and says plainly what they have not.",sections:cu,faqs:uu,links:[{href:`/fleet/${Sa}`,label:P(Sa)},{href:`/fleet/${po}`,label:P(po)},{href:`/fleet/${fo}`,label:P(fo)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter van service"},{href:"/pricing",label:"Published hourly pricing"}],sources:lu},bi="2026-09-24",fu="/guides/cactus-league-spring-training",rr="maybach-jet-sprinter-scottsdale",or="ultra-luxury-party-sprinter-scottsdale",wi="maybach-shuttle-sprinter-8",vi="premium-suv-scottsdale",ki="limo-sprinter-13-scottsdale",mo="limo-sprinter-16-scottsdale",Ko="party-bus-28-scottsdale",nr="executive-sprinter-scottsdale",mu="executive-white-sprinter-scottsdale",Si="executive-mini-bus-26-scottsdale",jo="executive-luxury-bus-29-scottsdale",G=e=>n[e],ye=e=>i[e],gu="https://cactusleague.com/schedule.php",yu="https://www.mlb.com/giants/spring-training/a-z-guide",bu="https://saltriverfields.com/welcome-to-salt-river-fields/",wu="https://saltriverfields.com/parking/",vu="https://www.mlb.com/camelback-ranch/your-visit/information-and-policies",ku="https://www.mlb.com/cubs/sloan-park/transportation",Su="https://www.mlb.com/athletics/spring-training/guide",Au="https://www.mlb.com/angels/spring-training/ballpark",Tu="https://www.mlb.com/brewers/spring-training/trip-planning",$u="https://www.peoriasportscomplex.com/spring-training/find-info/maps-directions",Cu="https://www.surprisestadium.com/stadium-info/stadium-a-z",Pu="https://www.goodyearbp.com/Ballpark-Visitors/Directions-and-Parking",Eu="https://www.mlb.com/guardians/spring-training/a-to-z-guide",Fu="https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals",Mu=[{label:"Cactus League 2027 schedule",href:gu},{label:"Scottsdale Stadium spring training A to Z (San Francisco Giants)",href:yu},{label:"Welcome to Salt River Fields: rideshare and address",href:bu},{label:"Salt River Fields parking and directions",href:wu},{label:"Sloan Park transportation (Chicago Cubs)",href:ku},{label:"Camelback Ranch information and policies",href:vu},{label:"Hohokam Stadium spring training guide (Athletics)",href:Su},{label:"Tempe Diablo Stadium ballpark information (Angels)",href:Au},{label:"American Family Fields of Phoenix trip planning (Brewers)",href:Tu},{label:"Peoria Sports Complex maps and directions",href:$u},{label:"Surprise Stadium A to Z",href:Cu},{label:"Goodyear Ballpark directions and parking",href:Pu},{label:"Goodyear Ballpark spring training A to Z (Cleveland Guardians)",href:Eu},{label:"MLB.com: the collective bargaining agreement’s expiry date",href:Fu}];function ct(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ru={head:["Ballpark (teams)","Drop-off or rideshare","Parking and gates"],rows:[["Camelback Ranch-Glendale (Dodgers, White Sox)","None published; staff direct","Free, no overnight parking; gates 60 minutes before first pitch"],["Hohokam Stadium, Mesa (Athletics)","None published; staff direct","Cash only; gates 1.5 hours before game time"],["Tempe Diablo Stadium (Angels)","Just outside the Alameda Drive entrance to the west lot, never inside it","Cashless; lots open 2.5 hours before home games"],["American Family Fields of Phoenix (Brewers)","Along 53rd Avenue and Indian School, outside the lot","Sold on the day, card only, more for larger vehicles; lots open 3 hours before"],["Peoria Sports Complex (Padres, Mariners)","Stadium Way and Paradise Lane, west of Gate D; buses at Mariners Way","Free, no overnight parking; gates about 90 minutes before"],["Surprise Stadium (Rangers, Royals)","Loading zone just north of the Surprise Aquatic Center","Free, more than 1,600 spaces; gates 1.5 hours before"],["Goodyear Ballpark (Guardians, Reds)","VIP lot off Wood Boulevard, or the Third Base Entrance","Free with a game ticket; gates 1.5 hours before"]]},xu=[ct("Is there parking at Scottsdale Stadium, and where is the drop-off?","Very little. The Giants say parking at Scottsdale Stadium is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and they encourage fans to walk, bike or take rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard, and gates open 2 hours before game time.","The Osborn Road lot is reserved for Giants and City of Scottsdale personnel only, so it is not a place to park or to wait. The stadium has four gates: Home Plate Plaza at Drinkwater Boulevard and Osborn Road, Gate A in centerfield facing 75th Street, Gate E on the third-base side along Drinkwater Boulevard, and Gate F in the left-field corner.","The Giants list the Gate A and Gate E drop-off zones under accessibility. We treat them as the stadium’s published drop-off points, never as a spot reserved for us: the chauffeur unloads at the zone, or where stadium and city staff direct, and the group walks in from there. A 2027 spring training trolley has not been announced.","The chauffeured alternative is the simple one: we pick the group up at the hotel or home, nobody hunts for one of the few spaces, and the vehicle comes back for the ride home after the last out. Game times are announced closer to the date, so the pickup is set once the league posts them."),ct("Where do you park at Sloan Park, and where do rideshares drop off?","Sloan Park’s lots open 4 hours before Cubs spring training games, and gameday parking is first come, first served and cashless, by credit card. Rideshares drop off and pick up outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview, across from the park, to Cubs home games.","Tempe Marketplace also runs a trolley to and from Cubs home games at Sloan Park. Both shuttles drop off at the First Base Gate. Parking prices depend on the lot, and the Cubs sell a limited number of pre-sale single-game and group spaces in the Purple Lot.","Sloan Park is the Cubs’ spring home in Mesa, and the league’s last game of 2027, the Brewers at the Cubs on Tuesday, March 23, is played there. A chauffeured group uses the published rideshare point outside the Right Field Gate, or unloads where staff direct, and meets the vehicle at the same side of Sheffield Avenue after the game."),ct("Where do rideshares and drop-offs go at Salt River Fields?","Salt River Fields at Talking Stick, at 7555 North Pima Road in Scottsdale, suggests the access road along the grass-field parking lots, or the Centerfield Parking Lots, for pickup and drop-off. There are 3 entrances off Pima Road. It is the spring home of the Diamondbacks and the Rockies.","The ballpark’s 2027 lot prices and its accessible drop-off are not yet published: its A to Z still describes the 2026 season, so this page prints neither. Our Salt River Fields arrival guide keeps the venue’s own sources in one place.","Salt River Fields and Scottsdale Stadium are the two Scottsdale ballparks. For the ride back, the group gathers at one pedestrian point first and the trip lead confirms the vehicle’s position before anyone walks toward traffic; event-day signs and staff direct the actual vehicle movement."),{...ct("Where do you park and get dropped off at the other Cactus League ballparks?","Each park sets its own rules. Camelback Ranch, Peoria Sports Complex and Surprise Stadium park free, and Goodyear Ballpark is free with a game ticket; Hohokam Stadium is cash only, and Tempe Diablo and American Family Fields are cashless or card only. Only Peoria publishes a bus drop-off, at Mariners Way off 83rd Avenue.","Camelback Ranch-Glendale (the Dodgers and the White Sox): parking is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published, so the chauffeur unloads where ballpark staff direct.","Hohokam Stadium in Mesa (the Athletics): on-site parking is cash only, and the gates open 1.5 hours before game time. No rideshare or drop-off zone is published.","Tempe Diablo Stadium (the Angels): rideshare drop-off and pickup is just outside the Alameda Drive entrance to the west parking lot, and no pickup or drop-off is allowed inside that lot. Both lots are entered from Alameda Drive and open 2.5 hours before home games, and the venue is cashless.","American Family Fields of Phoenix (the Brewers): drop-offs and rideshares use the designated space along 53rd Avenue and Indian School, outside the parking lot. Parking is sold on the day only, by card, with more charged for oversized and larger vehicles, and the lots open 3 hours before the game.","Peoria Sports Complex, 16101 North 83rd Avenue (the Padres and the Mariners): rideshare pickup and drop-off is near Stadium Way and Paradise Lane, just west of the Gate D entrance. Buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. Parking is free, with no overnight parking, and the gates typically open 90 minutes before the published game time.","Surprise Stadium (the Rangers and the Royals): the designated rideshare and drop-off loading zone is just north of the Surprise Aquatic Center. Parking is free, with more than 1,600 spaces, and the gates open 1.5 hours before game time.","Goodyear Ballpark, 1933 South Ballpark Way (the Guardians and the Reds): rideshare pickup and drop-off is in the VIP parking lot, reached from Wood Boulevard north of Lower Buckeye Road, and drop-off is also available at the Third Base Entrance. Parking is free with a game ticket, with no overnight parking, and the gates open 1.5 hours before game time."),table:Ru},ct("When is spring training in Arizona in 2027?","As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with 8 games, and the last Cactus League game is Tuesday, March 23, 2027. That is 229 games in about five weeks. Game times are announced closer to the date: the league lists every one of them as to be determined.","One date to know before you book: Major League Baseball’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates on this page are the Cactus League’s published schedule. We recheck them after December 1 and update this page if the league changes anything.",`If a game you planned around moves, every booking allows one free date change when you ask ${nd} or more hours before pickup, subject to availability: the deposit travels to the new date and the new date’s rate applies.`,`Saturday and Sunday games in the Cactus League window, February 19 to March 23, 2027, are major-event dates on our booking calendar, so they run on the ${Od}-day major-event cancellation window, with the deposit non-refundable. Weekday games follow the standard or large-group terms, depending on the size of the group. The booking step flags a major-event date before anything is paid.`),ct("Where is spring training in Arizona, and which teams play where?","Fifteen Major League teams train at 10 ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark.","Scottsdale Stadium: the Giants. Salt River Fields at Talking Stick: the Diamondbacks and the Rockies. Sloan Park: the Cubs. Hohokam Stadium: the Athletics. Tempe Diablo Stadium: the Angels. Camelback Ranch-Glendale: the Dodgers and the White Sox. American Family Fields of Phoenix: the Brewers. Peoria Sports Complex: the Padres and the Mariners. Surprise Stadium: the Rangers and the Royals. Goodyear Ballpark: the Guardians and the Reds.","The two Scottsdale parks, the two Mesa parks and Tempe Diablo are in the East Valley; Camelback Ranch, American Family Fields, Peoria, Surprise and Goodyear are in the West Valley. A two-ballpark day is simplest between neighbours, and it is one hourly booking: the first game, lunch, the second park and the ride home, confirmed once both game times are posted.","Which team plays where on a given day is the league’s to publish. Check the official Cactus League schedule for the game, buy the tickets from the teams, and send us the game or games; we build the pickup, the wait and the return around them in writing."),ct("Which vehicle fits a spring training group?",`Match the vehicle to the day: ballpark crews and bachelor groups ride a Limo Party Sprinter or the ${G(Ko)}, families and fan clubs take the ${G(nr)} or an executive coach for up to ${ye(jo)}, and VIP groups ride the ${G(rr)} or the ${G(or)}.`,`Ballpark crews and bachelor groups: the ${G(ki)} is a nightclub on wheels with a wet bar for ${ye(ki)}, the ${G(mo)} is our most spacious Sprinter, a lounge for ${ye(mo)} with four wet bars, and the ${G(Ko)} puts ${ye(Ko)} on limo seating on a wood floor when the whole crew comes. These are party rides, for a group out to celebrate.`,`Families and fan clubs: the ${G(nr)} and the ${G(mu)} seat ${ye(nr)} each in reclining leather, a cup holder at every seat and room for the gear. The ${G(Si)} (${ye(Si)} seats) and the ${G(jo)} (${ye(jo)} seats) carry a fan club or a company outing in one pickup.`,`VIP groups: the ${G(rr)} leads, ${ye(rr)} seats with four Maybach massage recliners and a wet bar. The ${G(or)} seats ${ye(or)} in a fiber-optic lounge with ultra-premium sound, our pick for a ballpark day that ends in Old Town. The ${G(wi)} seats ${ye(wi)} in custom Maybach seats, and the ${G(vi)} carries up to ${ye(vi)}.`,"Count riders for each direction. A group that arrives together for first pitch does not always leave together, and anyone leaving with another group comes off the return list before the chauffeur plans the pickup."),ct("Can a party bus, limo or charter drop off at a spring training ballpark?","Only Peoria Sports Complex publishes a bus rule: buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. None of the 10 ballparks publishes a permit rule for limos or party buses, so our chauffeur uses the park’s published drop-off or rideshare zone, or unloads where staff direct.","Two other published rules matter for a bigger vehicle. American Family Fields charges more for oversized and larger vehicles that park, and Tempe Diablo Stadium allows no pickup or drop-off inside its west lot. Where the vehicle waits during the game is confirmed with the reservations team before the day, not decided at the gate.","For the ride back, name one meeting point and one trip lead before the group goes in. After the last out the lead counts heads, confirms the vehicle’s position with the chauffeur and walks the group there together, rather than everyone chasing a map pin at once.",`We are a chauffeured transportation service. We do not sell tickets, parking passes or admission, and a ride includes none of them. Questions this page does not answer go to the reservations team at ${u} or ${p}.`)],Du=[{question:"When is spring training in Arizona in 2027?",answer:"As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with eight games, and the last Cactus League game is Tuesday, March 23, 2027. Game times are announced closer to the date."},{question:"Where is spring training in Arizona?",answer:"At ten ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark."},{question:"What teams have spring training in Arizona?",answer:"Fifteen: the Giants, the Diamondbacks and Rockies, the Dodgers and White Sox, the Cubs, the Athletics, the Angels, the Brewers, the Padres and Mariners, the Rangers and Royals, and the Guardians and Reds."},{question:"What is the Cactus League?",answer:"Major League Baseball’s spring training in Arizona. In 2027, as scheduled by the Cactus League, 15 teams play 229 games at 10 ballparks from February 19 to March 23."},{question:"Is there parking at Scottsdale Stadium?",answer:"Very little. The Giants say parking is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and encourage walking, biking or rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard."},{question:"Where do you park at Sloan Park?",answer:"The lots open four hours before Cubs spring training games; parking is first come, first served and cashless. Rideshares use the point outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview."},{question:"Where do rideshares drop off at Salt River Fields?",answer:"On the access road along the grass-field parking lots, or at the Centerfield Parking Lots. Salt River Fields is at 7555 North Pima Road, with three entrances off Pima Road."},{question:"Where do you park at Camelback Ranch?",answer:"Parking at Camelback Ranch-Glendale is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published."},{question:"Could the MLB labor talks change the 2027 dates?",answer:`MLB’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates here are the Cactus League’s published schedule; we recheck them after December 1, and every booking allows one free date change ${nd} or more hours before pickup.`},{question:"Do you sell spring training tickets or parking?",answer:"No. We sell chauffeured transportation only. Tickets come from the teams and the league, and parking from the ballparks; with a chauffeured ride, nobody in the group needs a parking space."}],Iu={path:fu,title:"Spring Training 2027 in Arizona: ballpark drop-off, parking and rides",metaTitle:"Spring Training 2027: Parking & Rides",description:"Cactus League spring training 2027 runs February 19 to March 23 at ten ballparks around Phoenix. The official dates, the fifteen teams, each ballpark’s parking, rideshare and drop-off rules, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Feb 19 – Mar 23 dates, parking and drop-off at all 10 ballparks",lastUpdated:bi,lastUpdatedLabel:l(bi),eyebrow:"As scheduled: February 19 to March 23, 2027",intro:"A spring training ride from Scottsdale Sprinters starts with the day your group is having: a ballpark crew or a bachelor weekend at the game, a family or a fan club with a few games on the list, or a VIP day in the Maybach Jet. This guide covers the ten Cactus League ballparks with only what the league, the teams and the ballparks publish, and says plainly what is announced closer to the date.",sections:xu,faqs:Du,links:[{href:"/experiences/spring-training",label:"Spring training group transportation: rates and two-game days"},{href:"/guides/venues/salt-river-fields",label:"Salt River Fields parking and group drop-off"},{href:"/guides/scottsdale-event-transportation",label:"Scottsdale event transportation guide"},{href:"/services/bachelor-party-transportation-scottsdale",label:"Bachelor party transportation"},{href:`/fleet/${or}`,label:G(or)},{href:`/fleet/${mo}`,label:G(mo)},{href:`/fleet/${nr}`,label:G(nr)},{href:`/fleet/${rr}`,label:G(rr)},{href:"/pricing",label:"Published hourly pricing"}],sources:Mu},Ai="2026-09-27",Nu="https://scottsdalearts.org/explore-scottsdale-arts/canal-convergence/",Wu="https://scottsdalearts.org/explore-scottsdale-arts/canal-convergence/canal-convergence-2026/",Lu="https://scottsdalearts.org/explore-scottsdale-arts/canal-convergence/2026-canal-convergence-artworks/",Ou="https://oldtownscottsdaleaz.com/get-around/public-parking/",_u="https://oldtownscottsdaleaz.com/get-around/ride-share/",Gu="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",Qo={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],families:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale","executive-mini-bus-26-scottsdale"]},Uu=[...Qo.vip,...Qo.crews,...Qo.families].filter(ae),Bu=Uu.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),V="ultra-luxury-party-sprinter-scottsdale",Ya="maybach-jet-sprinter-scottsdale",Ti="maybach-shuttle-sprinter-8",Xo="premium-suv-scottsdale",en="limo-sprinter-13-scottsdale",Hu="limo-sprinter-16-scottsdale",vt="party-bus-28-scottsdale",Ja="executive-sprinter-scottsdale",zu="executive-white-sprinter-scottsdale",$i="executive-mini-bus-26-scottsdale",y=e=>n[e],Fe=e=>i[e];function vr(e){return h(r[e].hourlyRateCents)}function Ci(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function be(e,t,...a){return{question:e,answer:t,paragraphs:a}}const qu=[{label:"Scottsdale Arts: Canal Convergence",href:Nu},{label:"Scottsdale Arts: Canal Convergence 2026, location, hours and highlights",href:Wu},{label:"Scottsdale Arts: 2026 Canal Convergence artworks",href:Lu},{label:"City of Scottsdale, Old Town: public parking",href:Ou},{label:"City of Scottsdale, Old Town: ride share",href:_u},{label:"City of Scottsdale: Transportation Safety Zone",href:Gu}],Vu=[be("What is Canal Convergence, and when and where is it in 2026?","Canal Convergence is Scottsdale Arts’ free, 10-night public art event of large-scale, light-based installations, running November 6 to 15, 2026, at the Scottsdale Waterfront in Old Town Scottsdale, in and above the Arizona Canal and along its pathways and bridges between Scottsdale Road and Goldwater Boulevard.","The address Scottsdale Arts prints for the event is Solstice Park, 4420 N Scottsdale Rd, Scottsdale, AZ 85251. The art is spread along the water on both banks, so the night is a walk: from one installation to the next, over the bridges, with Old Town’s restaurants a few steps away.","2026 is the event’s 15th year, and it falls in the City of Scottsdale’s 75th anniversary year. Scottsdale Arts produces it with annual support from the City of Scottsdale."),be("What are the Canal Convergence hours each night?","The installations are on from 6 p.m. every night: 6 to 10 p.m. on Friday and Saturday, November 6 and 7, and again November 13 and 14; 6 to 9 p.m. Sunday, November 8, through Thursday, November 12; and 6 to 9 p.m. on Sunday, November 15, the closing night.","That makes four late nights, the two Friday-Saturday pairs, and six earlier ones. A dinner-first plan fits the Friday and Saturday nights best; a family with young children often prefers a weeknight and an early walk.","Scottsdale Arts has not yet published the times of the workshops, performances or fire shows; it says that programme information is coming soon. Check its Canal Convergence page before you set the pickup."),be("Where do you park for Canal Convergence?","Scottsdale Arts publishes no event parking plan, but the City of Scottsdale says every public garage in Old Town is free and street parking has a three-hour limit; the city’s Old Town map marks public lots and garages on both banks of the canal around the Waterfront and the Soleri Bridge, and a chauffeured group skips parking altogether.","Old Town is compact, and the city says wherever you park you will not be far from the action. The catch on a busy November evening is the garage nearest the water, and a three-hour street limit that a dinner and a long art walk can outlast.","With a chauffeur, the parking question goes away: the group steps out where staff and police direct, walks the canal, and walks back to a vehicle that has been waiting nearby. Nobody circles the garages, and nobody drives home after the night out."),be("How do you get to Canal Convergence without driving?","By rideshare or a chauffeured ride: the City of Scottsdale says rideshare is widely available in Old Town, from Lyft, Uber and Waymo; no Canal Convergence drop-off zone is published, so a driver drops where staff and police direct near the Waterfront.","A booked ride keeps the group together from the resort or home to the canal and back, and the vehicle waits through dinner and the walk, so there is no queue for a car at 10 on a Saturday night.","If the night goes on to the bars of the Entertainment District, the city’s Transportation Safety Zone covers that district, east of Buckboard Trail from Sixth Avenue to Camelback Road, every night from 5 p.m.: hired vehicles load and unload only in the marked vehicle-for-hire lanes and Passenger Convenience Areas, never in a through lane, so your chauffeur stops where the city allows."),be("Is Canal Convergence free, and what is there besides the art?","Yes, Canal Convergence is free; alongside the light installations, Scottsdale Arts lists nightly fire shows, live music and dance performances, family-friendly workshops and activities, special events, rotating food trucks and vendors, and a beer and wine garden.","There is no ticket to buy, so the only booking for the night is dinner and, if you want one, the ride. The food trucks rotate, so the waterfront itself can be dinner for a family or a crew in a hurry.","The beer and wine garden is the event’s. We sell no alcohol, and nothing on this page sells a drink service."),be("What is the 2026 Canal Convergence theme, and which artworks are in it?","The 2026 theme is Western Nature: artworks on the environmental and cultural landscapes of the American West, the Southwest and Arizona, from water and native plants and animals to the region’s cultures and histories; Scottsdale Arts lists 11 artworks, among them APOGEE, Desert Choir, KaKtos, Prairie Fire, Sky Wrangler and Western Fire Garden.","The full list, as Scottsdale Arts prints it: APOGEE by Chalk River Labs (Melbourne, Australia); Another Slice of Reality: An Evolving Nature by Shaoyu Su x LedPulse (Tempe); Dream Rider and Sky Wrangler by William Nemitoff with Curious Form (New Orleans); Desert Choir by Ottomata (Montreal); grandmother turtle by In Theory Art Studios with Laura Tohe and Nora Naranjo-Morse, and the weight of light by In Theory Art Studio (Huntsville, Utah); KaKtos by Amigo & Amigo (Marrickville, Australia); Prairie Fire by True North Absurdities (Calgary); The Way The West Was Sold by Jolly Productions and Western Fire Garden by Walter Productions (Phoenix).","The pieces sit in and above the canal and along its bridges, so walking the whole run takes the group from one bank to the other and back."),be("Is Canal Convergence good for kids and families?",`Yes: Scottsdale Arts lists family-friendly workshops and activities among the event’s highlights, and the art starts at 6 p.m., so a family can walk it early; for a family or school group aboard, our house rule applies: ${Ft}`,"Families ride the executive row on this page: the Executive Sprinters, black or white, and the Mini Bus for a reunion or a youth group. No party unit is offered to a family group.","Put a parent’s or guardian’s cell number on the reservation, so the chauffeur has one point of contact, and set the pickup for the end of the walk rather than the close."),be("What does a chauffeured Canal Convergence night cost?",`An art night is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${y(V)} is ${vr(V)}/hr and seats ${Fe(V)}, a ${y(en)} is ${vr(en)}/hr, the ${y(Ja)} is ${vr(Ja)}/hr; the event itself is free, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${Fe(V)} riders in the ${y(V)} for 4 hours is about ${Ci(V,4,Fe(V))} each before tax. ${Fe(vt)} riders sharing the ${y(vt)} for 5 hours at ${vr(vt)}/hr is about ${Ci(vt,5,Fe(vt))} each. That is arithmetic on the published rates, not a flat event fare.`,"The hours run from the pickup to the drop-off at home, and the vehicle waits in Old Town in between, so dinner, the canal and the ride home are one booking, not three rides. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books.","Not in the fare: dinner, anything bought at the food trucks, vendors or the beer and wine garden."),be("Which vehicle fits a Canal Convergence night?",`Couples and VIP groups lead with the ${y(V)}, our pick for an Old Town art night, then the ${y(Ya)}, the ${y(Ti)} and the Suburban; friends’ crews ride a Limo Party Sprinter or the ${Fe(vt)}-seat party bus; families and company groups take the ${y(Ja)}, the white Executive Sprinter or the ${y($i)}.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. VIP: the ${y(Ya)}, the ${y(V)}, the ${y(Ti)} and the ${y(Xo)}. Friends’ crews: the ${y(en)}, the ${y(Hu)} and the ${y(vt)}. Families and company groups: the ${y(Ja)}, the ${y(zu)} and the ${y($i)}.`,`A VIP party larger than the ${y(V)} rides in two vehicles, one booking each for the same night and times: the ${y(V)} with the ${y(Ya)} seats ${Fe(V)+Fe(Ya)}, and with the ${y(Xo)} it seats ${Fe(V)+Fe(Xo)}.`),be("What is the best night to go, and how does a chauffeured Old Town night work?","For a dinner-and-art night, the Friday and Saturday nights (November 6 and 7, 13 and 14) run to 10 p.m., an hour later than the rest; for a quieter walk or young children, a weeknight from Sunday to Thursday, when the art closes at 9; a chauffeured night is pickup, dinner in Old Town, the walk along the canal, and the ride home.","The plan most groups book: pickup at the resort or home before dinner, a table in Old Town, then the installations along the water from one bank to the other, and the vehicle waiting when the group is done. A crew that wants the bars after adds the hours; the chauffeur moves the vehicle with the group.","Opening weekend and closing weekend are the nights most groups ask for, so book those first. A group with a flexible date gets the best choice of vehicles midweek."),be("How far ahead should a Canal Convergence ride be booked?","Availability varies by night and vehicle, so no fixed lead time applies; the Friday and Saturday nights go first. Send the night, the rider count, the pickup address and the dinner reservation, and the reservations team confirms what is open.","The first request needs the night, the hotel, resort or home pickup, a likely passenger count and the dinner time. A group does not need every name to begin. It does need to say which group is riding: a couple or VIP guests, a friends’ crew, or a family or company group with anyone under 21.",`During the final 48 hours, confirm addresses, phone numbers and the dinner time. Reach the reservations team at ${u} or ${p}.`)],Yu=[{question:"When is Canal Convergence 2026?",answer:"November 6 to 15, 2026: ten nights at the Scottsdale Waterfront in Old Town Scottsdale, from 6 p.m. each night."},{question:"Is Canal Convergence free?",answer:"Yes. Scottsdale Arts calls it a free, 10-night public art event; there is no ticket to buy."},{question:"Where is Canal Convergence?",answer:"At the Scottsdale Waterfront, in and above the Arizona Canal and along its pathways and bridges between Scottsdale Road and Goldwater Boulevard. The address Scottsdale Arts prints is Solstice Park, 4420 N Scottsdale Rd, Scottsdale, AZ 85251."},{question:"Is parking free at Canal Convergence?",answer:"Scottsdale Arts publishes no event parking plan; the City of Scottsdale says all Old Town public garages are free and street parking has a three-hour limit. A chauffeured group skips parking altogether."},{question:"What time does Canal Convergence close?",answer:"At 10 p.m. on Friday and Saturday, November 6, 7, 13 and 14, and at 9 p.m. Sunday through Thursday, including the closing night, Sunday, November 15."},{question:"What is the 2026 Canal Convergence theme?",answer:"Western Nature: artworks on the landscapes, water, plants, animals, cultures and histories of the American West, the Southwest and Arizona."},{question:"Can you rent a party bus or limo for Canal Convergence?",answer:`Yes. The ${y(V)}, the Limo Party Sprinters and the ${y(vt)} are booked by the hour, pickup to drop-off, and wait in Old Town for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],Ju={path:"/guides/canal-convergence-scottsdale",title:"Canal Convergence 2026 in Scottsdale: dates, hours, parking and a chauffeured art night",metaTitle:"Canal Convergence Scottsdale 2026",description:"Canal Convergence 2026 at the Scottsdale Waterfront, November 6 to 15: the nightly hours, where it is, free Old Town parking and rideshare, the Western Nature artworks, families, and a chauffeured Old Town art night so the group stays together and nobody drives.",metaDescription:"Canal Convergence 2026, Nov 6-15: hours, location, free parking, the artworks, or a chauffeured Old Town art night",lastUpdated:Ai,lastUpdatedLabel:l(Ai),eyebrow:"Free · ten nights · November 6 to 15",intro:`An art night with Scottsdale Sprinters starts with the event’s own dates, the night you want and a rider count. Couples and VIP groups lead with the ${y(V)}; friends’ crews ride a Limo Party Sprinter or the party bus; families and company groups take the Executive Sprinter or the Mini Bus, alcohol-free. This guide uses only published facts, from Scottsdale Arts and the City of Scottsdale, and turns the night into a written pickup, dinner, art walk and ride home.`,sections:Vu,faqs:Yu,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:y(V)},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:y(Ya)},{href:"/fleet/executive-sprinter-scottsdale",label:y(Ja)},{href:"/service-areas/scottsdale",label:"Scottsdale service area"},{href:"/services/scottsdale-chauffeur-service",label:"Scottsdale chauffeur service"},{href:"/pricing",label:"Published hourly pricing"}],sources:qu,fleetRows:Bu},Pi="2026-09-27",Zu="/guides/venues/celebrity-theatre",Ku=1e3,go=h(Ku),Jt="ultra-luxury-party-sprinter-scottsdale",tn="maybach-jet-sprinter-scottsdale",ju="maybach-shuttle-sprinter-8",Qu="premium-suv-scottsdale",Zt="limo-sprinter-13-scottsdale",an="limo-sprinter-16-scottsdale",rn="party-bus-28-scottsdale",Kt="executive-sprinter-scottsdale",Xu="executive-white-sprinter-scottsdale",on="executive-mini-bus-26-scottsdale",nn="executive-luxury-bus-29-scottsdale",E=e=>n[e],ut=e=>i[e],sn=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,Ao="https://www.celebritytheatre.com",ep=`${Ao}/`,tp=`${Ao}/faq-s`,ap=`${Ao}/about-6`,rp=`${Ao}/all-events`,op=[{label:"Celebrity Theatre, home page (address, parking, box office hours, Encore Lounge)",href:ep},{label:"Celebrity Theatre, FAQs (parking, rideshare, clear bag policy, capacity, stage)",href:tp},{label:"Celebrity Theatre, about the theatre",href:ap},{label:"Celebrity Theatre, upcoming events",href:rp}],kd=["January","February","March","April","May","June","July","August","September","October","November","December"],np=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function sp(e){const[t,a,o]=e.split("-").map(Number);return`${np[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${kd[a-1]} ${o}, ${t}`}function Ei(e){const[,t,a]=e.split("-").map(Number);return`${kd[t-1]} ${a}`}function ip(e){return`${sp(e.date)}: ${e.title} (show ${fa(`${e.date}T${e.starts}:00-07:00`)}).`}function Xe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const lr=Jd,Fi=lr[0],Mi=lr[lr.length-1],hp=[Xe("How does parking work at Celebrity Theatre?",`Celebrity Theatre parks its guests in its own secured lot at 440 North 32nd Street for ${go} per vehicle, paid in cash or by card on arrival, or bought early at checkout with your online ticket; the venue recommends arriving early for a sold-out show or for accessible parking.`,`A limited number of accessible (ADA) spaces sit at the East entrance, directly off the 32nd Street entrance, first come first served, for the same ${go} per vehicle; the wheelchair ramp is at that East entrance too.`,"The venue names no second lot and publishes no overflow parking, so on a sold-out night the lot is the thing to arrive early for."),Xe("Where is the drop-off at Celebrity Theatre?","Celebrity Theatre sends rideshare drivers to a walk-through gate on Filmore Street, just west of 32nd Street, and asks that they do not enter through the paid parking entrance, to avoid delays; that gate is the one drop-off point the venue publishes for guests who are dropped off rather than parked.","It is the point we use for a chauffeured group too. We unload the group at the Filmore Street gate, not in the paid lot, and agree one pickup point there for the ride home before the show.","The venue publishes no separate area for limousines or charters, so no curb is held for booked vehicles. If the venue posts a different plan for a show, that plan comes first.","A group that splits across cars also splits across the parking line and the walk in. One vehicle arrives with everyone at once and leaves with everyone at once."),Xe("Where is Celebrity Theatre, and how do you get there?","Celebrity Theatre is at 440 North 32nd Street, Phoenix, AZ 85008; guests driving in use the paid parking entrance to the secured lot, and guests arriving by rideshare use the walk-through gate on Filmore Street just west of 32nd Street.","The theatre is a round building, designed in 1963 as a conference center that could turn into a concert venue in the winter months, and it opened on January 13, 1964 with the musical South Pacific.","A chauffeured group needs no directions: the driver takes the group to the Filmore Street gate and waits for the ride home."),Xe("When should you arrive at Celebrity Theatre?","Arrive early at Celebrity Theatre: the venue wands every guest with a metal detector at all shows and asks guests to allow extra time for it, and its Encore Lounge opens 2 hours before showtime for anyone who wants to be there before the music starts.","The venue publishes no doors time for its seats; the ticket and the show page have the show time.","The box office is open Monday to Friday from 10 a.m. to 2 p.m., and from 12 p.m. on show days. Will call needs a valid photo ID, and a ticket bought by card is released only to the cardholder with the card and a photo ID. Children 12 months and under may enter without a ticket, on an adult’s lap.","The theatre serves food upstairs, charcuterie boxes, nachos, hot dogs, popcorn and pretzels among it, and has 5 bars that pour seasonal and specialty drinks, mocktails included."),Xe("What is the Celebrity Theatre bag policy?","Celebrity Theatre has a clear bag policy: clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, and small clutch bags up to 4.5 by 6.5 inches; no backpacks, and the venue wands every guest at every show.","Not allowed inside: Sharpies, pens and markers, outside food or beverages of any kind, smoking of any kind, firearms, knives, chains or weapons of any kind, backpacks and selfie sticks. Professional cameras with a detachable lens over 2 inches long, and video and audio recording devices, are not permitted.","Strollers are not allowed inside, and the venue has no storage room for them; walkers fold in front of the seat outside accessible seating. Call the box office at (602) 267-1600 for medical clearance of a prohibited item.","Settle bags before you leave: a group that is dropped off has no car in the lot to go back to during the show."),Xe("What is the seating like at Celebrity Theatre, and how many people does it hold?","Celebrity Theatre holds 2,606 in the round, 1,845 as a three-quarter house and 1,406 as a half house, around an extremely rare revolving stage, and no seat is more than 70 feet from the artist.","In the round the stage rotates through the show and faces no one direction; as a half or three-quarter house it faces the artist ramp, between sections A6 and A7. Which layout a show uses is on its seating chart when you pick the ticket.","Infrared assisted listening devices are available at every performance, free from guest services on the night or on request in advance, and sign language interpretation needs at least three weeks’ notice.","For a group, the round room means every seat is close: book the seats together and the ride together, and the night stays together."),Xe("Which vehicle fits a Celebrity Theatre group?",`A VIP night takes the ${E(tn)}, the ${E(Jt)}, the ${E(ju)} or the ${E(Qu)}. Friends and birthday crews ride the ${E(Zt)}, the ${E(an)} or the ${E(rn)}. Company nights and big groups take the ${E(Kt)}, the ${E(Xu)}, the ${E(on)} or the ${E(nn)}.`,`Seat counts are seated capacities from the fleet: the ${E(Jt)} seats ${ut(Jt)}, the ${E(Zt)} ${ut(Zt)}, the ${E(an)} ${ut(an)}, the ${E(rn)} ${ut(rn)} and the ${E(tn)} ${ut(tn)}. The ${E(Kt)} seats ${ut(Kt)}, the ${E(on)} ${ut(on)} and the ${E(nn)} ${ut(nn)}.`,`Our pick for a show night at the theatre is the ${E(Jt)}, ${sn(Jt)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${E(Zt)} is ${sn(Zt)}, and the ${E(Kt)} is ${sn(Kt)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),Xe("How should a group plan the ride to a Celebrity Theatre show?","Plan backwards from the show time on the ticket, and leave room for the metal-detector wanding every guest goes through; a group that wants the Encore Lounge before the show can arrive up to 2 hours ahead, when it opens.","The ride home is the part to plan hardest. Agree the pickup point at the Filmore Street gate before the show, and your chauffeur is there when the house lights come up, so the group walks out to its own vehicle instead of the parking line.","The venue publishes no age rule for its shows. If even one passenger is under 21, the trip is alcohol-free for the whole group, adults included; we sell no alcohol on any trip.",`Book by the hour and the vehicle is yours for the whole night, dinner before the show included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the date, the pickup area and the rider count.`)],dp=Xe("What’s coming up at Celebrity Theatre?",`Coming up at Celebrity Theatre this fall, among the shows the venue lists: ${lr.length} nights from ${Fi.label} on ${Ei(Fi.date)} to ${Mi.label} on ${Ei(Mi.date)}, 2026, including Chris Isaak, Dweezil Zappa, Don McLean, Todd Rundgren, The Psychedelic Furs and Alice Cooper’s Christmas Pudding. As the venue’s events list gave them on September 27, 2026:`,...lr.map(ip),"The Encore Lounge opens two hours before each show. New shows are added to the venue’s calendar through the year, and it is the place to check before you book."),lp=[{question:"How much is parking at Celebrity Theatre?",answer:`${go} per vehicle in the venue’s secured lot, cash or card on arrival, or bought early at checkout with your online ticket.`},{question:"Where do Uber and Lyft drop off at Celebrity Theatre?",answer:"At the walk-through gate on Filmore Street, just west of 32nd Street. The venue asks that drivers do not enter through the paid parking entrance. A chauffeured group unloads there too."},{question:"What is the bag policy at Celebrity Theatre?",answer:"Clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, and small clutch bags up to 4.5 by 6.5 inches. No backpacks, no outside food or beverages, and no pens or markers."},{question:"How many seats does Celebrity Theatre have?",answer:"The venue lists 2,606 in the round, 1,845 as a three-quarter house and 1,406 as a half house."},{question:"Does the stage at Celebrity Theatre rotate?",answer:"In the round, yes: the revolving stage turns through the show and faces no one direction. As a half or three-quarter house it faces the artist ramp between sections A6 and A7."},{question:"Is there a bad seat at Celebrity Theatre?",answer:"The venue says no seat is more than 70 feet from the stage."},{question:"What time does Celebrity Theatre open?",answer:"The Encore Lounge opens two hours before showtime. The venue publishes no separate doors time for the seats, and wands every guest at every show, so arrive early."},{question:"What are the Celebrity Theatre box office hours?",answer:"Monday to Friday, 10 a.m. to 2 p.m., and from 12 p.m. on show days. Will call needs a valid photo ID."},{question:"Do children need a ticket at Celebrity Theatre?",answer:"Children 12 months and under may enter without a ticket, sitting on an adult’s lap."},{question:"Where is Celebrity Theatre?",answer:"At 440 North 32nd Street, Phoenix, AZ 85008. The accessible parking and the wheelchair ramp are at the East entrance, off 32nd Street."}],cp={path:Zu,title:"Celebrity Theatre Parking Guide: Seating in the Round, Drop-Off and Upcoming Shows",metaTitle:"Celebrity Theatre Parking and Seating",description:"Celebrity Theatre in Phoenix: the secured lot and its fee, the Filmore Street drop-off gate, the clear bag policy, the revolving stage and seating in the round, the upcoming shows, and a chauffeured ride so nobody drives or parks.",metaDescription:"The lot, the drop-off gate, the bag policy and a chauffeured ride",lastUpdated:Pi,lastUpdatedLabel:l(Pi),eyebrow:"Phoenix · 32nd Street",intro:`Scottsdale Sprinters’ short answer on Celebrity Theatre parking: the theatre parks guests in its own secured lot at 440 North 32nd Street for ${go} per vehicle, cash or card, and sends rideshare drop-offs to a walk-through gate on Filmore Street, just west of 32nd Street. The theatre seats 2,606 in the round around a revolving stage, no seat more than 70 feet from the artist, and every guest is wanded at the door, so arrive early. For a group, one chauffeured vehicle replaces the lot, the line and the drive home.`,sections:[...hp,dp],faqs:lp,links:[{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts 2026–27, every show by venue"},{href:"/guides/venues/arizona-financial-theatre",label:"Arizona Financial Theatre parking and shows"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:`/fleet/${Jt}`,label:E(Jt)},{href:`/fleet/${Zt}`,label:E(Zt)},{href:`/fleet/${Kt}`,label:E(Kt)},{href:"/pricing",label:"Published hourly pricing"}],sources:op},Ri="2026-09-27",up="/guides/christmas-lights-scottsdale-phoenix",q="ultra-luxury-party-sprinter-scottsdale",Ga="maybach-jet-sprinter-scottsdale",xi="maybach-shuttle-sprinter-8",Ot="premium-suv-scottsdale",oe="executive-sprinter-scottsdale",hn="executive-white-sprinter-scottsdale",dn="executive-mini-bus-26-scottsdale",ln="executive-luxury-bus-29-scottsdale",kr="motorcoach-56",ba="party-bus-28-scottsdale",cn="limo-sprinter-13-scottsdale",c=e=>n[e],K=e=>i[e],Dt=e=>h(r[e].hourlyRateCents),ua=e=>r[e].minimumHours,un=(e,t)=>h(r[e].hourlyRateCents*Math.max(t,ua(e))),Di=(e,t,a)=>h(Math.round(r[e].hourlyRateCents*Math.max(t,ua(e))/a));function B(e,t,...a){return{question:e,answer:t,paragraphs:a}}const pp="https://www.christmasattheprincess.com/",fp="https://www.christmasattheprincess.com/faq",mp="https://fairmontscottsdaleprincess.ticketspice.com/2026-christmas-at-the-princess",gp="https://www.phoenixzoo.org/events/zoolights/",yp="https://www.phoenixzoo.org/visit/",bp="https://www.phoenixzoo.org/events/sensory-friendly-zoolights/",wp="https://www.phoenixzoo.org/events/cruise-zoolights/",vp="https://dbg.org/events/las-noches-de-las-luminarias/",kp="https://dbg.org/explore/private-events-rentals/rental-faqs/",Sp="https://www.glendaleaz.gov/Explore/Special-Events/Events",Ap="https://www.glendaleaz.gov/News/Whats-New/Glendale-Glitters-Returns",Tp="https://scottsdazzle.com/",$p="https://scottsdazzle.com/event/tree-lighting-spectacular-celebrating-75-years-of-scottsdale/",Cp="https://oldtownscottsdaleaz.com/events/scottsdazzle/",Pp="https://oldtownscottsdaleaz.com/get-around/public-parking/",Ep="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",Fp="https://desertfarmlights.com/",Mp="https://www.mesatemple.org/christmas",Rp="https://mortgagematchupcenter.com/events/transsiberian-orchestra/",xp="https://www.desertdiamondarena.com/events-tickets/",Dp="https://www.worldofillumination.com/locations/tempe-arizona-diablo-stadium-christmas",Ip="https://www.worldofillumination.com/",Np="https://www.therailroadpark.com/event/holiday-lights/",Wp="https://www.chandleraz.gov/events/tumbleweed-tree-lighting-ceremony",Lp="https://www.downtowntempe.com/do/fantasy-of-lights-street-parade-tree-lighting-1",Op="https://www.downtowntempe.com/events/fol-boat-parade",_p="https://www.phoenix.gov/administration/departments/parks/classes-programs/featured-events/aps-electric-light-parade.html",Gp="https://www.prattbrotherschristmas.com/purchase-tickets",Up="https://www.prattbrotherschristmas.com/faq",Bp="https://lightupahwatukee.org/about-lua",Hp="https://www.abc15.com/news/uplifting-arizona/scottsdale-neighborhood-lights-up-for-good-cause-through-christmas-day",zp="https://www.abc15.com/news/local-news/watch-christmas-in-gilberts-agritopia-neighborhood",qp=[{label:"Christmas at the Princess, official site",href:pp},{label:"Christmas at the Princess FAQ: tickets, parking and rideshare",href:fp},{label:"Christmas at the Princess 2026 tickets and parking",href:mp},{label:"Phoenix Zoo, ZooLights 2026-27",href:gp},{label:"Phoenix Zoo, hours and visit",href:yp},{label:"Phoenix Zoo, Sensory Friendly ZooLights",href:bp},{label:"Phoenix Zoo, Cruise ZooLights",href:wp},{label:"Desert Botanical Garden, Las Noches de las Luminarias",href:vp},{label:"Desert Botanical Garden, parking and arrival (rental FAQ)",href:kp},{label:"City of Glendale, special events: Glendale Glitters",href:Sp},{label:"City of Glendale, Glendale Glitters 2024 release (last year’s parking)",href:Ap},{label:"Scottsdazzle, City of Scottsdale",href:Tp},{label:"Scottsdazzle Tree Lighting Spectacular",href:$p},{label:"Old Town Scottsdale, Scottsdazzle",href:Cp},{label:"Old Town Scottsdale, public parking",href:Pp},{label:"City of Scottsdale, Transportation Safety Zone",href:Ep},{label:"Desert Farm Lights, official site (2026 season)",href:Fp},{label:"Mesa Arizona Temple, Christmas lights",href:Mp},{label:"Mortgage Matchup Center, Trans-Siberian Orchestra",href:Rp},{label:"Desert Diamond Arena, events and tickets",href:xp},{label:"World of Illumination, Tempe (Tempe Diablo Stadium), 2026",href:Dp},{label:"World of Illumination, all locations (Tempe and Glendale)",href:Ip},{label:"McCormick-Stillman Railroad Park, Holiday Lights 2026",href:Np},{label:"City of Chandler, Tumbleweed Tree Lighting 2026",href:Wp},{label:"Downtown Tempe, Fantasy of Lights Street Parade and Tree Lighting 2026",href:Lp},{label:"Downtown Tempe, Fantasy of Lights Boat Parade 2026",href:Op},{label:"City of Phoenix, APS Electric Light Parade",href:_p},{label:"Pratt Brothers Christmas, tickets",href:Gp},{label:"Pratt Brothers Christmas, FAQ",href:Up},{label:"Light Up Ahwatukee, the Chandler Boulevard lights",href:Bp},{label:"ABC15, Christmas Street in Grayhawk (news report)",href:Hp},{label:"ABC15, Christmas in Agritopia (news report)",href:zp}],Ii=xa.find(e=>e.fact==="DE11"),Ni=xa.find(e=>e.fact==="DE12"),Vp=["January","February","March","April","May","June","July","August","September","October","November","December"],Wi=e=>{const[,t,a]=e.split("-").map(Number);return`${Vp[t-1]} ${a}`},Yp=27,Jp=2,de={oldTownToGarden:9,zooToOldTown:10,oldTownToRailroad:7,railroadToPrincess:18,princessToGrayhawk:9,grayhawkToKierland:11,oldTownToAhwatukee:28,ahwatukeeToAgritopia:21,agritopiaToMesaTemple:21,mesaTempleToOldTown:25},Zp=[B("When is Christmas at the Princess 2026, and how do parking and drop-off work?","Christmas at the Princess runs nightly from Friday, November 20, 2026, through Saturday, January 2, 2027, at the Fairmont Scottsdale Princess, 7575 E Princess Dr. Parking is a separate paid ticket bought with admission; self-parkers follow the signs onto Cottage Terrace Drive, and rideshare guests are dropped at the Enchanted Plaza.","The resort publishes its hours by the day of the week: 5 to 10 p.m. Monday to Thursday, and 4 to 11 p.m. Friday to Sunday; from December 17 it is 4 to 11 p.m. every night. November 20 is a Friday, so opening night starts at 4 p.m., and the last night, Saturday, January 2, keeps the same hours. There are no closed nights. On November 30 the resort’s village is closed for a private event, so the Ferris wheel, the sledding and the mini golf are shut that night and tickets are priced lower.","Tickets are booked online in advance for a date, with no entry time. The organiser says it is a ticketed event with limited availability that often sells out, and it does not recommend waiting to buy on site. Children 3 and under enter free, the event is cashless, and tickets bought from resellers are not honored. Book only on the event’s own 2026 ticket page.","Admission and parking are separate. A self-parking or valet ticket is required to park on the property, and parking costs more when it is bought on arrival. Self-parkers follow the signs onto Cottage Terrace Drive, where an attendant scans tickets and hands out wristbands; valet guests go to the hotel’s front drive.","Guests who arrive by rideshare follow the signs to the ride-share drop-off in the Enchanted Plaza, where staff scan tickets and hand out wristbands. The resort publishes no drop-off for a limousine, a charter or a Sprinter, so our chauffeur unloads where resort staff direct. If the vehicle is to wait on the property through your visit, ask us when you book whether it needs a parking ticket of its own.","For dinner, the organiser names Bourbon Steak, La Hacienda and Toro Scottsdale at the resort, recommends reservations there, and suggests making them at least one month ahead. Santa is there until Christmas Eve."),B("When is ZooLights 2026 at the Phoenix Zoo, and where do you park?","ZooLights runs from Wednesday, November 25, 2026, to Friday, January 15, 2027, from 5:30 to 10:30 p.m., at the Phoenix Zoo, 455 North Galvin Parkway. When the main lots fill, message boards send drivers to the overflow lot at Phoenix Municipal Stadium, about a 15-minute walk away; the Zoo mentions no shuttle.","The overflow lot is at the southwest corner of Van Buren and Priest, and the walk from it is on a lit, paved path. The Zoo asks guests to carpool and to watch the message boards on the approach. It publishes no rideshare, limousine or bus drop-off for ZooLights, so the chauffeur unloads where Zoo staff direct and meets the group at a point agreed before you walk in.","Tickets go on sale October 1 and are good for any one public night of the season: there is no date and no entry time on them. Children 2 and under are free, tickets are non-refundable, and group tickets are sold when 50 or more are bought in advance. ZooLights is open on Christmas night; the Zoo itself is closed that day.","The Zoo’s own advice on crowds: Monday, Tuesday and Wednesday are the quietest nights, the first two weeks of December and all of January are less busy, and most guests arrive when the gates open, so arriving around 7:30 or 8 p.m. can make entry smoother. It is five million lights on over two miles of trail, and most animals are not visible at night.","Two nights are ticketed on their own. Sensory Friendly ZooLights is Tuesday, December 8, 2026, with smaller crowds, quieter music and reduced flashing lights. Cruise ZooLights, a drive-through night on Sunday, January 17, 2027, admits vehicles no larger than a full-size long-bed truck, so it is not a night for a Sprinter or a coach."),B("When is Las Noches de las Luminarias 2026 at the Desert Botanical Garden?","Las Noches de las Luminarias runs 26 nights from 5:30 to 9:30 p.m. at the Desert Botanical Garden, 1201 North Galvin Parkway: November 27 to 29, December 4 to 6, December 11 to 13, December 16 to 23, December 26 to 31, and January 1 to 3, 2027. There are no nights on December 24 or 25.","Member tickets go on sale October 1 and general admission tickets on October 16. December 4 to 6 is Members Weekend. Whether entry is timed is not stated on the 2026 page; it is announced closer to the date, so check the Garden’s ticket page when you buy.","The Garden has published no parking, overflow or shuttle plan for Luminarias. Its standing guidance, written for private events, says the Garden has complimentary on-site parking with over 600 spaces and bus parking, and that guests are welcome to arrive by ride-share. With a chauffeur, the group is dropped where Garden staff direct and nobody looks for a space.","During Luminarias the Garden recommends reserving Gertrude’s by Tarbell’s through OpenTable. The Garden closes to daytime visitors at 4 p.m. on many event days, so an afternoon visit and the evening event are separate plans."),B("When is Glendale Glitters 2026?","Glendale Glitters returns to Murphy Park in Historic Downtown Glendale for its 33rd year: the lighting ceremony is at 5:45 p.m. on Friday, November 27, 2026, the kickoff event runs November 27 and 28 from 5 to 10 p.m., and the lights stay on nightly through January 1, 2027, from 5 to 10 p.m.","The City of Glendale’s 2026 page gives Murphy Park in Historic Downtown Glendale as the place and no street address. Last year’s lighting was in front of the Glendale Civic Center.","The city has not published 2026 parking for Glendale Glitters; it is announced closer to the date. Two years ago, in its 2024 release, the city pointed drivers to free parking in the downtown garage at 5835 W. Palmaire Ave. and on surface streets. With a chauffeured ride the group is dropped close to the park where traffic staff allow, and the vehicle comes back at a time you set.","Glitter and Glow and any other special Glitters night have no official 2026 dates, so they are not on this page."),B("When is Scottsdazzle 2026 in Old Town Scottsdale?","Scottsdazzle, the City of Scottsdale’s holiday season in Old Town, kicks off on Saturday, November 28, 2026, with the Tree Lighting Spectacular at the Scottsdale Waterfront Canal Bank, 7135 E Camelback Rd, from 7 to 9 p.m., and runs through December 31, 2026, throughout Old Town Scottsdale.","The tree lighting is free and lights a 36-foot Scottsdazzle tree; this year it celebrates 75 years of Scottsdale. The city’s event calendar lists more evenings through December, and it says the full 2026 program is announced closer to the date, so check it before you set the night.","Old Town parking is free: every public garage is free, and street parking has a three-hour limit. Old Town is compact and walkable once you are there.","Old Town Scottsdale’s Transportation Safety Zone is in effect every night from 5 p.m. to 4 a.m. While it is in effect, hired vehicles load and unload only at the marked Passenger Convenience Areas and vehicle-for-hire lanes, never in a through lane, so your chauffeur stops where the city allows."),B("Can you see two holiday light displays in one night?",`Yes. ZooLights and Las Noches de las Luminarias are both on North Galvin Parkway in Phoenix, about ${Jp} minutes apart by car, and Christmas at the Princess is about ${Yp} minutes from the Phoenix Zoo in typical traffic. Book the vehicle by the hour and it waits between the stops, so the second display is a short, warm ride.`,"Those drive times are Google’s typical times without event traffic, measured on September 24, 2026. From Kierland the Princess is about 7 minutes; from Old Town Scottsdale about 22; from Sky Harbor or the Phoenician about 27; and from Historic Downtown Glendale about 34. The drive-time map on this page lists them.","Plan around the hours. ZooLights runs 5:30 to 10:30 p.m. and Luminarias 5:30 to 9:30 p.m., so the Garden goes first when you pair them. Christmas at the Princess opens at 4 or 5 p.m. and closes at 10 or 11 p.m., depending on the night, and Glendale Glitters is lit from 5 to 10 p.m. The Princess ticket is for a date and the ZooLights ticket for any one night, and neither carries an entry time.","One display with dinner fits the 4-hour minimum. Two displays usually take 5 or 6 hours, and three a longer evening. The hours you book cover the wait while you walk the lights, and a stop inside those hours costs nothing extra."),B("Which vehicle fits a family, a date night or an office party?",`Families and friends start with the ${c(oe)} (${K(oe)} seats) or the ${c(dn)}; date nights and VIP groups take the ${c(Ot)}, the ${c(Ga)} or our pick, the ${c(q)} (${K(q)} seats); office parties take the ${c(hn)}, the ${c(ln)} or the ${c(kr)}.`,`The ${c(q)} is our flagship for a lights night: fiber-optic lighting with eighteen modes takes the cabin from a dance party to something as quiet as candlelight, and it seats ${K(q)}. For a couple, the ${c(Ot)} is black on black with heated leather captain’s seats; the ${c(Ga)} (${K(Ga)} seats) and the ${c(xi)} (${K(xi)}) are the Maybach cabins.`,`For a family, the ${c(oe)} has black leather seats that each recline, with room for strollers, coats and bags; the ${c(dn)} seats ${K(dn)} for an extended family.`,`An office holiday party takes the ${c(hn)} (${K(hn)} seats), the ${c(ln)} (${K(ln)}) or, for the whole company, the ${c(kr)} (${K(kr)}). The motorcoach photos on this page are representative; the assigned coach is confirmed in writing. Count everyone who rides, plus coats and anything bought at the displays.`),B("What does a chauffeured holiday lights night cost?",`Every vehicle is booked by the hour with a ${ua(oe)}-hour minimum (the motorcoach ${ua(kr)}): 4 hours in the ${c(oe)} is ${un(oe,4)} before tax, about ${Di(oe,4,K(oe))} each for ${K(oe)} riders; the ${c(q)} is ${un(q,4)}, about ${Di(q,4,K(q))} each for ${K(q)}; the ${c(Ot)} is ${un(Ot,4)} for a date night.`,`Those are the published hourly rates times the hours, before ${xs}% Arizona sales tax: ${Dt(oe)} an hour for the ${c(oe)}, ${Dt(q)} for the ${c(q)}, ${Dt(Ot)} for the ${c(Ot)} and ${Dt(Ga)} for the ${c(Ga)}. The fare belongs to the vehicle, so one more rider does not change it. Admission and any parking at the displays are bought from the organisers, not from us.`,"The packages on this page add extras from our catalog to a vehicle and a set of hours, priced the same way: the Lights Crawl, Princess Date Night, the Family Lights Tour and the Holiday Crew Night. Checkout shows exactly what is charged today and when any balance is due.",`Call ${u} or email ${p} with the night, the pickup address and the rider count, and we confirm what is open. Availability varies by night and by vehicle.`),B("When is Desert Farm Lights 2026, and where is it?","Desert Farm Lights is open nightly from November 20 to December 27, 2026, and closed on Christmas Day, at 14629 W. Peoria Ave in Surprise, in the West Valley. It opens at 5 p.m., closes at 10 p.m. Sunday to Thursday and 11 p.m. Friday and Saturday, and parking is free.","The week of Christmas it stays open until 11 p.m. every night. The gate entrance closes one hour before the display does, so on a 10 p.m. night arrive by 9 p.m. It is a walk-through display with attractions, the organiser calls it a mostly cashless event, and children under 3 get in free.","Buy tickets on the organiser’s own site. Surprise is on the far side of the Valley from Scottsdale, so the drive is the long part of the night: book by the hour, and the vehicle waits in the free lot while you walk the lights and brings everyone home."),B("Which Christmas concerts are on in Phoenix this season?",`Three holiday shows are on the arena calendars: Trans-Siberian Orchestra at Mortgage Matchup Center on Sunday, December 6, 2026, at 3 p.m. and 7:30 p.m.; the Ugly Sweater Holiday Party at Desert Diamond Arena on ${Wi(Ii.dates.start)}; and Pentatonix at Desert Diamond Arena on ${Wi(Ni.dates.start)}.`,`Trans-Siberian Orchestra plays its 30th Anniversary Winter Tour, with doors an hour before each show. The Ugly Sweater Holiday Party brings Sublime, Slightly Stoopid and Codefendants, with the show at ${Ea(Ii.starts)}; Pentatonix starts at ${Ea(Ni.starts)}. Both are in Glendale, beside State Farm Stadium.`,"A concert and the lights fit one booking. The TSO matinee leaves the evening for ZooLights, which runs 5:30 to 10:30 p.m., or for Christmas at the Princess, which opens at 4 p.m. on Sundays. Our Trans-Siberian Orchestra page has the arena’s parking and drop-off."),B("Can we book a Christmas lights party bus or limo?",`Yes. For friends, our pick is the ${c(q)}, ${K(q)} seats under fiber-optic lighting; a bigger group takes the ${c(ba)} (${K(ba)} seats), and a classic limo night takes the ${c(cn)}. Each is booked by the hour with a ${ua(ba)}-hour minimum, so it waits while you walk the lights.`,`Rates are per vehicle, before tax: ${Dt(q)} an hour for the ${c(q)}, ${Dt(ba)} for the ${c(ba)} and ${Dt(cn)} for the ${c(cn)}. A lights crawl of two displays usually takes 5 or 6 hours; tell us the stops and we quote the whole night.`,"Drinks on board are for riders 21 and over. A family night with children fits the Executive Sprinter better, and an office party the mini coach; both are among this page’s groups."),B("Is there a drive-through Christmas light show near Phoenix in 2026?","Yes. World of Illumination runs two: at Tempe Diablo Stadium from November 13, 2026 to January 3, 2027, Tuesday to Sunday, with gates at 6 p.m. and last entry at 10 p.m., and a new show at Camelback Ranch in Glendale from November 12 to January 3. Tickets are sold online only, priced per vehicle.","The drive takes about 20 to 30 minutes, depending on the night’s traffic, with the synced music tuned in the car, and the organiser says weeknights move faster than weekends. Tempe Diablo Stadium has no concessions; outside food and non-alcoholic drinks are welcome in the vehicle.","The organiser does not publish whether a limo, Sprinter or bus can drive the route, so check with the show before planning a drive-through night in a large vehicle. The walk-through displays above have no such question: the vehicle waits while you walk the lights."),B("Are there free Christmas lights in Phoenix, like the Mesa Temple?","Yes. The Mesa Arizona Temple lights, at 101 S. LeSueur in downtown Mesa, are free, and the Scottsdazzle tree lighting in Old Town is free too. The temple has not published its 2026 dates; they are announced closer to the date. In 2025 the lights ran nightly from November 28 to December 30, 5 to 10 p.m.","For last season, the temple pointed visitors to free parking at the city’s Park and Ride lot at the northeast corner of Mesa Drive and Main Street. A chauffeured group is dropped where traffic allows and picked up at a time you set."),B("Which Phoenix-area neighborhoods have the best Christmas lights?","Three neighborhood displays are the best known: the million white lights on the medians of Chandler Boulevard in Ahwatukee, the Agritopia neighborhood near Higley and Ray roads in Gilbert, and Christmas Street on Rose Garden Lane in Grayhawk, Scottsdale, a 20-year tradition that collects for St. Mary’s Food Bank. All three are free.","The Chandler Boulevard lights are strung in the medians of the boulevard and are kept by the Foothills Community Association, so they are seen from the road: a good first stop for a Sprinter or a coach.","In Agritopia nearly every home is lit, and the neighbors share it with the Valley for free. Christmas Street, at 76th Way and Rose Garden Lane in Grayhawk, decorates every home on the street and stays lit through Christmas Day; visitors bring canned food or a donation for St. Mary’s Food Bank.","These are residents’ displays, not events: none publishes its dates, so no 2026 nights are announced, and each street sets its own. On these streets we drive slowly, keep the music down and never stop across a driveway; the chauffeur picks the approach that suits the vehicle, and the group sees the lights from the windows or on a short walk."),B("When are the McCormick-Stillman Railroad Park Holiday Lights in 2026?","Holiday Lights at McCormick-Stillman Railroad Park, 7301 E. Indian Bend Rd. in Scottsdale, runs from November 27 to December 30, 2026, from 5:30 to 9:30 p.m., with no lights on December 24 or 25. Tickets go on sale October 26 at 8 a.m., and the park says the event sells out every year.","The ticket includes the train and carousel rides, and children 2 and under are free. Tickets are sold by the City of Scottsdale’s park through its own booking page, so buy there on the morning they open.",`The park is about ${de.oldTownToRailroad} minutes from Old Town Scottsdale and about ${de.railroadToPrincess} from the Fairmont Scottsdale Princess, so the train ride and Christmas at the Princess fit one evening in one vehicle.`),B("Which holiday parades and tree lightings are in Phoenix, Tempe and Chandler in 2026?","Four city events: Tempe’s Fantasy of Lights Street Parade and tree lighting on Saturday, November 28, 2026, on Mill Avenue; the APS Electric Light Parade in Phoenix on Saturday, December 5, at 7 p.m.; Chandler’s Tumbleweed Tree Lighting the same day downtown; and Tempe’s Fantasy of Lights Boat Parade on Saturday, December 12.","The Tempe street parade and tree lighting runs from 4 to 8 p.m. at Centerpoint on Mill, 660-740 S Mill Ave. The Boat Parade, free, runs from 4 to 9 p.m. at Tempe Beach Park on Tempe Town Lake.","The APS Electric Light Parade, the 39th, starts at 7 p.m. at Central Avenue and Montebello Avenue and ends at 7th Street and Indian School Road. The City of Phoenix says viewing spots are first come, first served, and suggests light rail to avoid the traffic; a chauffeured group is dropped near the route where police allow and picked up at a time and a corner you set.","Chandler’s Tumbleweed Tree Lighting is free, from 4:30 to 9 p.m. at 3 S. Arizona Ave. in Downtown Chandler, with the Parade of Lights in the evening; the city lists 11 parking locations and asks guests to carpool and arrive early.","Pratt Brothers Christmas at Rawhide, 5700 W North Loop Rd in Chandler, has not published its 2026 dates; they are announced by the organizer. Its tickets are for one date, parking is free with general admission, children 3 and under are free, and no alcohol of any kind is allowed."),B("What are the best Christmas lights routes by limo or Sprinter?","Three routes work well: the Galvin Parkway pair (Las Noches de las Luminarias, then ZooLights), a North Scottsdale night (the Railroad Park, Christmas at the Princess and Christmas Street in Grayhawk) and an East Valley neighborhoods drive (Ahwatukee, Agritopia and the Mesa Temple). Each fits a booking of 4 to 6 hours.",`The Galvin Parkway pair, on a Luminarias night: Old Town Scottsdale to the Desert Botanical Garden is about ${de.oldTownToGarden} minutes, the Zoo is a minute or two down the road, and the ride back to Old Town is about ${de.zooToOldTown}. The Garden closes first, so walk the luminarias from opening and ZooLights after; 4 or 5 hours covers it.`,`The North Scottsdale night: Old Town to McCormick-Stillman Railroad Park is about ${de.oldTownToRailroad} minutes, the park to Christmas at the Princess about ${de.railroadToPrincess}, the Princess to Christmas Street in Grayhawk about ${de.princessToGrayhawk}, and Grayhawk to Kierland about ${de.grayhawkToKierland}. Book the Railroad Park and the Princess for the same date, and plan 5 or 6 hours.`,`The East Valley neighborhoods drive, all free displays: Old Town to the Chandler Boulevard lights in Ahwatukee is about ${de.oldTownToAhwatukee} minutes, on to Agritopia about ${de.ahwatukeeToAgritopia}, to the Mesa Temple about ${de.agritopiaToMesaTemple}, and back to Old Town about ${de.mesaTempleToOldTown}. That is about an hour and a half on the road, so book 5 hours, on a night the temple lights are on.`,"Those are Google’s typical drive times without holiday traffic, measured on September 27, 2026. December weekends run slower, so book early for them and let the chauffeur plan the approach. Tell us the stops and we price the whole night by the hour."),B("Is a Christmas lights tour good for kids?","Yes. Children 3 and under enter Christmas at the Princess free, children 2 and under enter ZooLights and the Railroad Park Holiday Lights free, and the neighborhood streets and the free city parades cost nothing. Book the Executive Black Sprinter, tell us about car seats when you book, and nobody circles for parking with tired children.","Sensory Friendly ZooLights, on Tuesday, December 8, 2026, has smaller crowds, quieter music and reduced flashing lights. At Desert Farm Lights children under 3 get in free.","The Family Lights Tour package carries no alcohol: it adds drinks for every guest and a sign with the family’s name. Christmas Street in Grayhawk has run a cocoa hut in past seasons, and a stop for the group photo in front of the vehicle is always inside the hours you book.")],Kp=[{question:"What time does Christmas at the Princess open?",answer:"At 5 p.m. Monday to Thursday and 4 p.m. Friday to Sunday, and at 4 p.m. every night from December 17. It closes at 10 p.m. on the 5 p.m. nights and at 11 p.m. on the others. Opening night, Friday, November 20, 2026, starts at 4 p.m."},{question:"When does Christmas at the Princess start and end?",answer:"Nightly from Friday, November 20, 2026, through Saturday, January 2, 2027, at the Fairmont Scottsdale Princess, 7575 E Princess Dr, Scottsdale. There are no closed nights; on November 30 some attractions are closed for a private event."},{question:"Is parking included with Christmas at the Princess tickets?",answer:"No. Admission and parking are separate, and a self-parking or valet ticket is required to park on the property; parking costs more if it is bought on arrival. Rideshare guests are dropped at the Enchanted Plaza."},{question:"When does ZooLights at the Phoenix Zoo start and end?",answer:"ZooLights runs from Wednesday, November 25, 2026, to Friday, January 15, 2027, from 5:30 to 10:30 p.m. every night, Christmas night included."},{question:"Where do you buy Phoenix ZooLights tickets?",answer:"Online from the Phoenix Zoo, with general sales from October 1. A ticket is good for any one public night of the season, with no date or entry time on it. Sensory Friendly ZooLights on December 8 and Cruise ZooLights on January 17 are ticketed separately."},{question:"Where do you park for ZooLights?",answer:"In the Zoo’s main lots; when they fill, message boards send drivers to the overflow lot at Phoenix Municipal Stadium, at Van Buren and Priest, about a 15-minute walk on a lit path. The Zoo mentions no shuttle."},{question:"When does Glendale Glitters start and end?",answer:"The lighting ceremony is Friday, November 27, 2026, at 5:45 p.m., the kickoff event runs November 27 and 28, and the lights stay on nightly through January 1, 2027, from 5 to 10 p.m."},{question:"Where is Glendale Glitters?",answer:"In Murphy Park, in Historic Downtown Glendale. The city has not published a street address or 2026 parking; its 2024 release pointed drivers to free parking in the downtown garage at 5835 W. Palmaire Ave. and on surface streets."},{question:"Where can you see Christmas lights in Phoenix and Scottsdale?",answer:"The five big displays of the 2026 season are Christmas at the Princess in Scottsdale, ZooLights at the Phoenix Zoo, Las Noches de las Luminarias at the Desert Botanical Garden, Glendale Glitters in Historic Downtown Glendale and Scottsdazzle in Old Town Scottsdale."},{question:"When is Desert Farm Lights open in 2026?",answer:"Nightly from November 20 to December 27, 2026, closed on Christmas Day: 5 to 10 p.m. Sunday to Thursday; on Friday and Saturday, and every night the week of Christmas, it opens at 5 p.m. and closes at 11 p.m."},{question:"Where is Desert Farm Lights?",answer:"At 14629 W. Peoria Ave in Surprise, in the West Valley. Parking is free, and the gate entrance closes one hour before the display closes."},{question:"When is World of Illumination in Tempe in 2026?",answer:"November 13, 2026 to January 3, 2027, at Tempe Diablo Stadium, Tuesday to Sunday, gates at 6 p.m. and last entry at 10 p.m. A second show runs at Camelback Ranch in Glendale from November 12. Tickets are online only, priced per vehicle."},{question:"Can you rent a party bus to see Christmas lights?",answer:"Yes. Book the vehicle by the hour and it takes the group from display to display and home, waiting at each stop. Our party bus, the Limo Party Sprinters and the Ultra Luxury Party Sprinter all fit a lights crawl."},{question:"Can the chauffeur wait while we walk the lights?",answer:"Yes. Book the vehicle by the hour and it is yours for the whole block: it waits while you walk the lights, takes you to a second display or to dinner, and brings everyone home. Stops inside the hours you booked cost nothing extra."},{question:"Which neighborhood in the Phoenix area is best for Christmas lights?",answer:"Three are the best known: Agritopia near Higley and Ray roads in Gilbert, where nearly every home is lit; Christmas Street on Rose Garden Lane in Grayhawk, Scottsdale, which collects for St. Mary’s Food Bank; and the million lights on the medians of Chandler Boulevard in Ahwatukee. All three are free, and none publishes dates."},{question:"When are the Holiday Lights at McCormick-Stillman Railroad Park in 2026?",answer:"November 27 to December 30, 2026, from 5:30 to 9:30 p.m., with no lights on December 24 or 25, at 7301 E. Indian Bend Rd., Scottsdale. Tickets include the train and carousel rides and go on sale October 26 at 8 a.m.; the park says the event sells out every year."},{question:"When is the Chandler Tumbleweed Tree Lighting in 2026?",answer:"Saturday, December 5, 2026, from 4:30 to 9 p.m. in Downtown Chandler, 3 S. Arizona Ave. It is free, with the Parade of Lights in the evening."},{question:"When is the APS Electric Light Parade in 2026?",answer:"Saturday, December 5, 2026, at 7 p.m., from Central Avenue and Montebello Avenue to 7th Street and Indian School Road in Phoenix. Viewing spots are first come, first served."},{question:"How long is a Christmas lights tour by limo or Sprinter?",answer:`Every vehicle is booked by the hour with a ${ua(oe)}-hour minimum. One display with dinner fits ${ua(oe)} hours; two displays, or a neighborhoods drive across the East Valley, usually take 5 or 6.`}],jp={path:up,title:"Christmas at the Princess, Phoenix ZooLights and Glendale Glitters 2026: parking and rides",metaTitle:"Christmas at the Princess & ZooLights",description:"Christmas at the Princess, Phoenix ZooLights, Las Noches de las Luminarias, Glendale Glitters and Scottsdazzle: the official 2026 dates and hours, where to park or be dropped off, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official dates, hours, parking and a ride home",lastUpdated:Ri,lastUpdatedLabel:l(Ri),eyebrow:"Official dates: November 20, 2026 – January 15, 2027",intro:"A holiday lights night with Scottsdale Sprinters starts with the organisers’ own 2026 dates, one vehicle for the whole group and a chauffeur who waits while you walk the lights. This guide covers Christmas at the Princess, ZooLights at the Phoenix Zoo, Las Noches de las Luminarias at the Desert Botanical Garden, Glendale Glitters and Scottsdazzle in Old Town, using only what each organiser publishes, parking and drop-off first.",sections:Zp,faqs:Kp,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:c(q)},{href:"/fleet/executive-sprinter-scottsdale",label:c(oe)},{href:"/fleet/premium-suv-scottsdale",label:c(Ot)},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/guides/venues/fairmont-scottsdale-princess",label:"Fairmont Scottsdale Princess guide"},{href:"/guides/trans-siberian-orchestra-phoenix-2026",label:"Trans-Siberian Orchestra in Phoenix, December 6"},{href:"/guides/new-years-eve-scottsdale-phoenix",label:"New Year’s Eve after the lights"},{href:"/guides/company-christmas-party-ideas-scottsdale-phoenix",label:"Company Christmas party ideas for the lights season"},{href:"/fleet/party-bus-28-scottsdale",label:c(ba)},{href:"/pricing",label:"Published hourly pricing"}],sources:qp},Li="2026-09-26",Qp="/guides/company-christmas-party-ideas-scottsdale-phoenix",Aa="maybach-jet-sprinter-scottsdale",Sr="executive-sprinter-scottsdale",Xp="executive-white-sprinter-scottsdale",Ar="executive-mini-bus-26-scottsdale",Ta="executive-luxury-bus-29-scottsdale",Ua="motorcoach-56",ue=e=>n[e],Ba=e=>i[e],Ha=e=>h(r[e].hourlyRateCents),Oi=e=>r[e].minimumHours;function It(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ts=["January","February","March","April","May","June","July","August","September","October","November","December"],ef=hd.items.filter(e=>e.series==="suns"&&e.date.startsWith("2026-12")).map(e=>`December ${Number(e.date.slice(8,10))} (${e.label.replace(/^Suns vs /,"")})`),$s=xa.find(e=>e.label==="Ugly Sweater Party"),Cs=xa.find(e=>e.label==="Pentatonix"),tf=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function yo(e){const[t,a,o]=e.split("-").map(Number);return`${tf[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${Ts[a-1]} ${o}`}const af=[{label:"Christmas at the Princess, official site",href:"https://www.christmasattheprincess.com/"},{label:"Christmas at the Princess FAQ: tickets, parking, dining",href:"https://www.christmasattheprincess.com/faq"},{label:"Phoenix Zoo, ZooLights 2026-27 (group tickets)",href:"https://www.phoenixzoo.org/events/zoolights/"},{label:"Desert Botanical Garden, Las Noches de las Luminarias",href:"https://dbg.org/events/las-noches-de-las-luminarias/"},{label:"Desert Farm Lights, official site (2026 season)",href:"https://desertfarmlights.com/"},{label:"Mortgage Matchup Center, Trans-Siberian Orchestra",href:"https://mortgagematchupcenter.com/events/transsiberian-orchestra/"},{label:"NBA, Phoenix Suns schedule",href:"https://www.nba.com/suns/schedule"},{label:"Desert Diamond Arena, events and tickets (Pentatonix, the Ugly Sweater Holiday Party)",href:"https://www.desertdiamondarena.com/events-tickets/"},{label:"Scottsdazzle Tree Lighting Spectacular",href:"https://scottsdazzle.com/event/tree-lighting-spectacular-celebrating-75-years-of-scottsdale/"},{label:"City of Glendale, special events: Glendale Glitters",href:"https://www.glendaleaz.gov/Explore/Special-Events/Events"}],rf=[It("What are the best company Christmas party ideas in Scottsdale and Phoenix?","The season gives an office six dated options: dinner and Christmas at the Princess in Scottsdale (November 20, 2026 to January 2, 2027), a ZooLights night with group tickets, Las Noches de las Luminarias at the Desert Botanical Garden, Desert Farm Lights in Surprise, the Trans-Siberian Orchestra matinee on December 6, and a Suns home game downtown.","Each one is a night out the organiser runs, so your team gets the event without anyone planning a venue. What the office still has to solve is the part the organisers leave out: getting everyone there together, and home again, without anyone driving after the party.","The answers below give each option’s official dates and what it means for a group, then the vehicles that move a team, a department or the whole company."),It("Can an office book Christmas at the Princess as a holiday party?","Yes, as a group of ticket holders: Christmas at the Princess at the Fairmont Scottsdale Princess runs nightly from November 20, 2026, to January 2, 2027, tickets are booked online for a date, and the organiser says it often sells out and recommends dinner reservations at least a month ahead.","The resort’s restaurants for the evening are Bourbon Steak, La Hacienda and Toro Scottsdale. Admission and parking are separate tickets, so a team that drives needs a parking ticket for every car; a team in one vehicle needs none of that, and rideshare guests are dropped at the Enchanted Plaza.","The resort opens at 5 p.m. Monday to Thursday and at 4 p.m. Friday to Sunday, and from December 17 at 4 p.m. every night, which leaves room for dinner first on a weeknight party."),It("Is ZooLights a good company holiday outing?","Yes for a big team: the Phoenix Zoo sells ZooLights group tickets when 50 or more are bought in advance, the lights run nightly from November 25, 2026, to January 15, 2027, opening at 5:30 p.m. and closing at 10:30 p.m., and a ticket is good for any one public night.","The Zoo’s own advice is that Monday to Wednesday are the quietest nights and that the first two weeks of December are less busy, which suits a weeknight office party. It is two miles of trail and five million lights, so dress the team for a walk.","When the Zoo’s lots fill, drivers are sent to an overflow lot about a 15-minute walk away. A team that arrives in one vehicle is dropped where Zoo staff direct and skips the lots."),It("Which other holiday events suit a work Christmas party?","Three more nights work for a group: Las Noches de las Luminarias at the Desert Botanical Garden on 26 nights from November 27, 2026, opening at 5:30 p.m. and closing at 9:30 p.m.; Desert Farm Lights in Surprise, nightly from November 20 to December 27; and Trans-Siberian Orchestra at Mortgage Matchup Center on December 6, at 3 p.m. and 7:30 p.m.","Luminarias general tickets go on sale October 16, and the Garden is next door to the Zoo, so the two pair well in one evening. Desert Farm Lights is a walk-through display with free parking; it is on the far side of the Valley from Scottsdale, so the ride is part of the night.",`A downtown Suns game is the other classic: the arena’s list has home games in December on ${ef.join(", ")}. Our Trans-Siberian Orchestra page and the Mortgage Matchup Center page have the parking and the 3rd Street drop-off.`),It("Which Christmas concerts and free light shows suit an office party?",`Two more arena nights are in Glendale: Pentatonix at Desert Diamond Arena on ${yo(Cs.dates.start)} at ${Ea(Cs.starts)}, and the Ugly Sweater Holiday Party with Sublime, Slightly Stoopid and Codefendants on ${yo($s.dates.start)} at ${Ea($s.starts)}. For a free night, Scottsdazzle’s tree lighting is November 28, 7 to 9 p.m.`,"The Scottsdazzle tree lighting is at the Scottsdale Waterfront canal bank, 7135 East Camelback Road in Old Town, and the city lists it as free. Glendale Glitters lights Murphy Park in Historic Downtown Glendale with its lighting ceremony on November 27 at 5:45 p.m. Both are walkable displays that pair with dinner nearby.","A concert suits a team that wants a seated night with a clear end time; a free lights night suits a long dinner with a short walk after it. Either way, the vehicle is booked by the hour and waits through both halves of the evening."),It("How do you get the whole office to a holiday party and home?",`Book one vehicle, or a pair, by the hour with a ${Oi(Sr)}-hour minimum: it collects the team at the office or a hotel, waits through dinner and the event, and takes everyone home, so nobody drives after the party and nobody is left to find a ride.`,"A holiday party is three movements in one night: collecting people, arriving together, and getting everyone home at the end, which is later than anyone plans for. Give us the pickup points, the event and the headcount, and we plan the timing back from the event’s own hours.",`Reach the reservations team at ${u} or ${p}. For the company’s other rides, see our corporate transportation page.`),It("Which vehicle fits a company Christmas party?",`For the leadership table, the ${ue(Aa)} (${Ba(Aa)} seats); for a team, the ${ue(Sr)} or the ${ue(Xp)} (${Ba(Sr)} seats each); for a department, the ${ue(Ar)} (${Ba(Ar)}) or the ${ue(Ta)} (${Ba(Ta)}); and for the whole company, the ${ue(Ua)} (${Ba(Ua)}).`,`Rates are per vehicle, before tax: ${Ha(Aa)} an hour for the ${ue(Aa)}, ${Ha(Sr)} for an Executive Sprinter, ${Ha(Ar)} for the ${ue(Ar)}, ${Ha(Ta)} for the ${ue(Ta)} and ${Ha(Ua)} for the ${ue(Ua)}, which has a ${Oi(Ua)}-hour minimum. The fare belongs to the vehicle, so one more colleague does not change it.`,"The motorcoach photos on this page are representative; the assigned coach is confirmed in writing. For a group larger than one vehicle, we plan two or more and quote them together.")],of=[{question:"What should you do for a corporate Christmas party in Scottsdale?",answer:"Pick a dated holiday event the team can share, such as Christmas at the Princess, ZooLights with group tickets, Las Noches de las Luminarias or a Suns game, add dinner, and book one chauffeured vehicle so everyone arrives together and nobody drives home."},{question:"What makes a good company holiday party?",answer:"An event people would choose on their own time, an easy start from the office, and a safe way home. The Valley’s holiday displays and shows supply the first; a chauffeured group ride covers the other two."},{question:"Are there Christmas concerts for a work party in Phoenix?",answer:`Yes: Trans-Siberian Orchestra at Mortgage Matchup Center on December 6 (3 p.m. and 7:30 p.m.), the Ugly Sweater Holiday Party at Desert Diamond Arena on ${yo($s.dates.start)}, and Pentatonix there on ${yo(Cs.dates.start)}.`},{question:"Does ZooLights sell group tickets?",answer:"Yes. The Phoenix Zoo sells ZooLights group tickets when 50 or more are bought in advance. A ticket is good for any one public night of the season."},{question:"When is Christmas at the Princess 2026?",answer:"Nightly from Friday, November 20, 2026, through Saturday, January 2, 2027, at the Fairmont Scottsdale Princess."},{question:"How do you get employees home safely after a holiday party?",answer:"Book the ride both ways. A vehicle booked by the hour waits through the party and takes everyone home at the end, so nobody drives and nobody is left to find a ride."}],nf={path:Qp,title:"Company Christmas party ideas in Scottsdale and Phoenix, 2026: the dated events and the ride",metaTitle:"Company Christmas Party Ideas 2026",description:"Company Christmas party ideas in Scottsdale and Phoenix for 2026: Christmas at the Princess, ZooLights for groups of 50 or more, Las Noches de las Luminarias, Desert Farm Lights, the TSO matinee and a Suns game, with official dates and a chauffeured ride for the whole office.",metaDescription:"Dated holiday events for a team and a ride for everyone",lastUpdated:Li,lastUpdatedLabel:l(Li),eyebrow:`Scottsdale · Phoenix · ${Ts[10]} 2026 to ${Ts[0]} 2027`,intro:"Scottsdale Sprinters’ short answer: the best company Christmas party in Scottsdale or Phoenix is a dated holiday event the whole team can share, such as Christmas at the Princess (November 20, 2026 to January 2, 2027), ZooLights with group tickets for 50 or more, Las Noches de las Luminarias or a Suns game, plus dinner and one chauffeured vehicle, so everyone arrives together and nobody drives home.",sections:rf,faqs:of,links:[{href:"/guides/christmas-lights-scottsdale-phoenix",label:"Christmas at the Princess, ZooLights and the 2026 lights"},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/guides/trans-siberian-orchestra-phoenix-2026",label:"Trans-Siberian Orchestra in Phoenix, December 6"},{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center parking and drop-off"},{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking for the Glendale shows"},{href:`/fleet/${Ta}`,label:ue(Ta)},{href:`/fleet/${Aa}`,label:ue(Aa)},{href:"/pricing",label:"Published hourly pricing"}],sources:af},_i="2026-09-26",sf="/guides/venues/desert-diamond-arena",jt="ultra-luxury-party-sprinter-scottsdale",pn="maybach-jet-sprinter-scottsdale",hf="maybach-shuttle-sprinter-8",df="premium-suv-scottsdale",$a="limo-sprinter-13-scottsdale",Gi="limo-sprinter-16-scottsdale",fn="executive-sprinter-scottsdale",Qt="party-bus-28-scottsdale",Tr="executive-luxury-bus-29-scottsdale",mn="executive-mini-bus-26-scottsdale",x=e=>n[e],pt=e=>i[e],gn=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,Da="https://www.desertdiamondarena.com",lf=`${Da}/venue-info/`,cf=`${Da}/venue-info/parking/`,uf="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/Parking_Map_0b35a191-a8e4-47e1-bca1-e73b26128e02.jpg",pf=`${Da}/venue-info/azguide/`,ff=`${Da}/events-tickets/`,mf=`${Da}/events-tickets/seat-map/`,gf=`${Da}/events-tickets/box-office/`,yf="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/DDA_Private_Event_Deck_2026_91290cc0-c10b-4ec7-b259-f9be05e09cf7.pdf",bf="https://www.pbr.com/news/2026/05/pbr-world-finals-championship-to-be-held-in-glendale-arizona-may-20-23-2027/",wf="https://westgateaz.com/",vf="https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley",_s=xa.filter(e=>e.featured),To=_s.find(e=>e.label==="Jonas Brothers"),Gs=_s.find(e=>e.label==="Pentatonix"),cr=_s.find(e=>e.kind==="sports"),kf="https://westgateaz.com/explore/parking/",Sf=[{label:"Desert Diamond Arena, venue information",href:lf},{label:"Desert Diamond Arena, parking and directions",href:cf},{label:"Desert Diamond Arena, official parking map",href:uf},{label:"Desert Diamond Arena, A to Z guide and bag policy",href:pf},{label:"Desert Diamond Arena, event calendar",href:ff},{label:"Desert Diamond Arena, seat map",href:mf},{label:"Desert Diamond Arena, box office",href:gf},{label:"Desert Diamond Arena, Jonas Brothers event page",href:To.url},{label:"Desert Diamond Arena, PBR World Finals 2027 event page",href:cr.url},{label:"PBR, World Finals Championship in Glendale, May 20–23, 2027",href:bf},{label:"Desert Diamond Arena, 2026 private events guide (capacity)",href:yf},{label:"Westgate Entertainment District",href:wf},{label:"Westgate Entertainment District, parking on arena and stadium event days",href:kf},{label:"Valley Metro, West Valley destinations",href:vf}],Af={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"},Za=["January","February","March","April","May","June","July","August","September","October","November","December"];function yn(e){const[t,a,o]=e.split("-").map(Number),d=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(Date.UTC(t,a-1,o)).getUTCDay()];return`${Af[d]}, ${Za[a-1]} ${o}, ${t}`}function He(e){const[t,a,o]=e.dates.start.split("-").map(Number);if(!e.dates.end||e.dates.end===e.dates.start)return`${Za[a-1]} ${o}, ${t}`;const[,d,z]=e.dates.end.split("-").map(Number);return d===a?`${Za[a-1]} ${o} to ${z}, ${t}`:`${Za[a-1]} ${o} to ${Za[d-1]} ${z}, ${t}`}function Tf(e){const t=e.dates.end&&e.dates.end!==e.dates.start?`${yn(e.dates.start)} to ${yn(e.dates.end)}`:yn(e.dates.start),a=[e.doors?`doors ${Ea(e.doors)}`:null,e.starts?`${e.dates.end&&e.dates.end!==e.dates.start?"first show":"show"} ${Ea(e.starts)}`:null].filter(Boolean);return`${t}: ${e.title}${a.length?` (${a.join(", ")})`:""}.`}function Me(e,t,...a){return{question:e,answer:t,paragraphs:a}}const $f=[Me("Where is Desert Diamond Arena?","Desert Diamond Arena is at 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101. State Farm Stadium is directly south across Maryland Avenue, and Westgate’s shops and restaurants are directly north across Entertainment Boulevard.","From Loop 101, exit 7A is Maryland Avenue and exit 7B is Glendale Avenue; the arena’s own parking map routes cars into its lots from both. The arena sits on 13.5 acres, is managed by Legends Global, and says it entertains over one million visitors a year with concerts, family shows and sporting events.","By Google’s typical drive time, measured on September 24, 2026 without event traffic, the arena is 23 minutes from downtown Phoenix, 28 minutes from Phoenix Sky Harbor, and 36 minutes from Old Town Scottsdale or Kierland. Show nights add the arena’s own traffic to the last mile.","Valley Metro lists no light rail to the Westgate area. Its West Valley destinations page gives the Westgate Entertainment District one bus connection, Route 70."),Me("How does parking work at Desert Diamond Arena?","Arena parking lots open one hour before doors. On the day, spaces are in lots G, J, L, Yellow, the Garage and VIP, as each event allows, and the entrances take credit or debit cards only, no cash. A pre-paid space, bought on the event page up to an hour before the event, is guaranteed until 30 minutes after the start.","Pre-paid parking is shown at the entrance from the Ticketmaster app, the ParkWhiz confirmation email or a ParkWhiz account. The arena says it gives faster entry and exit and closer spaces. Its VIP parking, sold on the event pages, is reserved front-row parking with an express lane in and out, in limited numbers.","Every pass covers one standard 12 by 18 foot space, and oversized vehicles must buy additional spaces. Overnight parking and camping are not permitted. Accessible parking is first come, first served in Lots G, J and the Garage for a valid placard or plate, with a pre-purchased permit or a day-of fee.","The arena’s pages publish no parking price: it is set by event and shown when you buy the space through the event page. Pay by card, and pre-pay when the lot matters to your group."),Me("Can you park at Westgate for a Desert Diamond Arena show?","Yes, in the Westgate Entertainment District’s lots, which run their own event-day paid parking: it starts 3 hours before an arena event’s start time and ends 2 hours after it begins. Payment is cashless, by the QR code on site, the Premium Parking app or text-to-pay, and license plate readers replace attendants.","A car that arrives before the paid window starts is not charged. Every Westgate guest also gets 2 hours of complimentary parking on event days after registering the car by the QR code on site or by texting P4807 to 504504; a concert night runs longer than that. Parking at the District Shops and Village Shops is limited to 2 hours, and Westgate says the limit is highly enforced on event days, with fines or towing.","Westgate says to pay only through its official channels and never to a person in a lot, and it posts the event-day windows on its events calendar. A chauffeured group skips all of it: nobody watches a 2-hour clock over dinner and the show."),Me("Where do rideshare and chauffeured groups drop off at Desert Diamond Arena?","Desert Diamond Arena publishes no rideshare, limo, charter or bus drop-off zone on its parking page, its A to Z guide or its event pages, so a chauffeured group unloads where arena staff and police direct on the night, and agrees one pickup point for the ride home before the show.","Nothing here is a reserved lane for booked vehicles. The chauffeur drives the approach the event’s traffic allows, lets the group out where staff direct, and meets it at the agreed point once the crowd clears. If the arena publishes a drop-off plan for a show, that plan replaces this paragraph.","A group that splits across cars also splits across lots and exits. One vehicle arrives with everyone at once and leaves with everyone at once, which matters most on a night that starts with dinner at Westgate."),Me("What’s coming up at Desert Diamond Arena?",`Coming up at Desert Diamond Arena: the Jonas Brothers on ${He(To)}, Rush on December 1 and 3, 2026, Pentatonix on ${He(Gs)}, and the PBR World Finals Championship on ${He(cr)}. The arena’s calendar lists these shows from October 21, 2026, as read on September 24, 2026:`,...xa.map(Tf),"Los Tigres del Norte moved from September 12 to October 24, and the arena says tickets for the original date are valid for the new one. The Hot Wheels Stunt Show has three performances: noon and 7 p.m. on Saturday, March 6, and 2 p.m. on Sunday, March 7.","The PBR World Finals Championship comes to Glendale after its opening rounds in Fort Worth on May 6 to 9, 2027. Session times are announced closer to the date. New shows are added to the arena’s calendar through the year, and it is the place to check before you book."),Me("How many people does Desert Diamond Arena hold?","Desert Diamond Arena’s own 2026 private events guide lists the arena at a capacity of 20,000, with a 24,400 square foot floor. The number sold for a show depends on its stage and seating layout, which the arena’s seat map shows event by event.","For a group, capacity decides the traffic, not the ride: a sold-out night means full lots, lines at the card readers and one long exit. That is the night to leave the driving to a chauffeur and the parking to the lot."),Me("What is the Desert Diamond Arena bag policy?","Bags and purses must be 12 by 12 by 6 inches or smaller to enter Desert Diamond Arena, clear or not. Laptop bags, briefcases, camera bags, coolers, luggage of any kind and seat cushions are not allowed at any size.","Outside food, drinks, cans, bottles and flasks are not allowed either; a factory-sealed water bottle under 17 ounces is. Every guest is screened on entry, with Evolv scanners at some entrances.","Settle bags at the hotel. A group that is dropped off has no car in the lot to go back to during the show."),Me("Which hotels and restaurants are near Desert Diamond Arena?","The arena’s parking map shows the Renaissance Hotel, the Hampton Inn & Suites, Home2 Suites by Hilton and the Tru Hotel just west of the arena, between 95th Avenue and Loop 101, and the Westgate Entertainment District’s restaurants directly north across Entertainment Boulevard.","Westgate describes itself as specialty shops, eateries and entertainment in the heart of Glendale, at 6770 North Sunrise Boulevard. On the arena’s own map it sits across one street from the arena.","Our Westgate Dinner + Show package is built for that night: pickup, dinner at Westgate, the show and the ride home, in one booking."),Me("Which vehicle fits a Desert Diamond Arena group?",`Concert crews ride a Limo Party Sprinter or the ${x(fn)}. A VIP night out takes the ${x(pn)}, the ${x(jt)}, the ${x(hf)} or the ${x(df)}. Big groups and fan clubs take the ${x(Qt)}, the ${x(Tr)} or the ${x(mn)}.`,`Seat counts are seated capacities from the fleet: the ${x(jt)} seats ${pt(jt)}, the ${x($a)} ${pt($a)}, the ${x(Gi)} ${pt(Gi)}, the ${x(fn)} ${pt(fn)} and the ${x(pn)} ${pt(pn)}. The ${x(Qt)} seats ${pt(Qt)}, the ${x(Tr)} ${pt(Tr)} and the ${x(mn)} ${pt(mn)}.`,`Our pick for an arena night is the ${x(jt)}, ${gn(jt)}: fiber-optic lighting with eighteen modes, lasers and a fog machine, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${x($a)} is ${gn($a)}, and the ${x(Qt)} is ${gn(Qt)}. Every rate prices the whole vehicle, before tax.`,`For a group bigger than the ${x(Tr)}, we plan two or more vehicles and quote them together. Count riders for the ride home as well as the ride there; the late list is the one that matters.`),Me("How should a group plan the ride to a Desert Diamond Arena show?","Plan backwards from the doors. At every listed concert the doors open an hour before the show, and the arena lots open an hour before the doors, so a pickup that lands the group at the arena around the doors time leaves room for the lines and the bag check.","Arena guests with the paid Bassline Bar upgrade get in 60 minutes before general doors, between Gates 3 and 4; plan that pickup earlier still. It is an add-on to a ticket, not a ticket.",`Book by the hour and the vehicle is yours for the whole night, dinner at Westgate included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the date, the pickup area and the rider count.`)],Cf=[{question:"Where do you park at Desert Diamond Arena?",answer:"In the arena’s own lots: on the day, lots G, J, L, Yellow, the Garage and VIP, as each event allows. They open one hour before doors, take cards only, and a pre-paid space bought on the event page is held until 30 minutes after the start."},{question:"How much is parking at Desert Diamond Arena?",answer:"The arena’s pages publish no parking price: it is set by event and shown when you pre-pay on the event page through Ticketmaster or ParkWhiz. At the entrance it is credit or debit card only, no cash, and oversized vehicles must buy additional spaces."},{question:"What time do Desert Diamond Arena parking lots open?",answer:"One hour before the event’s doors. At every listed concert the doors open an hour before the show."},{question:"What concerts are coming to Desert Diamond Arena?",answer:`Among the listed shows: the Jonas Brothers on ${He(To)}, Rush on December 1 and 3, 2026, and Pentatonix on ${He(Gs)}, then the PBR World Finals Championship on ${He(cr)}. The arena’s calendar has the full, current list.`},{question:"How many people does Desert Diamond Arena hold?",answer:"The arena’s own 2026 private events guide lists a capacity of 20,000. A show’s capacity depends on its stage and seating layout."},{question:"Where is Desert Diamond Arena?",answer:"At 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101, across Maryland Avenue from State Farm Stadium."},{question:"What is the Desert Diamond Arena bag policy?",answer:"Bags up to 12 by 12 by 6 inches, clear or not. No laptop bags, briefcases, camera bags, coolers, luggage or seat cushions at any size."},{question:"When is the PBR World Finals at Desert Diamond Arena?",answer:`The PBR World Finals Championship is ${He(cr)}, after the opening rounds in Fort Worth on May 6 to 9. Session times are announced closer to the date.`},{question:"Can a limo or party bus drop off at Desert Diamond Arena?",answer:"Yes, where arena staff and police direct on the night. The arena publishes no rideshare, limo or charter zone, so the chauffeur confirms the drop-off for your show and agrees one pickup point for the ride home."},{question:"Can you park at Westgate for Desert Diamond Arena?",answer:"Yes. Westgate’s lots charge event-day parking from 3 hours before an arena event starts until 2 hours after it begins, cashless, with 2 free hours for a car registered by QR code or text. Arrive before the window and you are not charged."},{question:"Is there light rail to Desert Diamond Arena?",answer:"No. Valley Metro lists no light rail to the Westgate area; its one listed connection there is bus Route 70."}],Pf={path:sf,title:"Desert Diamond Arena: Parking, Upcoming Shows and Concert Rides",metaTitle:"Desert Diamond Arena Parking & Shows",description:"Desert Diamond Arena in Glendale: how the arena’s parking works, the upcoming concerts and the PBR World Finals, capacity, the bag policy, the hotels and Westgate next door, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, doors, the upcoming shows and a chauffeured ride",lastUpdated:_i,lastUpdatedLabel:l(_i),eyebrow:"Glendale · Westgate Entertainment District",intro:`Scottsdale Sprinters’ short answer on Desert Diamond Arena: it is at 9400 West Maryland Avenue in Glendale, in the Westgate Entertainment District beside State Farm Stadium. Arena lots open one hour before doors and take cards only, and a pre-paid space is held until 30 minutes after the start. Coming up: the Jonas Brothers on ${He(To)}, Rush on December 1 and 3, Pentatonix on ${He(Gs)} and the PBR World Finals on ${He(cr)}. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive home.`,sections:$f,faqs:Cf,links:[{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking, across Maryland Avenue"},{href:"/service-areas/glendale",label:"Glendale service area"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:`/fleet/${jt}`,label:x(jt)},{href:`/fleet/${$a}`,label:x($a)},{href:`/fleet/${Qt}`,label:x(Qt)},{href:"/pricing",label:"Published hourly pricing"}],sources:Sf},Ui="2026-09-27",Ef="https://www.fearfarm.com/",Ff="https://zentix.com/help/brand/tfeg/fear-farm",Mf="https://www.13thflooraz.com/",Rf="https://www.13thflooraz.com/location-parking",xf="https://zentix.com/help/brand/tfeg/13-floor-phoenix",Df="https://fearfarm.com/location-parking/",If="https://www.terrorintolleson.com/faq",Nf="https://www.scarizona.com/",Wf="https://tickets.scarizona.com/e/scarizona-scaregrounds",Lf="https://www.scarizona.com/faq/",Of="https://www.sanctumofhorror.com/faq/",_f="https://www.tolmachoff-farms.com/post/az-field-of-screams-at-tolmachoff-farm",Gf="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",bn={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],teens:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale","executive-mini-bus-26-scottsdale"]},Uf=[...bn.vip,...bn.crews,...bn.teens].filter(ae),Bf=Uf.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),Y="ultra-luxury-party-sprinter-scottsdale",$r="maybach-jet-sprinter-scottsdale",Bi="maybach-shuttle-sprinter-8",wn="premium-suv-scottsdale",Cr="limo-sprinter-13-scottsdale",Hf="limo-sprinter-16-scottsdale",Be="party-bus-28-scottsdale",Ka="executive-sprinter-scottsdale",zf="executive-white-sprinter-scottsdale",Hi="executive-mini-bus-26-scottsdale",f=e=>n[e],Se=e=>i[e];function Pr(e){return h(r[e].hourlyRateCents)}function zi(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function ne(e,t,...a){return{question:e,answer:t,paragraphs:a}}const qf=[{label:"Fear Farm Haunted Fairgrounds: 2026 season, address and attractions",href:Ef},{label:"Fear Farm: location and parking",href:Df},{label:"Fear Farm help centre: season, ages, bags, costumes and groups",href:Ff},{label:"The 13th Floor Haunted House Phoenix: 2026 season and attractions",href:Mf},{label:"The 13th Floor Phoenix: location and parking",href:Rf},{label:"The 13th Floor Phoenix help centre: ages, bags, costumes and groups",href:xf},{label:"The Crypt: 2026 season, ages, parking and groups",href:If},{label:"Scarizona Scaregrounds: address, ages and free parking",href:Nf},{label:"Scarizona Scaregrounds: 2026 ticket calendar",href:Wf},{label:"Scarizona Scaregrounds FAQ: bags, costumes and rules",href:Lf},{label:"Sanctum of Horror FAQ: parking, groups, weather and costumes",href:Of},{label:"AZ Field of Screams at Tolmachoff Farms: 2026 dates and rules",href:_f},{label:"City of Scottsdale: Old Town Transportation Safety Zone",href:Gf}],Vf={head:["Haunt","Where","2026 season","Age guidance","Parking","Best for"],rows:[["Fear Farm Haunted Fairgrounds","1475 N McClintock Dr, Tempe","Select nights, Sept 19 to Nov 14","May be too intense for 12 and under","Details not yet published by the haunt","A long night: several haunts, a maze, rides and two 21+ bars"],["The 13th Floor","2710 W Bell Rd, Suite 1180, Phoenix","Select nights, Sept 19 to Nov 1","No minimum; 12 and older suggested","Free street parking","An indoor haunt in north Phoenix, three attractions"],["The Crypt","3801 E Washington St, Phoenix","Oct 2 to Nov 7","13 and older; under 18 with a parent or guardian","Free on-site parking","Six attractions and a contact haunt, for the bravest crew"],["Scarizona Scaregrounds","1901 N Alma School Rd, Mesa","Select nights, Sept 25 to Nov 1, timed entry","Not recommended under 12","Free parking","Three outdoor haunts on one ticket"],["Sanctum of Horror","6525 E Southern Ave, Mesa","Select nights on its own calendar","Not stated; a separate daylight walkthrough for families","Free parking on site","Two outdoor mazes, groups up to 8 at a time"],["AZ Field of Screams","Tolmachoff Farms, 5726 N 75th Ave, Glendale","Fridays, Saturdays and Halloween night, Oct 2 to 31","Not recommended under 13","Not stated","A haunted corn maze on a working farm"]]},Yf={head:["Haunt crawl","First stop","Second stop","Why it pairs"],rows:[["East Valley double","Scarizona Scaregrounds, Mesa","Fear Farm, Tempe","Neighbouring cities; Scarizona sells timed entry, so its slot sets the night"],["Mesa pair","Sanctum of Horror, Mesa","Scarizona Scaregrounds, Mesa","Both in Mesa, both outdoors, both with free parking the group will not need"],["West Valley and north Phoenix","AZ Field of Screams, Glendale","The 13th Floor, Bell Road","A corn maze outdoors, then an indoor haunt; Fridays and Saturdays only"],["Central and Tempe","The Crypt, Phoenix","Fear Farm, Tempe","The two longest seasons, so it works on a weeknight too"]]},Jf=[{...ne("What are the haunted houses in Phoenix for Halloween 2026?","Six haunts run in the Phoenix area this season: Fear Farm in Tempe (select nights, September 19 to November 14, 2026), The 13th Floor on Bell Road in Phoenix (select nights, September 19 to November 1), The Crypt on East Washington Street, Scarizona Scaregrounds and Sanctum of Horror in Mesa, and AZ Field of Screams, a haunted corn maze in Glendale.","Fear Farm is a haunted fairground: several haunted attractions, a maze, a zombie shooting gallery and carnival rides on one ground, at 1475 N McClintock Dr in Tempe. The 13th Floor is an indoor haunted house with three attractions and a few short extras, at 2710 W Bell Rd, Suite 1180, in Phoenix.","The Crypt, at 3801 E Washington St in Phoenix, runs October 2 to November 7, 2026 with six attractions, and it is a contact haunt for guests 13 and older. Scarizona Scaregrounds, at 1901 N Alma School Rd in Mesa, sells one timed-entry ticket for three outdoor haunts from September 25 to November 1. Sanctum of Horror, at 6525 E Southern Ave in Mesa, runs two outdoor mazes on the nights its calendar shows. AZ Field of Screams is a haunted corn maze at Tolmachoff Farms, 5726 N 75th Ave in Glendale, on Fridays, Saturdays and Halloween night from October 2 to 31.","None of them is open every night, and tickets, times and the open nights are each haunt’s own, sold on their sites, so this guide prints none of them: buy the tickets first, then book the ride for that night."),table:Vf},ne("Where do you park and get dropped off at the Phoenix haunted houses?","Fear Farm asks every guest to use its new address, 1475 N McClintock Dr, Tempe, AZ 85257, because rideshare and map apps may still find the old site by name; The 13th Floor says free street parking is available around it on Bell Road; The Crypt, Scarizona and Sanctum of Horror each say parking is free; a chauffeured group is dropped where each haunt’s staff direct.","Fear Farm’s own site is plain about the address: search the street address, not the business name, or the app may send you to the wrong place. That is the first thing we confirm for a Fear Farm night, and the address the booking carries as the drop-off. Its location page says more parking information will be released closer to the event.","At The 13th Floor, parking is on the street around the building. The haunt asks drivers not to park in front of no-parking signs, gates or driveways, to keep valuables out of sight, and it takes no responsibility for parked cars; any off-property lot is not affiliated with it. There is partial indoor waiting, and on crowded nights the line runs past the covered area.","The Crypt has free parking on site at its East Washington Street address. Scarizona says parking is free, and it bans alcohol anywhere on site, the parking areas included. Sanctum of Horror sits in a parking lot, so its parking is free and plentiful; its line and both mazes are outdoors. AZ Field of Screams does not publish parking details on its page.","With a chauffeur, the parking question goes away: the group steps out where the staff direct, walks in together, and walks back out to a vehicle that has been waiting nearby. Nobody circles the block, and nobody drives home after the scares."),ne("What is at Fear Farm in 2026?","Fear Farm’s 2026 attractions are Jason Universe: Survive the Night, Beyond the Veil, Mr. Tasty’s Funhouse, Sirens Wake, the Field of Fear Maze, Deadshot Alley, a zombie shooting range, and Phobia: Sensory Overload, with carnival ride passes on top; it is open rain or shine.","The haunt calls itself a haunted fairground, and the night is a walk from one attraction to the next. Fear Farm says the total time varies with how many attractions you visit and how busy the night is, so a group that wants all of them should plan a long evening and book the vehicle to match.","New for 2026, Fear Farm sells a VIP experience with extremely limited availability each night: a camp counsellor leads the group into a cabin where it picks how Jason attacks next.","Groups stay together. Fear Farm sends parties that bought their tickets together through in groups of 10, and says larger pre-purchased groups can usually be kept together if they ask at check-in. Buy the whole group’s tickets in one order, and the ride and the haunt both see one party."),ne("What is at The 13th Floor Phoenix in 2026?","The 13th Floor’s 2026 attractions are Dead City Uprising, House of Flesh and Reaping Grounds, with the Zombie Splat Gellyball Experience, Mini Escape Games and a Respawn Pass for a second run through; guests sign a waiver online before they go.","It is an indoor haunt on Bell Road in north Phoenix. The haunt’s hours vary by date, and its calendar shows each night’s times, so the pickup is set from the ticket time, with dinner before it if the group wants one.","For a group, the haunt says group pricing may be available for larger parties, and to contact it directly. Settle the tickets with the haunt, then send us the night and the time."),ne("What are The Crypt, Scarizona, Sanctum of Horror and AZ Field of Screams like?","The Crypt in Phoenix has six attractions and is a contact haunt, where actors may make light physical contact; Scarizona in Mesa is three outdoor haunts on one timed ticket; Sanctum of Horror in Mesa is two outdoor mazes; AZ Field of Screams in Glendale is a haunted corn maze planted, as its story goes, over an old cemetery.","The Crypt admits groups of two to six people into each attraction at a time and splits larger groups, so a crew of twelve walks through in pairs of six and meets again outside. It asks for closed-toe shoes and no loose clothing that could catch on the sets.","Scarizona’s three haunts are Mayhem in Madness, Startled Darkness and Dr. Death ICU. Every ticket is timed and non-refundable, and the busy nights sell out, so the group’s entry slot is the time the pickup is planned from. It asks for closed-toe shoes with sturdy soles, laced tight.","Sanctum of Horror runs Sanctum of Horror and The Breach, lets up to 8 people through at a time, and offers group rates for 13 or more with at least 24 hours’ notice. It is outdoors and closes for hard rain, hail or lightning; a ticket then works on a later night. Its Lights On daylight walkthrough is scareless and actorless, for families with young children.","AZ Field of Screams opens on Fridays, Saturdays and Halloween night only, from October 2 to 31, at Tolmachoff Farms. No food, drinks, alcohol or flashlights go inside the maze."),ne("Are the Phoenix haunted houses OK for kids and teenagers?",`Fear Farm and The 13th Floor say the event may be too intense for children 12 and under, Scarizona does not recommend it under 12, AZ Field of Screams does not recommend it under 13, and The Crypt admits only guests 13 and older, with anyone under 18 accompanied by a parent or guardian. For a teen group, our house rule applies: ${Ft}`,"The 13th Floor sets no minimum age but suggests guests 12 and older, and Fear Farm advises parental discretion. For younger children, Sanctum of Horror’s Lights On daylight walkthrough is the scareless option, on its own ticket.","Teenagers are a big part of the Halloween crowd, and a ride keeps a group of them together from the pickup to the door and home again. Put a parent’s or guardian’s cell number on the reservation, so the chauffeur has one point of contact for the night; at The Crypt that parent or guardian also walks in with anyone under 18.","Fear Farm and The 13th Floor run their own bars for guests 21 and over, with IDs checked on site: Fear Farm has two, The 13th Floor has the Tombstone Tiki. Those are the haunt’s, not ours. We sell no alcohol, and no package on this page carries a drink service."),ne("What can you bring to a haunted house: bags, costumes and masks?","Costumes are welcome at Fear Farm and The 13th Floor, but full-face masks and props are not, and The 13th Floor also bans full-face makeup that hides who you are; Scarizona bars costume masks and face coverings that conceal your identity, AZ Field of Screams bars face masks and costume props, and The 13th Floor and Scarizona both say larger bags should stay in your vehicle.","Fear Farm permits small bags, and The 13th Floor allows only small bags and clutches up to 4.5 by 6.5 inches and says larger bags should be left in your vehicle. Sanctum of Horror bars masks, helmets, oversized costumes and handheld props, and The Crypt asks for family-appropriate costumes with no realistic weapons.","That is where a chauffeured night helps: the bags, jackets, masks and the change of shoes stay in the vehicle, which waits nearby with the chauffeur, instead of in a parked car on a side street.","Dress for the walk and the line. Fear Farm is open rain or shine, Scarizona, Sanctum of Horror and the corn maze are outdoors, and The Crypt and Scarizona ask for closed-toe shoes."),ne("What does a haunted house night cost with a chauffeur?",`A haunt night is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${f(Y)} is ${Pr(Y)}/hr and seats ${Se(Y)}, a ${f(Cr)} is ${Pr(Cr)}/hr, the ${f(Ka)} is ${Pr(Ka)}/hr; haunt tickets are not included, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${Se(Y)} riders in the ${f(Y)} for 5 hours is about ${zi(Y,5,Se(Y))} each before tax. ${Se(Be)} riders sharing the ${f(Be)} for 5 hours at ${Pr(Be)}/hr is about ${zi(Be,5,Se(Be))} each. That is arithmetic on the published rates, not a flat Halloween fare.`,"The hours run from the pickup at your door to the drop-off at home, and the vehicle waits at the haunt in between, so the night is one booking, not two rides. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books.","Not in the fare: the haunt tickets, fast passes and ride passes, and anything bought inside."),{...ne("Can you do two haunted houses in one night?","Yes, with a vehicle that waits: pair two haunts in the same part of the Valley, such as Scarizona in Mesa then Fear Farm in Tempe, or AZ Field of Screams in Glendale then The 13th Floor on Bell Road, buy both tickets for the same night, and book the vehicle for the whole evening so it carries the group from one to the next.","Four pairs work well. The East Valley double: Scarizona Scaregrounds in Mesa, then Fear Farm in Tempe. The Mesa pair: Sanctum of Horror, then Scarizona. West Valley and north Phoenix: AZ Field of Screams in Glendale on a Friday or Saturday, then The 13th Floor on Bell Road. Central and Tempe: The Crypt on East Washington Street, then Fear Farm, the two longest seasons, so it works on a weeknight too.","Book the haunt with a timed entry first (Scarizona sells only timed tickets) and set the second haunt around it; check both calendars, since none of these haunts is open every night. A single haunt can fill an evening on a busy night, so a two-haunt crawl wants an early pickup and six hours or more on the vehicle.","Nobody re-parks between the two, the costumes and bags stay aboard, and the ride home is the same vehicle."),table:Yf},ne("What is there to do on Halloween night in Old Town Scottsdale?",`For adults, Halloween in Scottsdale is a costume night out in Old Town’s bars and clubs, and Halloween 2026 falls on a Saturday; the City’s Transportation Safety Zone covers the entertainment district every night into the early morning, so hired vehicles load only at the marked Passenger Convenience Areas, and a ${f(Cr)} meets the group there.`,"A haunt first and Old Town after is a common shape for a 21-and-over group: the scares early, then the bars, with the vehicle carrying the costumes between the two and everyone home at the end.",`The package for it is the Old Town Halloween Night (21+): a Limo Party Sprinter, a red carpet for the costume photos and the crew’s name on a sign. It is for guests 21 and over; ${Ft}`),ne("Which vehicle fits a Halloween haunt group?",`VIP groups lead with the ${f(Y)}, our pick for a haunt night, then the ${f($r)}, the ${f(Bi)} and the Suburban; friends and birthday crews ride a Limo Party Sprinter or the ${Se(Be)}-seat party bus; teens and families take the ${f(Ka)}, the white Executive Sprinter or the ${f(Hi)}.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. VIP: the ${f($r)}, the ${f(Y)}, the ${f(Bi)} and the ${f(wn)}. Friends and birthday crews: the ${f(Cr)}, the ${f(Hf)} and the ${f(Be)}. Teens and families: the ${f(Ka)}, the ${f(zf)} and the ${f(Hi)}.`,`A VIP party larger than the ${f(Y)} rides in two vehicles, one booking each for the same night and times: the ${f(Y)} with the ${f($r)} seats ${Se(Y)+Se($r)}, and with the ${f(wn)} it seats ${Se(Y)+Se(wn)}.`,"Count heads from the ticket order. Fear Farm moves bought-together parties through in groups of 10, so a crew of 13 or 16 is two haunt groups but one vehicle, and one pickup."),ne("When should you go, and is Halloween night busy?","Halloween 2026, October 31, falls on a Saturday, so the weekend before it and Halloween night itself are the nights to book first; every haunt opens select nights only, The 13th Floor, Scarizona and the corn maze close by November 1, The Crypt runs to November 7, and Fear Farm to November 14 for a quieter night after Halloween.","The haunts publish their open nights and each night’s times on their ticket calendars, and weekends in October are what everyone wants. A group with a flexible date gets the best choice of vehicles on a weeknight or in the first days of November at Fear Farm or The Crypt.","Book the tickets for a timed entry if the haunt offers one, then set the pickup so the group arrives with time to spare for the line."),ne("How far ahead should a Halloween ride be booked?","Buy the haunt tickets first, then book the ride: availability varies by night and vehicle, so no fixed lead time applies, and the October weekends and Halloween night go first; send the date, the rider count, the pickup address and the haunt, and the reservations team confirms what is open.","The first request needs the night, the home, hotel or school pickup, a likely passenger count, the haunt, and the ticket time. A group does not need every name to begin. It does need to say which group is riding: VIP guests, a friends’ or birthday crew, or teens with a guardian’s number.",`During the final 48 hours, confirm addresses, phone numbers and the ticket time. Reach the reservations team at ${u} or ${p}. A ride booking never includes a haunt ticket.`)],Zf=[{question:"Are there haunted houses in Phoenix, Arizona?",answer:"Yes. For 2026: Fear Farm in Tempe, The 13th Floor and The Crypt in Phoenix, Scarizona Scaregrounds and Sanctum of Horror in Mesa, and AZ Field of Screams, a haunted corn maze in Glendale. Each opens on select nights and sells its own tickets."},{question:"What is the scariest haunted house in Arizona?",answer:"Scary is personal, so go by what the haunts say about themselves: The Crypt is a contact haunt that admits only guests 13 and older, Scarizona says it is designed to be intense and is not recommended under 12, and Fear Farm and The 13th Floor say they may be too intense for 12 and under."},{question:"When does Fear Farm open in 2026?",answer:"Fear Farm’s 2026 season runs select nights from September 19 to November 14, 2026. Not every night is open; the haunt’s ticket calendar lists the open nights and times."},{question:"Where is Fear Farm now?",answer:"At 1475 N McClintock Dr, Tempe, AZ 85257. Fear Farm asks guests to use that address, because rideshare and map apps may not be current if you search the business name."},{question:"When does The 13th Floor Phoenix close for 2026?",answer:"The 13th Floor Phoenix is open select nights from September 19 to November 1, 2026, at 2710 W Bell Rd, Suite 1180, Phoenix, AZ 85053."},{question:"Is there parking at The 13th Floor Phoenix?",answer:"The haunt says free street parking is available around it; don’t park in front of no-parking signs, gates or driveways, and keep valuables out of sight. A chauffeured group skips parking altogether."},{question:"Can you wear a mask to a haunted house in Phoenix?",answer:"No. Costumes are welcome, but Fear Farm, The 13th Floor, Scarizona, Sanctum of Horror and AZ Field of Screams all bar full-face or costume masks, and The 13th Floor also bans full-face makeup that hides your identity. Leave the mask in the vehicle."},{question:"How old do you have to be for the Phoenix haunted houses?",answer:"The Crypt admits only guests 13 and older, with anyone under 18 accompanied by a parent or guardian. Fear Farm and The 13th Floor say they may be too intense for 12 and under, Scarizona does not recommend it under 12, and AZ Field of Screams not under 13."},{question:"Can you rent a party bus for a haunted house night?",answer:`Yes. The ${f(Be)} and the Limo Party Sprinters are booked by the hour, pickup to drop-off, and wait at the haunt for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`},{question:"Is there a Halloween party bus in Scottsdale?",answer:`Yes. Scottsdale Sprinters runs the ${f(Y)}, the Limo Party Sprinters and the ${Se(Be)}-seat party bus from Scottsdale for Halloween nights, to a haunt, through Old Town, or both, billed by the hour at published rates.`},{question:"Is Halloween on a Saturday in 2026?",answer:"Yes. October 31, 2026 is a Saturday, so Halloween weekend and the weekend before it are the busiest haunt nights of the season."}],Kf={path:"/guides/halloween-haunted-houses-phoenix",title:"Phoenix haunted houses 2026: six haunts compared, and a Halloween party bus",metaTitle:"Phoenix Haunted Houses 2026 & Rides",description:"The Phoenix haunted houses for Halloween 2026 side by side: Fear Farm, The 13th Floor, The Crypt, Scarizona, Sanctum of Horror and AZ Field of Screams, their seasons, ages, parking, masks and bags, two-haunt crawls, Old Town Halloween night, and a chauffeured ride so nobody drives.",metaDescription:"Dates, ages, parking and mask rules, Fear Farm to The Crypt",lastUpdated:Ui,lastUpdatedLabel:l(Ui),eyebrow:"Six haunts · September 19 to November 14",intro:`A haunt night with Scottsdale Sprinters starts with the haunt’s own season, the night the group’s tickets are for and a rider count. This guide sets the six Phoenix-area haunts side by side, from their own published pages, then turns the night into a written pickup, drop-off and ride home. VIP groups lead with the ${f(Y)}; friends’ and birthday crews ride a Limo Party Sprinter or the party bus; teens and families take the Executive Sprinter or the Mini Bus, alcohol-free.`,sections:Jf,faqs:Zf,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:f(Y)},{href:"/fleet/party-bus-28-scottsdale",label:f(Be)},{href:"/fleet/executive-sprinter-scottsdale",label:f(Ka)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/service-areas/mesa",label:"Mesa service area"},{href:"/services/scottsdale-nightlife-transportation",label:"Scottsdale nightlife transportation"},{href:"/experiences/birthday-celebration",label:"Birthday party rides"},{href:"/pricing",label:"Published hourly pricing"}],sources:qf,fleetRows:Bf},Mt="2026-09-26",Us="/guides/jonas-brothers-phoenix-2026",Bs="/guides/harry-styles-phoenix-2027",Hs="/guides/trans-siberian-orchestra-phoenix-2026",zs="/guides/hans-zimmer-phoenix-2027",fr="/guides/phoenix-concerts-2026-2027",ge="ultra-luxury-party-sprinter-scottsdale",Ra="maybach-jet-sprinter-scottsdale",jf="maybach-shuttle-sprinter-8",Sd="premium-suv-scottsdale",vn="limo-sprinter-13-scottsdale",sr="limo-sprinter-16-scottsdale",st="executive-sprinter-scottsdale",Er="party-bus-28-scottsdale",ur="executive-mini-bus-26-scottsdale",A=e=>n[e],Et=e=>i[e],Fr=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`;function R(e,t,...a){return{question:e,answer:t,paragraphs:a}}function $o(e,t){return R(`Which vehicle fits a group going to ${e}?`,`Our pick for ${e} is the ${A(ge)}, ${Fr(ge)}, seating ${Et(ge)}. A VIP night takes the ${A(Ra)} (${Et(Ra)} seats), the ${A(jf)} or the ${A(Sd)}; a friend crew takes the ${A(vn)} or the ${A(sr)}; a big group takes the ${A(Er)} (${Et(Er)} seats).`,`The ${A(ge)} has fiber-optic lighting with eighteen modes, lasers and a fog machine, an ultra-premium sound system and a partition with an intercom to your chauffeur. The ${A(vn)} is ${Fr(vn)} and the ${A(sr)} is ${Fr(sr)}; the ${A(Er)} is ${Fr(Er)}. Every rate prices the whole vehicle, before tax, so one more rider does not change it.`,t,`Reach the reservations team at ${u} or ${p} with the show, the pickup address and the rider count. Count riders for the ride home as well as the ride there.`)}const eo="https://www.desertdiamondarena.com",Qf=`${eo}/event/jonas-brothers/112/`,Xf=[{label:"Desert Diamond Arena, Jonas Brothers event page",href:Qf},{label:"Desert Diamond Arena, parking and directions",href:`${eo}/venue-info/parking/`},{label:"Desert Diamond Arena, A to Z guide and bag policy",href:`${eo}/venue-info/azguide/`},{label:"Desert Diamond Arena, venue information",href:`${eo}/venue-info/`},{label:"Westgate Entertainment District",href:"https://westgateaz.com/"}],em=[R("When are the Jonas Brothers in Phoenix?","The Jonas Brothers play Desert Diamond Arena in Glendale on Friday, November 27, 2026, the day after Thanksgiving, on The Burning Up Tour All Over Again. Doors open at 6:30 p.m. and the show starts at 7:30 p.m., as the arena’s event page lists them.","It is one night in the Phoenix area. The arena is at 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101, not in downtown Phoenix: plan the ride to the West Valley.","By Google’s typical drive time, measured without event traffic, the arena is 23 minutes from downtown Phoenix, 28 from Phoenix Sky Harbor and 36 from Old Town Scottsdale or Kierland. On a sold-out holiday Friday, the last mile takes the longest."),R("Where do you park for the Jonas Brothers at Desert Diamond Arena?","In the arena’s own lots, which open one hour before doors, so at 5:30 p.m. for this show. Day-of spaces are in lots G, J, L, Yellow, the Garage and VIP as the event allows, the entrances take cards only, and a space pre-paid on the event page is held until 30 minutes after the start.","The arena publishes no parking price: it is set by event and shown when you buy the space. Every pass covers one standard space, oversized vehicles buy more, and overnight parking is not allowed. Our Desert Diamond Arena guide has the full lot rules and the parking map.","Or skip the lot: a chauffeured group is dropped where arena staff direct and picked up at a point agreed before the show, so nobody queues at a card reader or drives home."),R("Where does a limo or party bus drop off for the Jonas Brothers?","Desert Diamond Arena publishes no rideshare, limo, charter or bus drop-off zone, so a chauffeured group unloads where arena staff and police direct on the night and agrees one pickup point for the ride home before walking in.","The chauffeur drives the approach the event traffic allows and meets the group once the crowd clears. If the arena publishes a drop-off plan for the show, that plan replaces this paragraph."),R("What bags are allowed at the Jonas Brothers concert?","Desert Diamond Arena allows bags and purses up to 12 by 12 by 6 inches, clear or not. Laptop bags, briefcases, camera bags, coolers, luggage and seat cushions are not allowed at any size, and neither is outside food or drink apart from a factory-sealed water bottle under 17 ounces.","Settle bags at the hotel or at home. A group that is dropped off has no car in the lot to go back to."),R("How should a group plan the Jonas Brothers night?","Work back from the 6:30 p.m. doors: a pickup that lands the group at the arena around doors leaves time for the lines and the bag check, and one that leaves earlier makes room for dinner at Westgate, across Entertainment Boulevard from the arena.","Book by the hour and the vehicle is yours for the whole evening: pickup, dinner, the show and the ride home, with the chauffeur waiting nearby. Or book a ride there and a ride back.","Tell us the dinner reservation when you book, and the chauffeur sets the pickup around it."),R("Is there a VIP or early-entry option for the Jonas Brothers at Desert Diamond Arena?","Yes, two upgrades sold on the arena’s Jonas Brothers event page. The Bassline Bar lets guests in 60 minutes before general doors, between Gates 3 and 4, with a private bar and bathroom all night and the arena’s only outdoor smoking section. VIP parking is reserved front-row parking with an express lane in and out.","The Bassline Bar is not a show ticket: every guest still needs a Jonas Brothers ticket as well. For this show it means going in at 5:30 p.m., an hour before the 6:30 p.m. doors, so a group booked into it sets the pickup an hour earlier than the plan below.","A chauffeured group needs neither parking pass: it is dropped where arena staff direct and picked up at the point agreed before the show. The arena also rents its premium spaces for single events."),$o("the Jonas Brothers",`Families with younger fans ride the ${A(st)}, reclining leather with room for everyone’s coats, or the ${A(ur)} for a bigger family group.`)],tm=[{question:"When are the Jonas Brothers in Phoenix in 2026?",answer:"Friday, November 27, 2026, at Desert Diamond Arena in Glendale, on The Burning Up Tour All Over Again. Doors 6:30 p.m., show 7:30 p.m."},{question:"Where is the Jonas Brothers concert in Phoenix?",answer:"At Desert Diamond Arena, 9400 West Maryland Avenue, Glendale, in the Westgate Entertainment District beside State Farm Stadium, not in downtown Phoenix."},{question:"What time do the Desert Diamond Arena lots open for the Jonas Brothers?",answer:"One hour before doors, so 5:30 p.m. The entrances take cards only, and a pre-paid space is held until 30 minutes after the 7:30 p.m. start."},{question:"Can a limo or party bus drop us off at the Jonas Brothers concert?",answer:"Yes, where arena staff and police direct on the night. The arena publishes no limo or rideshare zone, so the chauffeur confirms the drop-off and agrees one pickup point for after the show."},{question:"What size bag can you bring to Desert Diamond Arena?",answer:"Up to 12 by 12 by 6 inches, clear or not. No laptop bags, camera bags, coolers or luggage at any size."},{question:"Who is opening for the Jonas Brothers in Phoenix?",answer:"No opening act is listed yet. As of September 26, 2026, the arena’s event page for Friday, November 27 names only the Jonas Brothers, on The Burning Up Tour All Over Again, with doors at 6:30 p.m. and the show at 7:30 p.m."},{question:"What is the Bassline Bar at Desert Diamond Arena?",answer:"A paid upgrade, not a ticket: entry 60 minutes before general doors between Gates 3 and 4, a private bar and bathroom all night, and the arena’s only outdoor smoking section. Each guest also needs a show ticket."}],am={path:Us,title:"Jonas Brothers in Phoenix, November 27, 2026: Desert Diamond Arena parking, doors and the ride",metaTitle:"Jonas Brothers Phoenix 2026: Parking",description:"The Jonas Brothers at Desert Diamond Arena in Glendale on Friday, November 27, 2026: doors and show times, the arena’s lots, the bag policy, where groups are dropped off, and a chauffeured ride so nobody drives or parks.",metaDescription:"Doors 6:30, show 7:30, the arena lots and the ride home",lastUpdated:Mt,lastUpdatedLabel:l(Mt),eyebrow:"Desert Diamond Arena · Glendale · Fri, Nov 27, 2026",intro:"Scottsdale Sprinters’ short answer: the Jonas Brothers play Desert Diamond Arena in Glendale on Friday, November 27, 2026, with doors at 6:30 p.m. and the show at 7:30 p.m. The arena lots open an hour before doors and take cards only, and bags can be up to 12 by 12 by 6 inches. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive home.",sections:em,faqs:tm,links:[{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking and shows"},{href:fr,label:"Phoenix concerts 2026–27, venue by venue"},{href:Bs,label:"Harry Styles at State Farm Stadium, April 2027"},{href:`/fleet/${ge}`,label:A(ge)},{href:`/fleet/${sr}`,label:A(sr)},{href:"/pricing",label:"Published hourly pricing"}],sources:Xf},to="https://www.statefarmstadium.com",rm=`${to}/events/detail/tgtgtour`,om=[{label:"State Farm Stadium, Harry Styles: Together, Together Tour 2027",href:rm},{label:"State Farm Stadium, directions and parking",href:`${to}/plan-your-visit/directions-parking`},{label:"State Farm Stadium, safety and clear bag policy",href:`${to}/clear-bag-policy`},{label:"State Farm Stadium, A-Z guide",href:`${to}/a-z-guide`},{label:"Valley Metro, West Valley destinations",href:"https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley"}],nm=[R("When is Harry Styles in Phoenix?","Harry Styles plays State Farm Stadium in Glendale on two nights, Friday, April 2, and Saturday, April 3, 2027, on the Together, Together Tour 2027. Both shows start at 7:45 p.m., as the stadium’s event page lists them; it does not publish a doors time.","State Farm Stadium is at 1 Cardinals Drive, Glendale, AZ 85305, the home of the Arizona Cardinals, beside Desert Diamond Arena and the Westgate Entertainment District off Loop 101. From Old Town Scottsdale it is about 36 minutes by Google’s typical drive time without event traffic; from Phoenix Sky Harbor about 27.","Two stadium nights in a row means two full nights of traffic on the same roads. Book your night, not just the weekend."),R("Where do you park for Harry Styles at State Farm Stadium?","The stadium’s Harry Styles page recommends buying parking in advance through SeatGeek, and every parking area at State Farm Stadium is cashless. Staff and Glendale police direct cars to the lots with room, so you do not pick your lot on the night.","Concerts set their own lot hours, separate from Cardinals game days: check the event page before you leave. Our State Farm Stadium guide has the lot map, the exit routes and the full parking answer.","Or skip the lot: a chauffeured group heads for the Black Lot, the stadium’s named drop-off and pickup, and nobody waits in the exit line after the encore."),R("Where is the drop-off and rideshare pickup for Harry Styles?","State Farm Stadium names the Black Lot, south of the stadium across Cardinals Way, as its drop-off and pickup for rideshare and for family and friends. No limo or charter lane is published, so the exact spot for a chauffeured vehicle follows the event’s traffic plan on the night.","Every rideshare guest uses the same point after the show, which is where the waits build. A booked vehicle meets the group at a point agreed before the show and leaves once everyone is aboard."),R("What bags are allowed at the Harry Styles concert?","One clear bag up to 12 by 6 by 12 inches, or a one-gallon clear freezer bag, and the stadium strongly recommends bringing no bag at all. Small non-clear bags up to 4.5 by 6.5 inches are allowed under the stadium’s clear bag policy; coolers are not.","Once you leave the stadium there is no re-entry, and a group that is dropped off has no car in the lot to leave a bag in. Settle bags before pickup."),R("How should a group plan a Harry Styles night?","Work back from the 7:45 p.m. start: a pickup that lands the group at the Black Lot well before the show leaves time for security, merchandise and finding seats in a stadium this size.","Book by the hour and the vehicle is yours for the whole night, dinner at Westgate included, or book a ride there and a ride back. Tell us which night, April 2 or April 3, when you book: each is its own date.","Coming from out of town? We pick up at Phoenix Sky Harbor and at any Valley hotel, and the same vehicle can take the group to the show."),R("Can you bring a sign, water or kids to Harry Styles at State Farm Stadium?","Kids can come, but every guest needs a ticket, whatever their age. One factory-sealed, non-frozen 500 mL bottle of plain water is allowed. The stadium’s prohibited list on the Harry Styles event page includes banners or signs larger than 3 by 2 feet or with a non-sport message, so check before making one.","Also on that list: coolers of any kind, outside food (except for children under two), umbrellas longer than 12 inches, poles and selfie sticks, and cameras with professional lenses. The stadium has no place to store a prohibited item and sends it back to the car, so a group that was dropped off should leave it at home.","For families, every restroom has a baby-changing station, and Guest Services booths hand out diapers and wipes. Unopened bottles, formula and baby food for a child under two go in an approved clear bag, and umbrella-style strollers are allowed after inspection; diaper bags are not.","For a VIP group, the stadium sells premium seating for groups of 2 to 150, and its packages include complimentary parking and expedited entry."),$o("Harry Styles",`For a family or a group that wants a quieter ride, the ${A(st)} seats ${Et(st)} in reclining leather, and the ${A(ur)} seats ${Et(ur)}.`)],sm=[{question:"When is Harry Styles in Phoenix in 2027?",answer:"Friday, April 2, and Saturday, April 3, 2027, at State Farm Stadium in Glendale, on the Together, Together Tour 2027. Both shows start at 7:45 p.m."},{question:"Where is the Harry Styles concert in Phoenix?",answer:"At State Farm Stadium, 1 Cardinals Drive, Glendale, in the Westgate area off Loop 101, west of downtown Phoenix."},{question:"How do you park for Harry Styles at State Farm Stadium?",answer:"The stadium recommends buying parking in advance through SeatGeek, and every lot is cashless. Staff direct cars to lots with room on the night."},{question:"Where is rideshare pickup after Harry Styles at State Farm Stadium?",answer:"The Black Lot, south of the stadium across Cardinals Way, is the stadium’s drop-off and pickup for rideshare and for family and friends."},{question:"What bag can you bring to State Farm Stadium for Harry Styles?",answer:"One clear bag up to 12 by 6 by 12 inches or a one-gallon clear freezer bag, plus a small clutch up to 4.5 by 6.5 inches. The stadium recommends bringing no bag."},{question:"Do kids need a ticket for Harry Styles at State Farm Stadium?",answer:"Yes. The stadium’s family information says all guests, regardless of age, require a ticket. Umbrella-style strollers are allowed after inspection; diaper bags are not."},{question:"Can you bring a sign to Harry Styles at State Farm Stadium?",answer:"Check the size and wording first. The stadium’s prohibited list, printed on the Harry Styles event page, includes banners or signs larger than 3 by 2 feet or with a non-sport message."}],im={path:Bs,title:"Harry Styles in Phoenix, April 2–3, 2027: State Farm Stadium parking, drop-off and the ride home",metaTitle:"Harry Styles Phoenix 2027 & Parking",description:"Harry Styles at State Farm Stadium in Glendale on April 2 and 3, 2027: the show times, how the stadium’s parking works, the Black Lot drop-off, the clear bag policy, and a chauffeured ride so nobody drives or parks.",metaDescription:"Show times, SeatGeek parking, the Black Lot and the ride",lastUpdated:Mt,lastUpdatedLabel:l(Mt),eyebrow:"State Farm Stadium · Glendale · Apr 2–3, 2027",intro:"Scottsdale Sprinters’ short answer: Harry Styles plays State Farm Stadium in Glendale on Friday, April 2, and Saturday, April 3, 2027, both nights at 7:45 p.m. The stadium recommends buying parking ahead on SeatGeek, every lot is cashless, and rideshare and drop-offs use the Black Lot south of the stadium. For a group, one chauffeured vehicle replaces the lot, the exit line and the drive home.",sections:nm,faqs:sm,links:[{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking, lots and the Black Lot"},{href:fr,label:"Phoenix concerts 2026–27, venue by venue"},{href:Us,label:"Jonas Brothers at Desert Diamond Arena, November 2026"},{href:`/fleet/${ge}`,label:A(ge)},{href:`/fleet/${Ra}`,label:A(Ra)},{href:"/pricing",label:"Published hourly pricing"}],sources:om},Co="https://mortgagematchupcenter.com",hm=`${Co}/events/transsiberian-orchestra/`,Ad=`${Co}/plan-your-visit/transportation-parking/`,dm=[{label:"Mortgage Matchup Center, Trans-Siberian Orchestra event page",href:hm},{label:"Mortgage Matchup Center, transportation and parking",href:Ad},{label:"Mortgage Matchup Center, official venue site (bag policy, door times)",href:`${Co}/`}],lm=[R("When is Trans-Siberian Orchestra in Phoenix?",'Trans-Siberian Orchestra plays Mortgage Matchup Center in downtown Phoenix on Sunday, December 6, 2026, twice: a 3:00 p.m. matinee and a 7:30 p.m. show. Doors open 60 minutes before each, at 2:00 and 6:30 p.m. It is the 30th Anniversary Winter Tour, "Ghosts of Christmas Eve: The Best of TSO and More."',"Mortgage Matchup Center is the arena formerly called Footprint Center, at 201 East Jefferson Street, Phoenix, AZ 85004, the home of the Suns. Same building, new name: older tickets, maps and posts still use the old one.","The arena describes the show as its reimagined winter tale followed by a second set with lasers, pyrotechnics and special effects, for an audience of every generation."),R("Where do you park for Trans-Siberian Orchestra at Mortgage Matchup Center?","In the garages and lots within walking distance of the arena, which it says to buy ahead through ParkWhiz. Event parking generally opens about 30 minutes before doors, so about 1:30 p.m. for the matinee and 6:00 p.m. for the evening show, and there is no in-and-out.","Valet is not public: the arena reserves it for select guests and membership areas. Our Mortgage Matchup Center guide has the garages, the light rail and the full parking answer.","Or skip the garage: a chauffeured group is dropped at the arena’s curb on 3rd Street and nobody walks back to a car in December."),R("Where is the drop-off for Trans-Siberian Orchestra?","The arena’s drop-off and pickup is on 3rd Street just south of Jefferson, at the green curb, and no vehicle may wait there. We unload there or where event staff direct, clear the curb, and come back when the group is together after the show.","Rideshare pickups after an event are at 3rd Street and Jefferson, by the Phoenix Convention Center."),R("What bags are allowed at Mortgage Matchup Center for TSO?","Small clutches and crossbody bags are allowed; purses, medical bags and diaper bags are allowed within 14 by 14 by 6 inches with extra screening; standard backpacks are not allowed inside.","Guests without bags, or with a clutch smaller than 4 by 6 inches, can use the Evolv express lanes, which the arena recommends as the quickest way in. Leave the coats and the shopping in the vehicle: with a booked ride, it waits for you."),R("Can we see Christmas lights after the Trans-Siberian Orchestra show?","Yes. The 3:00 p.m. matinee leaves the evening open for holiday lights: ZooLights at the Phoenix Zoo runs 5:30 to 10:30 p.m. and Christmas at the Princess in Scottsdale opens at 4 p.m. on Sundays, both on December 6. Book the vehicle by the hour and it takes the group from the arena to the lights and home.","For the 7:30 p.m. show, turn it around: the lights first, then the concert. Our holiday lights guide has each display’s 2026 dates, hours and drop-off."),R("Can you buy Trans-Siberian Orchestra tickets at the Mortgage Matchup Center box office?","Yes. The box office is at the arena, 201 East Jefferson Street, and on weekend event days it opens three hours before the event, so at noon on Sunday, December 6 for the 3:00 p.m. matinee. Every ticket it sells is delivered to your phone; the windows print no paper tickets.","The arena files both December 6 shows under its Family category, and it has more than 700 parking spaces on its own property, with prices set by event through its parking office. A chauffeured group skips the garage and the walk back in December."),$o("Trans-Siberian Orchestra",`TSO is a family tradition for many groups: the ${A(st)} seats ${Et(st)} in reclining leather with room for coats, and the ${A(ur)} seats ${Et(ur)} for the whole extended family.`)],cm=[{question:"When is Trans-Siberian Orchestra in Phoenix in 2026?",answer:"Sunday, December 6, 2026, at Mortgage Matchup Center in downtown Phoenix: a 3:00 p.m. matinee and a 7:30 p.m. show, with doors 60 minutes before each."},{question:"Is Mortgage Matchup Center the same as Footprint Center?",answer:"Yes. Mortgage Matchup Center is the new name of the arena formerly called Footprint Center, at 201 East Jefferson Street in downtown Phoenix."},{question:"Where do you park for TSO at Mortgage Matchup Center?",answer:"In the nearby garages and lots, bought ahead through ParkWhiz as the arena advises. Event parking generally opens about 30 minutes before doors, with no in-and-out."},{question:"Where is the drop-off at Mortgage Matchup Center?",answer:"On 3rd Street just south of Jefferson, at the green curb. No vehicle may wait there, so the chauffeur clears the curb and comes back after the show."},{question:"Can we do Christmas lights and TSO in one day?",answer:"Yes. The 3:00 p.m. matinee leaves the evening for ZooLights (5:30 to 10:30 p.m.) or Christmas at the Princess the same evening, in one vehicle booked by the hour."},{question:"What is the Trans-Siberian Orchestra show in Phoenix in 2026?",answer:"The 30th anniversary winter tour: a reimagined staging of TSO’s tale The Ghosts of Christmas Eve, then a high-energy second set, with lasers, pyrotechnics and special effects, as the arena describes it. Two shows on Sunday, December 6: 3:00 and 7:30 p.m."}],um={path:Hs,title:"Trans-Siberian Orchestra in Phoenix, December 6, 2026: both shows, parking and the ride",metaTitle:"Trans-Siberian Orchestra Phoenix 2026",description:"Trans-Siberian Orchestra at Mortgage Matchup Center (formerly Footprint Center) on Sunday, December 6, 2026: the 3 p.m. matinee and the 7:30 p.m. show, downtown parking, the 3rd Street drop-off, the bag policy, and a chauffeured holiday night with the lights.",metaDescription:"The matinee, the evening show, parking and the lights after",lastUpdated:Mt,lastUpdatedLabel:l(Mt),eyebrow:"Mortgage Matchup Center · Phoenix · Sun, Dec 6, 2026",intro:"Scottsdale Sprinters’ short answer: Trans-Siberian Orchestra plays Mortgage Matchup Center, the former Footprint Center in downtown Phoenix, on Sunday, December 6, 2026, at 3:00 p.m. and 7:30 p.m., with doors an hour before each. Parking is in nearby garages bought ahead on ParkWhiz, and the drop-off is on 3rd Street. For a group, one chauffeured vehicle covers the show and the Christmas lights after it.",sections:lm,faqs:cm,links:[{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center parking and the 3rd Street drop-off"},{href:"/guides/christmas-lights-scottsdale-phoenix",label:"Christmas at the Princess, ZooLights and the 2026 lights"},{href:fr,label:"Phoenix concerts 2026–27, venue by venue"},{href:zs,label:"Hans Zimmer Live at the same arena, March 2027"},{href:`/fleet/${ge}`,label:A(ge)},{href:`/fleet/${st}`,label:A(st)}],sources:dm},pm=`${Co}/events/hans-zimmer-live/`,fm=[{label:"Mortgage Matchup Center, Hans Zimmer Live event page",href:pm},{label:"Mortgage Matchup Center, transportation and parking",href:Ad},{label:"Live Nation, Mortgage Matchup Center events",href:"https://www.livenation.com/venue/KovZpZAE617A/mortgage-matchup-center-events"},{label:"Fever, Candlelight: The Best of Hans Zimmer (a tribute concert)",href:"https://feverup.com/m/116531"}],mm=[R("When is Hans Zimmer in Phoenix?","Hans Zimmer Live – The Next Level plays Mortgage Matchup Center in downtown Phoenix on Tuesday, March 30, 2027. The arena’s event page lists the start at 7:00 p.m.; Live Nation’s listing says 7:30 p.m., so plan for 7:00 and check the arena’s page closer to the date.","Zimmer performs with his 19-piece band. The arena, formerly Footprint Center, is at 201 East Jefferson Street, Phoenix, AZ 85004."),R("Where do you park for Hans Zimmer at Mortgage Matchup Center?","In the garages and lots within walking distance, bought ahead through ParkWhiz as the arena advises. Event parking generally opens about 30 minutes before doors and there is no in-and-out; the arena does not publish a doors time for this show yet.","Our Mortgage Matchup Center guide has the garages, the light rail and the full parking answer."),R("Where is the drop-off for Hans Zimmer Live?","On 3rd Street just south of Jefferson, at the green curb: the arena’s drop-off and pickup for events. No vehicle may wait there, so we unload, clear the curb and come back when the group is together after the show."),R("What can you bring to Hans Zimmer Live?","Bags must fit within 14 by 14 by 6 inches and backpacks are not allowed, as the event page states. Professional cameras and audio or video recording devices are prohibited.","Leave the extras in the vehicle: with a booked ride it waits nearby, and nobody walks back to a garage."),R("How should a group plan the Hans Zimmer night?","Plan the pickup back from the 7:00 p.m. start on the arena’s page, with time for dinner downtown first. Book by the hour and the vehicle is yours for dinner, the show and the ride home, or book a ride there and a ride back.","It suits a quieter cabin as well as a party one: the Maybach Jet or the Suburban for a couple, the Party Sprinter for a crew."),R("Is Candlelight’s Best of Hans Zimmer the same concert as Hans Zimmer Live?","No. Candlelight: The Best of Hans Zimmer, held at the Phoenix Zoo and other Phoenix venues, is a tribute concert played by a string quartet, and its organizer, Fever, says it is not affiliated with the artist. Hans Zimmer himself plays Hans Zimmer Live – The Next Level at Mortgage Matchup Center on Tuesday, March 30, 2027.","The arena’s page puts Zimmer on stage with his 19-piece band. Buy from the arena’s event page, and check that the ticket names Hans Zimmer Live – The Next Level and Mortgage Matchup Center.","The arena box office at 201 East Jefferson Street sells tickets too, delivered to your phone. On a weekday event it opens at 3 p.m."),$o("Hans Zimmer Live",`For a quieter ride, the ${A(st)} seats ${Et(st)} in reclining black leather, and the ${A(Sd)} is black on black for a couple.`)],gm=[{question:"When is Hans Zimmer in Phoenix?",answer:"Tuesday, March 30, 2027, at Mortgage Matchup Center in downtown Phoenix. The arena lists 7:00 p.m.; Live Nation lists 7:30 p.m."},{question:"Where is Hans Zimmer Live in Phoenix?",answer:"At Mortgage Matchup Center, formerly Footprint Center, 201 East Jefferson Street, Phoenix."},{question:"What is the bag policy for Hans Zimmer at Mortgage Matchup Center?",answer:"Bags up to 14 by 14 by 6 inches; no backpacks. Professional cameras and recording devices are prohibited."},{question:"Where do you get dropped off for Hans Zimmer?",answer:"At the arena’s curb on 3rd Street just south of Jefferson. No vehicle may wait there, so the chauffeur comes back for the group after the show."},{question:"Is the Candlelight Hans Zimmer concert the real Hans Zimmer?",answer:"No. Candlelight: The Best of Hans Zimmer is a string-quartet tribute that Fever says is not affiliated with the artist. Zimmer himself plays Mortgage Matchup Center on March 30, 2027, with his 19-piece band."}],ym={path:zs,title:"Hans Zimmer Live in Phoenix, March 30, 2027: Mortgage Matchup Center parking and the ride",metaTitle:"Hans Zimmer Live Phoenix 2027",description:"Hans Zimmer Live – The Next Level at Mortgage Matchup Center (formerly Footprint Center) on Tuesday, March 30, 2027: the start time, downtown parking, the 3rd Street drop-off, the bag rules, and a chauffeured ride so nobody drives or parks.",metaDescription:"The start time, downtown parking, bags and the ride home",lastUpdated:Mt,lastUpdatedLabel:l(Mt),eyebrow:"Mortgage Matchup Center · Phoenix · Tue, Mar 30, 2027",intro:"Scottsdale Sprinters’ short answer: Hans Zimmer Live – The Next Level plays Mortgage Matchup Center in downtown Phoenix on Tuesday, March 30, 2027, at 7:00 p.m. on the arena’s page. Parking is in nearby garages bought ahead on ParkWhiz, bags must fit 14 by 14 by 6 inches, and the drop-off is on 3rd Street. For a group, one chauffeured vehicle covers dinner, the show and the ride home.",sections:mm,faqs:gm,links:[{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center parking and shows"},{href:fr,label:"Phoenix concerts 2026–27, venue by venue"},{href:Hs,label:"Trans-Siberian Orchestra at the same arena, December 2026"},{href:`/fleet/${Ra}`,label:A(Ra)},{href:`/fleet/${ge}`,label:A(ge)},{href:"/pricing",label:"Published hourly pricing"}],sources:fm},qi="2026-09-26",bm="https://www.inningsfestival.com/",ma="https://help.inningsfestival.com/article",wm=`${ma}/224-what-are-the-dates-hours-of-innings-festival`,vm=`${ma}/229-community-information-page`,km=`${ma}/250-how-do-i-get-home-from-the-festival`,Sm=`${ma}/196-what-is-the-bag-policy`,Am=`${ma}/249-what-are-the-ticket-tiers-what-is-the-difference-in-ticket-tiers`,Tm=`${ma}/204-ticket-and-wristband-policy`,$m=`${ma}/247-family-services`,Cm="https://www.downtowntempe.com/get-around/parking",Pm="https://www.valleymetro.org/how-to-ride/destinations/destinations-tempe",kn={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["party-bus-28-scottsdale","executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},Sn={oldTown:15,kierland:28},Em=[...kn.crews,...kn.vip,...kn.big].filter(ae),Fm=Em.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),Ge="ultra-luxury-party-sprinter-scottsdale",_t="maybach-jet-sprinter-scottsdale",Mr="maybach-shuttle-sprinter-8",An="premium-suv-scottsdale",ja="limo-sprinter-13-scottsdale",Mm="limo-sprinter-16-scottsdale",Ps="party-bus-28-scottsdale",Vi="executive-sprinter-scottsdale",Rm="executive-mini-bus-26-scottsdale",xm="executive-luxury-bus-29-scottsdale",Yi="motorcoach-56",T=e=>n[e],Ve=e=>i[e];function Ji(e){return h(r[e].hourlyRateCents)}function Zi(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function Re(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Dm="At 10:30 p.m. the whole crowd leaves at once, the festival asks everyone to head to the nearest exit, and rideshare prices and waits can climb when that many people request a car together.",Im=[{label:"Innings Festival official site: dates and venue",href:bm},{label:"Innings Festival help center: dates and hours",href:wm},{label:"Innings Festival help center: community information and road closures",href:vm},{label:"Innings Festival help center: getting home from the festival",href:km},{label:"Innings Festival help center: bag policy",href:Sm},{label:"Innings Festival help center: ticket tiers",href:Am},{label:"Innings Festival help center: ticket and wristband policy",href:Tm},{label:"Innings Festival help center: family services",href:$m},{label:"Downtown Tempe: parking in Downtown Tempe",href:Cm},{label:"Valley Metro: Tempe destinations (Tempe Beach Park/Town Lake)",href:Pm}],Nm=[Re("Where do you park for Innings Festival 2027?","Innings Festival has published no festival parking for 2027, so drivers use Downtown Tempe’s paid garages, lots and meters, more than 20,000 public spaces, some posting special event rates during events; with a chauffeured ride nobody in the group drives, parks or walks back to a garage after the 10:30 p.m. close.","The festival’s own help center covers entrances, re-entry, transit and the ride home, but for 2027 it lists no parking lot of its own. Its accessibility page says accessible parking locations, drop-off areas and entry procedures will be available closer to the festival. Until then, parking means the city’s downtown supply, not a festival lot.","Downtown Tempe, where the City of Tempe’s parking link leads, counts more than 20,000 paid public parking spaces across garages, lots and on-street zones, and more than a dozen paid garages and surface lots. During certain events some garages and lots post special event parking; where none is posted, standard rates apply. On-street meters are free on Sundays. Tempe TRiP shows availability in real time.","The catch is not the number of spaces. It is the closures around the park (the next answers), a walk from the garage to the entrance at Mill Avenue and Rio Salado Parkway, and the same walk back after close with everyone else. A chauffeured ride skips all three: the chauffeur drops the group near the entrance, as far as the closures and traffic staff allow, and is booked for the ride home."),Re("Where is the Innings Festival rideshare and drop-off area?","The 2027 rideshare zone is not announced yet: the official help center says the 2027 information is not yet available, so no pickup spot is confirmed for February 26 to 28; a chauffeured ride unloads at a legal curb outside the closed streets, where police and event staff direct, and meets the group at a set time.","The festival publishes its rideshare instructions in the “How do I get home from the festival?” article. For 2027 that section reads, in effect, check back shortly. When it is posted, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and no limo, charter or party-bus drop-off zone is published.","So a booked Sprinter, party bus or coach follows the current closures and the directions of Tempe police and event staff. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive. The chauffeur unloads as close to those as the open streets allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. The festival names the Main Guest Services Tent as the meeting point for anyone separated inside. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),Re("When is Innings Festival 2027, and what time do the gates open?","Innings Festival 2027 runs Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park; the gates open at 12 p.m. and the festival closes at 10:30 p.m. each of the 3 days, and guests may leave and re-enter as often as they like until 7 p.m.","The dates and daily hours come from the festival’s own help center, updated in September 2026: Friday, February 26, Saturday, February 27 and Sunday, February 28, 2027, opening at noon and closing at 10:30 p.m. each day. The countdown on this page counts to the first gate time, 12 p.m. on Friday, February 26, Arizona time.","The 2027 lineup and set times are not announced yet. The festival’s lineup and schedule pages still show last year’s, and its schedule article says 2027 information will come closer to the festival date. This guide names no artist. Plan the pickup around the gates and the close, then adjust once the schedule is out.","Re-entry is allowed until 7 p.m., local time. Each time, the wristband is scanned and the guest goes back through security. After 7 p.m., leaving means leaving for the night, so a group that wants dinner outside and the late sets inside should plan to be back through the gate before then."),Re("Which roads close for Innings Festival, and where is it?","Innings Festival is at Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281; for 2027 the festival lists Mill Avenue southbound closed between Washington Street and 2nd Street on all 3 festival days, starting at 10:30 a.m., and East Rio Salado Parkway closed between Ash Avenue and Mill Avenue.","The festival’s 2027 community page lists these closures. North Mill Avenue southbound, between Washington Street and West 2nd Street, closes on Friday, February 26, Saturday, February 27 and Sunday, February 28, starting at 10:30 a.m. and reopening at 11:59 p.m. East Rio Salado Parkway, between Ash Avenue and South Mill Avenue, closes on the same 3 days, starting at 8 a.m. and reopening at 11:59 p.m.","West Rio Salado Parkway eastbound, between South Hardy Drive and East Rio Salado Parkway, closes from 8 a.m. on Friday, February 26 until 5 a.m. on Monday, March 1. The westbound side of the same stretch closes earlier, from Wednesday, February 24; its reopening time is announced closer to the date. The walking and bike path between Tempe Center for the Arts and Hayden Ferry Lakeside closes from Monday, February 22 to Monday, March 1.","The City of Tempe posts its own event traffic notices closer to each event; its 2027 notice for the festival is not out yet. Your chauffeur plans the approach around the published closures and follows police and event staff on the day. Anyone driving themselves should expect the streets nearest the park to be closed and should not plan to reach the entrance by car."),Re("Can you take the light rail or streetcar to Innings Festival?","Yes: Valley Metro’s A line stops at the Mill Ave/3rd St station for Tempe Beach Park, the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway, and bus Route 48 stops at Ash Avenue/Rio Salado Parkway; the festival also points to 11 free park-and-rides, with no overnight parking.","The festival’s getting-home article lists Valley Metro rail, the local bus and the streetcar, and 11 free park-and-rides that reach rail stations in Phoenix, Tempe and Mesa. Overnight parking is not allowed at the park-and-rides. Valley Metro fares apply; the festival’s article and valleymetro.org list them.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after a 10:30 p.m. close. That is where a chauffeured ride earns its keep."),Re("Is a chauffeured ride worth it when Scottsdale is so close?",`The drive is short, about ${Sn.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no parking, no rideshare wait at the 10:30 p.m. close, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Tempe Beach Park is about ${Sn.oldTown} minutes by Google’s typical time, and about ${Sn.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what the evening does to those minutes: closed blocks around the park, a garage to find and pay for, and a walk back to it.`,Dm,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before the gates open. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to get the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),Re("What is the Innings Festival bag policy?","The 2027 bag policy allows a clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or an emptied hydration pack; every bag is searched, entry is an airport-style screening, and outside food, drinks, coolers and chairs are prohibited.","Hydration packs need not be clear, but they must be emptied of all liquid and have no more than two main compartments and one smaller one. The festival’s advice is to leave the bag at home for the quickest entry. All fans are subject to an airport-style search, which may include a pat-down and magnetometer screening. The policy is marked subject to change.","Prohibited items include outside food or beverage of any kind, alcohol included, coolers, glass, aerosols, chairs of any kind, umbrellas, tents and shade structures, selfie sticks and drones. Empty reusable water bottles, blankets, portable battery packs and non-aerosol sunscreen up to 3.4 ounces are allowed. The park is smoke free, and the festival is 100% cashless.","Anything the gate will not take can stay in the vehicle for the ride home when the vehicle is booked by the hour. Tell the reservations team what the group will carry, so the vehicle fits the bags as well as the people."),Re("Which vehicle fits an Innings Festival group?",`Festival crews ride a Limo Party Sprinter; VIP guests lead with the ${T(_t)}, then the ${T(Ge)}, our pick for the festival, the ${T(Mr)} and the Suburban; big groups take the ${Ve(Ps)}-seat party bus, the ${T(Vi)}, the mini bus, the mini coach or the ${Ve(Yi)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${T(ja)} and the ${T(Mm)}. VIP guests: the ${T(_t)}, the ${T(Ge)}, which seats ${Ve(Ge)} at ${Ji(Ge)}/hr, the ${T(Mr)} and the ${T(An)}. Big groups: the ${T(Ps)}, the ${T(Vi)}, the ${T(Rm)}, the ${T(xm)} and the ${T(Yi)}.`,`A VIP party larger than the ${T(_t)} rides in two vehicles, one booking each for the same day and times: the ${T(_t)} with the ${T(Mr)} seats ${Ve(_t)+Ve(Mr)}, and with the ${T(An)} it seats ${Ve(_t)+Ve(An)}.`,"Count riders for each direction. The group that arrives at the noon gates is not always the group that leaves at 10:30 p.m. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For all 3 days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${T(ja)} for 5 billed hours at ${Ji(ja)}/hr is about ${Zi(ja,5,13)} each before tax; ${Ve(Ge)} riders in the ${T(Ge)} for 6 hours is about ${Zi(Ge,6,Ve(Ge))} each. That is arithmetic, not a flat festival fare.`),Re("How should the pickup after Innings Festival work?","Use 2 checkpoints after Innings Festival: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because at the 10:30 p.m. close the streets nearest the park are still closed and the 2027 rideshare zone is not yet announced.","Mill Avenue southbound and East Rio Salado Parkway stay closed until 11:59 p.m. on each festival day, so the vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it.","If the group splits inside, the festival’s meeting point for separated guests is the Main Guest Services Tent. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),Re("How far ahead should Innings Festival transportation be booked?","Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 3 festival days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as the festival announces its 2027 details.","The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want against the noon gates, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the 2027 rideshare zone and the city’s traffic notice once they are posted. Reach the reservations team at ${u} or ${p}. A ride booking never includes a festival ticket or wristband.`)],Wm=[{question:"When is Innings Festival 2027?",answer:"Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park in Tempe. The festival opens at 12 p.m. and closes at 10:30 p.m. each day."},{question:"What time does Innings Festival start?",answer:"The gates open at 12 p.m. (noon) on each festival day, and the festival closes at 10:30 p.m. The 2027 set times are announced closer to the date."},{question:"Where is Innings Festival?",answer:"At Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive."},{question:"Where do you park for Innings Festival?",answer:"The festival has published no parking lot of its own for 2027. Drivers use Downtown Tempe’s paid garages, lots and meters; some garages post special event parking during events. With a chauffeured ride nobody drives or parks."},{question:"Where is the Innings Festival rideshare pickup?",answer:"The 2027 rideshare zone is not announced yet; the festival’s getting-home article says the information is coming. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing Innings Festival 2027?",answer:"The 2027 lineup is not announced yet. The festival’s lineup and schedule pages still show last year’s; check the official site for the 2027 announcement."},{question:"Can I leave Innings Festival and come back?",answer:"Yes, as often as you like until 7 p.m. local time. Your wristband is scanned and you go through security each time you re-enter."},{question:"What bags are allowed at Innings Festival?",answer:"A clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or a hydration pack emptied of liquid. Every bag is searched."},{question:"Can I take the light rail to Innings Festival?",answer:"Yes. The Valley Metro A line stops at the Mill Ave/3rd St station for Tempe Beach Park, and the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway."},{question:"Can we book a ride for all three days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-to-Sunday group books three rides, one for each day, and can ask for the same vehicle each time."},{question:"How much do Innings Festival tickets cost?",answer:"Innings sells tickets in tiers: each tier starts at one price, and when it sells out the next tier opens at a higher price, with the same access at every tier. Only wristbands bought through Front Gate Tickets or the festival’s Ticketmaster Verified Exchange are valid, and all sales are final. A ride booking never includes a festival ticket or wristband."},{question:"Can kids go to Innings Festival?",answer:"The festival plans for families. A Family Services tent next to the Guest Services and Access Center booth has room to change a diaper or nurse, and at Guest Services a guardian can register a child for a Tag-Your-Kid wristband, so staff can reunite a lost child with their parents quickly."}],Lm={path:"/guides/innings-festival-transportation",title:"Innings Festival 2027: parking, rideshare and getting there",metaTitle:"Innings Festival 2027 Parking & Rides",description:"Innings Festival 2027 runs February 26–28 at Tempe Beach Park & Arts Park. The official dates and gate times, the 2027 road closures, parking, rideshare, light rail and the bag policy, and a chauffeured ride from Scottsdale so nobody drives, parks or waits at close.",metaDescription:"Feb 26–28 dates, noon gates, road closures and light rail, or a chauffeured ride",lastUpdated:qi,lastUpdatedLabel:l(qi),eyebrow:"Official dates: February 26–28, 2027",intro:`An Innings Festival ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter; VIP guests lead with the ${T(_t)} and the ${T(Ge)}; big groups take the party bus, the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:Nm,faqs:Wm,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:T(Ge)},{href:"/fleet/limo-sprinter-13-scottsdale",label:T(ja)},{href:"/fleet/party-bus-28-scottsdale",label:T(Ps)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/guides/phoenix-concerts-2026-2027",label:"Every Phoenix concert in 2026–27, by venue"},{href:"/guides/m3f-festival-transportation",label:"M3F in March: the other spring music festival"},{href:"/pricing",label:"Published hourly pricing"}],sources:Im,fleetRows:Fm},Ki="2026-09-26",Om="https://www.m3ffest.com/",_m="https://www.m3ffest.com/faqs",Gm="https://www.m3ffest.com/lineup-by-day",Um="https://www.m3ffest.com/ticket-types-1-1",Bm="https://www.valleymetro.org/maps-schedules/b",Hm="https://www.phoenix.gov/administration/departments/parks/activities-facilities/city-parks/steele-indian-school-park.html",Tn={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["party-bus-28-scottsdale","executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},$n={oldTown:22,kierland:27},zm=[...Tn.crews,...Tn.vip,...Tn.big].filter(ae),qm=zm.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),Ue="ultra-luxury-party-sprinter-scottsdale",Gt="maybach-jet-sprinter-scottsdale",Rr="maybach-shuttle-sprinter-8",Cn="premium-suv-scottsdale",xr="limo-sprinter-13-scottsdale",Td="limo-sprinter-16-scottsdale",Es="party-bus-28-scottsdale",ji="executive-sprinter-scottsdale",Vm="executive-mini-bus-26-scottsdale",Ym="executive-luxury-bus-29-scottsdale",Qi="motorcoach-56",$=e=>n[e],Ye=e=>i[e];function Xi(e){return h(r[e].hourlyRateCents)}function eh(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function we(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Jm="When the last set ends, the crowd leaves at once, and rideshare prices and waits can climb when that many people request a car together.",Zm=[{label:"M3F official site: M3F 2027 at Steele Indian School Park",href:Om},{label:"M3F official FAQs: dates, parking, bag policy, re-entry and box office",href:_m},{label:"M3F official lineup by day: Friday and Saturday, March 5–6",href:Gm},{label:"M3F official passes: general admission, VIP and Club Pass",href:Um},{label:"Valley Metro: B line stops and schedule",href:Bm},{label:"City of Phoenix: Steele Indian School Park",href:Hm}],Km=[we("Where do you park for M3F 2027?","M3F has no official festival parking for 2027: its FAQ tells guests to use Valley Metro, rideshare, or to park at 4041 N Central Ave, the one address it names; with a chauffeured ride nobody in the group drives, parks or walks back to a car after the last set.","The festival’s own FAQ answers the parking question in three lines: there is no official festival parking; use public transport (Valley Metro) or rideshare services; or park at 4041 N Central Ave. It publishes no lot map, no rate, no operator and no capacity for that address, so this guide prints none either.","Steele Indian School Park is a busy city park in central Phoenix, and on a festival day the streets around it fill with people arriving from every direction. The festival’s own advice, to come by light rail or rideshare, says as much. Anyone who drives should plan the parking before leaving home, not on arrival.","A chauffeured ride takes parking off the list. The chauffeur drops the group near the entrance, where police and event staff allow, and is booked for the ride home. Nobody circles for a space, pays for one, or walks back to it at the end of the night, and nobody has to stay sober to drive."),we("Where is the M3F rideshare and drop-off area?","M3F has not posted a 2027 rideshare zone: its FAQ tells guests to use rideshare services but names no pickup spot, and no limo or charter drop-off is published for March 5 and 6; a chauffeured ride unloads where police and event staff direct and meets the group at a time set in advance.","When the festival posts a rideshare zone, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and a booked Sprinter, party bus or coach follows its own instruction on the day: the directions of Phoenix police and event staff, and the closures in place around the park.","The festival does name one entrance: its bike valet is near the entrance at N Central Ave. The chauffeur unloads as close to the entrance as the open streets and traffic staff allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. There is no re-entry, so the group leaves once. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),we("When is M3F 2027, and what time does it start?","M3F 2027 is Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix; the gate and set times are not announced yet, and the festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday, closing at 11 p.m. both days.","Every current official source agrees on the dates: the festival’s 2027 lineup poster (Friday 03/05/27 and Saturday 03/06/27), its lineup-by-day, music and passes pages, and the ticket seller the site links. One FAQ line prints the year as 2026, but its question says 2027 and the weekdays are 2027’s: March 5, 2027 is a Friday. Some search results still show an old page title with March 6 and 7; the festival’s current pages all say March 5 and 6.","The gate times and set times for 2027 are not published. The only times on the festival’s site are the box office’s: open festival weekend at Steele Indian School Park, from 12 p.m. on Friday and from 11 a.m. on Saturday, closing at 11 p.m. each day. Those are the box office’s hours, not the gates’. The countdown on this page counts to Friday, March 5, Arizona time, and says so.","Plan the pickup around the sets you want to see once the festival posts its schedule, then adjust. Your chauffeur works to the time you set, and the reservations team updates the plan when the gate times are announced."),we("Where is M3F, and which entrance do you use?","M3F is at Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012, the 72-acre park at Central Avenue and Indian School Road; the festival’s FAQ places its bike valet near the entrance at N Central Ave, and it publishes no other entrance for 2027.","The address comes from the festival’s FAQ, and the ticket seller and the City of Phoenix list the same one. The city calls Steele Indian School Park the premiere special event park in central Phoenix.","The festival’s FAQ mentions one entrance, on N Central Ave, near the bike valet. A festival map for 2027 is not posted yet; when it is, check which entrance your pass uses. How each pass enters is the festival’s to describe, not ours.","Children 12 and under get in free with a ticketed adult, and the ticket seller lists the event as all ages, so a family group can ride together. Tell the reservations team if a child seat is needed."),we("Can you take the light rail to M3F?","Yes: the festival’s FAQ points guests to Valley Metro, and the B line runs up Central Avenue past the park, stopping at the Indian School/Central Ave station (stop 10006); the festival also offers bike valet near its N Central Ave entrance, so a pair staying near a station can skip the car.","The festival’s parking answer names Valley Metro first. Valley Metro’s B line schedule lists the Indian School/Central Ave station, stop number 10006, on its route along Central Avenue. Valley Metro fares apply; its site lists them and the service hours.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after the last set. That is where a chauffeured ride earns its keep."),we("Is a chauffeured ride worth it from Scottsdale?",`The drive is about ${$n.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no festival parking to find, no rideshare wait after the last set, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Steele Indian School Park is about ${$n.oldTown} minutes by Google’s typical time, and about ${$n.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what a festival day does to them: no festival lot, streets full of people, and the same crowd leaving together at the end.`,Jm,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before anyone goes in. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to fetch the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),we("What is the M3F bag policy?","The M3F bag policy allows clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches, fanny packs and wallets up to 5 by 7 inches that need not be clear, and empty single-pocket hydration packs; outside food and drink are not allowed, except empty water bottles.","Clear backpacks and handbags within 12 by 12 by 8 inches are allowed, as are small clutches, non-professional cameras, phones and GoPros, prescribed medication with a matching ID, sunglasses, hats, earplugs, sunscreen and bug spray. Water stations run throughout the festival, so bring the empty bottle.","Not allowed: totems, wagons, folding chairs and large backpacks; professional cameras and audio recording devices; outside food and drink; weapons and drugs; glass containers, lighters, drones and selfie sticks. The festival is fully cashless: every vendor takes credit and debit cards.","Anything the gate will not take can stay in the vehicle when it is booked by the hour. With no re-entry, though, it stays there until you leave for the night, so pack for the whole day before you go in."),we("Is there re-entry at M3F?","No: the M3F FAQ says there is no re-entry allowed, so each guest goes in once and leaves once on each of the 2 festival days; plan the arrival time, what to carry and the pickup before the group reaches the gate, because stepping out to the vehicle ends that guest’s day.","No re-entry changes how a day is planned. A group that wants dinner out before the late sets should eat before going in, or plan to leave for the night after dinner. Nobody runs back to the car for a jacket or a charger: what is not in the bag stays outside.","It also sets the shape of the booking. A vehicle booked by the hour waits for the whole group at the end; a group that splits, with some leaving early, can book a second pickup for the early leavers or keep one vehicle and one time for everyone. Tell the reservations team which you want."),we("Which vehicle fits an M3F group?",`Festival crews ride a Limo Party Sprinter; VIP guests lead with the ${$(Gt)}, then the ${$(Ue)}, our pick for M3F, the ${$(Rr)} and the Suburban; big groups take the ${Ye(Es)}-seat party bus, the ${$(ji)}, the mini bus, the mini coach or the ${Ye(Qi)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${$(xr)} and the ${$(Td)}. VIP guests: the ${$(Gt)}, the ${$(Ue)}, which seats ${Ye(Ue)} at ${Xi(Ue)}/hr, the ${$(Rr)} and the ${$(Cn)}. Big groups: the ${$(Es)}, the ${$(ji)}, the ${$(Vm)}, the ${$(Ym)} and the ${$(Qi)}.`,`A VIP party larger than the ${$(Gt)} rides in two vehicles, one booking each for the same day and times: the ${$(Gt)} with the ${$(Rr)} seats ${Ye(Gt)+Ye(Rr)}, and with the ${$(Cn)} it seats ${Ye(Gt)+Ye(Cn)}.`,"Count riders for each direction. The group that arrives for the early sets is not always the group that leaves after the last one. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For both days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${$(xr)} for 5 billed hours at ${Xi(xr)}/hr is about ${eh(xr,5,13)} each before tax; ${Ye(Ue)} riders in the ${$(Ue)} for 6 hours is about ${eh(Ue,6,Ye(Ue))} each. That is arithmetic, not a flat festival fare.`),we("How should the pickup after M3F work?","Use 2 checkpoints after M3F: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because the 2027 rideshare zone and any charter pickup area are not yet announced.","The vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it. Central Avenue carries both traffic and the light rail, so the exact spot is set on the day.","If the group splits inside, pick a landmark to regroup at before the last set, and charge phones before going in. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),we("How far ahead should M3F transportation be booked?","Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 2 festival days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as the festival announces its 2027 details.","The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the gate times and any rideshare zone once they are posted. Reach the reservations team at ${u} or ${p}. A ride booking never includes a festival ticket or pass: those are sold by the festival, final sale.`)],jm=[{question:"When is M3F 2027?",answer:"Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix. The festival’s poster, lineup, passes and ticket pages all give those two days."},{question:"What time does M3F start?",answer:"The 2027 gate and set times are not announced yet. The festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday; those are its hours, not the gates’."},{question:"What is M3F?",answer:"M3F Music Festival is a two-day music and art festival at Steele Indian School Park in central Phoenix, with multiple stages and art installations. It also runs The Community Project, year-round programs for art, music and community."},{question:"Where is M3F?",answer:"At Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012. The festival’s bike valet is near its entrance on N Central Ave."},{question:"Where do you park for M3F?",answer:"M3F has no official festival parking. Its FAQ says to use Valley Metro or rideshare, or to park at 4041 N Central Ave. With a chauffeured ride nobody drives or parks."},{question:"Is there a rideshare drop-off at M3F?",answer:"The festival tells guests to use rideshare services but has not posted a 2027 pickup zone. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing M3F 2027?",answer:"The 2027 lineup is on the festival’s own site, split into Friday and Saturday on its lineup-by-day page. Set times are not announced yet. This guide does not repeat the lineup."},{question:"What bags are allowed at M3F?",answer:"Clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches; fanny packs and wallets up to 5 by 7 inches, which need not be clear; and empty single-pocket hydration packs."},{question:"Can I leave M3F and come back?",answer:"No. The festival’s FAQ says there is no re-entry, so plan to go in once and leave once each day."},{question:"Can kids go to M3F?",answer:"Yes. Children 12 and under get in free with a ticketed adult, and the ticket seller lists the festival as all ages."},{question:"Can we book a ride for both days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-and-Saturday group books two rides, one for each day, and can ask for the same vehicle each time."},{question:"What kinds of M3F tickets are there?",answer:"Three passes. General Admission opens every stage and art installation, with 25+ performances. VIP adds VIP viewing areas and lounge access, dedicated VIP bars, expedited entry and VIP-only restrooms. Club Pass adds complimentary drinks, limited-capacity Club spaces with side-stage viewing and the fastest entry. A ride booking never includes a festival pass."}],Qm={path:"/guides/m3f-festival-transportation",title:"M3F Festival 2027: parking, rideshare and getting there",metaTitle:"M3F Festival 2027 Parking & Rides",description:"M3F 2027 is Friday and Saturday, March 5–6, at Steele Indian School Park in Phoenix. The official dates, parking, rideshare, light rail, the bag policy and re-entry, and a chauffeured ride from Scottsdale so nobody drives, parks or chases a rideshare at the end.",metaDescription:"March 5–6 dates, no festival parking, light rail and bag rules, or a chauffeured ride",lastUpdated:Ki,lastUpdatedLabel:l(Ki),eyebrow:"Official dates: March 5–6, 2027",intro:`An M3F ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter; VIP guests lead with the ${$(Gt)} and the ${$(Ue)}; big groups take the party bus, the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:Km,faqs:jm,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:$(Ue)},{href:"/fleet/limo-sprinter-16-scottsdale",label:$(Td)},{href:"/fleet/party-bus-28-scottsdale",label:$(Es)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:"/guides/phoenix-concerts-2026-2027",label:"Every Phoenix concert in 2026–27, by venue"},{href:"/guides/innings-festival-transportation",label:"Innings Festival in Tempe, the week before"},{href:"/pricing",label:"Published hourly pricing"}],sources:Zm,fleetRows:qm},th="2026-09-27",Xm="/guides/venues/mesa-amphitheatre",eg=1e3,qs=h(eg),Xt="ultra-luxury-party-sprinter-scottsdale",Pn="maybach-jet-sprinter-scottsdale",tg="maybach-shuttle-sprinter-8",ag="premium-suv-scottsdale",ea="limo-sprinter-13-scottsdale",En="limo-sprinter-16-scottsdale",Fn="party-bus-28-scottsdale",ta="executive-sprinter-scottsdale",rg="executive-white-sprinter-scottsdale",Mn="executive-mini-bus-26-scottsdale",Rn="executive-luxury-bus-29-scottsdale",F=e=>n[e],ft=e=>i[e],xn=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,og="https://www.mesaamp.com/",Vs="https://mesaamp.com/Online/default.asp?doWork::WScontent::loadArticle=Load&BOparam::WScontent::loadArticle::article_id=",ng=`${Vs}C2A7801A-5AAF-4E51-8211-27DBAD552E45&menu_id=9EAD52D6-25A3-4ADE-B38C-7F795E90B022`,sg=`${Vs}29754C2C-6A81-4A8C-9468-8B76C4F62B0E&menu_id=4EB99B0E-A386-4220-8601-4BE111FB1A93`,ig=`${Vs}478E80DE-E804-409F-A80D-EB72E6C921AA&menu_id=18191D1E-E12C-413D-AEDA-58F3DD579597`,hg="https://www.mesaaz.gov/Activities-Culture/Parks-Recreation-and-Community-Facilities/Parks-Facilities/Mesa-Amphitheatre",dg=[{label:"Mesa Amphitheatre, home page and upcoming events",href:og},{label:"Mesa Amphitheatre, FAQ (parking, light rail, gates, bag policy, seating)",href:ng},{label:"Mesa Amphitheatre, about the venue",href:sg},{label:"Mesa Amphitheatre, map and directions",href:ig},{label:"City of Mesa, Mesa Amphitheatre (capacity and features)",href:hg}],$d=["January","February","March","April","May","June","July","August","September","October","November","December"],lg=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function Dn(e){const[t,a,o]=e.split("-").map(Number);return`${lg[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${$d[a-1]} ${o}, ${t}`}function ah(e){const[,t,a]=e.split("-").map(Number);return`${$d[t-1]} ${a}`}const In=(e,t)=>fa(`${e}T${t}:00-07:00`);function cg(e){const t=e.endDate?`${Dn(e.date)}, and ${Dn(e.endDate)}`:Dn(e.date),a=e.doors?`doors ${In(e.date,e.doors)}, show ${In(e.date,e.starts)}`:`show ${In(e.date,e.starts)}`,o=e.ages?`, ${e.ages==="All ages"?"all ages":`ages ${e.ages}`}`:"";return`${t}: ${e.title} (${a}${o}).`}function et(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ys=Zd,rh=Ys[0],Fs=Ys.filter(e=>e.kind==="concert"),oh=Fs[Fs.length-1],ug=[et("How does parking work at Mesa Amphitheatre?",`Mesa Amphitheatre has free (limited) and paid on-site parking, ${qs} cash per car for the paid spaces; the venue sits on the southeast corner of University Drive and Center Street in downtown Mesa, and Main Street and Center light rail station is 1/3 mile south, about an 8-minute walk.`,"The venue’s guest pages name no lot and publish no overflow parking beyond its own, and the free spaces are limited, so on a busy night they are the first thing to go. Bring cash for the paid parking.","Tickets are sold only on mesaamp.com and scan from a phone or a printout, and there is no re-entry once you are inside."),et("Where is the drop-off at Mesa Amphitheatre?","Mesa Amphitheatre publishes no drop-off, rideshare, limo or charter point on its guest pages: the venue gives its address, 263 North Center Street, on the southeast corner of University Drive and Center Street in downtown Mesa, and a group being dropped off unloads at the venue where traffic and the venue’s staff allow.","That is what a chauffeured group does too. We bring the group to the venue at University Drive and Center Street, unload where the staff and the traffic allow, and agree one pickup point for the ride home before the show.","No curb is held for booked vehicles. If the venue posts a drop-off plan for a show, that plan comes first.","Every show ends by 10 p.m. (the venue’s rule and the City of Mesa’s noise curfew), so the ride home is easy to time: your chauffeur is waiting when the lawn empties."),et("Where is Mesa Amphitheatre, and how do you get there?","Mesa Amphitheatre is at 263 North Center Street, Mesa, AZ 85201, on the southeast corner of University Drive and Center Street in downtown Mesa; the City of Mesa owns and runs it, and the Main Street and Center light rail station is 2 blocks south.","By light rail, the Main Street and Center station is 1/3 mile south of the venue, about an 8-minute walk, the venue says. By car, the on-site parking is free (limited) or paid, cash only.","A chauffeured group needs neither: the driver takes the group to the venue and waits for the ride home."),et("What time do gates open at Mesa Amphitheatre, and when do shows end?","At Mesa Amphitheatre each show’s own page lists its doors time, half an hour to an hour before the show on this fall’s listings, and every show concludes by or before 10 p.m.; every guest and item is subject to search and metal detection at the gate.","Every attendee needs a ticket, infants and children included, and tickets are sold only on mesaamp.com. The box office sells in person on show days only, opening 1 to 2 hours before door times, and holds will call with a valid ID; its phone and online hours are 9 a.m. to 4 p.m., Monday to Friday, at 480-644-2560.","There is no re-entry, and the venue runs rain or shine: it is open air.","Ages are set show by show: 16 and over for some, 18 and over for others, all ages for the rest. Check the show’s page before you book the ride."),et("What is the Mesa Amphitheatre bag policy?","Mesa Amphitheatre allows clear bags only: a clear plastic or vinyl PVC bag no larger than 12 by 6 by 12 inches, inspected by security at entry, and 1 factory-sealed, unfrozen water per person, up to 20 ounces.","Not allowed: alcohol, strollers, animals, illegal substances, re-entry, weapons of any kind, outside food or beverage, seating, blankets, towels or umbrellas, bags, purses or backpacks that are not clear, and professional cameras or audio recording devices. There is no on-site storage for items that are turned away.","Settle bags before you leave: a group that is dropped off has no car on site to go back to during the show."),et("What is the seating like at Mesa Amphitheatre, and how many people does it hold?","Mesa Amphitheatre is an open-air, general admission venue with a tiered grass lawn and no fixed seats unless a show says otherwise, and the City of Mesa lists its festival capacity at 5,000.","Some shows add reserved chairs or a pit: this fall 38 Special sells chaired reserved seating beside the lawn, and Tucker Wetmore sells pit admission. Everyone else sits or stands on the lawn itself: chairs, blankets and towels are not allowed in.","For a group, general admission means arriving together counts: a group that walks in at doors picks its spot on the lawn together."),et("Which vehicle fits a Mesa Amphitheatre group?",`A VIP night takes the ${F(Pn)}, the ${F(Xt)}, the ${F(tg)} or the ${F(ag)}. Friends and birthday crews ride the ${F(ea)}, the ${F(En)} or the ${F(Fn)}. Company nights and big groups take the ${F(ta)}, the ${F(rg)}, the ${F(Mn)} or the ${F(Rn)}.`,`Seat counts are seated capacities from the fleet: the ${F(Xt)} seats ${ft(Xt)}, the ${F(ea)} ${ft(ea)}, the ${F(En)} ${ft(En)}, the ${F(Fn)} ${ft(Fn)} and the ${F(Pn)} ${ft(Pn)}. The ${F(ta)} seats ${ft(ta)}, the ${F(Mn)} ${ft(Mn)} and the ${F(Rn)} ${ft(Rn)}.`,`Our pick for a night on the lawn is the ${F(Xt)}, ${xn(Xt)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${F(ea)} is ${xn(ea)}, and the ${F(ta)} is ${xn(ta)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),et("How should a group plan the ride to a Mesa Amphitheatre show?","Plan backwards from the doors time on the show’s page, and forward from the 10 p.m. curfew: a pickup that lands the group at University Drive and Center Street around doors leaves room for the search at the gate and gets everyone onto the lawn together.","The ride home is the easy part to time: every show ends by 10 p.m. Agree the pickup point before the show, and your chauffeur is there when the lawn empties.","Many shows here are 16 and over or all ages. If even one passenger is under 21, the trip is alcohol-free for the whole group, adults included; we sell no alcohol on any trip.",`Book by the hour and the vehicle is yours for the whole night, dinner downtown before the show included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the date, the pickup area and the rider count.`)],pg=et("What’s coming up at Mesa Amphitheatre?",`Coming up at Mesa Amphitheatre, every show the venue lists: ${Fs.length} concerts from ${rh.label} on ${ah(rh.date)} to ${oh.label} on ${ah(oh.date)}, 2026, then 8123 Fest on January 15 and 16, 2027. As the venue’s event pages gave them on September 27, 2026:`,...Ys.map(cg),"New shows are added to the venue’s calendar through the year, and mesaamp.com, where the tickets are sold, is the place to check before you book."),fg=[{question:"How much is parking at Mesa Amphitheatre?",answer:`The venue has free (limited) and paid on-site parking; the paid parking is ${qs} per car, cash.`},{question:"Is there light rail to Mesa Amphitheatre?",answer:"Yes: the Main Street and Center station is 1/3 mile south of the venue, about an 8-minute walk."},{question:"Where do you get dropped off at Mesa Amphitheatre?",answer:"The venue publishes no drop-off or rideshare point. It is on the southeast corner of University Drive and Center Street; a group being dropped off unloads there where traffic and the venue’s staff allow."},{question:"What is the bag policy at Mesa Amphitheatre?",answer:"Clear bags only, no larger than 12 by 6 by 12 inches. One factory-sealed, unfrozen water per person, up to 20 ounces. No chairs, blankets, towels or umbrellas."},{question:"Can you bring chairs or blankets to Mesa Amphitheatre?",answer:"No. Seating, blankets, towels and umbrellas are on the venue’s not-permitted list; guests sit on the tiered lawn itself."},{question:"Is Mesa Amphitheatre general admission?",answer:"Yes, unless a show says otherwise: a tiered grass lawn with no fixed seats. Some shows add reserved chairs or a pit."},{question:"How many people does Mesa Amphitheatre hold?",answer:"The City of Mesa lists its festival capacity at 5,000."},{question:"What time do shows end at Mesa Amphitheatre?",answer:"By or before 10 p.m.: the venue’s rule and the City of Mesa’s noise curfew."},{question:"Is Mesa Amphitheatre all ages?",answer:"It depends on the show: some are 16 and over, some 18 and over, some all ages. Every attendee needs a ticket, infants and children included."},{question:"Does Mesa Amphitheatre allow re-entry?",answer:"No. Once you leave, you cannot come back in."}],mg={path:Xm,title:"Mesa Amphitheatre Parking Guide: Drop-Off, the Lawn and Upcoming Events",metaTitle:"Mesa Amphitheatre Parking and Events",description:"Mesa Amphitheatre in downtown Mesa: on-site parking and its fee, the light rail, getting dropped off, gates and the 10 p.m. curfew, the clear bag policy, the lawn, the upcoming events, and a chauffeured ride so nobody drives or parks.",metaDescription:"Parking, the light rail, the bag policy, the lawn and a chauffeured ride",lastUpdated:th,lastUpdatedLabel:l(th),eyebrow:"Mesa · Downtown",intro:`Scottsdale Sprinters’ short answer on Mesa Amphitheatre parking: the venue has free (limited) and paid on-site parking, ${qs} cash per car for the paid spaces, at 263 North Center Street on the southeast corner of University Drive and Center Street in downtown Mesa. It is an open-air, general admission lawn with clear bags only, and every show ends by 10 p.m. For a group, one chauffeured vehicle replaces the lot, the cash and the drive home.`,sections:[...ug,pg],faqs:fg,links:[{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts 2026–27, every show by venue"},{href:"/guides/venues/talking-stick-resort-amphitheatre",label:"Talking Stick Resort Amphitheatre parking and shows"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/mesa",label:"Mesa service area"},{href:`/fleet/${Xt}`,label:F(Xt)},{href:`/fleet/${ea}`,label:F(ea)},{href:`/fleet/${ta}`,label:F(ta)},{href:"/pricing",label:"Published hourly pricing"}],sources:dg},nh="2026-09-27",gg="https://mesamarathon.com/",yg="https://mesamarathon.com/info?tab=quick-info",bg="https://mesamarathon.com/faqs",Dr={runners:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale"],clubs:["executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"]},wg=[...Dr.runners,...Dr.clubs,...Dr.crews,...Dr.vip].filter(ae),vg=wg.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),pe="executive-sprinter-scottsdale",Qa="executive-white-sprinter-scottsdale",ot="executive-mini-bus-26-scottsdale",sh="executive-luxury-bus-29-scottsdale",kg="limo-sprinter-13-scottsdale",Nn="limo-sprinter-16-scottsdale",ih="party-bus-28-scottsdale",za="maybach-jet-sprinter-scottsdale",Sg="ultra-luxury-party-sprinter-scottsdale",Wn="maybach-shuttle-sprinter-8",Ln="premium-suv-scottsdale",b=e=>n[e],xe=e=>i[e];function Ir(e){return h(r[e].hourlyRateCents)}function hh(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function le(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ag=[{label:"Mesa Marathon: 2027 race date and the Desert Double",href:gg},{label:"Mesa Marathon race information: start times, course, start and finish, buses and parking, expo, spectators, Kids 1K",href:yg},{label:"Mesa Marathon FAQ: buses, time limits, cheering spots, packet pickup, strollers",href:bg}],Tg=[le("When is the Mesa Marathon 2027, and what time does it start?","The Mesa Marathon is on Saturday, February 13, 2027; the marathon, half marathon and 10K all start at 6:30 a.m., the free Kids 1K starts at noon at Riverview Park, and the finish line closes at 1:03 p.m.","The race was formerly known as the Mesa-Phoenix Marathon. It offers a marathon, a half marathon, a 10K and a free Kids 1K, and the marathon and half marathon are USATF sanctioned and certified. The marathon calls itself a fast Boston Qualifier, with nearly 1,000 feet of net elevation loss; the half marathon drops nearly 200 feet and is pitched as great for a first half.","The time limit is 6.5 hours for the marathon and the half marathon and 3 hours for the 10K. The race’s weather note gives an average low of 46F at the start, and cooler still at the marathon start, so plan layers."),le("Where do the Mesa Marathon, half marathon and 10K start and finish?","The marathon starts on N Ellsworth Road near the Rio Salado Sportsman’s Club, below Usery Mountain; the half marathon starts on E McDowell Rd between Ogden St and Greenfield Rd; the 10K starts on E 8th St, just north of the baseball diamonds at Fitch Park; all three finish at Paseo Lago Vista and N Riverview, with the finish festival at Riverview Park in Mesa.","The marathon runs south on N. Usery Pass Rd with views across the Valley, the half marathon descends from McDowell Road past citrus groves, and the 10K winds through historic downtown Mesa before joining the other two for the same finish. The course is paved asphalt throughout.","Riverview Park is at 2100 W Rio Salado Pkwy, Mesa, AZ 85201, beside Sloan Park at 2330 W Rio Salado Pkwy, where the race buses load and the expo is held."),le("How do runners get to the start line: race buses, parking and drop-off?","Marathon and 10K runners must ride the race buses from Sloan Park, because there is no parking or drop-off near those start lines once the roads close; half marathon runners get no bus from Riverview Park and must park at 3260 North 40th Street or be dropped at 4201 East Oasis Street, near their start, with shuttles back from the finish.","Marathon buses load at the southeast corner of Sloan Park, at Sheffield Avenue and Rio Salado Parkway: the first leaves at 4 a.m. and the last at 5 a.m., and runners should be in the parking area by 4:30 a.m. 10K buses load at the southwest corner, at Clark Street and Rio Salado Parkway: the first leaves at 4:45 a.m. and the last at 5:45 a.m., with runners there by 5:15 a.m. All parking around the Riverview Park finish is open to marathon and 10K runners; there are no lots assigned by distance.","A runner who is dropped off rather than parking is asked to get out near Riverview Auto Drive, just east of the bus loading area, to keep clear of the congestion. For the half marathon, the race asks parkers to arrive at the 40th Street lot by 5:15 a.m.; after the race, shuttles staged along Sheffield Street at the finish run back to that lot from 8 a.m., the last at 11:30 a.m.","With a chauffeur, nobody parks at 4 a.m. and nobody needs a car at the finish: we drop the runner exactly where the race asks drop-offs to go, come back for the family later in the morning, and meet everyone at a pickup point agreed in advance."),le("Which roads close for the Mesa Marathon?","Street closures begin at 4 a.m. on Saturday, February 13, and reopen in stages, with every street reopened by 1:30 p.m.; traffic cannot cross the race route during the event, so the race advises skirting it on the 202 Red Mountain Freeway, the 101 Price Freeway and US 60, the Superstition Freeway.","The race links a detailed map of the route and its closures from its information page, and a traffic and detours PDF. Expect slow traffic around the course all morning.","This is the reason to book a chauffeur rather than drive: your driver plans the approach around the closures, and the family is not stuck on the wrong side of the course when the runner finishes."),le("Where can spectators watch the Mesa Marathon, and where do you meet your runner?","Spectators are welcome along most of the route, and the race recommends spots such as Hawes Rd and E McDowell Rd, N Power Rd and E Thomas Rd, WAXIE Sanitary Supply at 4136 E McDowell Rd, Mesa Dr and E Brown Rd, Westwood High School at 945 W Rio Salado Pkwy and the finish line approach on N. Riverview; runners pass through an enclosed Runner Services area after the finish, and families meet them in the festival area north of the finish line.","Confetti cannons are not permitted and bring fines and removal. Spectators must follow the instructions of volunteers and police at all times. Runners cannot re-enter Runner Services once they leave it, so they should collect the medal and recovery items first.","Community groups can take over an aid station in the Mesa Marathon Cheer Challenge, with music, costumes and signs; runners vote, and the top groups win a donation to their organization."),le("When and where is the Mesa Marathon expo and packet pickup?","The Health & Lifestyle Expo is on Friday, February 12, 2027, at Sloan Park, entered through the Home Plate Gate; it opens at 9 a.m. and closes at 5:30 p.m., and there is no race-day packet pickup for the marathon, half marathon or 10K.","Each runner brings a valid photo ID or a copy of the confirmation email to collect the bib, timing chip and shirt. Someone picking up for another runner needs that runner’s ID (a photo or copy is accepted) or the confirmation email, and a written note authorizing it. Runners who cannot attend can choose bib mailing at registration, for a fee."),le("What should Mesa Marathon runners bring on race morning?","Bring the bib, warm layers to shed and the race bag from the expo: each start has a gear check truck, bags must be on it by 6 a.m., and the race asks runners not to leave phones, wallets or car keys in checked bags; start chutes open at 6 a.m.","The race supplies disposable gloves and a mylar blanket in the race bag for the cold start. Clothing shed along the course is collected and donated to charity.","With a chauffeured morning, the phone, wallet and keys can stay in the vehicle with the family, and the dry clothes wait at the finish instead of in a gear truck."),le("Is the Mesa Marathon good for kids and families?",`Yes: the free Kids 1K at noon is for children 12 and under, limited to the first 700 registrants, and starts at the northeast corner of Riverview Park, near the playground, beside the finish festival; for a family ride, our house rule applies: ${Ft}`,"Strollers are allowed in the Kids 1K, at the back of the pack, but not on the race buses or in the marathon, half marathon or 10K. The race asks Kids 1K families to reach Riverview Park from the west on Rio Salado Parkway, then Clark Street or Sheffield Avenue to Cubs Way to park.","Families ride the Executive Sprinters, never a party unit, and no family package carries a drink service. The finish festival’s beer garden is the race’s, for runners of legal age; we sell no alcohol."),le("Is the Mesa Marathon the same race as the Phoenix Marathon?","No: the Mesa Marathon is the race formerly called the Mesa-Phoenix Marathon, and the Phoenix Marathon is a separate race; runners who complete any distance at the 2026 Phoenix Marathon and any distance at the 2027 Mesa Marathon earn the Desert Double medal.","This guide covers the Mesa Marathon only. Check the Phoenix Marathon’s own site for its date and course."),le("What does a chauffeured race morning cost?",`A race morning is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${b(pe)} is ${Ir(pe)}/hr and seats ${xe(pe)}, the ${b(Qa)} is ${Ir(Qa)}/hr, and a ${b(Nn)} is ${Ir(Nn)}/hr; race entry is sold by the race, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${xe(pe)} riders in the ${b(pe)} for 7 hours is about ${hh(pe,7,xe(pe))} each before tax. A club of ${xe(ot)} sharing the ${b(ot)} for 7 hours at ${Ir(ot)}/hr is about ${hh(ot,7,xe(ot))} each. That is arithmetic on the published rates, not a flat race fare.`,"The hours run from the pickup at your hotel or home to the last drop-off, and the vehicle can wait between the start-line drop and the finish, so the morning is one booking. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books."),le("Which vehicle fits a runner, a family or a running club?",`A runner and the cheer crew lead with the ${b(pe)}, our pick for race morning, or the ${b(Qa)}; running clubs and company teams too big for a Sprinter take the ${b(ot)} or the ${b(sh)}; a post-race celebration rides a Limo Party Sprinter or the ${xe(ih)}-seat party bus, alcohol-free when anyone under 21 is aboard.`,`The table uses current published names, seated capacities, hourly rates and minimums, in four groups. Runners and families: the ${b(pe)} and the ${b(Qa)}. Clubs and teams: the ${b(ot)} and the ${b(sh)}. Celebrations: the ${b(kg)}, the ${b(Nn)} and the ${b(ih)}. VIP: the ${b(za)}, the ${b(Sg)}, the ${b(Wn)} and the ${b(Ln)}.`,`A VIP party larger than the ${b(za)} rides in two vehicles, one booking each for the same day and times: the ${b(za)} with the ${b(Wn)} seats ${xe(za)+xe(Wn)}, and with the ${b(Ln)} it seats ${xe(za)+xe(Ln)}.`),le("How does a chauffeured race morning work, and how far ahead should you book?","Your chauffeur picks the runner up in the dark, drops them near Riverview Auto Drive for the Sloan Park race buses or at 4201 East Oasis Street for the half, brings the family to the finish later in the morning, and drives everyone home from a pickup point agreed in advance; availability varies by day and vehicle, so send the day and the group early.","The first request needs the distance each runner is racing, the pickup address, a likely passenger count and whether the family rides to the finish separately. A club or team does not need every name to begin.",`During the final 48 hours, confirm addresses, phone numbers and the meeting point for the ride home. Reach the reservations team at ${u} or ${p}.`)],$g=[{question:"When is the Mesa Marathon 2027?",answer:"Saturday, February 13, 2027. The marathon, half marathon and 10K start at 6:30 a.m.; the Kids 1K starts at noon."},{question:"Where does the Mesa Marathon finish?",answer:"All three races finish at Paseo Lago Vista and N Riverview, with the finish festival at Riverview Park, 2100 W Rio Salado Pkwy, Mesa."},{question:"Can you be dropped off at the Mesa Marathon start line?",answer:"Not for the marathon or 10K: those runners must ride the race buses from Sloan Park, and drop-offs go near Riverview Auto Drive. Half marathon runners are dropped at 4201 East Oasis Street, near their start."},{question:"What time do the Mesa Marathon buses leave?",answer:"Marathon buses leave Sloan Park from 4 a.m.; the last leaves at 5 a.m. 10K buses leave from 4:45 a.m.; the last leaves at 5:45 a.m. There is no bus to the half marathon start."},{question:"When do roads reopen after the Mesa Marathon?",answer:"Closures begin at 4 a.m. and streets reopen in stages, all of them by 1:30 p.m."},{question:"Was the Mesa Marathon called the Mesa-Phoenix Marathon?",answer:"Yes. The Mesa Marathon was formerly known as the Mesa-Phoenix Marathon. The Phoenix Marathon is a separate race."},{question:"Is the Mesa Marathon a Boston qualifier?",answer:"Yes. The race describes the marathon as a fast Boston Qualifier on a USATF-certified course."},{question:"Can you hire a Sprinter for the Mesa Marathon?",answer:`Yes. The ${b(pe)} and the white Executive Sprinter are booked by the hour, pickup to drop-off, for the race buses, the finish and the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],Cg={path:"/guides/mesa-marathon",title:"Mesa Marathon 2027: race buses, start lines, finish and a chauffeured race morning",metaTitle:"Mesa Marathon 2027: Buses & Finish",description:"The Mesa Marathon, formerly the Mesa-Phoenix Marathon, on February 13, 2027: start times and start lines, the Sloan Park race buses, half marathon parking and drop-off, road closures, where to cheer, the expo, the Kids 1K, and a chauffeured race morning for runners and families.",metaDescription:"Mesa Marathon, Feb 13, 2027: start times, race buses, drop-off, road closures, finish, and a chauffeured race morning",lastUpdated:nh,lastUpdatedLabel:l(nh),eyebrow:"Saturday, February 13, 2027 · Mesa",intro:`A race morning with Scottsdale Sprinters starts with the race’s own times, the distance each runner is racing and a rider count. Runners and their cheer crews lead with the ${b(pe)}; running clubs and company teams take the ${b(ot)} or the Executive Mini Coach; a post-race celebration rides a Limo Party Sprinter, alcohol-free when anyone under 21 is aboard. This guide uses only facts the Mesa Marathon publishes, and turns race day into a written pickup, drop-off and ride home.`,sections:Tg,faqs:$g,links:[{href:"/fleet/executive-sprinter-scottsdale",label:b(pe)},{href:"/fleet/executive-white-sprinter-scottsdale",label:b(Qa)},{href:"/fleet/executive-mini-bus-26-scottsdale",label:b(ot)},{href:"/service-areas/mesa",label:"Mesa service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:Ag,fleetRows:vg},dh="2026-09-27",Pg="/guides/venues/mullett-arena",Eg=1500,Js=h(Eg),aa="ultra-luxury-party-sprinter-scottsdale",On="maybach-jet-sprinter-scottsdale",Fg="maybach-shuttle-sprinter-8",Mg="premium-suv-scottsdale",ra="limo-sprinter-13-scottsdale",_n="limo-sprinter-16-scottsdale",Gn="party-bus-28-scottsdale",oa="executive-sprinter-scottsdale",Rg="executive-white-sprinter-scottsdale",Un="executive-mini-bus-26-scottsdale",Bn="executive-luxury-bus-29-scottsdale",M=e=>n[e],mt=e=>i[e],Hn=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,mr="https://www.mullettarena.com",xg=`${mr}/a-zguide/`,Dg=`${mr}/know-before-you-go/`,Ig=`${mr}/parking/`,Ng=`${mr}/directions/`,Wg=`${mr}/box-office-information/`,Lg="https://thesundevils.com/facilities-venues/mullett-arena",Og="https://thesundevils.com/clear-bag-policy",_g="https://thesundevils.com/sports/mens-ice-hockey/schedule",Gg="https://cfo.asu.edu/multipurpose-arena",Ug=[{label:"Mullett Arena, A-Z guide",href:xg},{label:"Mullett Arena, know before you go",href:Dg},{label:"Mullett Arena, parking",href:Ig},{label:"Mullett Arena, directions, rideshare and light rail",href:Ng},{label:"Mullett Arena, box office information",href:Wg},{label:"Sun Devil Athletics, Mullett Arena",href:Lg},{label:"Sun Devil Athletics, clear bag policy",href:Og},{label:"Sun Devil Athletics, 2026–27 men’s hockey schedule",href:_g},{label:"Arizona State University, Mullett Arena",href:Gg}],Cd=["January","February","March","April","May","June","July","August","September","October","November","December"],Bg=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function Hg(e){const[t,a,o]=e.split("-").map(Number);return`${Bg[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${Cd[a-1]} ${o}, ${t}`}function lh(e){const[t,a,o]=e.split("-").map(Number);return`${Cd[a-1]} ${o}, ${t}`}function zg(e){const t=fa(`${e.date}T${e.starts}:00-07:00`);return`${Hg(e.date)}: ${e.title} (${e.kind==="game"?"puck drop":"show"} ${t}).`}function tt(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Zs=Kd,Nr=Zs.filter(e=>e.kind==="game"),qg=Zs.filter(e=>e.kind==="concert"),Vg=[tt("How does parking work at Mullett Arena?",`ASU Parking controls all event parking at Mullett Arena: Sun Devil hockey, concerts and touring shows park in the Packard Structure garage, off Packard Drive and 6th Street, and/or the Novus garage; Sun Devil games cost ${Js}, concert parking varies by show, and the lots are staffed 3 hours before the event.`,"Pay on site by credit card when you arrive, or buy parking ahead through the team’s or the show’s Ticketmaster page, which may add Ticketmaster fees. With ParkMobile at ASU you can also pay from your phone when you arrive on campus.","For hockey, Sun Devil Athletics lists the Packard Drive Structure, the Novus Parking Structure (only in the spring) and a surface lot for hockey season pass holders only.","The arena is cashless, with no ATMs inside, so a card or phone covers the parking and the concessions alike."),tt("Where is the drop-off at Mullett Arena?","Mullett Arena’s one published drop-off point is Lot 10, at the northeast corner of Rio Salado Parkway and Packard Drive, where Lyft, the arena’s rideshare partner, picks up and drops off; the venue publishes no separate area for limousines, charters or buses.","That is where a chauffeured group unloads too, unless ASU Parking directs otherwise on the night. We unload the group in Lot 10 and agree one pickup point there for the ride home before the puck drops or the show starts.","No curb is held for booked vehicles. If the arena or ASU posts a different plan for an event, that plan comes first.","A group that splits across cars also splits across the garage and the exit line. One vehicle arrives with everyone at once and leaves with everyone at once."),tt("Where is Mullett Arena, and how do you get there?","Mullett Arena is at 411 South Packard Drive, Tempe, on ASU’s Tempe campus, just west of Rural Road, south of Rio Salado Parkway and the 202 and north of University Drive; from the Loop 202, take Exit 7 (Scottsdale Road and Rural Road) south, turn right on Rio Salado Parkway and left on Packard Drive, and the arena is on your left.","From the south, head north on Rural Road, turn left on 6th Street and right on Packard Drive. The closest light rail stops the arena names are Veterans Way and College Avenue, and Mill Avenue and 3rd Street.","The arena opened in 2022 and was the Arizona Coyotes’ home for the 2022-23 and 2023-24 NHL seasons, ASU says. A chauffeured group needs no directions: the driver takes the group to Lot 10 and waits for the ride home."),tt("What time do doors open at Mullett Arena?","Doors at Mullett Arena open 1 hour before Sun Devil events, and typically 1 hour before concerts and special events, when each show’s page lists its own time; every entrance has a bag check and metal detectors, so arrive early enough to clear security.","Tickets are paperless, on your phone through Ticketmaster, and there is no re-entry. The box office, at 411 South Packard Drive, opens an hour before Sun Devil events and ahead of concerts at times that vary by show; guest services is at the box office, on the south side behind section 110.","For Sun Devil events, children aged 3 and older need a ticket; under 3 they share a seat with an adult. Some events have their own age requirements, and a hockey game has two intermissions.","ASU is a smoke-free, tobacco-free campus, vaping included, inside and outside the arena."),tt("What is the Mullett Arena bag policy?","For Sun Devil events Mullett Arena has a clear bag policy: clear bags no larger than 12 by 6 by 12 inches, plus a small bag no larger than 4.5 by 6.5 inches; for shows and concerts each event page sets its own policy, most of them the same, and every bag is subject to search.","Not allowed: backpacks, large purses, oversized totes, colored plastic bags, solid drawstring bags, camera bags, binocular cases, mesh bags and reusable grocery bags, and there is no check-in location for them. Luggage is not permitted either.","Also not allowed: outside food and beverages, weapons, refillable or metal water bottles, strollers, selfie sticks, professional cameras with detachable lenses, noise makers, laser pointers, balloons and hockey sticks. One sealed plastic water bottle per guest is allowed.","Settle bags before you leave: a group that is dropped off has no car in the garage to go back to, and the arena says turned-away items go back to the vehicle or are discarded."),tt("What is the seating like at Mullett Arena, and how many people does it hold?","Mullett Arena is a 5,000-seat arena on three levels, with two NHL regulation-size ice sheets, 20 suites for 17 people each and 2 group suites for 29, loge boxes at center ice and rinkside, and a social deck on the 300 level that runs the length of the east side.","The arena is fully ADA accessible, with elevators at the VIP entrance on the southeast side and on the northeast side behind section 105, wheelchairs through guest services, and a KultureCity sensory inclusive certification.","ASU says the arena can be transformed for concerts; the show’s own seating chart is on its ticket page. For a group, book the seats together and the ride together, and the night stays together."),tt("Which vehicle fits a Mullett Arena group?",`A VIP night takes the ${M(On)}, the ${M(aa)}, the ${M(Fg)} or the ${M(Mg)}. Game-night and concert crews ride the ${M(ra)}, the ${M(_n)} or the ${M(Gn)}. Families, company nights and big groups take the ${M(oa)}, the ${M(Rg)}, the ${M(Un)} or the ${M(Bn)}.`,`Seat counts are seated capacities from the fleet: the ${M(aa)} seats ${mt(aa)}, the ${M(ra)} ${mt(ra)}, the ${M(_n)} ${mt(_n)}, the ${M(Gn)} ${mt(Gn)} and the ${M(On)} ${mt(On)}. The ${M(oa)} seats ${mt(oa)}, the ${M(Un)} ${mt(Un)} and the ${M(Bn)} ${mt(Bn)}.`,`Our pick for a night at the arena is the ${M(aa)}, ${Hn(aa)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${M(ra)} is ${Hn(ra)}, and the ${M(oa)} is ${Hn(oa)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),tt("How should a group plan the ride to a Mullett Arena game or show?","Plan backwards from the puck drop or the show time: doors open 1 hour before Sun Devil events and typically 1 hour before concerts, so a pickup that lands the group in Lot 10 around doors leaves room for the bag check and the metal detectors.","The ride home is the part to plan hardest. Agree the pickup point before the game or the show, and your chauffeur is waiting when it ends, so the group walks out to its own vehicle instead of the garage line.","Families bring children to Sun Devil games (every child aged 3 and older needs a ticket). If even one passenger is under 21, the trip is alcohol-free for the whole group, adults included; we sell no alcohol on any trip.",`Book by the hour and the vehicle is yours for the whole night, dinner in Tempe before the game included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the game or show, the date, the pickup area and the rider count.`)],Yg=tt("What’s coming up at Mullett Arena?",`Coming up at Mullett Arena: ${qg.length} concerts, Hudson Westbrook, YG, Morrissey and Motown for Veterans, and Sun Devil men’s hockey at home, ${Nr.length} Friday series openers from ${lh(Nr[0].date)} to ${lh(Nr[Nr.length-1].date)}. As the venue and Sun Devil Athletics listed them on September 27, 2026:`,...Zs.map(zg),"Each hockey series has a second home game the next day. New events are added to the arena’s calendar through the season, and it is the place to check before you book."),Jg=[{question:"Where do you park for Mullett Arena?",answer:"ASU Parking runs it: the Packard Structure garage, off Packard Drive and 6th Street, and/or the Novus garage. Pay by card on arrival or buy ahead through Ticketmaster."},{question:"How much is parking at Mullett Arena?",answer:`${Js} for Sun Devil games; concert parking varies by show. Pay by card on site, or ahead through the event’s Ticketmaster page.`},{question:"Where is the drop-off at Mullett Arena?",answer:"Lot 10, at the northeast corner of Rio Salado Parkway and Packard Drive, is the rideshare pickup and drop-off. A chauffeured group unloads there too, unless ASU Parking directs otherwise."},{question:"What is the Mullett Arena bag policy?",answer:"For Sun Devil events, clear bags no larger than 12 by 6 by 12 inches, plus a small bag up to 4.5 by 6.5 inches. Concerts set their own policy on the event page. No backpacks, and no bag check."},{question:"How many seats does Mullett Arena have?",answer:"The arena has 5,000 seats on three levels, with 20 suites, 2 group suites and loge boxes."},{question:"What time do doors open at Mullett Arena?",answer:"One hour before Sun Devil events, and typically one hour before concerts; the show’s page has its time."},{question:"Is Mullett Arena cashless?",answer:"Yes. Cash is not accepted and there are no ATMs; tickets are mobile only, through Ticketmaster."},{question:"Is there light rail to Mullett Arena?",answer:"The arena names two closest stops: Veterans Way and College Avenue, and Mill Avenue and 3rd Street."},{question:"Do kids need a ticket at Mullett Arena?",answer:"For Sun Devil events, children aged 3 and older need a ticket; under 3 they share a seat with an adult."},{question:"Did the Coyotes play at Mullett Arena?",answer:"Yes. ASU says the arena hosted Arizona Coyotes home games in the 2022-23 and 2023-24 NHL seasons."}],Zg={path:Pg,title:"Mullett Arena Parking Guide: Seating, Drop-Off, Sun Devil Hockey and Concerts",metaTitle:"Mullett Arena Parking and Seating",description:"Mullett Arena on ASU’s Tempe campus: ASU event parking and the Sun Devil game fee, the Lot 10 drop-off, doors, the clear bag policy, seating and suites, Sun Devil hockey and the concerts, and a chauffeured ride so nobody drives or parks.",metaDescription:"Parking, the Lot 10 drop-off, the bag policy and a chauffeured ride",lastUpdated:dh,lastUpdatedLabel:l(dh),eyebrow:"Tempe · Campus",intro:`Scottsdale Sprinters’ short answer on Mullett Arena parking: ASU Parking runs it, in the Packard Structure garage off Packard Drive and 6th Street and/or the Novus garage, ${Js} for Sun Devil games and varying by show for concerts, paid by card. The 5,000-seat arena is at 411 South Packard Drive on ASU’s Tempe campus, doors open an hour before Sun Devil events, and the one published drop-off point is Lot 10, at Rio Salado Parkway and Packard Drive. For a group, one chauffeured vehicle replaces the garage, the card reader and the drive home.`,sections:[...Vg,Yg],faqs:Jg,links:[{href:"/guides/venues/asu-gammage",label:"ASU Gammage parking and Broadway nights"},{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts 2026–27, every show by venue"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/tempe",label:"Tempe service area"},{href:`/fleet/${aa}`,label:M(aa)},{href:`/fleet/${ra}`,label:M(ra)},{href:`/fleet/${oa}`,label:M(oa)},{href:"/pricing",label:"Published hourly pricing"}],sources:Ug},ch="2026-09-25",Kg="/guides/nba-all-star-weekend-2027",zn={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],fans:["executive-sprinter-scottsdale","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-white-sprinter-scottsdale","executive-luxury-bus-29-scottsdale","executive-mini-bus-26-scottsdale","motorcoach-56"]},jg=[...zn.vip,...zn.fans,...zn.corporate].filter(ae),Pd=jg.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),H="maybach-jet-sprinter-scottsdale",uh="ultra-luxury-party-sprinter-scottsdale",Wr="maybach-shuttle-sprinter-8",Lr="premium-suv-scottsdale",kt="executive-sprinter-scottsdale",Qg="executive-luxury-bus-29-scottsdale",Xg="motorcoach-56",I=e=>n[e],ve=e=>i[e],qn=e=>h(r[e].hourlyRateCents);function ph(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}const ey=Math.max(...Pd.map(e=>e.capacity)),Ed="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.",ty="https://www.nba.com/news/phoenix-suns-nba-all-star-2027-official-release",ay="https://pr.nba.com/phoenix-to-host-nba-all-star-2027/",ry="https://www.phoenix.gov/major-events.html",oy="https://mortgagematchupcenter.com/plan-your-visit/transportation-parking/",ny="https://mortgagematchupcenter.com/venue/accessibility-ada-information/",sy="https://mortgagematchupcenter.com/",iy="https://mortgagematchupcenter.com/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/",hy=[{label:"NBA: Phoenix Suns to host NBA All-Star 2027 (official release)",href:ty},{label:"NBA Communications: Phoenix to host NBA All-Star 2027",href:ay},{label:"City of Phoenix: major events, NBA All-Star 2027",href:ry},{label:"Mortgage Matchup Center: transportation and parking",href:oy},{label:"Mortgage Matchup Center: accessibility, drop-off and pickup",href:ny},{label:"Mortgage Matchup Center: bag policy and parking",href:sy},{label:"Mortgage Matchup Center: the arena’s new name",href:iy}];function gt(e,t,...a){return{question:e,answer:t,paragraphs:a}}const dy=[gt("When is NBA All-Star weekend 2027, and where is it?","NBA All-Star 2027 is in Phoenix from Friday, February 19 to Sunday, February 21, 2027. The 76th NBA All-Star Game is on Sunday, February 21, at Mortgage Matchup Center, home of the Phoenix Suns, at 201 East Jefferson Street in downtown Phoenix. Tip-off times are announced by the NBA closer to the date.","The NBA announced Phoenix as the host on March 7, 2024. Its release names the arena Footprint Center; it is the same building, renamed Mortgage Matchup Center by the Suns and the Mercury on October 2, 2025. Use that name when you book and when you give the address: 201 East Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson.","As announced in March 2024, the on-court events start on Friday, February 19, with a showcase of top rookies and second-year players, then a Saturday night of contests on February 20, and the All-Star Game itself on Sunday, February 21. The NBA also plans a practice, a celebrity game and a fan fest at venues around Phoenix. Where and when each of those takes place is announced by the NBA closer to the date.","So this page prints no tip-off time, no Saturday venue and no fan-fest address. When the NBA publishes the 2027 schedule, the reservations team plans each pickup from it, not from a previous year’s weekend. Until then a quote can still hold the days, the hotel, the group size and the vehicle."),gt("Where do you park for the NBA All-Star Game, and where is drop-off?","For a game or event, Mortgage Matchup Center publishes 3rd Street, just south of Jefferson, at the green curb as its drop-off and pickup, and garages within walking distance bought ahead through ParkWhiz. The 2027 All-Star parking and traffic plan is announced closer to the date. With a chauffeured ride nobody drives or parks.","The arena’s own event-night plan, which is the one published now: several garages and lots within walking distance, with guests encouraged to buy parking in advance through ParkWhiz. Event parking is generally available from about 30 minutes before doors open, parking does not include in-and-out privileges, and availability, pricing and access may vary by event. The arena lists more than 700 on-site spaces and publishes no price.","Valet is available only for select ticketed guests and membership-based areas; it is not open to the general public. Vehicles cannot be parked or left unattended in the drop-off zones, so the curb on 3rd Street is a place to unload, not to wait. Drop-off for will call and the ticket office is on 1st Street, just north of Madison.","An All-Star weekend can bring its own street closures and a security perimeter around the arena. None is published for 2027, so this page does not guess one. Your chauffeur unloads at the arena’s published curb or where event and police staff direct, and the reservations team passes on any 2027 instruction the NBA or the city publishes."),gt("Where do rideshares drop off and pick up at Mortgage Matchup Center?","The arena lists 4 Lyft drop-off points: 1st Street at Jefferson by the arena plaza, South 2nd Street, South 3rd Street at the Phoenix Convention Center, and East Jefferson Street. Rideshare pickup is at South 3rd Street and East Jefferson Street, by the Phoenix Convention Center. A booked chauffeur uses the 3rd Street curb or where staff direct.","After a game every rideshare in downtown Phoenix is heading for the same corner. A chauffeured vehicle is booked before the weekend, so the group is not waiting on surge pricing or a car that cannot reach the pin. Name one meeting point before going in, and one person who counts heads before anyone walks to the curb.","Light rail is the other published option: the arena says light rail fare is included in a ticket to any game or event there, bus fare excepted. Stations and bus stops are on accessible routes. That helps a guest who is staying downtown; a group coming from a Scottsdale resort usually wants the door-to-door ride."),gt("Which vehicle fits an All-Star VIP, fan or corporate group?",`VIP and courtside guests lead with the ${I(H)}, which seats ${ve(H)}, then the ${I(uh)}, the ${I(Wr)} and the ${I(Lr)}; friends and fan crews ride the ${I(kt)} or a Limo Party Sprinter; corporate hosts take the mini coach, the white Sprinter, the mini bus or the full-size coach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in the page’s three groups. VIP and courtside guests: the ${I(H)}, our pick for All-Star weekend, seats ${ve(H)} at ${qn(H)}/hr in a private jet cabin with Maybach massage recliners, a wet bar and a full partition, then the ${I(uh)}, the ${I(Wr)} and the ${I(Lr)}.`,`A VIP party larger than the ${I(H)} rides in two vehicles, one booking each for the same times: the ${I(H)} with the ${I(Wr)} seats ${ve(H)+ve(Wr)}, and with the ${I(Lr)} it seats ${ve(H)+ve(Lr)}. Friends and fan crews: the ${I(kt)} and the two Limo Party Sprinters. Corporate hospitality: the ${I(Qg)}, the Executive White Sprinter, the Mini Bus and the ${I(Xg)}, the largest in the table at ${ey} seats.`,"Count riders for each direction. The ride to the game and the ride home are often different lists, and a guest who leaves with another host should come off the return manifest before seats are assigned. Arrive without bags where you can: the arena encourages it, allows small clutches and crossbody bags, and does not allow standard backpacks inside."),gt("How does pickup after the All-Star Game work downtown?","Plan 2 steps: the group gathers at one meeting point the chauffeur and the transportation lead agreed before tip-off, then walks to the vehicle together once the lead confirms where it is. No vehicle may wait in the arena’s drop-off zone, so the chauffeur clears the curb after drop-off and comes back for the group.",`What if the game runs late? ${Ed}`,"Book by the hour and the vehicle is yours for the whole block: the dinner before, the arena, the after-party and the ride back to the hotel. A ride there and a ride back is the other shape; it suits a group that knows it will leave with the crowd. Either way the chauffeur follows event and police staff on the day.","For more than one return wave, label each vehicle, its lead and its hotel. A VIP group heading to a resort and a client group heading to another hotel should not rely on spotting a driver in a crowd. The final sweep checks the manifest before the vehicle rolls."),gt("Can one booking cover the whole All-Star weekend?","Each day is its own booking by the hour, and one request can hold all 3 days, February 19 to 21: the reservations team quotes each day’s vehicle and hours together. Friday and Saturday times are announced by the NBA closer to the date, so those blocks stay flexible until the schedule is out.","A weekend plan often starts at the airport: a VIP guest landing at Phoenix Sky Harbor can be met there and driven to the hotel, and the rest of the weekend fills in around the game, with dinners, a hotel party and the fan events once the NBA names their venues.","Write one line per day: the pickup address and ready time, the destination, the return rule, and the name of the person who owns the headcount. Leave the unannounced lines open rather than copying last year’s weekend, and let the reservations team fill them in when the NBA publishes the 2027 schedule."),gt("How far ahead should All-Star weekend transportation be booked?",`No fixed lead time applies: availability for February 19 to 21 varies by vehicle, and the ${ve(H)}-seat ${I(H)} is a single unit. Request a quote with the days, the hotel, the rider count and the group, and the reservations team confirms what is open and holds it in writing.`,"The first request needs the days, the lodging or pickup area, the likely passenger count and which group is riding: VIP and courtside guests, a fan crew or a corporate hospitality list. A group does not need every name to begin, but it should separate committed riders from possible ones.",`In the final 48 hours, verify addresses, contact numbers and the newest NBA and arena directions, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${u} or ${p}.`),gt("How is All-Star transportation priced per person?",`For ${ve(H)} guests sharing the ${I(H)} across 5 billed hours, its published ${qn(H)}-per-hour rate works out to about ${ph(H,5,ve(H))} per person before tax for the whole shared ride; the price changes with the vehicle, the hours, the add-ons and the confirmed plan.`,`The same arithmetic for a fan crew of ${ve(kt)} in the ${I(kt)} at ${qn(kt)}/hr for 5 hours is about ${ph(kt,5,ve(kt))} each. It is hourly rate times billed hours, divided by riders, not a flat game-night fare. If fewer people ride, divide across fewer.`,"Every vehicle has a minimum number of hours, shown in the table. The ready-made packages on this page add extras from the published add-on list, and each one is priced by the same engine as the vehicle, so the number on the tile is the number at checkout, before tax.")],ly=[{question:"When is NBA All-Star weekend 2027?",answer:"Friday, February 19 to Sunday, February 21, 2027, in Phoenix. The NBA All-Star Game is on Sunday, February 21. The full weekend schedule and tip-off times are announced by the NBA closer to the date."},{question:"Where is the 2027 NBA All-Star Game?",answer:"At Mortgage Matchup Center, home of the Phoenix Suns, 201 East Jefferson Street, Phoenix, AZ 85004. The NBA’s 2024 announcement calls it Footprint Center; the arena was renamed in October 2025."},{question:"What time does NBA All-Star 2027 start?",answer:"Not yet announced. The NBA publishes tip-off times for the Friday, Saturday and Sunday events closer to the date. Book the day now and the reservations team sets the pickup time once the schedule is out."},{question:"Where do you park for the All-Star Game at Mortgage Matchup Center?",answer:"On a normal event night, in the garages and lots within walking distance, bought ahead through ParkWhiz, with no in-and-out. Valet is not open to the general public. The All-Star weekend parking plan is announced closer to the date."},{question:"Where is drop-off at Mortgage Matchup Center?",answer:"On 3rd Street, just south of Jefferson, at the green curb, for games and events. Vehicles cannot wait there, so a chauffeur unloads, clears the curb and comes back for the group at the time you set."},{question:"Is Mortgage Matchup Center the same as Footprint Center?",answer:"Yes. The Suns and the Mercury renamed Footprint Center as Mortgage Matchup Center on October 2, 2025. It is the same arena at 201 East Jefferson Street in downtown Phoenix."},{question:"What if the game runs late?",answer:Ed},{question:"Does a ride booking include All-Star tickets?",answer:"No. Buy tickets only through the NBA’s official channels; a ride booking does not include tickets, credentials or hospitality. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center."}],cy={path:Kg,title:"NBA All-Star 2027 in Phoenix: the weekend, the arena and getting there",metaTitle:"NBA All-Star 2027 Weekend in Phoenix",description:"NBA All-Star 2027 is in Phoenix, February 19–21, with the All-Star Game on Sunday, February 21, at Mortgage Matchup Center. The official dates, what is announced and what is not, the arena’s parking, drop-off and rideshare points, and a chauffeured ride so nobody drives or parks.",metaDescription:"Feb 19–21 in Phoenix, the game at Mortgage Matchup Center, parking, drop-off, and a chauffeured ride",lastUpdated:ch,lastUpdatedLabel:l(ch),eyebrow:"Official dates: February 19–21, 2027",intro:`An All-Star ride from Scottsdale Sprinters starts with the NBA’s own announcement, a realistic rider count and one transportation lead. VIP and courtside guests lead with the ${I(H)}; friends and fan crews ride the ${I(kt)} or a Limo Party Sprinter; corporate hosts take the mini coach, the mini bus or the full-size coach. This guide uses only published NBA and arena facts, leaves the unannounced schedule for closer to the date, and turns each day of the weekend into a written pickup, arrival and return plan. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center.`,sections:dy,faqs:ly,links:[{href:"/fleet/maybach-jet-sprinter-scottsdale",label:n[H]},{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center group arrival guide"},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/experiences/corporate-event",label:"Corporate event transportation planning"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:hy,fleetRows:Pd},fh="2026-09-24",uy="/guides/new-years-eve-scottsdale-phoenix",Ca="ultra-luxury-party-sprinter-scottsdale",mh="limo-sprinter-13-scottsdale",bo="limo-sprinter-16-scottsdale",Vn="party-bus-28-scottsdale",Or="executive-luxury-bus-29-scottsdale",py="executive-mini-bus-26-scottsdale",ir="maybach-jet-sprinter-scottsdale",fy="maybach-shuttle-sprinter-8",Yn="premium-suv-scottsdale",Jn="executive-sprinter-scottsdale",W=e=>n[e],yt=e=>i[e],my="https://decadencearizona.com/",gy="https://decadencearizona.com/faq",yy="https://decadencearizona.com/location",by="https://decadencearizona.com/extras",wy="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",vy="https://www.scottsdaleaz.gov/docs/default-source/scottsdaleaz/transportation/transportation-safety-zone-ordinance.pdf?sfvrsn=fe6b7d49_2",ky="https://www.valleymetro.org/how-to-ride/hours-service",Sy="https://www.phoenix.gov/newsroom/public-transit-news/free-rides-return-to-phoenix-for-new-year-s-eve.html",Ay="https://www.scottsdaleaz.gov/transit-system",Ty="https://www.visitphoenix.com/events/annual-events/new-years-eve-events/",$y="https://event.marriott.com/phxwh-w-scottsdale/events/scottsdale/new-years-eve-event-with-fireworkds",Cy="https://www.fiestasportsfoundation.org/news/2026/9/14/cactus-bowl-tickets-now-on-sale-for-saturday-night-primetime-college-football-postseason-action-in-tempe-at-mountain-america-stadium.aspx",Py="https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx",Ey=[{label:"Decadence Arizona 2026, official site",href:my},{label:"Decadence Arizona FAQ: age, doors, parking, re-entry and bags",href:gy},{label:"Decadence Arizona location, parking and transit",href:yy},{label:"Decadence Arizona extras: premium parking and the Tempe shuttle",href:by},{label:"City of Scottsdale, Transportation Safety Zone",href:wy},{label:"City of Scottsdale, Transportation Safety Zone ordinance",href:vy},{label:"Valley Metro hours of service and holiday schedule",href:ky},{label:"City of Phoenix, New Year’s Eve 2025 free rides (last year)",href:Sy},{label:"City of Scottsdale trolley service",href:Ay},{label:"Visit Phoenix New Year’s Eve events",href:Ty},{label:"W Scottsdale New Year’s Eve 2025 event page (last year)",href:$y},{label:"Fiesta Sports Foundation, Cactus Bowl 2026",href:Cy},{label:"Fiesta Sports Foundation, Vrbo Fiesta Bowl dates",href:Py}];function Nt(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Fy=[Nt("What is on in Scottsdale and Phoenix for New Year’s Eve 2026?","New Year’s Eve 2026 is Thursday, December 31, 2026. Confirmed so far: Decadence Arizona on December 30 and 31 at Phoenix Raceway in Avondale, the Fiesta Bowl on December 30 in Glendale, and the Cactus Bowl on December 26 in Tempe. Scottsdale, Phoenix and Tempe have not published their 2026 New Year’s Eve events yet.","As of September 24, 2026, the official listings still describe last year. Visit Phoenix’s New Year’s Eve page and Experience Scottsdale’s New Year’s Eve story both still cover New Year’s Eve 2025. The City of Phoenix major-events page lists no New Year’s Eve event, and neither does Old Town Scottsdale’s official events list. Last year the official listings were resort, hotel, bar and venue parties, with no city-run celebration. The 2026 events are announced closer to the date; recheck the official pages in December.","The Vrbo Fiesta Bowl, a College Football Playoff quarterfinal, kicks off at 5:30 p.m. Arizona time on Wednesday, December 30, the same night as the first night of Decadence. Our Fiesta Bowl guide covers the game.","New Year’s Day is Friday, January 1, 2027. Plan the ride home for the early hours of that morning, not for the evening of December 31."),Nt("How do drop-off and pickup work in Old Town Scottsdale on New Year’s Eve?","Old Town Scottsdale’s Transportation Safety Zone is in effect every night from 5 p.m. to 4 a.m., New Year’s Eve included. While it is in effect, hired vehicles load and unload only at the marked Passenger Convenience Areas and vehicle-for-hire lanes, never in a through lane, so your chauffeur stops where the city allows.","The zone covers the downtown entertainment district east of Buckboard Trail, from Sixth Avenue to Camelback Road, Sunday through Saturday. The city’s ordinance counts limousines, livery vehicles and any other motorized vehicle that carries passengers for hire as vehicles for hire. Stopping, standing, loading or unloading in a designated through lane is not allowed while the zone is in effect.","Exact curbs follow the posted signs, so the chauffeur goes by the signs and the officers on the night rather than an old map. No Old Town street closures or rideshare zones have been published for New Year’s Eve 2026; they are announced closer to the date if the city sets any.","Agree one loading point for the whole group before midnight. A crew spread across three bars walks to that point together, and the transportation lead calls the chauffeur once everyone is there. Nobody steps into a through lane to meet the vehicle."),Nt("How do you get to Decadence Arizona at Phoenix Raceway?","Decadence Arizona runs December 30 and 31, 2026, at Phoenix Raceway, 7602 Jimmie Johnson Drive, Avondale, off I-10 and Loop 202. Doors open at 6 p.m. and the event ends at 3 a.m. both nights. The organizer says public transit is limited and recommends personal vehicles, event shuttles or rideshare.","Parking lots open at 4 p.m. Free parking is Entry G, premium parking is Entry F and rideshare is Entry E, and the organizer asks drivers to stay in the right lane until they reach their entry. There is no overnight parking: cars left behind are towed at the owner’s expense, on a night that ends at 3 a.m.","The organizer has not published a lane for limousines, party buses or charters. The only drop-off lane it names is Rideshare, Entry E, and its location page says dedicated rideshare pick-up and drop-off points operate near the primary entrance gates. Your chauffeur follows event staff on the night. If the organizer publishes charter guidance, that replaces this paragraph.","Wristbands scan once a day, so there is no leaving and coming back on the same night, and set times are released the week of the event. The organizer also sells a round-trip shuttle from Sunbar in Tempe as an extra, and two West Valley hotel packages include a festival shuttle."),Nt("What should a Decadence group know before the ride?","Decadence is strictly 18 and over with a physical government-issued photo ID, and 21 and over for alcohol service, so a ride group can include riders under 21. The event is cashless, enforces a clear-bag policy, and does not admit patrons who are clearly intoxicated or under the influence of drugs.","The largest bag allowed is a clear bag up to 15 by 15 by 5 inches, or a one-gallon clear freezer bag, plus one small clutch up to 5 by 7 by 2 inches. An empty hydration pack of that size with no more than 2 pockets is the only exception. Outside food and drinks, glass, cans, coolers, chairs and festival totems are not allowed; two factory-sealed water bottles are.","There are no ATMs on site. The event takes Visa, Mastercard, American Express, Discover, Apple Pay and Google Pay.","Tell the reservations team the ages in the group when you book. Our guide to Arizona party bus alcohol rules explains what applies on board."),Nt("Which vehicle fits which New Year’s Eve group?",`VIP and dinner parties ride the ${W(ir)}, the ${W(Ca)}, the ${W(fy)} or the ${W(Yn)}. Old Town crews take a Limo Party Sprinter or the ${W(Jn)}. Decadence and big crews take the ${W(Vn)}, the ${W(Or)} or the ${W(py)}.`,`Seat counts are seated capacities from the fleet: the ${W(Ca)} seats ${yt(Ca)}, the ${W(ir)} ${yt(ir)}, the ${W(mh)} ${yt(mh)}, the ${W(bo)} ${yt(bo)} and the ${W(Jn)} ${yt(Jn)}. The ${W(Vn)} seats ${yt(Vn)}, the ${W(Or)} ${yt(Or)}, and the ${W(Yn)} ${yt(Yn)}.`,`Our pick for the night is the ${W(Ca)}: fiber-optic lighting with eighteen modes, lasers and a fog machine for the countdown, and a full partition with an intercom to your chauffeur. It rides with the VIP group because it is one of our ultra-luxury units.`,`When a group outgrows its row, the page offers the next row that seats everyone: a VIP table or an Old Town crew too big for its row moves up to the party bus or a coach. For a group bigger than the ${W(Or)}, we plan two or more vehicles and quote them together.`,"Count riders for each direction. The group that leaves at 6 p.m. and the group that rides home at 3 a.m. are often different lists, and the return manifest is the one that matters."),Nt("How late can you ride home on New Year’s Eve?","As late as you book. Reserve by the hour and the vehicle is yours for the whole night block, or book a ride there and a ride back. Valley Metro light rail’s last full trips start between 10:50 p.m. and 12:10 a.m., and no New Year’s Eve extension has been announced for 2026.","Last New Year’s Eve (2025), Valley Metro bus, rail and paratransit rides were free from 7 p.m. on December 31 to 2 a.m. or end of service on January 1. The 2026 plan is announced closer to the date; recheck in December.","Scottsdale’s free trolleys run Monday to Friday, 5:45 a.m. to 7:45 p.m., and do not run on New Year’s Day. On New Year’s Day, light rail and streetcar run a Sunday schedule.",`Decadence ends at 3 a.m. and allows no overnight parking, so the ride home is the leg to book first. Reach the reservations team at ${u} or ${p} with the date, the pickup area, the rider count and the night you are planning.`),Nt("When and where is the Cactus Bowl?","The Cactus Bowl is Saturday, December 26, 2026, at 5:30 p.m. Arizona time at ASU’s Mountain America Stadium in Tempe: Big Ten against Big 12. Parking, rideshare and drop-off for the bowl are announced closer to the date, so plan the ride around the kickoff and the official instructions when they appear.","The bowl sets its own parking, so ASU’s regular-season game-day rules are not bowl guidance. The Cactus Bowl’s online A-to-Z guide still describes last year’s game at a different stadium; wait for the 2026 version.","Tickets are sold by the Fiesta Sports Foundation. A ride booking does not include a game ticket or a parking pass.")],My=[{question:"What is there to do on New Year’s Eve 2026 in Phoenix and Scottsdale?",answer:"Confirmed so far: Decadence Arizona on December 30 and 31 at Phoenix Raceway in Avondale, and the Fiesta Bowl on December 30 in Glendale. Scottsdale, Phoenix and Tempe have not published their 2026 New Year’s Eve events yet. Last year the official listings were resort, hotel, bar and venue parties, with no city-run celebration."},{question:"Where can I watch fireworks in Scottsdale on New Year’s Eve?",answer:"No public fireworks show is announced for New Year’s Eve 2026 as of September 24, 2026. Last year (December 31, 2025), the W Scottsdale’s ticketed 21+ New Year’s Eve party, 9 p.m. to 2 a.m., advertised a fireworks show, and Visit Phoenix’s 2025 listings also advertised a fireworks display at Allegra, The REMI Scottsdale. Check again in December."},{question:"What is Decadence Arizona?",answer:"A New Year’s festival at Phoenix Raceway on December 30 and 31, 2026, presented by Relentless Beats and Global Dance. It is strictly 18 and over with a government photo ID, and 21 and over for alcohol."},{question:"Where is Decadence Arizona?",answer:"At Phoenix Raceway, 7602 Jimmie Johnson Drive, Avondale, AZ 85323, off I-10 and Loop 202. The organizer says public transit is limited and recommends personal vehicles, event shuttles or rideshare."},{question:"What time does Decadence start and end?",answer:"Doors open at 6 p.m. and the event ends at 3 a.m., both nights. Wristbands scan once a day, so there is no same-day re-entry."},{question:"Where do you park or get dropped off at Decadence?",answer:"Lots open at 4 p.m. Free parking is Entry G, premium parking is Entry F and rideshare is Entry E; stay in the right lane until your entry. There is no overnight parking, and cars left behind are towed at the owner’s expense. The organizer has not published guidance for limos, party buses or charters."},{question:"Where and when is the Cactus Bowl?",answer:"Saturday, December 26, 2026, at 5:30 p.m. Arizona time, at ASU’s Mountain America Stadium in Tempe: Big Ten against Big 12. Parking and drop-off for the bowl are announced closer to the date."},{question:"Is Valley Metro free on New Year’s Eve 2026?",answer:"Not announced as of September 24, 2026. Last New Year’s Eve (2025), Valley Metro bus, rail and paratransit rides were free from 7 p.m. on December 31 to 2 a.m. or end of service on January 1. On New Year’s Day, light rail and streetcar run a Sunday schedule."}],Ry={path:uy,title:"New Year’s Eve 2026 in Scottsdale and Phoenix: Old Town, Decadence and the ride home",metaTitle:"New Year’s Eve Scottsdale & Decadence",description:"New Year’s Eve 2026 is Thursday, December 31. Old Town Scottsdale’s drop-off rules, Decadence Arizona at Phoenix Raceway on December 30 and 31, the Cactus Bowl on December 26, late transit, and a chauffeured ride home after midnight.",metaDescription:"Official dates, drop-off rules and late-night transit",lastUpdated:fh,lastUpdatedLabel:l(fh),eyebrow:"New Year’s Eve: Thursday, December 31, 2026",intro:"A New Year’s Eve ride from Scottsdale Sprinters starts with the night your group is actually having: an Old Town countdown, Decadence Arizona at Phoenix Raceway, or a dinner and the drive home. This guide uses only what the organizers, the City of Scottsdale and Valley Metro have published, labels last year’s details as last year’s, and says plainly what is still announced closer to the date.",sections:Fy,faqs:My,links:[{href:"/guides/fiesta-bowl-transportation",label:"Fiesta Bowl transportation guide"},{href:"/services/scottsdale-nightlife-transportation",label:"Scottsdale nightlife transportation"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Arizona party bus alcohol rules"},{href:`/fleet/${Ca}`,label:W(Ca)},{href:`/fleet/${bo}`,label:W(bo)},{href:`/fleet/${ir}`,label:W(ir)},{href:"/pricing",label:"Published hourly pricing"}],sources:Ey},gh="2026-09-26",Fd="2026-09-24",_r="ultra-luxury-party-sprinter-scottsdale",xy="maybach-jet-sprinter-scottsdale",yh="limo-sprinter-13-scottsdale",bh="limo-sprinter-16-scottsdale",Zn="party-bus-28-scottsdale",wh="executive-sprinter-scottsdale",ya=e=>n[e],Kn=e=>i[e],Gr=e=>h(r[e].hourlyRateCents),Dy=e=>r[e].minimumHours;function wa(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Iy=[{id:"state-farm-stadium",name:"State Farm Stadium",where:"Glendale",href:"/guides/venues/state-farm-stadium",items:sd},{id:"mortgage-matchup-center",name:"Mortgage Matchup Center",where:"downtown Phoenix",href:"/guides/venues/footprint-center",items:hd.items},{id:"desert-diamond-arena",name:"Desert Diamond Arena",where:"Glendale",href:"/guides/venues/desert-diamond-arena",items:jd.items},{id:"talking-stick-resort-amphitheatre",name:"Talking Stick Resort Amphitheatre",where:"west Phoenix",href:"/guides/venues/talking-stick-resort-amphitheatre",items:Qd.items}],Ia=Iy.flatMap(e=>Is({items:e.items.filter(t=>t.kind==="concert")}).map(t=>({item:t,venue:e}))).sort((e,t)=>(e.item.startsAt??e.item.date).localeCompare(t.item.startsAt??t.item.date)),Md=["January","February","March","April","May","June","July","August","September","October","November","December"],Ny={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function Wy(e){const t=ie(e);return`${Ny[Ns(e)]}, ${Md[t.month]} ${t.day}`}function Ly({item:e,venue:t}){const a=e.startsAt?`, ${fa(e.startsAt)}`:"",o=`${Wy(e.date)}: ${e.label} at ${t.name}${a}`;return o.endsWith(".")?o:`${o}.`}function Oy(e){return Ia.filter(t=>t.item.date.startsWith(e)).map(Ly)}const jn=[...new Set(Ia.map(e=>e.item.date.slice(0,7)))];function _y(e){const[t,a]=e.split("-").map(Number);return`${Md[a-1]} ${t}`}const Ur=e=>Ia.filter(t=>t.venue.id===e).length,Gy="https://azstatefair.com/concerts/",Uy="https://azstatefair.com/fair-directions-parking/",By=[{label:"State Farm Stadium, upcoming events",href:"https://www.statefarmstadium.com/events"},{label:"Mortgage Matchup Center, events (Live Nation listing)",href:"https://www.livenation.com/venue/KovZpZAE617A/mortgage-matchup-center-events"},{label:"Desert Diamond Arena, events and tickets",href:"https://www.desertdiamondarena.com/events-tickets/"},{label:"Talking Stick Resort Amphitheatre, shows",href:"https://www.talkingstickresortamphitheatre.com/"},{label:"Arizona Diamondbacks, Chase Field events (Hondo Rodeo Fest)",href:"https://www.mlb.com/dbacks/ballpark/events"},{label:"Arizona State Fair, 2026 Coliseum Concert Series",href:Gy},{label:"Arizona State Fair, directions and parking",href:Uy}];function Hy(){return[{label:"fall 2026",months:jn.filter(t=>t<="2026-11")},{label:"December 2026",months:jn.filter(t=>t==="2026-12")},{label:"2027",months:jn.filter(t=>t>="2027-01")}].filter(t=>t.months.length>0).map(t=>{const a=Ia.filter(d=>t.months.includes(d.item.date.slice(0,7))),o=[...new Set(a.map(d=>d.item.label))].slice(0,6);return wa(`Which concerts are in Phoenix in ${t.label}?`,`${a.length} shows are listed at the Valley’s big venues in ${t.label}, among them ${o.slice(0,-1).join(", ")} and ${o[o.length-1]}. Every date and start time below is the venue’s own, in Arizona time.`,...t.months.map(d=>`${_y(d)}: ${Oy(d).join(" ")}`))})}const zy=Xd.event.dates,qy=el.event.dates,Vy=[wa("What concerts are coming to Phoenix in 2026 and 2027?",`As the venues listed them on ${l(Fd)}, the Phoenix area has ${Ia.length} concerts on the calendar at its four big concert venues: ${Ur("talking-stick-resort-amphitheatre")} at Talking Stick Resort Amphitheatre, ${Ur("mortgage-matchup-center")} at Mortgage Matchup Center, ${Ur("desert-diamond-arena")} at Desert Diamond Arena and ${Ur("state-farm-stadium")} at State Farm Stadium, led by the Jonas Brothers on November 27, Trans-Siberian Orchestra on December 6, Hans Zimmer on March 30 and Harry Styles on April 2 and 3, 2027.`,`Chase Field adds the Hondo Rodeo Fest, a rodeo and a concert each night, on November 13 to 15, 2026. Two festivals follow in 2027: Innings Festival at Tempe Beach Park (${Ks(zy)}) and M3F at Steele Indian School Park (${Ks(qy)}).`,"Venues add shows through the year, so each venue’s own calendar is the final word before you book. The month-by-month list below prints every show from the venue lists our venue pages use, so a date here and a date on the venue page always match."),...Hy(),wa("Which concerts are at the Arizona State Fair in 2026?","Six, in the fair’s Coliseum Concert Series at Veterans Memorial Coliseum in Phoenix, each at 7 p.m.: Gin Blossoms on October 2, Becky G on October 9, All Time Low on October 10, The Offspring on October 16, Russell Dickerson on October 17 and Public Enemy on October 24, 2026.","The Coliseum is at 1826 West McDowell Road, on the fairgrounds. Each show is An Evening With the headliner, with no opening act, and every seat is reserved and includes fair admission.","The fair itself runs Thursday to Sunday, October 1 to November 1, 2026. Its official lots are the North Lot and the West Lot, which open 2 hours before the admission gates, plus limited reserved VIP parking in the North Lot; the fair says other lots nearby are privately owned. A free Park n’ Ride shuttle runs from Phoenix College, 1202 West Thomas Road, on Fridays, Saturdays and Sundays, with no shuttles on Thursdays, and its last shuttle back leaves the fairgrounds at 11 p.m.","Rideshare drivers enter on 19th Avenue at Encanto and drop off at the southwest corner of the West Lot, and McDowell Road closes between 15th and 19th Avenues after 9 p.m. on Fridays and Saturdays. A chauffeured group is dropped where fair staff direct and picked up at one agreed point after the encore. These Coliseum shows are not counted in the four-venue list above."),wa("Which Phoenix concert venue is where?","State Farm Stadium and Desert Diamond Arena face each other across Maryland Avenue in Glendale, in the Westgate Entertainment District off Loop 101. Mortgage Matchup Center, formerly Footprint Center, is in downtown Phoenix at 201 East Jefferson Street. Talking Stick Resort Amphitheatre is in west Phoenix, at 2121 North 83rd Avenue in Maryvale. Chase Field is downtown too, on the same street as Mortgage Matchup Center, at 401 East Jefferson Street.","That matters for the drive: from Old Town Scottsdale, the Glendale venues are about 36 minutes by Google’s typical drive time without event traffic, and downtown Phoenix is closer. Talking Stick Resort Amphitheatre is not the Talking Stick casino resort in Scottsdale; our venue page explains the difference."),wa("How does parking work at Phoenix concerts?","Every venue sells its own parking and none publishes a limo lane: Desert Diamond Arena’s lots open an hour before doors and take cards only; State Farm Stadium’s lots are cashless and it recommends buying ahead on SeatGeek; Mortgage Matchup Center points to nearby garages bought through ParkWhiz, with a drop-off curb on 3rd Street; Talking Stick Resort Amphitheatre has a Gate 3 drop-off.","Each venue page has the full parking answer, the drop-off point and the bag policy for that building. A chauffeured group skips all of it: dropped where staff direct, picked up at one agreed point, and nobody drives home."),wa("How do you get home from a Phoenix concert without driving?",`Book the ride both ways. By the hour, the vehicle is yours for the night: pickup, dinner, the show and the ride home, with the chauffeur nearby. Our concert pick is the ${ya(_r)}, ${Gr(_r)} an hour with a ${Dy(_r)}-hour minimum, seating ${Kn(_r)}.`,`A VIP night takes the ${ya(xy)}; a friend crew the ${ya(yh)} (${Gr(yh)} an hour) or the ${ya(bh)} (${Gr(bh)}); a big group the ${ya(Zn)} (${Kn(Zn)} seats, ${Gr(Zn)} an hour); and a family the ${ya(wh)} (${Kn(wh)} seats). Every rate prices the whole vehicle, before tax.`,`Tell the reservations team the show, the pickup address and the rider count at ${u} or ${p}. Rideshare works too, but after a sold-out show every rideshare guest waits at the same pickup point.`)],Yy=[{question:"What are the biggest concerts in Phoenix in 2026 and 2027?",answer:"Among the announced shows: the Jonas Brothers at Desert Diamond Arena on November 27, 2026, Trans-Siberian Orchestra at Mortgage Matchup Center on December 6, Hans Zimmer there on March 30, 2027, and Harry Styles at State Farm Stadium on April 2 and 3, 2027."},{question:"What concerts are at the Arizona State Fair in 2026?",answer:"Six Coliseum Concert Series shows at Veterans Memorial Coliseum, all at 7 p.m.: Gin Blossoms (October 2), Becky G (October 9), All Time Low (October 10), The Offspring (October 16), Russell Dickerson (October 17) and Public Enemy (October 24). Every seat is reserved and includes fair admission."},{question:"Which concert venues are in Glendale?",answer:"State Farm Stadium and Desert Diamond Arena, across Maryland Avenue from each other in the Westgate Entertainment District."},{question:"Is Mortgage Matchup Center the same as Footprint Center?",answer:"Yes. Mortgage Matchup Center is the new name of the downtown Phoenix arena formerly called Footprint Center, at 201 East Jefferson Street."},{question:"Where is Talking Stick Resort Amphitheatre?",answer:"At 2121 North 83rd Avenue in the Maryvale area of west Phoenix. It was formerly Ak-Chin Pavilion, and it is not the Talking Stick casino resort in Scottsdale."},{question:"How do you get to a Phoenix concert without parking?",answer:"Book a chauffeured ride: the group is dropped where venue staff direct, picked up at one agreed point after the show, and nobody drives home. Every venue page lists its drop-off."}],Jy={path:fr,title:"Phoenix concerts 2026–27: every big show by venue, with parking and a ride",metaTitle:"Phoenix Concerts 2026–27 & Rides",description:"Every announced concert at State Farm Stadium, Mortgage Matchup Center, Desert Diamond Arena and Talking Stick Resort Amphitheatre, month by month, with each venue’s parking and drop-off and a chauffeured ride so nobody drives.",metaDescription:"Every big show by date and venue, parking and the ride home",lastUpdated:gh,lastUpdatedLabel:l(gh),eyebrow:"Glendale · Downtown Phoenix · Fall 2026 to summer 2027",intro:`Scottsdale Sprinters’ short answer: ${Ia.length} concerts are announced at the Phoenix area’s four big concert venues, as the venues listed them on ${l(Fd)}, led by the Jonas Brothers on November 27, Trans-Siberian Orchestra on December 6, Hans Zimmer on March 30 and Harry Styles on April 2 and 3, 2027. Below is every show by month and venue, how parking works at each, and a chauffeured ride so the whole group arrives together and nobody drives home.`,sections:Vy,faqs:Yy,links:[{href:Us,label:"Jonas Brothers in Phoenix, November 27, 2026"},{href:Hs,label:"Trans-Siberian Orchestra in Phoenix, December 6, 2026"},{href:zs,label:"Hans Zimmer Live in Phoenix, March 30, 2027"},{href:Bs,label:"Harry Styles in Phoenix, April 2–3, 2027"},{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking and the Black Lot"},{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center parking and drop-off"},{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking and shows"},{href:"/guides/venues/talking-stick-resort-amphitheatre",label:"Talking Stick Resort Amphitheatre parking and Gate 3"},{href:"/guides/venues/chase-field",label:"Chase Field parking and events"},{href:"/guides/innings-festival-transportation",label:"Innings Festival 2027 rides"},{href:"/guides/m3f-festival-transportation",label:"M3F 2027 rides"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/guides/country-thunder-transportation",label:"Country Thunder Arizona, April 2027"}],sources:By},vh="2026-09-26",Zy="/guides/phoenix-raceway-nascar-transportation",St="maybach-jet-sprinter-scottsdale",At="ultra-luxury-party-sprinter-scottsdale",kh="maybach-shuttle-sprinter-8",Sh="premium-suv-scottsdale",Ah="limo-sprinter-13-scottsdale",$t="limo-sprinter-16-scottsdale",Br="party-bus-28-scottsdale",Th="executive-sprinter-scottsdale",$h="executive-mini-bus-26-scottsdale",Ch="executive-luxury-bus-29-scottsdale",Qn="motorcoach-56",L=e=>n[e],j=e=>i[e],Xn=e=>h(r[e].hourlyRateCents);function Ky(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}const Hr=10,Ph=9,Eh=j($t),jy="https://www.phoenixraceway.com/events/spring-cup-race/",Qy="https://www.phoenixraceway.com/schedule/",Xy="https://www.phoenixraceway.com/parkingdirections/",eb="https://www.phoenixraceway.com/faqs/",tb="https://www.phoenixraceway.com/phx-weekend-schedule/",ab="https://www.phoenixraceway.com/hospitality/",rb="https://www.phoenixraceway.com/about-phoenix-raceway/",ob="https://speedwaymedia.com/2026/08/05/phoenix-raceway-unveils-power-packed-2027-race-schedule/",nb=[{label:"Phoenix Raceway: the 2027 spring NASCAR weekend, days and tickets",href:jy},{label:"Phoenix Raceway event calendar: the October 2026 races and the spring and fall 2027 dates",href:Qy},{label:"Phoenix Raceway parking and directions: free parking, entries and routes",href:Xy},{label:"Phoenix Raceway FAQs and gate policy",href:eb},{label:"Phoenix Raceway weekend schedule (the October 2026 race weekend)",href:tb},{label:"Phoenix Raceway spring hospitality: suites, Ally Curve and The Perch",href:ab},{label:"Phoenix Raceway track facts",href:rb},{label:"Phoenix Raceway 2027 schedule release (August 5, 2026)",href:ob}];function De(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Fh=[["Old Town Scottsdale","31.1","about 44 minutes"],["The Phoenician","30.5","about 43 minutes"],["Phoenix Sky Harbor (PHX)","26.0","about 35 minutes"],["Kierland / Scottsdale Quarter","39.1","about 53 minutes"],["Scottsdale Airport (SDL)","39.4","about 52 minutes"],["Fairmont Scottsdale Princess","43.3","about 52 minutes"]],sb=[De("Where do you park at Phoenix Raceway, and is parking free?","Parking is free for ticket holders: with no pass, follow the signs from I-10 to the free general lots at Entries J, K and L. Paid Premium, El Mirage and Preferred passes park closer to the gates. With a chauffeured ride from Scottsdale, nobody in the group drives the 31 miles or parks.","The track says it plainly: Phoenix Raceway offers free general parking to ticket holders. Without a parking pass, follow the directional signage from I-10 to the free lots on site; the general-admission entries are J, K and L. A parking tram runs along Kevin Harvick Road from Cotton Lane to Blue 6, and a camping shuttle runs the Mountain Road route from Gate 2 to Dunes North 5.","Paid passes, sold by the track for the spring and fall weekends, buy distance. Premium Parking is a reserved spot, the closest parking to the gates, by Gates 4 and 5 at Entry E. El Mirage Parking is closest to the ticket gates, at Entry F. Preferred Parking is a reserved spot on asphalt, entered through Entry G. Suite guests park at Entry C. Pass holders follow the map printed on the back of their pass.","Accessible parking: guests with a state-issued plate or placard exit I-10 at Avondale Boulevard, Exit 131, head south and follow the blue route signs. Spaces are first come, first served until the lots fill, and then traffic control directs cars to general parking, so the track advises arriving early.","The chauffeured alternative: we pick the group up at the hotel or home in Scottsdale, drive the approach and unload where race-day traffic staff direct. Nobody hunts for a lot, rides a tram back after the checkered flag or drives the interstate home after a long day in the sun. No lot or lane is published for hired vehicles, so the reservations team confirms the current instruction before race day rather than promising one."),De("Where do Uber, Lyft and drop-offs go at Phoenix Raceway?","At Phoenix Raceway, 7602 Jimmie Johnson Drive in Avondale, rideshares and taxis use Entry E, the entry the track lists for Uber, Lyft and taxis, shared with Premium and Ally Curve parking. No entry is published for limos, party buses or charters, so a chauffeured vehicle unloads where race-day traffic staff direct.","Entry E is the only drop-off the track names for a hired ride, and it names rideshare apps and taxis, not limos or buses. Suite guests park at Entry C, and The Perch, a hospitality area, is sold with the convenience of bringing in your own motor coach. None of that is a privilege a chauffeured Sprinter or coach can claim, so this page promises no gate, lane or curb.","On the day, the chauffeur follows the signs from I-10 and the traffic staff, unloads the group where directed, and waits where staff assign. If the track publishes a 2027 instruction for hired vehicles, the reservations team passes it on before race day.","For the ride home, name one meeting point and one transportation lead before the group goes in. The curb you arrived at may not be where a vehicle can wait at the end of the race, and phones struggle when a grandstand empties at once. The lead counts heads, confirms the vehicle’s spot with the chauffeur and walks the group there together."),{...De("How far is Phoenix Raceway from Scottsdale, and which way do you drive?","Phoenix Raceway is in Avondale, about 31 miles and 44 minutes from Old Town Scottsdale by I-10 West without race traffic, and about 53 minutes from Kierland. The track sits about 6 miles south of I-10 at Exit 131, Avondale Boulevard; drivers headed for general parking use Exit 126 or 128.",`Measured with Google Directions on September 24, 2026, driving, with no race traffic: ${Fh.map(([e,t,a])=>`${e}, ${t} miles, ${a}`).join("; ")}. Every route runs on I-10 West.`,"The track’s own routes, for guests driving themselves: on I-10 West, or coming down I-17 or Loop 101 to I-10 West, general parking uses Exit 126 (Estrella Parkway) or Exit 128 (Litchfield Road), and parking-pass and ADA traffic uses Exit 131 (Avondale Boulevard). From Loop 202 North, general parking uses Exit 76 (Buckeye Road) and passes use Exit 73 (Broadway Road). ADOT’s traveler line is 511, or az511.com.","Race traffic is not normal traffic. Those minutes are Google’s typical times, not race-day times, so the chauffeur builds the buffer into the pickup: the drive, the approach to the lots, screening at the gate and the walk to the seats. The return is a window rather than a fixed minute: the race’s length, the crowd and the lots decide it."),table:{head:["From","Miles","Typical drive"],rows:Fh.map(([e,t,a])=>[e,t,a])}},{...De("When is NASCAR at Phoenix Raceway in 2027?","The spring race weekend runs Friday, March 12 to Sunday, March 14, 2027. Friday is the ARCA Menards Series race, Saturday, March 13 puts IndyCar and the NASCAR O’Reilly Auto Parts Series on one card, and the NASCAR Cup Series races on Sunday, March 14. Start times are announced closer to the date.","The track’s calendar lists the 2027 spring weekend as March 12 to 14, with times to be decided, and its schedule release says the full 2027 NASCAR and NTT INDYCAR SERIES schedules, with broadcast details and times, will be released at a later date. Tickets, hospitality and camping are already on sale from the track: Sunday only, Saturday only, or a 2-day package for Saturday and Sunday.","NASCAR comes back in the fall: the track lists its 2027 fall weekend as October 22 to 24, with the Truck Series on Friday, the O’Reilly Auto Parts Series and ARCA Menards Series West on Saturday, and the Cup Series race on Sunday, October 24.","For a ride, pick the day first: Sunday is the Cup race, Saturday puts 2 races on one card, and Friday is the ARCA race. A group staying for the whole weekend books each day as its own ride, so no vehicle sits idle overnight in Avondale."),table:{head:["Day","Date","On track"],rows:[["Friday","March 12, 2027","ARCA Menards Series"],["Saturday","March 13, 2027","IndyCar and the NASCAR O’Reilly Auto Parts Series"],["Sunday","March 14, 2027","NASCAR Cup Series"]]}},De("Is there a NASCAR race at Phoenix Raceway in October 2026?","Yes. On the track’s October 2026 calendar, the NASCAR Cup Series Freeway Insurance 500 runs at Phoenix Raceway on Sunday, October 18, at 12:00 p.m. Arizona time. In the same October 2026 weekend, the Truck Series races on Friday, October 16, and the O’Reilly Auto Parts Series Timberland Pro 200 on Saturday, October 17, both at 4:30 p.m.","The October 2026 weekend starts downtown: Fan Fest, powered by Freeway Insurance, runs on Thursday, October 15, from 4:00 to 7:00 p.m. at Heritage Square and Science Park in downtown Phoenix. The gate and parking-lot times quoted in the next answer are the track’s own schedule for this same weekend.","Parking and drop-off work as the answers above describe, from the track’s standing parking page: free general parking at Entries J, K and L, and rideshares at Entry E. For a chauffeured Cup Sunday, tell the reservations team the seats, the rider count and whether the group wants the pre-race, and the ride is set around the race start."),De("What time do the gates open at Phoenix Raceway?","2027 gate and race times are announced closer to the date. On the track’s most recent published schedule, for the October 2026 weekend, Sunday’s lots open at 6:00 a.m., the gates at 8:00 a.m. and the Cup race starts at 12:00 p.m.; Saturday’s lots open at 8:00 a.m. and the gates at 10:00 a.m.","The same October 2026 schedule runs the parking trams from 6:00 a.m. on Sunday until an hour after the race, and on Friday opens the lots at 9:30 a.m. and the gates at 11:30 a.m. It is the track’s schedule for a different weekend, printed here only to show how early a race day starts; the March 2027 times replace it when the track publishes them.","What that means for a pickup: a group that wants the pre-race, a meal and its seats before the green flag leaves Scottsdale in the morning, well before the start. Your chauffeur sets the ready time from the published 2027 schedule once it is out, and from your seats and plans until then.","The Infield Experience, the suites and Ally Curve open with the spectator gates on that schedule. On race day, pit road access for Infield Experience pass holders ends one hour before the race, by the track’s own FAQ."),De("How many hours should you book for a race day at Phoenix Raceway?",`Plan about ${Hr} hours for Cup Sunday and ${Ph} for Saturday’s two-race card, from pickup in Scottsdale to drop-off at home. The drive is about 45 minutes each way from Old Town before race traffic, the gates open hours before the start, and after the checkered flag the lots take time to clear, so the vehicle waits with the group.`,`Where the ${Hr} hours go on a Sunday, with the track’s most recent published race day as the model: about 45 minutes out from Old Town, more with race traffic; arriving before the gates so the group is in its seats well ahead of the green flag; the race itself, which runs for hours; and the wait after the checkered flag while the lots empty. Booked by the hour, the vehicle is yours for the whole block: it waits while the lots clear instead of the group standing in them, and nobody drives the interstate home after a day in the sun.`,`Saturday is shorter on the clock but puts 2 races on one card, IndyCar and the O’Reilly Auto Parts Series; ${Ph} hours covers both and the drive. A group that wants only one race, or a drop-off and a set pickup, books fewer hours: tell the reservations team the plan and the quote prices it.`,"If the race runs long, from caution laps or a weather delay, your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.","The ready-made packages on this page are built on those hours, and each prints the engine’s own total, including any hour the rate ladder gives free."),De("Which vehicle fits a race-day group?",`VIP and infield guests ride the ${L(St)} or the ${L(At)}, race-day crews take a Limo Party Sprinter or the ${L(Br)} for up to ${j(Br)}, and suite and client groups take an Executive Sprinter or an executive coach, up to the ${L(Qn)}.`,`VIP and infield guests: the ${L(St)} leads the VIP row, ${j(St)} seats with Maybach massage recliners and a wet bar. The ${L(At)}, our flagship for race weekend, seats ${j(At)} in a fiber-optic lounge with a wet bar for the ride home after the checkered flag. The ${L(kh)} seats ${j(kh)} in custom Maybach seats, and the ${L(Sh)} carries a couple or a small VIP party of up to ${j(Sh)}.`,`Race-day crews: the ${L(Ah)} and the ${L($t)} are limo lounges on wheels for ${j(Ah)} and ${j($t)}, and the ${L(Br)} puts ${j(Br)} on limo seating with two wet bars when the whole crew comes. These are party rides for a group out to celebrate; we never send one as a corporate client vehicle.`,`Suites and client groups: the ${L(Th)} seats ${j(Th)} in reclining leather with room for bags, the ${L($h)} (${j($h)} seats) and the ${L(Ch)} (${j(Ch)} seats) carry a client list or a company outing in one vehicle, and the ${L(Qn)} takes up to ${j(Qn)} when the whole company goes to the race.`,"Count riders for each direction. A morning arrival and the ride home after the race are often different lists. Anyone leaving with another group comes off the return manifest before seats are assigned; “we will decide at the track” is not a count the chauffeur can plan around when the lots are emptying."),De("What can you bring into Phoenix Raceway?","Each guest may bring 2 bags up to 18 by 18 by 14 inches and 1 soft-sided cooler up to 14 by 14 by 14 inches, with ice and sealed food or drinks. Alcohol, glass, hard or foam coolers, collapsible chairs and wagons are not allowed through the grandstand gates, and the track is cashless.","Hillside guests, general admission on Sunday only, sit on the hill with no seats: bring a chair or blanket, and a hard or soft cooler is allowed there without glass or alcohol. Anything bigger than the gate limits stays on the vehicle, which is one reason to book it by the hour: the extra cooler, the spare layers and the bags ride back with the group.","On the ride itself, guests 21 and over may bring their own drinks aboard: Arizona’s open-container law, A.R.S. § 4-251, exempts passengers in a vehicle for hire. We do not sell alcohol, the chauffeur never drinks, and if anyone on board is under 21 the vehicle is dry for everyone. Nothing opened on board goes through the gates.","Write the day plan in 5 lines: ready time, the entry you are heading for, the meeting point, one transportation lead and the ride home. The ready time is when guests are at the pickup point with tickets on their phones, not when they start getting ready. Tell the reservations team about mobility needs when you book, so the pickup and the unload suit the rider.",`During the final 48 hours, verify addresses, contact numbers and the track’s newest parking and entry notes, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${u} or ${p}.`),De("How is Phoenix Raceway transportation priced per person?",`For ${Eh} race fans sharing the ${L($t)} for ${Hr} billed hours, the published ${Xn($t)}-per-hour rate comes to about ${Ky($t,Hr,Eh)} per person before tax for the whole shared race day; the price changes with the vehicle, the hours, the day and the confirmed plan.`,"That example is arithmetic, not a flat race-day fare: the hourly rate times the billed hours, divided by the riders. If only ten people ride, divide by ten. A day that waits through the race and the lots needs more hours than a drop-off and a set pickup, so describe the real pattern and let the quote price it.",`The same arithmetic on the ${L(At)} uses its own rate of ${Xn(At)} an hour and its ${j(At)} seats; on the ${L(St)}, ${Xn(St)} an hour for ${j(St)}. The ready-made packages on this page print the engine’s own total for their hours and extras, including any hour the rate ladder gives free.`,"One person collects the shares and one person owns the manifest. Neither job belongs to the chauffeur, and neither should wait until the group is standing at the curb after the race.")],ib=[{question:"When is the next NASCAR race in Phoenix?",answer:"Sunday, October 18, 2026: the NASCAR Cup Series Freeway Insurance 500 at Phoenix Raceway. On the track’s October 2026 calendar it starts at 12:00 p.m. Arizona time, and the rest of the October 2026 card, the Truck Series on Friday, October 16 and the O’Reilly Auto Parts Series on Saturday, October 17, starts at 4:30 p.m. both days. After that, the spring weekend is March 12 to 14, 2027."},{question:"What time is the NASCAR race at Phoenix?",answer:"On the track’s October 2026 calendar, the Cup Series race on Sunday, October 18 starts at 12:00 p.m. Arizona time. Start times for the March 12 to 14, 2027 weekend are not published yet; the track says they come later."},{question:"When is NASCAR in Phoenix in 2027?",answer:"Friday, March 12 to Sunday, March 14, 2027, at Phoenix Raceway in Avondale: the ARCA race on Friday, IndyCar and the NASCAR O’Reilly Auto Parts Series on Saturday, and the NASCAR Cup Series on Sunday. The fall weekend is October 22 to 24, 2027."},{question:"Is parking free at Phoenix Raceway?",answer:"Yes. General parking is free for ticket holders: follow the signs from I-10 to Entries J, K and L. Premium, El Mirage and Preferred passes, sold by the track, park closer to the gates. With a chauffeured ride, nobody in the group drives or parks."},{question:"Where do Uber and Lyft drop off at Phoenix Raceway?",answer:"At Entry E, which the track lists for rideshare (Uber, Lyft and taxis), Premium and Ally Curve parking."},{question:"Can a limo or party bus drop off at the Phoenix Raceway gate?",answer:"No entry or lane for limos, party buses or charters is published; Entry E is listed for rideshares and taxis. Our chauffeur unloads where race-day traffic staff direct and follows any instruction the track publishes for 2027."},{question:"What time do gates open at Phoenix Raceway?",answer:"The 2027 times are announced closer to the date. On the track’s October 2026 schedule, Sunday’s lots open at 6:00 a.m. and the gates at 8:00 a.m., with the Cup race at 12:00 p.m."},{question:"How far is Phoenix Raceway from Scottsdale?",answer:"About 31 miles and 44 minutes from Old Town Scottsdale by I-10 West without race traffic (Google Directions, measured September 24, 2026). The track is about six miles south of I-10 at Exit 131, Avondale Boulevard."},{question:"How long should I book a Sprinter for a NASCAR race day?",answer:"About 10 hours for Cup Sunday from Scottsdale, and about 9 for Saturday’s two races: the drive each way, arriving before the gates, the race, and the wait while the lots clear. If the race runs long, your chauffeur waits and extra time is billed hourly."},{question:"What is the Phoenix Raceway bag policy?",answer:"Up to 2 bags per person, each no larger than 18 by 18 by 14 inches, plus 1 soft-sided cooler up to 14 by 14 by 14 inches. No alcohol, glass, or hard or foam coolers through the grandstand gates."},{question:"Is IndyCar racing at Phoenix in 2027?",answer:"Yes. The NTT INDYCAR SERIES races at Phoenix Raceway on Saturday, March 13, 2027, on the same card as the NASCAR O’Reilly Auto Parts Series. The start time is announced closer to the date."},{question:"How long is Phoenix Raceway?",answer:"Phoenix Raceway is a 1-mile oval with an asphalt surface and banking from 0 to 11 degrees, by the track’s own figures."}],hb={path:Zy,title:"Phoenix Raceway 2027: NASCAR and IndyCar parking and rides",metaTitle:"Phoenix Raceway 2027: Parking & Rides",description:"NASCAR and IndyCar race at Phoenix Raceway March 12–14, 2027. The official dates, free and paid parking, the rideshare entry, the drive from Scottsdale, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"March 12–14 dates, free parking, the rideshare entry, or a chauffeured ride",lastUpdated:vh,lastUpdatedLabel:l(vh),eyebrow:"Official dates: March 12–14, 2027",intro:"A race-day ride from Scottsdale Sprinters starts with the day your group is having: Cup Sunday with the crew, IndyCar Saturday, a client day in the suites or a VIP day in the infield. This guide uses only what Phoenix Raceway publishes, labels the October 2026 race-day schedule as October’s, and says plainly what is announced closer to the date. Scottsdale Sprinters is independent and not affiliated with Phoenix Raceway, NASCAR or INDYCAR.",sections:sb,faqs:ib,links:[{href:"/services/corporate-transportation-scottsdale",label:"Corporate transportation for client days"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Party bus alcohol laws in Arizona"},{href:`/fleet/${At}`,label:L(At)},{href:`/fleet/${St}`,label:L(St)},{href:`/fleet/${$t}`,label:L($t)},{href:"/pricing",label:"Published hourly pricing"}],sources:nb},Mh="2026-09-27",db="https://www.runrocknroll.com/events/arizona",lb="https://www.runrocknroll.com/events/arizona/schedule",cb="https://www.runrocknroll.com/events/arizona/course-overview",ub="https://www.runrocknroll.com/events/arizona/transportation",pb="https://www.runrocknroll.com/events/arizona/health-fitness",fb="https://www.runrocknroll.com/events/arizona/faqs",mb="https://www.runrocknroll.com/events/arizona/traffic-impact",gb="https://www.runrocknroll.com/events/arizona/kids-rock",yb="https://www.runrocknroll.com/events/arizona/accommodations",zr={runners:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],clubs:["executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale"]},bb=[...zr.runners,...zr.crews,...zr.vip,...zr.clubs].filter(ae),wb=bb.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),fe="executive-sprinter-scottsdale",vb="executive-white-sprinter-scottsdale",ao="limo-sprinter-13-scottsdale",kb="limo-sprinter-16-scottsdale",Wt="party-bus-28-scottsdale",Te="maybach-jet-sprinter-scottsdale",Sb="ultra-luxury-party-sprinter-scottsdale",es="maybach-shuttle-sprinter-8",ts="premium-suv-scottsdale",Rh="executive-mini-bus-26-scottsdale",xh="executive-luxury-bus-29-scottsdale",m=e=>n[e],Ie=e=>i[e];function qr(e){return h(r[e].hourlyRateCents)}function Dh(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function Ne(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ab=[{label:"Rock ’n’ Roll Arizona: January 16 and 17, 2027, distances and course summary",href:db},{label:"Rock ’n’ Roll Arizona: 2027 event schedule",href:lb},{label:"Rock ’n’ Roll Arizona: course overview (start and finish lines, time limits)",href:cb},{label:"Rock ’n’ Roll Arizona: parking and transportation (drop-off, light rail)",href:ub},{label:"Rock ’n’ Roll Arizona: Health & Fitness Expo",href:pb},{label:"Rock ’n’ Roll Arizona: FAQs (age limits, Gear Check, Secure Zone)",href:fb},{label:"Rock ’n’ Roll Arizona: traffic impact and road closures",href:mb},{label:"Rock ’n’ Roll Arizona: KiDS ROCK",href:gb},{label:"Rock ’n’ Roll Arizona: official race hotels",href:yb}],Tb=[Ne("When is Rock ’n’ Roll Arizona 2027, and which race runs on which day?","Rock ’n’ Roll Arizona 2027 runs Saturday, January 16 and Sunday, January 17, 2027, in Tempe: the 5K starts at 8 a.m. on Saturday, and on Sunday the 10K starts at 7 a.m. and the half marathon follows; there is no full marathon on the 2027 program, and every race finishes by Tempe Beach Park.","The organiser lists three distances for 2027: the Half Marathon, the 10K and the 5K. Its half-marathon start time differs between two of its own pages: 7:30 a.m. on the course overview and 7:40 a.m. on the event schedule, and both say times are subject to change. Check the organiser’s final information before you set the pickup.","The weekend has run in the Valley for more than 20 years, and the organiser calls it a tri-city tour: the courses take in Tempe, Scottsdale and Phoenix, past the red sandstone formations of Papago Park, and end at the Finish Line Festival at Tempe Beach Park. The average air temperature it prints for race weekend is 68°F."),Ne("Where do runners get dropped off, and where do you park for Rock ’n’ Roll Arizona?","Sunday half-marathon and 10K runners are dropped off on Farmer Avenue just south of 5th Street, and Saturday 5K runners at 5th Street and Farmer; drivers who park use ASU Lot 59 on Sunday, at the southwest corner of Rio Salado Parkway and Packard Drive, or the ASU covered parking structures for the 5K, and the organiser recommends reserving a spot in advance.","The organiser prints directions to the Farmer Avenue drop-off from the 202, from I-10 and from Tempe or the 60, and notes that taxis and ride-share apps serve Phoenix, Tempe and Scottsdale on race weekend. It prints the parking rates on its own page; we do not repeat them here.","With a chauffeur there is no lot at all: we drop the runners where the organiser and race staff direct, take the cheer crew to the finish, and keep the dry layers and the post-race bag in the vehicle. Nobody hunts for a space before dawn."),Ne("Where do the Rock ’n’ Roll Arizona races start and finish?","The half marathon starts on S. Mill Avenue at 3rd Street in Tempe and the 10K on N. Mill Avenue north of E. Curry Road, and both finish on W. Rio Salado Parkway by Tempe Beach Park; the 5K starts and finishes at Tempe Beach Park, 80 West Rio Salado Parkway, by the Mill Avenue Bridge.","The organiser gives the half marathon a 4-hour time limit, the 10K 2 hours and the 5K 1 hour, and notes that courses and times are subject to change. Its course maps are on the course overview page.","Music lines the way: the organiser plans 13 entertainment and motivational stops on the half-marathon course and 10 on the 10K, with bands, DJs and cheer stations between the start and the finish."),Ne("Can you take light rail to Rock ’n’ Roll Arizona, and which roads close?","Yes: on Sunday Valley Metro Rail runs its Sunday schedule with extra trains before the races and after the finish; the closest station to the start is University Drive/Rural and the closest to the finish is Mill Ave/3rd St, and every rider, runners included, pays the fare; road closures for 2027 are not posted yet.","The organiser’s traffic page says course and road-closure information will be posted as it becomes available, and suggests the Waze app to avoid race-day closures. We write no street or time here until it does.","Flying in? The organiser points out that the free PHX Sky Train runs from the Sky Harbor terminals to the 44th Street station, which connects to Valley Metro Rail. A chauffeured group skips the transfers: one pickup at the airport or the hotel, one ride to the start."),Ne("Where and when is the Rock ’n’ Roll Arizona expo and packet pickup?","The Health & Fitness Expo is at Tempe Beach Park and is free and open to the public; it opens at 1 p.m. on Friday, January 15 and closes at 7 p.m., and on Saturday, January 16 it opens at 10 a.m. and closes at 5 p.m.; every runner must collect a race number, gear bag and T-shirt there, with photo ID.","Packets are handed out only at the expo, so plan the expo stop before race morning. The organiser adds a bonus Remix Challenge medal for runners who finish two distances over race weekend, the Saturday 5K and a Sunday race.","The organiser’s schedule, its race-week page and its expo page do not print the same expo dates; the schedule and race-week pages say Friday, January 15 and Saturday, January 16, and the hours on all three agree. An expo run fits a short booking: the hotel, the expo and back."),Ne("Where do family and friends meet runners at the finish?","Just outside the Secure Zone: after the finish line runners enter a fenced Secure Zone for participants only, collect water and the finisher’s medal, then leave it to reclaim a gear bag and join family and friends at the Finish Line Festival at Tempe Beach Park, where the Encore Entertainment starts at 8:30 a.m. on Sunday.","Once runners leave the Secure Zone they cannot go back in, and gear bags must be claimed before the Finish Line Festival closes on race day. The organiser has not announced the 2027 Encore line-up yet.","The organiser prints no age rule, bag rule or closing time for the festival itself on its pages. Agree a meeting point near the park and a pickup time with your chauffeur in advance; the vehicle is there when the group is ready."),Ne("Can kids run Rock ’n’ Roll Arizona, and is it good for families?",`Yes, from age 8: the organiser’s minimum ages are 8 for the 5K, 10 for the 10K and 12 for the half marathon, and there is no KiDS ROCK race in 2027, the organiser says; strollers and dogs are not allowed on any part of the course; for a family ride, our house rule applies: ${Ft}`,"An adult completes the registration for anyone under 18. Families who come to cheer meet their runner just outside the Secure Zone.","Families and runners ride the Executive Sprinters, never a party unit, and no family package carries a drink service. We sell no alcohol."),Ne("What does a chauffeured race morning cost?",`A race morning is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${m(fe)} is ${qr(fe)}/hr and seats ${Ie(fe)}, the ${m(ao)} is ${qr(ao)}/hr, and the ${m(Te)} is ${qr(Te)}/hr; race entry is sold by the organiser, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${Ie(fe)} riders in the ${m(fe)} for 5 hours is about ${Dh(fe,5,Ie(fe))} each before tax. ${Ie(Wt)} riders sharing the ${m(Wt)} for 5 hours at ${qr(Wt)}/hr is about ${Dh(Wt,5,Ie(Wt))} each. That is arithmetic on the published rates, not a flat race-day fare.`,"The hours run from the pickup at your hotel or home to the drop-off at the end of the morning, and the vehicle waits nearby in between, so the morning is one booking, not two rides. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books."),Ne("Which vehicle fits a Rock ’n’ Roll Arizona group?",`Runners and families lead with the ${m(fe)}, our pick for race morning, or the white Executive Sprinter, alcohol-free; friends staying for the Finish Line Festival ride a Limo Party Sprinter or the ${Ie(Wt)}-seat party bus; a run-cation couple or VIP group takes the ${m(Te)}; running clubs overflow onto the ${m(Rh)} or the ${m(xh)}.`,`The table uses current published names, seated capacities, hourly rates and minimums, in four groups. Runners and families: the ${m(fe)} and the ${m(vb)}. Finish-festival crews: the ${m(ao)}, the ${m(kb)} and the ${m(Wt)}. VIP: the ${m(Te)}, the ${m(Sb)}, the ${m(es)} and the ${m(ts)}. Running clubs and teams: the ${m(Rh)} and the ${m(xh)}.`,`A VIP party larger than the ${m(Te)} rides in two vehicles, one booking each for the same day and times: the ${m(Te)} with the ${m(es)} seats ${Ie(Te)+Ie(es)}, and with the ${m(ts)} it seats ${Ie(Te)+Ie(ts)}.`),Ne("How does a chauffeured race morning work, and how far ahead should you book?","Your chauffeur picks the runners up before dawn at the hotel or home, drops them where race staff direct, takes the cheer crew to Tempe Beach Park, waits nearby through the Finish Line Festival and drives everyone home; availability varies by day and vehicle, so no fixed lead time applies; send the race day and the group early.","The first request needs the race day, the pickup address, the runners’ start, a likely passenger count and which group is riding: runners and family, a finish-festival crew, or a running club. The organiser lists official race hotels in Tempe, among them the Omni Tempe Hotel at ASU and Tempe Mission Palms; we pick up from any hotel or home.",`During the final 48 hours, confirm addresses, phone numbers and the meeting point for the ride home. Reach the reservations team at ${u} or ${p}.`)],$b=[{question:"When is the Rock ’n’ Roll marathon in Phoenix in 2027?",answer:"Rock ’n’ Roll Arizona is January 16 and 17, 2027, in Tempe: the 5K on Saturday, the 10K and half marathon on Sunday. The 2027 program has no full marathon."},{question:"What time does the Rock ’n’ Roll Arizona half marathon start?",answer:"The organiser’s course page says 7:30 a.m. and its schedule says 7:40 a.m. on Sunday, January 17, on S. Mill Avenue at 3rd Street. The 10K starts at 7 a.m.; the 5K at 8 a.m. on Saturday."},{question:"Where does Rock ’n’ Roll Arizona finish?",answer:"Every race finishes by Tempe Beach Park on W. Rio Salado Parkway, where the Finish Line Festival is held."},{question:"Where is the runner drop-off for Rock ’n’ Roll Arizona?",answer:"On Sunday, Farmer Avenue just south of 5th Street. For the Saturday 5K, 5th Street and Farmer. A chauffeured group is dropped where race staff direct and skips parking."},{question:"Where is packet pickup for Rock ’n’ Roll Arizona?",answer:"At the Health & Fitness Expo at Tempe Beach Park, free and open to the public, on Friday, January 15 from 1 p.m. and Saturday, January 16 from 10 a.m. Runners need photo ID."},{question:"Can spectators ride light rail to the finish?",answer:"Yes. Mill Ave/3rd St is the organiser’s closest station to the finish, and every rider pays the Valley Metro fare."},{question:"Is there a kids race at Rock ’n’ Roll Arizona 2027?",answer:"No. The organiser says KiDS ROCK will not occur in 2027. The youngest runners, from age 8, can enter the 5K."},{question:"Can you hire a Sprinter or limo for Rock ’n’ Roll Arizona?",answer:`Yes. The ${m(fe)}, the Limo Party Sprinters and the ${m(Te)} are booked by the hour, pickup to drop-off, and wait nearby for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],Cb={path:"/guides/rock-n-roll-arizona-marathon",title:"Rock ’n’ Roll Arizona 2027: race days, start lines, drop-off and a chauffeured race morning",metaTitle:"Rock ’n’ Roll Arizona 2027 Race Guide",description:"Rock ’n’ Roll Arizona, January 16 and 17, 2027 in Tempe: which race runs which day, the half marathon, 10K and 5K start and finish lines, runner drop-off, parking and light rail, the expo, meeting runners at the Finish Line Festival, and a chauffeured race morning.",metaDescription:"Rock ’n’ Roll Arizona, Jan 16–17, 2027: race days, start lines, drop-off, light rail, the expo and a chauffeured race morning",lastUpdated:Mh,lastUpdatedLabel:l(Mh),eyebrow:"Half marathon, 10K and 5K · January 16 and 17, 2027",intro:`A race morning with Scottsdale Sprinters starts with the organiser’s own schedule, the day you run and a rider count. Runners and families lead with the ${m(fe)}, alcohol-free; friends staying for the Finish Line Festival ride a Limo Party Sprinter or the party bus; a run-cation takes the ${m(Te)}. This guide uses only facts the Rock ’n’ Roll Arizona organiser publishes, and turns the weekend into a written pickup, drop-off and ride home.`,sections:Tb,faqs:$b,links:[{href:"/fleet/executive-sprinter-scottsdale",label:m(fe)},{href:"/fleet/limo-sprinter-13-scottsdale",label:m(ao)},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:m(Te)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:Ab,fleetRows:wb},Ih="2026-09-26",ga="https://www.fs.usda.gov/r03/tonto",Pb=`${ga}/recreation/saguaro-lake`,Eb=`${ga}/passes`,Fb=`${ga}/recreation/butcher-jones-day-use-area`,Mb=`${ga}/recreation/saguaro-del-norte-day-use-motorized-boat-launch`,Rb=`${ga}/recreation/saguaro-lake-marina`,xb=`${ga}/recreation/saguaro-lake-ranch`,Db=`${ga}/alerts/canyon-lake-drawdown-public-safety-closure`,Ib="https://saguarolakemarina.com/",Nb="https://desertbellecruises.com/",as={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],families:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale","executive-luxury-bus-29-scottsdale"]},Wb=[...as.vip,...as.crews,...as.families].filter(ae),Lb=Wb.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),X="ultra-luxury-party-sprinter-scottsdale",Xa="maybach-jet-sprinter-scottsdale",Nh="maybach-shuttle-sprinter-8",rs="premium-suv-scottsdale",Vr="limo-sprinter-13-scottsdale",Rd="limo-sprinter-16-scottsdale",Wh="party-bus-28-scottsdale",er="executive-sprinter-scottsdale",Ob="executive-white-sprinter-scottsdale",Lh="executive-luxury-bus-29-scottsdale",k=e=>n[e],bt=e=>i[e];function os(e){return h(r[e].hourlyRateCents)}function Oh(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function We(e,t,...a){return{question:e,answer:t,paragraphs:a}}const _b=[{label:"Tonto National Forest: Saguaro Lake",href:Pb},{label:"Tonto National Forest: passes (Tonto Daily Pass, Discovery Pass, watercraft sticker)",href:Eb},{label:"Tonto National Forest: Butcher Jones Day Use Area",href:Fb},{label:"Tonto National Forest: Saguaro del Norte Day Use & Motorized Boat Launch",href:Mb},{label:"Tonto National Forest: Saguaro Lake Marina",href:Rb},{label:"Tonto National Forest: Saguaro Lake Ranch",href:xb},{label:"Tonto National Forest: Canyon Lake drawdown closure",href:Db},{label:"Saguaro Lake Marina: rentals and restaurant",href:Ib},{label:"Desert Belle: narrated cruises on Saguaro Lake",href:Nb}],Gb=[We("Do you need a Tonto Pass for Saguaro Lake, and who pays it?","Yes: the Forest Service charges a Tonto Pass per vehicle per day at Saguaro Lake’s picnic sites, shorelines and boat launches, cheaper bought ahead from a Forest Service office or retail vendor than at the on-site fee machine; launching a motorized boat adds a watercraft sticker, and the pass is not part of a chauffeured fare.","Saguaro Lake is in the Tonto National Forest, and the Forest Service runs its recreation sites. Its own lake page lists the day-use fee for the picnic sites, and a higher one for the boat launches, which adds the watercraft sticker. Each is charged per vehicle per day. The same fee costs more at the Tonto Fee Machine on site than as a Tonto Daily Pass bought in advance, so buying ahead is the cheaper habit.","The Tonto Daily Pass is a self-validating hangtag: scratch off the date and time on arrival, and it expires 24 hours later. The Forest Service sells it at its offices, including the Mesa Ranger Station, which sells passes on weekdays only, and through retail vendors around the Valley. The annual Tonto Discovery Pass is honored too, but it is valid only for the occupants of a single private, non-commercial vehicle.","With a chauffeured ride, tell the reservations team which marina, beach or launch the group wants. The team confirms the access point and anything charged at it before the day, and it stays outside our hourly fare, as the boat and the cruise do."),We("Where do you park and get dropped off at Saguaro Lake?","Drivers park in the marina’s lot or at the Forest Service day-use sites, Butcher Jones and Saguaro del Norte, and on summer weekends and holidays the lots fill early; a chauffeured group is dropped at the marina, the beach or the launch it confirms, and the vehicle waits for the ride home.","Saguaro Lake Marina, at 14011 North Bush Highway, is a commercial operation, not a Forest Service site, and it is where the rentals, the restaurant and the Desert Belle cruise are. Butcher Jones Day Use Area has mesquite shade, a nature trail and a gently sloping beach, and the Forest Service calls it one of the most-visited sites in the whole forest. Saguaro del Norte has 38 picnic units and the motorized boat launch.","The Forest Service is plain about the crowds. At Butcher Jones, parking can reach capacity on weekends and holidays through the summer, so it asks visitors to arrive early or have a second destination in mind. On most weekends and holidays from April to October, the lake itself reaches its boating capacity early in the day and more boats are not let in; once boat parking is full, vehicles towing boats are turned away at the entrance.","A chauffeured ride takes the parking question off the table: nobody hunts for a space, and nobody who has been on the water all day drives home. The group picks the stop, the chauffeur unloads there, and the vehicle waits nearby for the agreed time."),We("How do you get to Saguaro Lake from Scottsdale or Phoenix?","By road, Saguaro Lake is reached from State Route 87, the Beeline Highway: the Forest Service’s directions from Mesa are 27 miles north on SR 87 to Bush Highway, Forest Road 204, then right for 4 miles to the lake, which sits at 1,500 feet in the Tonto National Forest.","From Scottsdale and Phoenix, the route reaches SR 87 and turns onto Bush Highway for the last stretch to the lake. The Forest Service puts Butcher Jones at 31 miles northeast of Mesa, reached from SR 87 by Bush Highway and then Forest Road 166. Saguaro Lake Marina sits on Bush Highway itself.","It is a desert-highway drive out of the Valley, which is the case for a vehicle that stays with the group. After a day of sun and water, the ride home is the part nobody in the group should be driving."),We("Can you rent a boat at Saguaro Lake Marina?","Yes: Saguaro Lake Marina, a commercial operation on Bush Highway, rents pontoons, tritoons, a deck boat and a double-decker with a slide, and its Lakeshore Landing Restaurant serves outdoor meals on the shore; boats are booked with the marina, not with us, and we drive the crew there and home.","The marina lists its own rental fleet: pontoons, a tritoon, a deck boat and a double-decker with a slide. Rates, hours and booking are the marina’s, on its website or by phone at (480) 986-5546, so this guide prints none of them.","Bringing your own boat means the launch at Saguaro del Norte, the watercraft sticker on the pass, and the summer-weekend capacity limit. The lake has its own rules on the water: travel is counter-clockwise, the east end is no-wake, the bay in front of Butcher Jones and Saguaro del Norte is closed to motorized watercraft, and motors louder than 82 decibels are prohibited.","For a pontoon crew, the usual shape is a morning pickup, the drop-off at the marina with the coolers and the bags, a day on the water and a pickup at the dock before dark. The Pontoon Day package on this page is built on it."),We("What is the Desert Belle, and is Saguaro Lake good for families?","The Desert Belle is a tour boat that has cruised Saguaro Lake since 1964, on 80-minute narrated cruises past canyon walls and desert wildlife, with live-music cruises on weekends; with the Butcher Jones beach and picnic sites on the same lake, it makes Saguaro Lake a family day as much as a boat party.","The Forest Service’s own lake page points visitors to the Desert Belle for tour-boat trips. The cruise company describes an air-conditioned boat and a narration of the lake’s history, geology and wildlife by its captain. Tickets, times and seasons are the company’s own, so book them first and give us the departure time.","For families, the day usually pairs the cruise with the shore: the gently sloping beach at Butcher Jones, where motorized boats are kept out of the swimming area by buoys, or a picnic at Saguaro del Norte. The Executive Sprinter carries the chairs, the cooler and the beach bags in the back, and nobody has to leave early to beat the parking."),We("What does a Saguaro Lake day cost with a chauffeur?",`A Saguaro Lake day is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${k(X)} is ${os(X)}/hr and seats ${bt(X)}, the ${k(er)} is ${os(er)}/hr; the pass, the boat and the cruise are not included, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${bt(X)} riders in the ${k(X)} for 7 hours is about ${Oh(X,7,bt(X))} each before tax. 13 riders sharing the ${k(Vr)} for 8 hours at ${os(Vr)}/hr is about ${Oh(Vr,8,13)} each. That is arithmetic on the published rates, not a flat lake fare.`,"The hours run from the pickup at your door to the drop-off at home, and the vehicle waits at the lake in between, so the day is one booking, not two transfers. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books.","Not in the fare: the Tonto Pass or any fee at the stop the group picks, the boat rental, the Desert Belle tickets, and food and drinks at the lake."),We("Which vehicle fits a Saguaro Lake group?",`VIP groups lead with the ${k(Xa)}, then the ${k(X)}, our pick for the lake, the ${k(Nh)} and the Suburban; pontoon crews ride a Limo Party Sprinter or the ${bt(Wh)}-seat party bus; families and reunions take the ${k(er)}, the white Executive Sprinter or the ${k(Lh)}.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. VIP: the ${k(Xa)}, the ${k(X)}, the ${k(Nh)} and the ${k(rs)}. Pontoon crews: the ${k(Vr)}, the ${k(Rd)} and the ${k(Wh)}. Families and reunions: the ${k(er)}, the ${k(Ob)} and the ${k(Lh)}.`,`A VIP party larger than the ${k(X)} rides in two vehicles, one booking each for the same day and times: the ${k(X)} with the ${k(Xa)} seats ${bt(X)+bt(Xa)}, and with the ${k(rs)} it seats ${bt(X)+bt(rs)}.`,"Count the gear as well as the people. A lake day brings coolers, towels, chairs and dry bags, and the vehicles with room in the back (the Executive Sprinters, the larger Limo Sprinter and the party bus) carry it without taking seats."),We("When is the best time to go to Saguaro Lake?","Saguaro Lake is open year round; from April to October most weekends and holidays reach the lake’s boating capacity early in the day, and the Butcher Jones lot fills on summer weekends, so summer groups go early or on a weekday, and the cooler months are the quieter ones on the water.","The Forest Service lists the lake as open in every season. Summer is when it is busiest: a group that wants a rental pontoon on a July Saturday should book the boat well ahead and plan an early pickup, and a group bringing its own boat should expect a wait or a turn-away once the lake is full.","For a quieter day, the Forest Service points to the upper, east end of the lake for more seclusion, and weekdays are calmer everywhere. Lake levels change daily with irrigation demand and power generation, so rocks and obstacles can sit near the surface; that is a boat operator’s concern, not a passenger’s, but it is one more reason to book the boat with the marina’s own guidance."),We("What are the rules at Saguaro Lake?","The Forest Service’s main rules for visitors: glass containers are not permitted, there is no trash service, so everything packed in is packed out, the day-use sites are day use only with no overnight camping, pets must be on a leash, and motorized boats stay out of the swimming area at Butcher Jones.","Glass is the rule that catches groups out, so pack drinks in cans and plastic. With no trash pickup, bring bags for the rubbish and take it home; the vehicle has room for it. Butcher Jones and Saguaro del Norte are day-use only, with no overnight camping and, at Butcher Jones, no trailers.","Group events at the lake, fishing tournaments included, need a permit from the Mesa Ranger District. A private group’s day out with its own boat or a rental is not that, but a larger organised event should call the district first."),We("How far ahead should a Saguaro Lake ride be booked?","Book the boat or the cruise first, then the ride: availability varies by day and vehicle, so no fixed lead time applies, and summer weekends go first; send the date, the rider count, the pickup address and the stop at the lake, and the reservations team confirms what is open.","The first request needs the date, the hotel, rental or home, a likely passenger count, the marina, beach or launch, and the pickup time the boat or cruise needs. A group does not need every name to begin. It does need to say which group is riding: VIP guests, a pontoon crew, or a family or reunion.",`During the final 48 hours, confirm addresses, phone numbers, the boat or cruise time, and who is carrying the Tonto Pass if the stop needs one. Reach the reservations team at ${u} or ${p}. A ride booking never includes a boat, a cruise ticket or a pass.`)],Ub=[{question:"Is Saguaro Lake open?",answer:"Yes. The Forest Service lists Saguaro Lake as open year round. On most weekends and holidays from April to October the lake reaches its boating capacity early in the day, and more boats are not let in."},{question:"Do you need a pass for Saguaro Lake?",answer:"Yes, at the Forest Service picnic sites, shorelines and boat launches: a Tonto Pass per vehicle per day, plus a watercraft sticker to launch a motorized boat. It is cheaper bought ahead than at the on-site machine."},{question:"Where is Saguaro Lake Marina?",answer:"At 14011 North Bush Highway, Mesa, AZ 85215, on Saguaro Lake in the Tonto National Forest. It is a commercial operation, not run by the Forest Service; call it at (480) 986-5546."},{question:"Can you rent boats at Saguaro Lake?",answer:"Yes, from Saguaro Lake Marina: pontoons, tritoons, a deck boat and a double-decker with a slide. Book the boat with the marina; we drive the crew there and home."},{question:"Can you swim at Saguaro Lake?",answer:"The Forest Service lists swimming at the lake, and Butcher Jones has a gently sloping beach with its swimming area buoyed off from motorized boats. The site is day use only."},{question:"Are glass bottles allowed at Saguaro Lake?",answer:"No. Glass containers are not permitted at Saguaro Lake, and there is no trash service, so pack drinks in cans or plastic and take everything home."},{question:"What is Saguaro Lake Ranch?",answer:"A separate commercial site on the Forest Service’s list, a river access point with tube rentals, apart from the lake’s marina and day-use areas. Call it directly for its own information."},{question:"Is Canyon Lake open?",answer:"No. The Tonto National Forest has closed every recreation site around Canyon Lake, the marina and the lakebed included, for the dam drawdown from September 8, 2026 to February 28, 2027. Saguaro Lake is open."},{question:"Can a chauffeur wait at the lake all day?",answer:"Yes. The booking is by the hour from pickup to drop-off, so the vehicle waits at the lake between the drop-off and the ride home, and nobody in the group drives after a day on the water."}],Bb={path:"/guides/saguaro-lake-transportation",title:"Saguaro Lake: Tonto Pass, marina, parking and a ride there",metaTitle:"Saguaro Lake: Marina, Pass & Rides",description:"Saguaro Lake in the Tonto National Forest: the Tonto Pass, where to park and get dropped off, the marina’s boat rentals, the Desert Belle cruise, the lake’s rules, and a chauffeured day from Scottsdale so nobody drives home after the water.",metaDescription:"Tonto Pass, marina rentals, the Desert Belle, parking and rules, or a chauffeured lake day",lastUpdated:Ih,lastUpdatedLabel:l(Ih),eyebrow:"Open year round · Tonto National Forest",intro:`A Saguaro Lake day with Scottsdale Sprinters starts with the Forest Service’s own rules, the stop the group wants and a rider count. VIP groups lead with the ${k(Xa)} and the ${k(X)}; pontoon crews ride a Limo Party Sprinter or the party bus; families take the Executive Sprinter or the mini coach. This guide uses only published facts, from the Tonto National Forest, the marina and the cruise company, and turns the day into a written pickup, drop-off and ride home.`,sections:Gb,faqs:Ub,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:k(X)},{href:"/fleet/limo-sprinter-16-scottsdale",label:k(Rd)},{href:"/fleet/executive-sprinter-scottsdale",label:k(er)},{href:"/tours/lake-pleasant",label:"Lake Pleasant chauffeured day"},{href:"/service-areas/mesa",label:"Mesa service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:_b,fleetRows:Lb},_h="2026-09-25",Hb="/guides/scottsdale-limo-service",ns={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],nights:["pink-hummer-limo","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],weddings:["chrysler-limo-10","executive-white-sprinter-scottsdale","executive-sprinter-scottsdale"]},Ct="maybach-jet-sprinter-scottsdale",me="ultra-luxury-party-sprinter-scottsdale",ro="maybach-shuttle-sprinter-8",va="premium-suv-scottsdale",ee="pink-hummer-limo",da="limo-sprinter-13-scottsdale",la="limo-sprinter-16-scottsdale",Z="chrysler-limo-10",oo="executive-white-sprinter-scottsdale",zb="executive-sprinter-scottsdale",qb=[...ns.vip,...ns.nights,...ns.weddings].filter(ae),Po=qb.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),s=e=>n[e],U=e=>i[e],Gh=e=>h(r[e].hourlyRateCents);function ss(e,t){const{hourlyRateCents:a,minimumHours:o}=r[e];return h(a*Ds(t,o))}const xd=Po.map(e=>e.hourlyRateCents),Dd=h(Math.min(...xd)),Id=h(Math.max(...xd)),Uh=[...new Set(Po.map(e=>e.minimumHours))],Nd=Uh.length===1?`a ${Uh[0]}-hour minimum on every limo here`:"the minimum hours shown for each limo",Vb=Math.max(...Po.map(e=>e.capacity)),Yb=`${_d.toFixed(1)}-star Google rating across ${Gd.toLocaleString("en-US")} reviews`;function Je(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Jb="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",Zb=[{label:"City of Scottsdale, Transportation Safety Zone (Old Town)",href:Jb}],Kb=[Je("How much does a limo cost in Scottsdale?",`A Scottsdale limo from Scottsdale Sprinters is priced by the hour, from ${Dd} to ${Id} an hour across the limos on this page, with ${Nd}: the vehicle’s published hourly rate times your billable hours, plus ${xs}% Arizona sales tax at checkout, with no per-mile charge, no service fee and no booking fee.`,`Four hours in the ${s(Z)} comes to ${ss(Z,4)} before tax. Five hours in the ${s(ee)} comes to ${ss(ee,5)}. Every card on this page prints its vehicle’s own rate from the same grid, so the number you see is the number checkout uses.`,`Longer bookings earn free hours that come off automatically: book 7 to 11 hours and one hour is free, 12 to 14 hours and two are free, 15 hours or more and three are free. A seven-hour night in the ${s(me)} bills six hours, ${ss(me,7)} before tax.`,"A one-way ride is priced as a trip instead of by the hour, with no hourly minimum. Gratuity is optional and never added automatically."),Je("Which Scottsdale limo fits your group?",`Pick by who is riding: VIP and ultra-luxury parties lead with the ${s(Ct)}, then the ${s(me)}, the ${s(ro)} and the ${s(va)}; nights out and bachelorettes ride the ${s(ee)} or a Limo Party Sprinter; weddings, proms and executive groups take the ${s(Z)} or an Executive Sprinter.`,`Seats, from the fleet grid: the ${s(ee)} seats ${U(ee)}, the ${s(la)} ${U(la)}, the ${s(me)} ${U(me)}, the ${s(da)} ${U(da)}, the ${s(oo)} and the ${s(zb)} ${U(oo)} each, the ${s(Ct)} ${U(Ct)}, the ${s(Z)} and the ${s(ro)} ${U(Z)} each, and the ${s(va)} ${U(va)}.`,`The table lists each limo with its seats, hourly rate and minimum. The largest limo here seats ${Vb}. For a bigger group we plan two or more vehicles and quote them together; a VIP party larger than the ${s(Ct)} can ride it with the ${s(ro)} or the ${s(va)}, one booking each.`,"If your group is on the edge of a vehicle’s seats, tell us and we confirm the fit in writing before payment."),Je("What is the Pink Hummer Limo?",`The ${s(ee)} is our one-of-one pink stretch Hummer, the bachelorette mobile: ${U(ee)} guests on handmade custom leather seats behind privacy-tinted windows, with a lit wet bar, a champagne bar, star lighting and a custom sound system, at ${Gh(ee)} an hour.`,"It is our most popular ride for women: bachelorettes first, then girls’ birthdays, prom and any night out that celebrates the women in it. Ambient lighting runs outside as well as in, and a partition separates the cabin from the chauffeur.","There is one Pink Hummer, so it books by the date. If a pink party bus is what you searched for, the pink party bus guide explains why the pink ride here is a stretch Hummer limousine rather than a bus."),Je("Do you have a classic stretch limo?",`Yes: the ${s(Z)} is our classic stretch limousine, black outside with ambient lighting and privacy tint, up to ${U(Z)} guests on classic leather seats, with a wet bar, a custom sound system and seventeen colour settings for the cabin lights, at ${Gh(Z)} an hour.`,"It is the one for prom, anniversaries, date nights, concerts and the wedding exit: the long silhouette everybody turns to look at. A stretch limo is a sedan lengthened for a lounge cabin; the Pink Hummer is the same idea built on a Hummer, which is why it seats a bigger group."),Je("What is a Limo Party Sprinter?",`A Limo Party Sprinter puts limo-style seating, a wet bar and party lighting in a Mercedes Sprinter: the ${s(da)} seats ${U(da)} under fiber-optic roof lights, the ${s(la)} is our largest Sprinter with a star-roof ceiling for ${U(la)}, and the ${s(me)} is the top of the line.`,`The ${s(me)} adds fiber-optic lighting with eighteen modes, laser lights, a fog machine, automatic doors and an intercom to your chauffeur, for up to ${U(me)}. It is also ultra-luxury, so it rides with the VIP group on this page.`,"The Limo Party Sprinters ride with the nights-out group, never with a corporate or family booking. For executive groups and weddings that want the room without the party lighting, the Executive Sprinters carry reclining leather seats and space for bags."),Je("Where do Scottsdale limos pick up?","Anywhere in Scottsdale and the greater Phoenix area: your hotel, home, restaurant or venue, with every stop on an hourly booking included; in Old Town’s entertainment district, from 5 p.m. to 4 a.m. every night, hired vehicles load and unload only in the marked Passenger Convenience Areas.",`Old Town Scottsdale is where nights out start: dinner, the bars and the clubs, in the ${s(ee)} or a Limo Party Sprinter. The City’s Transportation Safety Zone covers the entertainment district every night from 5 p.m. to 4 a.m.: through lanes stay clear, and hired vehicles stop only to load or unload at the marked Passenger Convenience Areas, so your chauffeur meets the group where the City allows a limo to load.`,`North Scottsdale books weddings at the resorts and desert venues along the 101, and dinners around Kierland and Scottsdale Quarter; the ${s(Z)} and the ${s(oo)} are the wedding picks. Central Scottsdale, Gainey Ranch and McCormick Ranch book anniversary dinners and small-group evenings in the ${s(va)} or the ${s(Ct)}. Paradise Valley estate events stage the vehicle at the property.`,"Stops on an hourly booking are complimentary, because you have already bought the time. On a one-way ride or a round trip, an added stop carries a fee shown on the quote."),Je("Do you offer limo service in Phoenix?","Yes: we run chauffeured limos throughout Phoenix and the Valley, from the Biltmore to downtown Phoenix, Tempe, Mesa, Chandler, Gilbert and Glendale, with the same vehicles, rates and chauffeurs as in Scottsdale.","The drive is part of the hours you book, and your chauffeur plans the route around the Valley’s freeway traffic, so a Phoenix dinner and a Scottsdale nightcap can share one booking. On summer evenings the cabin is cooled before the group boards.","For a Phoenix wedding, a Tempe or ASU celebration, or a concert downtown, pick the group above and the limos that fit it appear with their rates."),Je("Can you pick us up at Phoenix Sky Harbor in a limo?",`Yes. ${dd} We also pick up at Scottsdale Airport and Phoenix-Mesa Gateway, and your chauffeur tracks your flight.`,"Airport rides are priced as a one-way trip with no hourly minimum. The airport transportation page has the full detail, from greeters to luggage."),Je("Can you drink in a limo in Arizona?","Passengers 21 and over may bring their own alcohol, and we do not sell it; if anyone under 21 rides, no alcohol comes on that trip, which makes every prom ride alcohol-free, and there is no smoking, vaping or food inside any vehicle.","Arizona’s vehicle-for-hire open-container policy, A.R.S. § 4-251, is what allows adults to drink on board; the alcohol-laws guide covers the law itself. Anyone under 21 stays on soft drinks, and the chauffeur never drinks.","Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates; the prom night page has the full plan, from the photo stop to the ride home.")],jb=[{question:"How much does it cost to rent a limo in Scottsdale?",answer:`A limo is priced by the hour: the vehicle’s published hourly rate times your billable hours, from ${Dd} to ${Id} an hour across the limos on this page. There is no per-mile charge, no service fee and no booking fee. Arizona sales tax of ${xs}% is added at checkout, and gratuity is optional. Pick the limo above and the price is on the page.`},{question:"How much is a limo for 2 hours, 4 hours or a whole night?",answer:`An hourly booking has ${Nd}, so a two-hour ride books the minimum; a one-way ride is priced as a trip instead, with no hourly minimum. Bookings of 7 hours or more earn free hours that come off automatically, so a seven-hour night bills six.`},{question:"How many people fit in a limo?",answer:`It depends on the limo: the ${s(ee)} seats ${U(ee)}, the ${s(la)} seats ${U(la)}, the ${s(me)} seats ${U(me)}, the ${s(da)} seats ${U(da)} and the ${s(Z)} seats ${U(Z)}. If your group is on the edge, tell us and we confirm the fit in writing.`},{question:"Can you drink in a limo?",answer:"If everyone drinking is 21 or over, yes: bring your own, because we do not sell alcohol. Nobody under 21 drinks, and if anyone under 21 rides, no alcohol comes on that trip. There is no smoking, vaping or food inside the vehicle."},{question:"How much do you tip a limo driver?",answer:"Gratuity is optional, is never added automatically, and goes 100% to your chauffeur. Add it at checkout or hand it over in person."},{question:"Can we book a limo for prom?",answer:`Yes. Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates. The ${s(Z)} is the classic prom stretch; the ${s(oo)} carries a bigger group.`},{question:"What is the difference between a limo, a stretch limo and a limo Sprinter?",answer:`The ${s(Z)} is the classic stretch: the long black silhouette, up to ${U(Z)} guests. The ${s(ee)} is a stretch Hummer that seats a bigger group. Our Limo Party Sprinters put limo-style seating, a wet bar and party lighting in a Mercedes Sprinter.`},{question:"Is Scottsdale Sprinters a reputable limo company?",answer:`Every chauffeur is background and MVR checked, drug screened and trained, and the company is licensed and insured with commercial coverage on every vehicle. Guests give us a ${Yb}.`},{question:"Do you pick up at Phoenix Sky Harbor?",answer:`Yes: Phoenix Sky Harbor (PHX), Scottsdale Airport (SCF) and Phoenix-Mesa Gateway (AZA). ${dd} Your chauffeur tracks your flight.`},{question:"How far in advance should I book a limo?",answer:Rs},{question:"Do you serve Phoenix?",answer:"Yes. We run chauffeured limos throughout Scottsdale, Paradise Valley and the greater Phoenix area."},{question:"Can we decorate the limo or add a Just Married sign?",answer:"Yes, as priced add-ons you choose at checkout: Just Married signage, balloons and décor, a red carpet arrival and more. Anything vehicle-specific is confirmed in writing before payment."}],Qb={path:Hb,title:"Limo service in Scottsdale and Phoenix",metaTitle:"Scottsdale Limo Service & Limo Rental",description:`Scottsdale limo service with a professional chauffeur on every booking: the ${s(ee)}, the classic stretch ${s(Z)}, the Limo Party Sprinters and the ${s(Ct)}, each with its published hourly rate. Pick the group, see the price and reserve online, in Scottsdale and across Phoenix.`,metaDescription:"The Pink Hummer, a classic stretch, Limo Sprinters and the Maybach Jet, chauffeured, with the price on the page",lastUpdated:_h,lastUpdatedLabel:l(_h),intro:`Scottsdale limo service from Scottsdale Sprinters comes with a professional chauffeur on every booking, in Scottsdale and across Phoenix. Start with who is riding. VIP and ultra-luxury parties lead with the ${s(Ct)}, then the ${s(me)}, the ${s(ro)} and the ${s(va)}. Nights out and bachelorettes ride the one-of-one ${s(ee)} or a Limo Party Sprinter. Weddings, proms and executive groups take the classic stretch, the ${s(Z)}, or an Executive Sprinter. Every limo here shows its published hourly rate, and you can reach the reservations team at ${u} or ${p}.`,sections:Kb,faqs:jb,links:[{href:"/fleet/pink-hummer-limo",label:s(ee)},{href:"/fleet/limo-sprinter-13-scottsdale",label:s(da)},{href:"/fleet/limo-sprinter-16-scottsdale",label:s(la)},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:s(me)},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:s(Ct)},{href:"/guides/pink-party-bus-scottsdale",label:"Pink party bus or pink limo?"},{href:"/guides/party-bus-vs-limo-vs-sprinter",label:"Party bus vs limo vs Sprinter"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Arizona alcohol rules on board"},{href:"/services/wedding-transportation-scottsdale",label:"Wedding limo and transportation"},{href:"/experiences/prom-night",label:"Prom night limo"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport limo pickups"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:"/pricing",label:"Published hourly pricing"}],sources:Zb,fleetRows:Po},Bh="2026-09-25",Xb="/guides/venues/talking-stick-resort-amphitheatre",na="ultra-luxury-party-sprinter-scottsdale",is="maybach-jet-sprinter-scottsdale",ew="maybach-shuttle-sprinter-8",tw="premium-suv-scottsdale",sa="limo-sprinter-13-scottsdale",hs="limo-sprinter-16-scottsdale",ds="party-bus-28-scottsdale",ia="executive-sprinter-scottsdale",aw="executive-white-sprinter-scottsdale",ls="executive-mini-bus-26-scottsdale",cs="executive-luxury-bus-29-scottsdale",us="motorcoach-56",S=e=>n[e],Ze=e=>i[e],ps=e=>`${h(r[e].hourlyRateCents)} an hour with a ${r[e].minimumHours}-hour minimum`,Na="https://www.talkingstickresortamphitheatre.com",rw=`${Na}/visit`,ow=`${Na}/know-before-you-go`,nw=`${Na}/faq`,sw=`${Na}/upgrades/parking`,iw=`${Na}/accessibility`,hw=`${Na}/shows`,dw="https://www.livenation.com/venue/KovZpZAE6vJA/talking-stick-resort-amphitheatre-events",lw="https://www.prnewswire.com/news-releases/phoenix-music-venue-to-be-renamed-talking-stick-resort-amphitheatre-301719437.html",cw=[{label:"Talking Stick Resort Amphitheatre, plan your visit",href:rw},{label:"Talking Stick Resort Amphitheatre, the need-to-know before you go",href:ow},{label:"Talking Stick Resort Amphitheatre, frequently asked questions",href:nw},{label:"Talking Stick Resort Amphitheatre, parking upgrades",href:sw},{label:"Talking Stick Resort Amphitheatre, accessibility",href:iw},{label:"Talking Stick Resort Amphitheatre, upcoming shows",href:hw},{label:"Live Nation, Talking Stick Resort Amphitheatre events",href:dw},{label:"Live Nation, Phoenix music venue to be renamed Talking Stick Resort Amphitheatre (January 11, 2023)",href:lw}],Ms=["January","February","March","April","May","June","July","August","September","October","November","December"],uw=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function pw(e){const[t,a,o]=e.split("-").map(Number);return`${uw[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${Ms[a-1]} ${o}, ${t}`}function fw(e){return`${pw(e.date)}: ${e.title} (show ${fa(`${e.date}T${e.starts}:00-07:00`)}).`}function at(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Le=Ws.filter(e=>e.date.startsWith("2026")),fs=Ws.filter(e=>!e.date.startsWith("2026")),mw=[at("How does parking work at Talking Stick Resort Amphitheatre?","Talking Stick Resort Amphitheatre’s parking lots typically open 30 minutes before the scheduled gate time, and gates usually open 60 to 90 minutes before the show. Parking is sold show by show on the venue’s parking page, and its upgrades include Premier Parking, a short walk from the gates, and Easy Out Parking near the West Gate (Gate 2) for the fastest exit.","Reserved Premier Parking is a guaranteed space at the front of the Premier lot, held all night whether you arrive early or late; it is for cars only. The venue also sells an oversized space for a limousine or an RV in the Premier lot. Every upgrade is limited.","No tailgating is allowed, and no overnight parking: an unauthorized vehicle on site before or after an event is towed at the owner’s expense. Accessible parking is inside Gate 3 and Gate 6 off Encanto Boulevard, first come, first served, for a state-issued placard or plate; the venue suggests arriving when the lots open.","The venue’s pages publish no parking price: parking is sold per show, and the box office handles parking refunds and upgrades."),at("Where is the drop-off and rideshare pickup at Talking Stick Resort Amphitheatre?","The venue’s drop-off and pick-up area is on the west side of Talking Stick Resort Amphitheatre, through Gate 3: tell parking staff you are dropping off and they show you the way. To pick up, arrive at least 45 minutes before the show ends, or you will not be able to enter. Rideshare riders meet their car on Palm Lane, on the southwest side of the venue.","That is the area a chauffeured group uses too. We tell parking staff we are dropping off, unload the group through Gate 3, and are back inside the pick-up area before the 45-minute cutoff, so the group walks out to its own vehicle instead of joining the rideshare line on Palm Lane.","A group that splits across cars also splits across lots, gates and exits. One vehicle arrives with everyone at once and leaves with everyone at once."),at("Where is Talking Stick Resort Amphitheatre, and is it at Talking Stick Resort?","Talking Stick Resort Amphitheatre is at 2121 North 83rd Avenue, Phoenix, AZ 85035, in Maryvale on the west side of Phoenix. It is not at Talking Stick Resort: the venue says plainly that it is not the same location as the Talking Stick Resort & Casino, which is in Scottsdale. Talking Stick Resort is the amphitheatre’s name-in-title sponsor.","Live Nation, which runs the venue, renamed it in January 2023; it was the Ak-Chin Pavilion before that. The venue has hosted concerts for over 30 years.","By Google’s typical drive time, measured on September 24, 2026 without show traffic, the amphitheatre is 16 minutes from downtown Phoenix, 20 minutes from Phoenix Sky Harbor, 29 minutes from Old Town Scottsdale, 34 minutes from the Talking Stick Resort casino and 38 minutes from Kierland. Show nights add the venue’s own traffic to the last mile."),at("What time do gates open at Talking Stick Resort Amphitheatre?","Gates at Talking Stick Resort Amphitheatre usually open 60 to 90 minutes before showtime, and the parking lots about 30 minutes before the gates. The exact gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date.","There are two main entry gates, the West Gate and the East Gate, and some shows open only one. The box office is open on show days only: the West Box Office from noon, the East Box Office about an hour before doors, card only.","Re-entry is not permitted: once you leave, you need a new ticket to come back in. Events are all ages unless the show says otherwise, and shows go on rain or shine, barring severe weather."),at("What is the Talking Stick Resort Amphitheatre bag policy?","Only small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear plastic bags up to 12 by 12 by 6 inches, are allowed inside Talking Stick Resort Amphitheatre. All bags are subject to search at entry, with metal detectors and sometimes a pat-down.","Not allowed: backpacks and other bags outside the policy, coolers of any size, outside food or drink except factory-sealed water, alcohol, glass, cans, metal hydroflasks, lawn chairs, strollers, laser pointers, selfie sticks and aerosol sunscreen. Factory-sealed, unfrozen water up to one gallon per person is allowed, and refill stations are inside.","The venue is cash-free: guest services swap cash for a card at no charge. Settle bags at the hotel; a group that is dropped off has no car in the lot to go back to during the show."),at("How many people does Talking Stick Resort Amphitheatre hold, and how does the lawn work?","Live Nation describes Talking Stick Resort Amphitheatre as a 20,000-seat outdoor venue. The lawn is always first come, first served: a row or seat number on a lawn ticket is only for the box office’s tracking, and there are no assigned seats on the lawn.","Lawn chairs can be rented for most shows and are the only chairs allowed inside; blankets are not permitted at some shows. For a large party, the venue’s Premium Seating department sells VIP boxes, suites and clubs that hold more guests than the standard ticket limit.","For a group, the lawn decides the ride: arriving together at gate time is how a crew gets a spot together, and leaving together is how it gets home."),at("Which vehicle fits a Talking Stick Resort Amphitheatre group?",`Concert crews ride the ${S(sa)}, the ${S(hs)} or the ${S(ds)}. A VIP night takes the ${S(is)}, the ${S(na)}, the ${S(ew)} or the ${S(tw)}. Corporate and big groups take the ${S(ia)}, the ${S(aw)}, the ${S(ls)}, the ${S(cs)} or the ${S(us)}.`,`Seat counts are seated capacities from the fleet: the ${S(na)} seats ${Ze(na)}, the ${S(sa)} ${Ze(sa)}, the ${S(hs)} ${Ze(hs)}, the ${S(ds)} ${Ze(ds)} and the ${S(is)} ${Ze(is)}. The ${S(ia)} seats ${Ze(ia)}, the ${S(ls)} ${Ze(ls)}, the ${S(cs)} ${Ze(cs)} and the ${S(us)} ${Ze(us)}.`,`Our pick for a night on the lawn is the ${S(na)}, ${ps(na)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system with subwoofers, a wet bar with champagne glass holders and a full partition with an intercom to your chauffeur. The ${S(sa)} is ${ps(sa)}, and the ${S(ia)} is ${ps(ia)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),at("How should a group plan the ride to a Talking Stick Resort Amphitheatre show?","Plan backwards from the show time. Gates usually open 60 to 90 minutes before the show, so a pickup that lands the group at the Gate 3 drop-off around gate time leaves room for the lines, the bag check and a spot on the lawn.","The ride home is the part to plan hardest. The venue lets pickups into its pick-up area only until 45 minutes before the show ends, so your chauffeur is in place before the encore and the group walks straight out to its vehicle.",`Book by the hour and the vehicle is yours for the whole night, dinner before the show included, or book a ride there and a ride back. Reach the reservations team at ${u} or ${p} with the show, the date, the pickup area and the rider count.`)],gw=at("What’s coming up at Talking Stick Resort Amphitheatre?",`Talking Stick Resort Amphitheatre lists ${Le.length} more shows this fall, from ${Le[0].label} on ${Ms[Number(Le[0].date.slice(5,7))-1]} ${Number(Le[0].date.slice(8))} to ${Le[Le.length-1].label} on ${Ms[Number(Le[Le.length-1].date.slice(5,7))-1]} ${Number(Le[Le.length-1].date.slice(8))}, and ${fs.length===1?`one 2027 show so far, ${fs[0].label}`:`${fs.length} 2027 shows so far`}. As the venue’s show list gave them on September 24, 2026:`,...Ws.map(fw),"Gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date. New shows are added to the venue’s calendar through the year, and it is the place to check before you book."),yw=[{question:"Where do you park at Talking Stick Resort Amphitheatre?",answer:"In the venue’s own lots, which typically open 30 minutes before the gates. Parking is sold per show, with Premier Parking a short walk from the gates and Easy Out Parking by the West Gate (Gate 2) for the fastest exit. No tailgating and no overnight parking."},{question:"How much is parking at Talking Stick Resort Amphitheatre?",answer:"The venue’s pages publish no price: parking is sold per show on the venue’s parking page. Premier, Reserved Premier and Easy Out spaces cost more and are limited."},{question:"Where is the rideshare pickup at Talking Stick Resort Amphitheatre?",answer:"On Palm Lane, on the southwest side of the venue. Drop-off is on the west side through Gate 3; tell parking staff you are dropping off."},{question:"Can a limo or party bus drop off at Talking Stick Resort Amphitheatre?",answer:"Yes, in the venue’s drop-off and pick-up area on the west side through Gate 3, as parking staff direct. For the ride home the vehicle must be in the pick-up area at least 45 minutes before the show ends, or it cannot enter."},{question:"Is Talking Stick Resort Amphitheatre at Talking Stick Resort?",answer:"No. The amphitheatre is at 2121 North 83rd Avenue in Phoenix; the Talking Stick Resort & Casino is in Scottsdale, about 34 minutes’ drive away. The venue says they are not the same location."},{question:"What time do gates open at Talking Stick Resort Amphitheatre?",answer:"Usually 60 to 90 minutes before showtime, with the lots about 30 minutes before the gates. Exact times are posted for each show on the venue’s Need-to-Know page."},{question:"What is the Talking Stick Resort Amphitheatre bag policy?",answer:"Small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear bags up to 12 by 12 by 6 inches. No backpacks, coolers or lawn chairs of your own."},{question:"Can you tailgate at Talking Stick Resort Amphitheatre?",answer:"No. The venue allows no tailgating and no overnight parking."},{question:"How many people does Talking Stick Resort Amphitheatre hold?",answer:"Live Nation describes it as a 20,000-seat outdoor venue, with a first-come, first-served lawn."},{question:"Can you leave and come back in at Talking Stick Resort Amphitheatre?",answer:"No. Re-entry is not permitted; leaving means a new ticket to come back in."},{question:"Can I bring lawn chairs to Talking Stick Resort Amphitheatre?",answer:"No. The venue rents lawn chairs for most shows, and no other chairs are permitted inside. The lawn is first come, first served with no assigned seats, and some shows allow neither lawn chairs nor blankets, so check the show’s note on the venue’s Know Before You Go page."},{question:"Is Talking Stick Resort Amphitheatre the old Ak-Chin Pavilion?",answer:"Yes. Live Nation renamed the Ak-Chin Pavilion as Talking Stick Resort Amphitheatre in January 2023. It is the same 20,000-seat outdoor venue in Maryvale, and not the Talking Stick casino resort in Scottsdale."}],bw={path:Xb,title:"Talking Stick Resort Amphitheatre: Parking, Upcoming Shows and Concert Rides",metaTitle:"Talking Stick Amphitheatre Parking",description:"Talking Stick Resort Amphitheatre in Phoenix, not the Scottsdale casino: how the parking works, the Gate 3 drop-off and the Palm Lane rideshare pickup, gate times, the bag policy, the lawn, the upcoming shows, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, gates, the Gate 3 drop-off and a chauffeured ride",lastUpdated:Bh,lastUpdatedLabel:l(Bh),eyebrow:"Phoenix · Maryvale",intro:"Scottsdale Sprinters’ short answer on Talking Stick Resort Amphitheatre: it is the outdoor concert venue at 2121 North 83rd Avenue in Phoenix, not the Talking Stick Resort casino in Scottsdale. Its lots typically open 30 minutes before the gates, and the gates usually 60 to 90 minutes before the show. The drop-off and pick-up area is on the west side through Gate 3, and rideshare pickup is on Palm Lane. For a group, one chauffeured vehicle replaces the lot, the pickup line and the drive home.",sections:[...mw,gw],faqs:yw,links:[{href:"/guides/venues/talking-stick-resort",label:"Talking Stick Resort group arrival guide"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/phoenix",label:"Phoenix limo and chauffeur service"},{href:`/fleet/${na}`,label:S(na)},{href:`/fleet/${sa}`,label:S(sa)},{href:`/fleet/${ia}`,label:S(ia)},{href:"/pricing",label:"Published hourly pricing"}],sources:cw},Hh="2026-09-27",ww="https://tempefestivalofthearts.com/",vw="https://tempefestivalofthearts.com/info/festival-dates",kw="https://tempefestivalofthearts.com/info/get-here",Sw="https://tempefestivalofthearts.com/info/about",Aw="https://tempefestivalofthearts.com/the-experience/beer-and-wine",Tw="https://tempefestivalofthearts.com/the-experience/kids-block",$w="https://tempefestivalofthearts.com/the-experience/eats-and-drinks",ms={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],families:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale","executive-mini-bus-26-scottsdale"],crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"]},Cw=[...ms.vip,...ms.families,...ms.crews].filter(ae),Pw=Cw.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),J="maybach-jet-sprinter-scottsdale",zh="ultra-luxury-party-sprinter-scottsdale",Yr="maybach-shuttle-sprinter-8",gs="premium-suv-scottsdale",tr="executive-sprinter-scottsdale",Ew="executive-white-sprinter-scottsdale",qh="executive-mini-bus-26-scottsdale",Fw="limo-sprinter-13-scottsdale",no="limo-sprinter-16-scottsdale",Lt="party-bus-28-scottsdale",v=e=>n[e],Oe=e=>i[e];function Jr(e){return h(r[e].hourlyRateCents)}function Vh(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}function _e(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Mw=[{label:"Tempe Festival of the Arts: fall 2026 dates, hours, free admission",href:ww},{label:"Tempe Festival of the Arts: festival dates through 2027",href:vw},{label:"Tempe Festival of the Arts: Get Here (streets, transit, parking, drop-off)",href:kw},{label:"Tempe Festival of the Arts: about the festival and dogs",href:Sw},{label:"Tempe Festival of the Arts: beer and wine gardens",href:Aw},{label:"Tempe Festival of the Arts: Kids Block",href:Tw},{label:"Tempe Festival of the Arts: eats and drinks",href:$w}],Rw=[_e("When is the Tempe Festival of the Arts 2026?","The fall 2026 Tempe Festival of the Arts runs Friday, December 4 through Sunday, December 6, 2026, on Mill Avenue in Downtown Tempe; it opens at 10 a.m. each day and closes at 5 p.m. on Friday and Saturday and at 4 p.m. on Sunday, and the spring festival follows on March 12 through 14, 2027.","It is the 58th fall festival. The festival holds two a year, in early December and in early to mid-March, and calls itself one of the oldest festivals in the Southwest, with a history of more than 50 years in Tempe.","The festival’s own dates page lists the 50th spring festival for March 12 through 14, 2027, and the 59th fall festival for December 3 through 5, 2027, and notes that the dates are tentative and subject to change. Check its site close to the weekend before you set the pickup."),_e("Where do you park for the Tempe Festival of the Arts, and where is drop-off?","There is no parking inside the festival perimeter, so drivers use paid downtown lots and garages or ride light rail from one of 13 free Park-and-Ride lots; the drop-off areas by each entrance are only for vehicles with ADA tags or permits, so a chauffeured group is unloaded where festival security and staff direct, and the vehicle waits nearby.","The festival names five major entrances with limited drop-off areas beside them: 3rd and Mill, 3rd and University, 5th and Ash, 5th and Myrtle, and 7th and Myrtle, near the water barricades. Security permits loading and unloading there only for vehicles displaying ADA accessible tags or permits.","For accessible parking, the festival reserves accessible meters on 5th Street east of Mill to College Avenue and on 7th Street east of Mill, beside the festival, and ADA parking in the 201 S. Ash Garage, on Ash between Rio Salado and 3rd Street, where posted rates apply. On-street parking in Downtown Tempe is free for vehicles displaying current disabled access plates or placards. The festival also notes that motorized wheelchairs are not available at the event.","With a chauffeur, the parking question goes away: we drive the approach, step you out where security directs, and meet you again at the pickup point agreed in advance. Nobody circles a garage, and the art you buy rides home in the vehicle."),_e("Which streets does the festival cover, and can you take light rail or the streetcar?","The festival fills Mill Avenue between 3rd Street and University Drive, and 5th Street between Myrtle and Ash Avenue; light rail riders get off at Mill Ave/3rd St or the Tempe Transportation Center, and during the festival the Tempe Streetcar runs only between the Dorsey and 9th Street stops.","The Tempe Transportation Center sits one block east of the 5th Street entrance. Valley Metro’s trip planner and app cover fares and times, and the festival’s Get Here page lists the 13 Park-and-Ride lots by name.","Those streets are the festival’s, so cars do not reach the booths. A chauffeured day starts at your resort or home and ends where you want it, without a transfer or a walk from a garage with your purchases."),_e("Is the Tempe Festival of the Arts free, and can you bring your dog?","Admission is free, and the festival is dog friendly: leashed, well-behaved dogs are welcome, and the festival asks that no dog wander at the full length of its leash, standard or retractable, so it does not block the crowd or disturb the artwork on display.","Keep a short leash in the booths, where the work sits at nose height."),_e("What is at the Tempe Festival of the Arts?","As many as 350 artist booths line Mill Avenue and the surrounding streets, with handmade work juried from more than 500 applications in 17 visual arts categories, plus live entertainment, food trucks, three beer and wine gardens, a Wine + Spirits Tasting in Centerpoint Plaza on Saturday and Sunday, and a Kids Block on Saturday and Sunday.","The festival ranks among the Top 100 Classic & Contemporary Craft Shows in the nation in Sunshine Artist magazine and has won the Pinnacle Award from the International Festival and Events Association. Each spring and fall festival draws nearly 225,000 visitors to Downtown Tempe over its three-day weekend.","Food comes from food trucks, snack stands and beverage vendors throughout the festival, with Food Truck Alley and the Festival Food Court for lunch between the booths. The festival announces its food and drink lineup closer to the weekend."),_e("What should you bring to the Tempe Festival of the Arts?","Bring a credit card and photo ID: the festival’s bars are cashless, credit card only, and serve guests 21 and over with valid photo ID and a wristband, and the Young Artist Exhibition takes card payments only; bring a short leash for a dog, and leave room in the day, and in the vehicle, for what you buy.","The festival publishes no bag rule or list of banned items on its pages. What it does publish is where things are: the Young Artist Exhibition sits on the west side of Maple Avenue between 5th and 6th Street, across from the Kids Block entrance.","With a chauffeured day, a large canvas or a piece of pottery does not have to be carried for the rest of the afternoon: walk it back to the vehicle, and keep browsing."),_e("Is the Tempe Festival of the Arts good for kids and families?",`Yes: the Kids Block, open Saturday and Sunday only, has hands-on art projects, the Young Collectors Gallery and games, the Parent’s Lounge is open Friday through Sunday, and the Young Artist Exhibition shows K-12 work all weekend; for a family ride, our house rule applies: ${Ft}`,"The Young Collectors Gallery, on Saturday and Sunday, lets children buy a small piece handcrafted by one of the festival’s professional artists, with volunteers on hand to help them shop. The Parent’s Lounge is a place to sit, feed a baby or change a diaper.","Families ride the Executive Sprinters or the Mini Bus, never a party unit, and no family package carries a drink service. The festival’s beer and wine gardens are the festival’s, for guests 21 and over; we sell no alcohol."),_e("What does a chauffeured festival day cost?",`A festival day is billed by the hour at each vehicle’s published rate, from pickup to drop-off, with its minimum hours: the ${v(J)} is ${Jr(J)}/hr and seats ${Oe(J)}, the ${v(tr)} is ${Jr(tr)}/hr, a ${v(no)} is ${Jr(no)}/hr; admission to the festival is free, and prices are before tax.`,`Split across the group, the hourly rate becomes a per-person figure. ${Oe(J)} riders in the ${v(J)} for 5 hours is about ${Vh(J,5,Oe(J))} each before tax. ${Oe(Lt)} riders sharing the ${v(Lt)} for 5 hours at ${Jr(Lt)}/hr is about ${Vh(Lt,5,Oe(Lt))} each. That is arithmetic on the published rates, not a flat festival fare.`,"The hours run from the pickup at your resort or home to the drop-off at the end of the day, and the vehicle waits nearby in between, so the day is one booking, not two rides. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books."),_e("Which vehicle fits a Tempe Festival of the Arts group?",`Art buyers and couples lead with the ${v(J)}, our pick for a festival day, then the ${v(zh)}, the ${v(Yr)} and the Suburban; families take the ${v(tr)}, the white Executive Sprinter or the ${v(qh)}, alcohol-free; friends’ crews ride a Limo Party Sprinter or the ${Oe(Lt)}-seat party bus.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. VIP: the ${v(J)}, the ${v(zh)}, the ${v(Yr)} and the ${v(gs)}. Families: the ${v(tr)}, the ${v(Ew)} and the ${v(qh)}. Friends’ crews: the ${v(Fw)}, the ${v(no)} and the ${v(Lt)}.`,`A VIP party larger than the ${v(J)} rides in two vehicles, one booking each for the same day and times: the ${v(J)} with the ${v(Yr)} seats ${Oe(J)+Oe(Yr)}, and with the ${v(gs)} it seats ${Oe(J)+Oe(gs)}.`),_e("How does a chauffeured festival day work, and how far ahead should you book?","Your chauffeur picks you up at your resort or home, unloads the group where festival security and staff direct, waits nearby while you browse and lunch on Mill Avenue, takes purchases aboard between laps, and drives you home at close; availability varies by day and vehicle, so no fixed lead time applies; send the day and the group early.","The first request needs the festival day, the pickup address, a likely passenger count and which group is riding: art buyers, a family with children, or a friends’ crew. A group does not need every name to begin.",`During the final 48 hours, confirm addresses, phone numbers and the pickup point for the ride home. Reach the reservations team at ${u} or ${p}.`)],xw=[{question:"What are the dates of the Tempe Festival of the Arts 2026?",answer:"Friday, December 4 through Sunday, December 6, 2026, on Mill Avenue, Downtown Tempe. The spring festival is March 12 through 14, 2027 (dates tentative, the festival says)."},{question:"What time does the Tempe Festival of the Arts open?",answer:"It opens at 10 a.m. each day. It closes at 5 p.m. on Friday and Saturday and at 4 p.m. on Sunday."},{question:"Is the Tempe arts festival free?",answer:"Yes. Admission to the Tempe Festival of the Arts is free."},{question:"Are dogs allowed at the Tempe Festival of the Arts?",answer:"Yes. Leashed, well-behaved dogs are welcome; the festival asks that dogs not wander at the full length of the leash."},{question:"Where do you park for the Tempe Festival of the Arts?",answer:"There is no parking inside the festival. Drivers use paid downtown lots and garages, or ride light rail from a free Park-and-Ride lot to Mill Ave/3rd St or the Tempe Transportation Center. A chauffeured group skips parking altogether."},{question:"Which streets are closed for the Tempe Festival of the Arts?",answer:"The festival occupies Mill Avenue between 3rd Street and University Drive, and 5th Street between Myrtle and Ash Avenue."},{question:"Is there beer at the Tempe Festival of the Arts?",answer:"Yes. The festival runs three beer and wine locations, 21 and over with valid photo ID and a wristband, cashless and credit card only, plus a Wine + Spirits Tasting on Saturday and Sunday."},{question:"Can you hire a limo or Sprinter for the Tempe Festival of the Arts?",answer:`Yes. The ${v(J)}, the Executive Sprinters and the Limo Party Sprinters are booked by the hour, pickup to drop-off, and wait nearby for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],Dw={path:"/guides/tempe-festival-of-the-arts",title:"Tempe Festival of the Arts 2026: dates, parking and a chauffeured art day",metaTitle:"Tempe Festival of the Arts 2026 Guide",description:"The Tempe Festival of the Arts, December 4 to 6, 2026 on Mill Avenue: dates and hours, the streets it fills, parking, drop-off and light rail, free admission, dogs, what to bring, the Kids Block, and a chauffeured festival day with room aboard for the art you buy.",metaDescription:"Tempe Festival of the Arts, Dec 4–6, 2026: hours, parking, drop-off, light rail, dogs, and a chauffeured art day",lastUpdated:Hh,lastUpdatedLabel:l(Hh),eyebrow:"Free admission · December 4 to 6, 2026",intro:`A festival day with Scottsdale Sprinters starts with the festival’s own dates, the day you want and a rider count. Art buyers and couples lead with the ${v(J)}; families take the Executive Sprinters or the Mini Bus, alcohol-free; friends’ crews ride a Limo Party Sprinter or the party bus. This guide uses only facts the Tempe Festival of the Arts publishes, and turns the day into a written pickup, drop-off and ride home.`,sections:Rw,faqs:xw,links:[{href:"/fleet/maybach-jet-sprinter-scottsdale",label:v(J)},{href:"/fleet/executive-sprinter-scottsdale",label:v(tr)},{href:"/fleet/limo-sprinter-16-scottsdale",label:v(no)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:Mw,fleetRows:Pw},Yh="2026-09-27",Iw="https://arizonawildcats.com/sports/football/schedule",Nw="https://arizonawildcats.com/news/2026/1/21/arizona-football-announces-2026-schedule",Ww="https://thesundevils.com/news/2026/01/21/big-12-sun-devil-athletics-unveil-2026-football-schedule",Lw="https://arizonawildcats.com/sports/2022/8/30/AZFanGuide",Ow="https://arizonawildcats.com/sports/2013/4/18/Stadium-Policies",_w="https://arizonawildcats.com/sports/2026/9/4/casino-del-sol-parking-information",Gw="https://arizonawildcats.com/sports/2017/1/24/tailgating.aspx",Uw="https://arizonawildcats.com/sports/2026/7/29/bear-down-bash",Bw="https://arizonawildcats.com/sports/2026/7/14/Casino-Del-Sol-Stadium",Hw="https://sundevils.com/spirit/traditions/territorial-cup",Zr={crews:["party-bus-28-scottsdale","limo-sprinter-16-scottsdale","limo-sprinter-13-scottsdale"],families:["executive-sprinter-scottsdale","executive-white-sprinter-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],groups:["executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},zw=[...Zr.crews,...Zr.families,...Zr.vip,...Zr.groups].filter(ae),qw=zw.map(e=>({slug:e,name:n[e],capacity:i[e],hourlyRateCents:r[e].hourlyRateCents,minimumHours:r[e].minimumHours})),se="party-bus-28-scottsdale",so="limo-sprinter-16-scottsdale",Vw="limo-sprinter-13-scottsdale",rt="executive-sprinter-scottsdale",Yw="executive-white-sprinter-scottsdale",Ut="maybach-jet-sprinter-scottsdale",Jw="ultra-luxury-party-sprinter-scottsdale",ys="maybach-shuttle-sprinter-8",bs="premium-suv-scottsdale",Zw="executive-mini-bus-26-scottsdale",Kw="executive-luxury-bus-29-scottsdale",jw="motorcoach-56",qa=12,w=e=>n[e],Ke=e=>i[e];function ws(e){return h(r[e].hourlyRateCents)}function Qw(e,t){const a=r[e];return a.hourlyRateCents*Ds(t,a.minimumHours)}function Jh(e,t,a){return h(Math.round(Qw(e,t)/a))}function je(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Xw=[{label:"Arizona Athletics: 2026 football schedule (Arizona State, November 28, kickoff TBA)",href:Iw},{label:"Arizona Athletics: Arizona Football announces 2026 schedule",href:Nw},{label:"Sun Devil Athletics: 2026 football schedule",href:Ww},{label:"Arizona Athletics: A–Z Fan Guide (pregame timeline, bags)",href:Lw},{label:"Arizona Athletics: Casino Del Sol Stadium policies (clear bags, rideshare, re-entry)",href:Ow},{label:"Arizona Athletics: Casino Del Sol Stadium parking information",href:_w},{label:"Arizona Athletics: football tailgating",href:Gw},{label:"Arizona Athletics: Bear Down Bash",href:Uw},{label:"Arizona Athletics: Casino Del Sol Stadium",href:Bw},{label:"Sun Devil Athletics: the Territorial Cup tradition",href:Hw}],ev=[je("When is the 2026 Territorial Cup, and what time is kickoff?","The 2026 Territorial Cup is Arizona State at Arizona on Saturday, November 28, 2026, at Casino Del Sol Stadium in Tucson, the 100th Territorial Cup and Arizona’s Senior Day; the kickoff time is not announced yet, because both schools say game times are selected later for television, so we set the pickup once it is.","Arizona’s schedule lists the game as “TBA” and the 2026 regular-season finale for both teams. Its schedule release adds that select Saturday games may be moved to a Friday, another special date or Black Friday, announced later, so check the date and the kickoff on the schools’ own schedules before the pickup is set.","The game is a Big 12 Conference game. Sun Devil Athletics lists it as “@Arizona” on November 28, and Arizona Athletics as its home game against Arizona State."),je("Where do you park for ASU at Arizona, and where is the drop-off?","Casino Del Sol Stadium’s rideshare drop-off and pick-up is lot 4063, just north of Flandrau, and drivers park in campus lots and garages that take cards only; a chauffeured group skips the lot: we unload where stadium and traffic staff direct and meet the group again at the pickup point agreed in advance.","Arizona Athletics says every surface lot is credit only and every garage takes credit cards or tap only. It lists game-day parking in named garages and lots around campus, free garage parking for carpools of four or more in four named garages, and Cat Tran shuttles from the Park Ave. Garage that start two hours before kickoff and drop fans on 6th Street, immediately south of the stadium.","ADA drop-off is at the Cherry Avenue pull-out at Cherry and University, at Highland and 6th Street, on 4th Street west of Highland Avenue, and on 6th Street just south of the stadium. No drop-off zone for charter vehicles, limos or party buses is printed, so a chauffeured group is unloaded where stadium and traffic staff direct.","With a chauffeur, the long drive and the parking question both go away: nobody drives the interstate home after the game, and nobody walks back to a garage."),je("Can you tailgate at the Territorial Cup in Tucson?","Tailgating on the University of Arizona mall needs a season or game-specific tailgate pass displayed on the vehicle, and Arizona Athletics lists the 2026 passes as sold out; groups without a pass can walk to the free Bear Down Bash on Bear Down Field, just north of the stadium, which opens three and a half hours before kickoff.","The tailgating area opens six hours before kickoff, its entrance closes three hours before kickoff, all tailgating stops at kickoff, and the grounds are cleared within an hour after the game. Large parties must meet outside the area and arrive together to be parked together. Tailgating (beer and wine allowed) is also permitted in the 4052 surface lot, where a tailgate permit or a game-day fee is required to park; it is not allowed in any garage.","The university’s alcohol rules on the tailgate grounds: bring your own beer and wine only, no hard alcohol, no kegs and no glass, only in the six hours before kickoff, and no alcohol inside the stadium. Those are the university’s rules for its grounds; we sell no alcohol.","The Bear Down Bash is free for Wildcat fans, with live music, food trucks and a bar, and closes half an hour before kickoff. Arizona’s list for November 28 reads “Country Night”."),je("What is the clear bag policy at Casino Del Sol Stadium?","Arizona Athletics allows clear plastic or vinyl bags no larger than 12 by 6 by 12 inches, one-gallon clear freezer bags, and small clutch bags about the size of a hand, which are searched; backpacks, purses larger than a clutch, fanny packs, diaper bags and cooler bags are not allowed, and no food or drink containers go in but sealed plastic water bottles.","Exceptions are made for medically necessary items after inspection. Prohibited bags may not be carried inside a clear bag to get in.","There is no re-entry: once you leave the stadium, you need a new ticket to return. On a road trip with us, the bags, the cooler and the jackets stay in the vehicle until the ride home."),je("What is the Territorial Cup, and why is it called the Duel in the Desert?","The Territorial Cup is the trophy of the Arizona State and Arizona football rivalry, also known as the Duel in the Desert; it was first awarded in 1899 in the Arizona Territory, and both schools call it the nation’s oldest rivalry trophy game, recognized by the NCAA as the oldest rivalry trophy in college football.","Sun Devil Athletics writes that the Arizona Normal School, now ASU, won the first Territorial Cup game on November 30, 1899, beating the University of Arizona 11-2 in Tucson, and that the two teams have met every year since 1946.","The original cup disappeared for decades and was found again in the early 1980s. Since 2001 it has travelled as a shared trophy, displayed each year by the winner. Arizona Athletics calls the November 28, 2026 game the 100th Territorial Cup."),je("What time do the gates open, and how does the day run?","Arizona Athletics’ general timeline runs from kickoff: tailgate lots open six hours before, the ticket office windows five hours before, the Bear Down Bash three and a half hours before, the Wildcat Walk two and a half hours before, and the Casino Del Sol Stadium gates an hour and a half before kickoff.","Arizona Athletics notes that times are subject to change depending on the start time of the game. Once the kickoff is announced, the timeline falls into place, and so does your pickup time in the Valley.","For a road trip, that means leaving the Valley early enough for the drive, the pregame you want and the walk to the gates, and a ride home that starts after the final whistle."),je("What does a chauffeured Territorial Cup road trip cost?",`A game day from Scottsdale or Phoenix is booked by the hour at each vehicle’s published rate, from pickup to drop-off, with the vehicle waiting in Tucson: the ${w(se)} is ${ws(se)}/hr and seats ${Ke(se)}, a ${w(so)} is ${ws(so)}/hr, the ${w(rt)} is ${ws(rt)}/hr; prices are before tax, and game tickets are sold by the schools.`,`Long days cost less per hour: a ${qa}-hour game day bills ${Ds(qa,r[se].minimumHours)} hours, the free hours taken off automatically. ${Ke(se)} riders sharing the ${w(se)} for ${qa} hours is about ${Jh(se,qa,Ke(se))} each before tax; ${Ke(rt)} riders in the ${w(rt)} is about ${Jh(rt,qa,Ke(rt))} each. That is arithmetic on the published rates, not a flat game-day fare.`,"On an hourly day the stops are yours and the miles are not counted. The ready-made packages on this page are priced the same way, with the extras they carry, and show the total before anyone books."),je("Which vehicle fits a Territorial Cup group?",`Fan crews and alumni lead with the ${w(se)}, our pick for the road trip, or a Limo Party Sprinter; families and parents take the ${w(rt)} or the white Executive Sprinter, alcohol-free; VIP guests and boosters ride the ${w(Ut)}; a big alumni club takes the Mini Bus, the Mini Coach or the coach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in four groups. Crews: the ${w(se)}, the ${w(so)} and the ${w(Vw)}. Families: the ${w(rt)} and the ${w(Yw)}. VIP: the ${w(Ut)}, the ${w(Jw)}, the ${w(ys)} and the ${w(bs)}. Alumni clubs: the ${w(Zw)}, the ${w(Kw)} and the ${w(jw)}.`,`A VIP party larger than the ${w(Ut)} rides in two vehicles, one booking each for the same day and times: the ${w(Ut)} with the ${w(ys)} seats ${Ke(Ut)+Ke(ys)}, and with the ${w(bs)} it seats ${Ke(Ut)+Ke(bs)}.`,`Students often ride with the group, so our house rule applies: ${Ft} Families ride the Executive Sprinters, never a party unit, and no package on this page carries a drink service.`),je("How far ahead should you book, and what if the date or kickoff changes?","Send the group, the pickup address and a likely passenger count as soon as you know you are going; availability varies by vehicle on a rivalry weekend, so no fixed lead time applies, and the pickup time is set once the kickoff is announced.","If the schools move the game to another date, tell us the new one as soon as it is announced, and we check the vehicle for that day. The first request needs the game day, the pickup address in the Valley, the group size and who is riding: a fan crew, a family with students, VIP guests or an alumni club.",`During the final 48 hours, confirm addresses, phone numbers and the pickup point for the ride home. Reach the reservations team at ${u} or ${p}.`)],tv=[{question:"When is the 2026 Territorial Cup?",answer:"Saturday, November 28, 2026: Arizona State at Arizona, at Casino Del Sol Stadium in Tucson. Arizona calls it the 100th Territorial Cup."},{question:"What time is the ASU vs Arizona football game?",answer:"The kickoff is not announced yet. Both schools say game times are selected later for television; check the schools’ schedules before you set a pickup."},{question:"Where is the 2026 Territorial Cup played?",answer:"At Casino Del Sol Stadium, Arizona’s home stadium on the University of Arizona campus in Tucson."},{question:"Why is it called the Duel in the Desert?",answer:"It is the other name of the Arizona State and Arizona football rivalry, whose trophy, the Territorial Cup, was first awarded in 1899 and is recognized as the oldest rivalry trophy in college football."},{question:"When do the gates open at Casino Del Sol Stadium?",answer:"An hour and a half before kickoff, on Arizona Athletics’ general game-day timeline. Tailgate lots open six hours before kickoff."},{question:"Where is rideshare drop-off at Casino Del Sol Stadium?",answer:"Lot 4063, just north of Flandrau. A chauffeured group is unloaded where stadium and traffic staff direct."},{question:"Does Casino Del Sol Stadium have a clear bag policy?",answer:"Yes. Clear bags up to 12 by 6 by 12 inches, one-gallon clear freezer bags and small clutch bags only; no backpacks, and no re-entry."},{question:"Can you hire a party bus from Scottsdale to the Territorial Cup?",answer:`Yes. The ${w(se)}, the Limo Party Sprinters and the Executive Sprinters are booked by the hour for the whole day, and wait in Tucson for the ride home. If anyone aboard is under 21, the whole trip is alcohol-free.`}],av={path:"/guides/territorial-cup-tucson",title:"Territorial Cup 2026 in Tucson: ASU at Arizona game day, parking and a road trip from the Valley",metaTitle:"Territorial Cup 2026: ASU at Arizona Guide",description:"The 2026 Territorial Cup, Arizona State at Arizona on November 28 at Casino Del Sol Stadium in Tucson: the kickoff (not announced yet), parking and rideshare drop-off, tailgating, the clear bag rule, the Duel in the Desert’s history, and a chauffeured road trip from Scottsdale or Phoenix.",metaDescription:"Territorial Cup, Nov 28, 2026 in Tucson: kickoff, parking, tailgating, clear bags, and a road trip from Scottsdale",lastUpdated:Yh,lastUpdatedLabel:l(Yh),eyebrow:"ASU at Arizona · November 28, 2026",intro:`A Territorial Cup road trip with Scottsdale Sprinters starts with the schools’ own date, the group and a rider count. Fan crews and alumni lead with the ${w(se)} or a Limo Party Sprinter; families take the Executive Sprinters, alcohol-free; VIP guests ride the ${w(Ut)}. This guide uses only facts Arizona Athletics and Sun Devil Athletics publish, and turns the day into a written pickup, drop-off and ride home.`,sections:ev,faqs:tv,links:[{href:"/fleet/party-bus-28-scottsdale",label:w(se)},{href:"/fleet/limo-sprinter-16-scottsdale",label:w(so)},{href:"/fleet/executive-sprinter-scottsdale",label:w(rt)},{href:"/guides/phoenix-to-tucson-shuttle",label:"Phoenix to Tucson private shuttle"},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:Xw,fleetRows:qw},Zh="2026-09-24",rv="/guides/wm-phoenix-open-parking",Tt="maybach-jet-sprinter-scottsdale",wo="ultra-luxury-party-sprinter-scottsdale",Kh="maybach-shuttle-sprinter-8",jh="premium-suv-scottsdale",Qh="limo-sprinter-13-scottsdale",ha="limo-sprinter-16-scottsdale",Kr="party-bus-28-scottsdale",ka="executive-sprinter-scottsdale",ov="executive-white-sprinter-scottsdale",Xh="executive-mini-bus-26-scottsdale",jr="executive-luxury-bus-29-scottsdale",O=e=>n[e],Q=e=>i[e],vs=e=>h(r[e].hourlyRateCents);function nv(e,t,a){return h(Math.round(r[e].hourlyRateCents*t/a))}const ed=Q(ka),td=6,sv="https://wmphoenixopen.com/event-schedule/",iv="https://wmphoenixopen.com/spectator-info/",hv="https://wmphoenixopen.com/wp-content/uploads/2026/04/2026-Parking-Map_Public.pdf",dv="https://wmphoenixopen.com/wp-content/uploads/2026/05/ADA-Spectator-Information.pdf",lv="https://wmphoenixopen.com/tickets-packages/tickets-concerts-coors-birds-nest/",cv="https://coorslightbirdsnest.com/",uv="https://wmphoenixopen.com/insights/grammy-award-winning-imagine-dragons-to-kick-off-wm-phoenix-open-week-at-the-iconic-16th-hole-for-year-6-of-concert-in-the-coliseum/",pv="https://tpc.com/scottsdale/",fv=[{label:"WM Phoenix Open 2027 event schedule",href:sv},{label:"WM Phoenix Open spectator information: parking, entrances, entry times and bags",href:iv},{label:"WM Phoenix Open 2026 parking map (last year’s plan)",href:hv},{label:"WM Phoenix Open accessibility services (ADA) guide",href:dv},{label:"Coors Light Birds Nest 2027 tickets and lineup",href:lv},{label:"Coors Light Birds Nest FAQ",href:cv},{label:"Concert in the Coliseum 2027 announcement",href:uv},{label:"TPC Scottsdale, the host course",href:pv}];function wt(e,t,...a){return{question:e,answer:t,paragraphs:a}}const mv=[wt("Where do you park for the WM Phoenix Open 2027, and is it free?","The 2027 parking plan and any parking price are announced closer to the date. In 2026, general parking used remote WestWorld Lots A, B and C, plus a Salt River Fields lot with a free shuttle; ADA parking is Lot 2, at Hayden and Bell. With a chauffeured ride, nobody in the group drives or parks.","Last year’s plan, labelled as last year’s: in 2026 the remote general-parking lots were WestWorld Lots A, B and C, open Monday through Sunday and reached from the WestWorld area near Frank Lloyd Wright Boulevard, Thompson Peak Parkway, Pima Road and Bell Road. The 2026 Salt River Fields lot ran Wednesday through Sunday from 9:00 a.m. to 6:00 p.m., about 7.6 miles south of TPC Scottsdale, with a free shuttle to the tournament. The tournament’s parking answers still link that 2026 map.","Also from 2026: general-parking guests were told not to leave Loop 101 at Hayden Road or Scottsdale Road, which were kept for ADA access and credentialed passes because of restrictions on 78th Street and Mayo Boulevard, and to use the Princess Boulevard or Bell Road exits instead. Treat that as last year’s routing until the tournament publishes the 2027 version.","Confirmed now: some areas and parking lots are reserved for specific pass types, including event staff, vendors, volunteers, media, charter buses and internal operations, and guests may enter only the areas their pass allows. The ADA lot is Lot 2, at the corner of Hayden and Bell Roads, with a valid handicap placard displayed. The tournament also says parking operations, routes and lot availability may change as the event approaches.","The chauffeured alternative: we pick the group up at the hotel or home and unload where traffic staff direct. Nobody hunts for a lot, waits for a remote-lot shuttle or drives home after the 16th hole. Whether a booked Sprinter or coach needs a pass for any lot is not published, so the reservations team confirms the current instruction before the day rather than promising a lot."),wt("Where do rideshares and drop-offs go at the Phoenix Open?","In 2026, rideshare vehicles, taxis and all passenger drop-off and pick-up used Lot R, entered from Pima Road, instead of the public lots; the 2027 plan is announced closer to the date. At the Birds Nest, rideshares use Hartford Drive, south of Princess. A chauffeured vehicle unloads where traffic staff direct.","No official page gives a limo, a party bus or a charter a gate or drop-off privilege. The only published line about charters is that some lots are reserved for pass types, charter buses among them, and the tournament has not published how an operator gets that pass. So this page promises no gate, lot or curb: the chauffeur follows traffic staff, and the reservations team passes on any 2027 instruction the tournament publishes.","The entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance. Checkpoints stand throughout the area and must be passed before entering designated zones, and some roads and private areas are closed to event guest traffic. Plan the pickup as a place the group can walk to from the entrance it used, not a pin dropped beside a checkpoint.","For the ride home, name one meeting point and one transportation lead before the group goes in. The curb you arrived at may not be where a vehicle can wait at the end of play. The lead counts heads, confirms the vehicle’s position with the chauffeur and walks the group there together, rather than everyone chasing a map pin at once."),wt("When is the WM Phoenix Open 2027?","The WM Phoenix Open runs Monday, February 8 to Sunday, February 14, 2027, at TPC Scottsdale. Monday and Tuesday are Ford Free Days with free general admission, and the 4 rounds run Thursday, February 11 to Sunday, February 14: play begins at 7:30 a.m. Thursday and Friday and 9:00 a.m. on the weekend.","The week opens early. The Concert in the Coliseum is on Saturday, February 6, 2027, on the 16th hole: Imagine Dragons, with Counting Crows opening, for guests 21 and over, with venue gates at 3:30 p.m. The Carlisle Pro-Am starts at 8:30 a.m. on Monday, February 8, and the Annexus Pro-Am at 8:30 a.m. on Wednesday, February 10, the day the WHOOP Shot at Glory is on the 16th hole at 3:30 p.m.","Saturday, February 13 is Green Out Saturday: guests wear green, and a donation goes to the tournament’s Working for Tomorrow fund. The Coors Light Birds Nest runs the evenings of Wednesday, February 10 to Saturday, February 13. The tournament says its agenda is subject to change, so recheck the official schedule in the week before you ride.","For a ride, pick the day first, then the arrival. The tournament suggests lining up early for a seat at the 16th hole, especially on Friday and Saturday, when early arrivals are asked to use the Main Entrance. On the Ford Free Days, Monday and Tuesday, no ticket is needed at all."),wt("Where is the Phoenix Open played, and when do the gates open?","The Phoenix Open is played on the Stadium Course at TPC Scottsdale, 17020 North Hayden Road, Scottsdale, AZ 85255. Entry opens each day at 7:00 a.m. at the Main and Princess entrances and at 7:15 a.m. at Hayden; on Friday and Saturday, Hayden opens only once the Main line is in.","The three entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance. Guests arriving early on Friday and Saturday are asked to use the Main Entrance; a line may form at Hayden, but Hayden admits guests only after everyone at the Main Entrance is in. Tournament Guest Services is north of Bell Road between Hayden and 82nd Street and opens daily at 7 a.m.","The entry times are the tournament’s own answers, written after the 2026 event and not dated for 2027, so recheck them in January. The street address is the host club’s, from TPC Scottsdale’s own site. On the day the tournament routes guests by entrance, lot and signage rather than by street number, and the chauffeur follows its signs and staff.","Tournament traffic is not normal traffic. Build the buffer before the time the group wants to be through the gate, count screening and the walk from the unload point, and plan the return as a window rather than a fixed minute: the round, the crowd at the 16th hole and the exits decide it."),wt("Which vehicle fits a Phoenix Open group?",`Match the vehicle to the day: hospitality hosts and VIP guests ride the ${O(Tt)} or our other ultra-luxury rides, 16th-hole crews take a Limo Party Sprinter or the ${O(Kr)} for up to ${Q(Kr)}, and couples and golf fans take an Executive Sprinter or, for a club of up to ${Q(jr)}, the ${O(jr)}.`,`Corporate hospitality and VIP: the ${O(Tt)} leads, ${Q(Tt)} seats with Maybach massage recliners and a wet bar. The ${O(wo)} seats ${Q(wo)} in a fiber-optic lounge for a Birds Nest night, the ${O(Kh)} seats ${Q(Kh)} in custom Maybach seats, and the ${O(jh)} carries a couple or a small client party of up to ${Q(jh)}. A larger hospitality list moves in the executive coaches below.`,`16th-hole crews: the ${O(Qh)} and the ${O(ha)} are limo lounges on wheels for ${Q(Qh)} and ${Q(ha)}, and the ${O(Kr)} puts ${Q(Kr)} on limo seating when the whole crew comes. These are party rides for a group out to celebrate; we never send one as a corporate client vehicle.`,`Couples and golf fans: the ${O(ka)} and the ${O(ov)} seat ${Q(ka)} each in reclining leather, and the ${O(Xh)} (${Q(Xh)} seats) and the ${O(jr)} (${Q(jr)} seats) carry a golf club, a supporters’ group or a company outing in one vehicle.`,"Count riders for each direction. A morning arrival for the 16th hole and an evening return after the Birds Nest are often different lists. Anyone leaving with another group comes off the return manifest before seats are assigned; “we will decide at the course” is not a count the chauffeur can plan around when the tournament is releasing traffic."),wt("What is the Coors Light Birds Nest, and how do you get there and back?","The Coors Light Birds Nest is the tournament’s 21-and-over concert tent at 82nd Street and Bell Road, across from the main entrance, from Wednesday, February 10 to Saturday, February 13, 2027. Headliners usually go on at about 8:30 p.m.; rideshares use Hartford Drive, south of Princess, and a booked ride waits for the group.","The 2027 lineup so far: Riley Green with Ashley Cooke on Wednesday, Jason Aldean with Josh Ross on Thursday, and Snoop Dogg with T-Pain on Friday. Saturday’s act is to be announced. Valid government-issued ID is required at the gate, and Will Call is at the Birds Nest front gate on 82nd Street and Bell Road, opening at noon Wednesday through Saturday.","The gate time is announced closer to the date: the organizer’s own pages do not yet agree on it. Birds Nest parking hours are also listed as to be determined. After the concert, the organizer’s shuttles take guests to the WestWorld of Scottsdale parking used for the tournament.","A chauffeured group skips the lot and the shuttle: book the vehicle by the hour for the evening, or a drop-off and a set pickup, and agree the meeting point before the headliner starts. The Birds Nest and the Concert in the Coliseum are both 21 and over, so a group with anyone younger plans the tournament day instead of the concert night."),wt("What can you bring into the Phoenix Open, and what should the day plan include?","The gate allows no opaque bag larger than 6 by 6 by 6 inches and no clear bag larger than 12 by 6 by 12 inches, and admission is a digital AXS ticket. Write the day plan in 5 lines: ready time, entrance, meeting point, one transportation lead and the ride home.","General admission for the tournament and for the Birds Nest is a digital AXS Mobile ID ticket; guests without a smartphone can visit Guest Services. Guests 15 and younger get in free, and on the Ford Free Days, Monday, February 8 and Tuesday, February 9, no ticket is needed. Suites and hospitality packages are sold by the tournament, not by us: a ride includes no ticket, pass or parking.","Anything bigger than those bag limits, a cooler included, stays on the vehicle. The ready time is when guests are at the pickup point with tickets on their phones, not when they start getting dressed. On Green Out Saturday the tournament asks guests to wear green; its FAQ sets no other dress code.","Free mobility scooters are offered first come, first served, Tuesday through Sunday, on Bell Road near the main entrance, and there are ADA viewing platforms at the 16th green, the 17th fairway and the 18th green. Tell the reservations team about mobility needs when you book, so the pickup and the unload point suit the rider.",`During the final 48 hours, verify addresses, contact numbers and the tournament’s newest parking and entry notes, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${u} or ${p}.`),wt("How is Phoenix Open transportation priced per person?",`For ${ed} Phoenix Open riders sharing the ${O(ka)} for ${td} billed hours, the published ${vs(ka)}-per-hour rate comes to about ${nv(ka,td,ed)} per person before tax for the whole shared ride; the price changes with the vehicle, the hours, the day and the confirmed plan.`,"That example is arithmetic, not a flat tournament fare: the hourly rate times the billed hours, divided by the riders. If only ten people ride, divide by ten. A day that waits through the round and dinner after needs more hours than a drop-off and a set pickup, so describe the real pattern and let the quote price it.",`The same arithmetic on the ${O(ha)} uses its own rate of ${vs(ha)} an hour and its ${Q(ha)} seats; on the ${O(Tt)}, ${vs(Tt)} an hour for ${Q(Tt)}. The ready-made packages on this page print the engine’s own total for their hours and extras, including any hour the rate ladder gives free.`,"One person collects the shares and one person owns the manifest. Neither job belongs to the chauffeur, and neither should wait until the group is standing at the curb after the round.")],gv=[{question:"When is the WM Phoenix Open 2027?",answer:"Monday, February 8 to Sunday, February 14, 2027, at TPC Scottsdale. Monday and Tuesday are Ford Free Days with free general admission, and the four tournament rounds run Thursday, February 11 to Sunday, February 14."},{question:"Where is the Phoenix Open played?",answer:"On the Stadium Course at TPC Scottsdale, 17020 North Hayden Road, Scottsdale, AZ 85255. The entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance."},{question:"What time do gates open at the Phoenix Open?",answer:"Entry opens at 7:00 a.m. at the Main and Princess entrances and at 7:15 a.m. at Hayden. Play begins at 7:30 a.m. on Thursday and Friday and 9:00 a.m. on Saturday and Sunday. The entry times are undated, so recheck them in January."},{question:"Is parking free at the Phoenix Open?",answer:"The 2027 parking plan and any price are announced closer to the date. In 2026, general parking used remote lots at WestWorld and at Salt River Fields, which had a free shuttle. With a chauffeured ride nobody in the group drives or parks."},{question:"Where do Uber and Lyft drop off at the Phoenix Open?",answer:"In 2026, rideshares, taxis and all stop-and-drop used Lot R, entered from Pima Road; the 2027 plan is announced closer to the date. For the Birds Nest, rideshare pickup and drop-off is on Hartford Drive, south of Princess."},{question:"Can a limo or party bus drop off at the Phoenix Open gate?",answer:"No official page gives a limo, party bus or charter a gate or drop-off privilege, and some lots are reserved for pass types, charter buses included. Our chauffeur unloads where traffic staff direct and follows any 2027 instruction the tournament publishes."},{question:"What does it cost to get into the Phoenix Open?",answer:"Monday, February 8 and Tuesday, February 9 are Ford Free Days: free admission, no ticket needed. Guests 15 and younger get in free. Other admission is sold through AXS; the official site says its link is coming soon, so 2027 prices are announced closer to the date."},{question:"Where is the Coors Light Birds Nest?",answer:"At 82nd Street and Bell Road, across from the main tournament entrance, Wednesday, February 10 to Saturday, February 13, 2027. It is 21 and over, headliners usually go on at about 8:30 p.m., and rideshares use Hartford Drive, south of Princess."},{question:"What happens at the 16th hole during Phoenix Open week?",answer:"The week opens with the Concert in the Coliseum on the 16th hole on Saturday, February 6, 2027: Imagine Dragons, with Counting Crows opening, for guests 21 and over, gates at 3:30 p.m. The WHOOP Shot at Glory is on the 16th at 3:30 p.m. on Wednesday, February 10."},{question:"What should I wear to the Phoenix Open?",answer:"The tournament’s FAQ sets no general dress code. Saturday, February 13 is Green Out Saturday: wear green, and a donation goes to its Working for Tomorrow fund. Keep bags small: opaque up to 6 by 6 by 6 inches, clear up to 12 by 6 by 12."}],yv={path:rv,title:"WM Phoenix Open 2027: parking and getting there",metaTitle:"WM Phoenix Open 2027: Parking & Rides",description:"The WM Phoenix Open 2027 runs February 8–14 at TPC Scottsdale. The official dates and entry times, last year’s parking and stop-and-drop plan, the Birds Nest, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official Feb 8–14 dates, parking and drop-off, the Birds Nest, or a chauffeured ride",lastUpdated:Zh,lastUpdatedLabel:l(Zh),eyebrow:"Official dates: February 8–14, 2027",intro:"A Phoenix Open ride from Scottsdale Sprinters starts with the day your group is having: the 16th hole with the crew, a client day in hospitality, a round with the golf fans or a Birds Nest night. This guide uses only what the tournament and TPC Scottsdale publish, labels last year’s parking plan as last year’s, and says plainly what is announced closer to the date.",sections:mv,faqs:gv,links:[{href:"/experiences/wm-phoenix-open",label:"WM Phoenix Open group transportation"},{href:"/guides/arabian-horse-show-transportation",label:"Arabian Horse Show at WestWorld, the same week"},{href:"/services/golf-outing-sprinter-van-scottsdale",label:"Golf outing transportation"},{href:`/fleet/${wo}`,label:O(wo)},{href:`/fleet/${Tt}`,label:O(Tt)},{href:`/fleet/${ha}`,label:O(ha)},{href:"/pricing",label:"Published hourly pricing"}],sources:fv},ad=Object.assign({"./arabian-horse-show-transportation.ts":Zl,"./arizona-financial-theatre.ts":gc,"./arizona-state-fair.ts":Mc,"./asu-gammage.ts":Qc,"./asu-gcu-graduation-transportation.ts":pu,"./barrett-jackson-transportation.ts":md,"./cactus-league-spring-training.ts":Iu,"./canal-convergence-scottsdale.ts":Ju,"./celebrity-theatre.ts":cp,"./chase-field.ts":Ll,"./christmas-lights-scottsdale-phoenix.ts":jp,"./company-christmas-party-ideas-scottsdale-phoenix.ts":nf,"./country-thunder-transportation.ts":cl,"./desert-diamond-arena.ts":Pf,"./fiesta-bowl-transportation.ts":ll,"./footprint-center.ts":Jl,"./halloween-haunted-houses-phoenix.ts":Kf,"./hans-zimmer-phoenix-2027.ts":ym,"./harry-styles-phoenix-2027.ts":im,"./innings-festival-transportation.ts":Lm,"./jonas-brothers-phoenix-2026.ts":am,"./m3f-festival-transportation.ts":Qm,"./mesa-amphitheatre.ts":mg,"./mesa-marathon.ts":Cg,"./mullett-arena.ts":Zg,"./nba-all-star-weekend-2027.ts":cy,"./new-years-eve-scottsdale-phoenix.ts":Ry,"./phoenix-concerts-2026-2027.ts":Jy,"./phoenix-raceway-nascar-transportation.ts":hb,"./rock-n-roll-arizona-marathon.ts":Cb,"./saguaro-lake-transportation.ts":Bb,"./scottsdale-limo-service.ts":Qb,"./state-farm-stadium.ts":Hl,"./talking-stick-resort-amphitheatre.ts":bw,"./tempe-festival-of-the-arts.ts":Dw,"./territorial-cup-tucson.ts":av,"./trans-siberian-orchestra-phoenix-2026.ts":um,"./wm-phoenix-open-parking.ts":yv}),Av=Object.keys(ad).sort().map(e=>ad[e]);export{Zl as A,Sv as B,Ll as C,Av as F,Jl as M,dl as P,Hl as S};
